/* =========================================================
   CAMPUSCONNECT — PROFESSIONAL STUDENT DASHBOARD
========================================================= */

.studentDashboard {
  display: grid;
  gap: 18px;
  animation: dashboardEnter .3s ease both;
}

@keyframes dashboardEnter {
  from {
    opacity: 0;
    transform: translateY(5px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* HERO */

.studentDashboardHero {
  position: relative;
  overflow: hidden;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 250px;
  gap: 32px;
  min-height: 205px;
  padding: 30px 32px;
  border-radius: 18px;
  background:
    radial-gradient(
      circle at 88% 10%,
      rgba(255,255,255,.16),
      transparent 27%
    ),
    linear-gradient(
      125deg,
      #14213d 0%,
      #233f8d 58%,
      #365ed1 100%
    );
  color: #fff;
  box-shadow: 0 22px 55px rgba(34,61,124,.2);
}

.studentDashboardHero::after {
  content: "";
  position: absolute;
  width: 290px;
  height: 290px;
  right: -105px;
  bottom: -165px;
  border: 1px solid rgba(255,255,255,.17);
  border-radius: 50%;
  box-shadow:
    0 0 0 42px rgba(255,255,255,.045),
    0 0 0 84px rgba(255,255,255,.025);
}

.studentDashboardHeroCopy,
.studentDashboardHeroStatus {
  position: relative;
  z-index: 1;
}

.studentDashboardHeroCopy > span {
  color: #c6d6ff;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .14em;
}

.studentDashboardHeroCopy h2 {
  margin: 12px 0 8px;
  font-size: clamp(27px, 3vw, 36px);
  line-height: 1.05;
  letter-spacing: -.045em;
}

.studentDashboardHeroCopy p {
  max-width: 650px;
  margin: 0;
  color: #d9e4ff;
  font-size: 11px;
  line-height: 1.7;
}

.studentHeroActions {
  display: flex;
  gap: 10px;
  margin-top: 23px;
}

.studentHeroActions button {
  min-height: 39px;
}

.dashboardSecondaryButton {
  border: 1px solid rgba(255,255,255,.25);
  background: rgba(255,255,255,.08);
  color: #fff;
}

.dashboardSecondaryButton:hover {
  background: rgba(255,255,255,.14);
}

/* PROFILE READINESS */

.studentDashboardHeroStatus {
  align-self: center;
  padding: 20px;
  border: 1px solid rgba(255,255,255,.15);
  border-radius: 15px;
  background: rgba(255,255,255,.085);
  backdrop-filter: blur(9px);
}

.studentDashboardHeroStatus > small {
  color: #c7d6ff;
  font-size: 8px;
  font-weight: 800;
  letter-spacing: .12em;
}

.studentDashboardHeroStatus > strong {
  display: block;
  margin-top: 6px;
  font-size: 31px;
  letter-spacing: -.04em;
}

.studentDashboardHeroStatus p {
  margin: 9px 0 13px;
  color: #d9e4ff;
  font-size: 9px;
  line-height: 1.55;
}

.studentDashboardHeroStatus button {
  padding: 0;
  border: 0;
  background: transparent;
  color: #fff;
  font-size: 9px;
  font-weight: 700;
}

.dashboardProgress {
  overflow: hidden;
  height: 5px;
  margin-top: 9px;
  border-radius: 999px;
  background: rgba(255,255,255,.18);
}

.dashboardProgress span {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: #fff;
}

/* ERROR */

.dashboardNotice {
  padding: 11px 14px;
  border: 1px solid #f2c5c5;
  border-radius: 10px;
  background: #fff6f6;
  color: #b33a3a;
  font-size: 10px;
}

/* TOP STATS */

.studentDashboardStats {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 13px;
}

.dashboardStatCard {
  appearance: none;
  display: block;
  width: 100%;
  min-height: 133px;
  padding: 18px;
  border: 1px solid #e7ebf1;
  border-radius: 14px;
  background: #fff;
  color: inherit;
  text-align: left;
  box-shadow: 0 8px 28px rgba(32,50,85,.045);
  transition:
    transform .18s ease,
    box-shadow .18s ease,
    border-color .18s ease;
}

.dashboardStatCard:hover {
  transform: translateY(-2px);
  border-color: #d6def0;
  box-shadow: 0 13px 34px rgba(32,50,85,.08);
}

.dashboardStatCard > div {
  display: flex;
  align-items: center;
  gap: 8px;
}

.dashboardStatIcon {
  display: grid;
  place-items: center;
  width: 27px;
  height: 27px;
  border-radius: 8px;
  background: #eef3ff;
  color: #3159d9;
  font-size: 10px;
  font-style: normal;
  font-weight: 800;
}

.dashboardStatCard small {
  color: #7b8799;
  font-size: 8px;
  font-weight: 800;
  letter-spacing: .08em;
}

.dashboardStatCard > strong {
  display: block;
  margin: 12px 0 5px;
  color: #1d2b45;
  font-size: 28px;
  line-height: 1;
  letter-spacing: -.04em;
}

.dashboardStatCard p {
  margin: 0;
  color: #8b95a5;
  font-size: 9px;
  line-height: 1.45;
}

/* MAIN GRID */

.studentDashboardMainGrid {
  display: grid;
  grid-template-columns: minmax(0, 1.6fr) minmax(285px, .8fr);
  gap: 16px;
  align-items: start;
}

.studentDashboardPrimaryColumn,
.studentDashboardSideColumn {
  display: grid;
  gap: 16px;
}

.dashboardPanel {
  overflow: hidden;
  padding: 20px;
}

.dashboardPanelHeader {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  padding-bottom: 15px;
  border-bottom: 1px solid #edf0f5;
}

.dashboardPanelHeader span {
  color: #3159d9;
  font-size: 8px;
  font-weight: 850;
  letter-spacing: .13em;
}

.dashboardPanelHeader h3 {
  margin: 5px 0 0;
  color: #1c2940;
  font-size: 16px;
  letter-spacing: -.02em;
}

.dashboardPanelHeader > button {
  padding: 0;
  border: 0;
  background: transparent;
  color: #536caa;
  font-size: 9px;
  font-weight: 700;
}

/* ATTENDANCE */

.dashboardAttendanceHeadline {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 18px 0 14px;
}

.dashboardAttendanceHeadline > div:first-child strong {
  display: block;
  color: #1c2940;
  font-size: 32px;
  line-height: 1;
  letter-spacing: -.05em;
}

.dashboardAttendanceHeadline small {
  color: #8a96a8;
  font-size: 9px;
}

.dashboardHealthStatus {
  padding: 6px 10px;
