}

.dashboardHealthStatus.risk {
  background: #fff1f1;
  color: #c04444;
}

.dashboardSubjectList {
  display: grid;
}

.dashboardSubjectRow {
  display: grid;
  grid-template-columns: minmax(150px, 1fr) minmax(110px, .7fr) 48px;
  gap: 13px;
  align-items: center;
  padding: 11px 0;
  border-top: 1px solid #f1f3f6;
}

.dashboardSubjectRow:first-child {
  border-top: 0;
}

.dashboardSubjectRow > div:first-child b {
  display: block;
  color: #27344a;
  font-size: 10px;
}

.dashboardSubjectRow > div:first-child small {
  display: block;
  margin-top: 3px;
  color: #929cab;
  font-size: 8px;
}

.dashboardMiniProgress {
  overflow: hidden;
  height: 6px;
  border-radius: 999px;
  background: #edf0f5;
}

.dashboardMiniProgress span {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: #3159d9;
}

.dashboardSubjectRow > strong {
  text-align: right;
  font-size: 10px;
}

.dashboardGood {
  color: #238153;
}

.dashboardRisk {
  color: #c04444;
}

/* ASSIGNMENTS */

.dashboardAssignmentList {
  display: grid;
}

.dashboardAssignmentRow {
  display: grid;
  grid-template-columns: 35px minmax(0, 1fr) auto;
  gap: 12px;
  align-items: center;
  width: 100%;
  padding: 13px 0;
  border: 0;
  border-top: 1px solid #f0f2f6;
  background: transparent;
  color: inherit;
  text-align: left;
}

.dashboardAssignmentRow:first-child {
  border-top: 0;
}

.dashboardAssignmentIcon {
  display: grid;
  place-items: center;
