/* ANNOUNCEMENTS */

.dashboardAnnouncementList {
  display: grid;
}

.dashboardAnnouncement {
  display: grid;
  grid-template-columns: 31px minmax(0, 1fr);
  gap: 10px;
  align-items: center;
