/* NON-STUDENT QUICK VIEW */

.dashboardQuickGrid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 13px;
}

.dashboardQuickAction {
  display: grid;
  gap: 7px;
  padding: 20px;
  border: 1px solid #e6eaf1;
  text-align: left;
}

.dashboardQuickAction span {
  color: #3159d9;
  font-size: 8px;
  font-weight: 800;
}

.dashboardQuickAction strong {
  color: #27344a;
  font-size: 12px;
}

.dashboardQuickAction small {
  color: #8e98a8;
