/* =========================================================
   CAMPUSCONNECT — COLLEGE DASHBOARD HEADER + SIDEBAR TOGGLE
========================================================= */


/* ---------- PAGE TITLE ---------- */

.campusPageTitle {
  display: flex;
  align-items: center;
  gap: 14px;
  min-width: 0;
}

.campusPageHeading {
  min-width: 0;
}

.campusIdentityLine {
  display: flex;
  align-items: center;
  gap: 7px;
  margin-bottom: 5px;
}

.campusIdentityLine span {
  color: #3159d9;
  font-size: 8px;
  font-weight: 900;
  letter-spacing: .14em;
}

.campusIdentityLine i {
  width: 3px;
  height: 3px;
  border-radius: 50%;
  background: #aeb7c6;
}

.campusIdentityLine small {
  color: #8b95a5;
  font-size: 8px;
  font-weight: 600;
}


/* ---------- GREETING ---------- */

.dashboardGreeting {
  margin: 0;
  color: #15233d;
  font-size: clamp(23px, 2.5vw, 30px);
  font-weight: 850 !important;
  line-height: 1.08;
  letter-spacing: -.045em;
}

.dashboardGreetingSub {
  margin: 5px 0 0;
  color: #7d899a;
  font-size: 9px;
  line-height: 1.5;
}


/* ---------- SIDEBAR TOGGLE ---------- */

.sidebarToggle {
  flex: 0 0 auto;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;

  width: 37px;
  height: 37px;

  gap: 4px;

  padding: 0;

  border: 1px solid #e2e7ef;
  border-radius: 10px;

  background: #fff;

  box-shadow:
    0 4px 14px rgba(28, 41, 64, .055);

  transition:
    background .18s ease,
    border-color .18s ease,
    transform .18s ease,
    box-shadow .18s ease;
}

.sidebarToggle:hover {
  transform: translateY(-1px);

  border-color: #ccd6eb;

  background: #f7f9ff;

  box-shadow:
    0 7px 18px rgba(28, 41, 64, .09);
}

.sidebarToggle span {
  display: block;

  width: 15px;
  height: 1.5px;

  border-radius: 999px;

  background: #31415d;

  transition:
    width .18s ease,
    transform .18s ease;
}

.sidebarToggle:hover span:nth-child(2) {
  width: 11px;
}


/* =========================================================
   COLLAPSIBLE SIDEBAR
========================================================= */

.shell {
  transition: grid-template-columns .24s ease;
}

.shell > aside {
  overflow: hidden;

  transition:
    width .24s ease,
    min-width .24s ease,
    opacity .18s ease,
    transform .24s ease,
    padding .24s ease;
}

.shell.sidebarCollapsed {
  grid-template-columns: 0 minmax(0, 1fr) !important;
}

.shell.sidebarCollapsed > aside {
  width: 0 !important;
  min-width: 0 !important;

  padding-left: 0 !important;
  padding-right: 0 !important;

  border-right: 0;

  opacity: 0;

  pointer-events: none;

  transform: translateX(-18px);
}


/* =========================================================
   SUBTLE COLLEGE DASHBOARD FEEL
========================================================= */

.studentDashboard {
  position: relative;
}

.studentDashboard::before {
  content: "";

  position: absolute;
  top: -5px;
  right: 2%;

  width: 220px;
  height: 220px;

  border-radius: 50%;

  background:
    radial-gradient(
      circle,
      rgba(49, 89, 217, .045),
      rgba(49, 89, 217, 0) 68%
    );

  pointer-events: none;
}

.studentDashboardHero {
  border: 1px solid rgba(255, 255, 255, .08);
}

.dashboardPanel,
.dashboardStatCard {
  backdrop-filter: blur(3px);
}


/* =========================================================
   MOBILE SIDEBAR
========================================================= */

@media (max-width: 820px) {

  .shell {
    position: relative;
    grid-template-columns: minmax(0, 1fr) !important;
  }

  .shell > aside {
    position: fixed;

    z-index: 100;

    top: 0;
    left: 0;
    bottom: 0;

    width: min(280px, 86vw);

    box-shadow:
      18px 0 45px rgba(23, 34, 55, .16);
  }

  .shell.sidebarCollapsed > aside {
    width: min(280px, 86vw) !important;

    transform: translateX(-105%);

    opacity: 1;
  }

  .sidebarToggle {
    width: 35px;
    height: 35px;
  }

  .dashboardGreeting {
    font-size: 22px;
  }

  .dashboardGreetingSub {
    max-width: 280px;
  }
}

/* CampusConnect logo fix */

.campusConnectLogo {
  display: block;
  width: 205px;
  height: auto;
  max-height: 58px;
  object-fit: contain;
  object-position: left center;
}

.campusConnectHeaderLogo {
  display: block;
  width: 160px;
  height: auto;
  max-height: 44px;
  object-fit: contain;
}

.brandLogo {
  min-height: 72px;
  padding: 10px 14px !important;
}

@media (max-width: 820px) {
  .campusConnectLogo {
    width: 190px;
  }

  .campusConnectHeaderLogo {
    width: 145px;
  }
}

/* =========================================================
   FIX COLLAPSED SIDEBAR SPACE + TOP BRAND
========================================================= */

.shell.sidebarCollapsed {
  grid-template-columns: minmax(0, 1fr) !important;
}

.shell.sidebarCollapsed > aside {
  position: fixed !important;
  left: 0;
  top: 0;
  bottom: 0;

  width: 0 !important;
  min-width: 0 !important;
  padding: 0 !important;

  opacity: 0;
  overflow: hidden;
  pointer-events: none;
  transform: translateX(-100%);
}

.shell.sidebarCollapsed .workspace {
  width: 100%;
  min-width: 0;
  margin-left: 0 !important;
}

