/* =========================================================
   CAMPUSCONNECT — WARM COLLEGE DASHBOARD
========================================================= */

:root {
  --campus-bg: #fbf7ef;
  --campus-paper: #fffdf8;
  --campus-paper-2: #faf3e7;
  --campus-sidebar: #fffaf1;
  --campus-border: #eadfce;
  --campus-border-soft: #f0e7d8;
  --campus-brown: #854816;
  --campus-brown-dark: #4e2b12;
  --campus-text: #2c251f;
  --campus-muted: #807568;
}

/* PAGE */

body {
  background: var(--campus-bg) !important;
  color: var(--campus-text);
}

.workspace {
  background: var(--campus-bg) !important;
}

.content {
  background: var(--campus-bg) !important;
}

/* =========================================================
   TOP NAVBAR
========================================================= */

.workspaceHeader {
  min-height: 86px !important;
  padding: 0 28px !important;

  border-bottom: 1px solid var(--campus-border-soft) !important;

  background: rgba(255,252,245,.96) !important;

  box-shadow: 0 4px 20px rgba(96,63,28,.025) !important;
}

.workspaceBrandLogo {
  width: 190px !important;
  max-height: 54px !important;

  filter:
    sepia(.28)
    saturate(.75)
    brightness(.78)
    contrast(1.12);
}

.topSidebarToggle {
  width: 45px !important;
  height: 45px !important;

  border: 1px solid var(--campus-border) !important;
  border-radius: 13px !important;

  background: var(--campus-paper) !important;

  box-shadow: 0 5px 15px rgba(93,61,27,.045) !important;
}

.topSidebarToggle span {
  background: var(--campus-brown-dark) !important;
}

/* SEARCH */

.workspaceHeader input,
.campusSearchInput,
.searchInput {
  background: var(--campus-paper) !important;

  border-color: var(--campus-border) !important;

  color: var(--campus-text) !important;
}

/* =========================================================
   USER
========================================================= */

.headerProfileIdentity {
  display: flex;
  align-items: center;
  gap: 10px;

  padding: 5px 7px;

  border: 0;
  background: transparent;

  color: var(--campus-text);

  text-align: left;
}

.headerProfileAvatar {
  display: grid;
  place-items: center;

  width: 41px;
  height: 41px;

  border-radius: 50%;

  background: var(--campus-brown);
  color: #fff;

  font-size: 10px;
  font-weight: 800;
}

.headerProfileText {
  display: grid;
  gap: 2px;
}

.headerProfileText strong {
  font-size: 10px;
  color: var(--campus-text);
}

.headerProfileText small {
  color: var(--campus-muted);
  font-size: 8px;
}

.headerProfileChevron {
  margin-left: 4px;

  color: #978779;
  font-size: 12px;
}

/* =========================================================
   SIDEBAR
========================================================= */

.shell > aside {
  background: var(--campus-sidebar) !important;

  border-right: 1px solid var(--campus-border-soft) !important;
}

.shell > aside nav label {
  color: #a39280 !important;
}

.shell > aside nav button {
  min-height: 43px;

  margin-bottom: 2px;

  border-radius: 10px !important;

  color: #514941 !important;

  font-size: 10px;
  font-weight: 600;
}

.shell > aside nav button:hover {
  background: #faf0df !important;
}

.shell > aside nav button.active {
  background: #f4e5cf !important;

  color: var(--campus-brown-dark) !important;

  box-shadow: none !important;
}

.shell > aside nav button.active i {
  color: var(--campus-brown) !important;
}

/* college identity */

.college {
  border-color: var(--campus-border) !important;
  background: #fffaf2 !important;
}

.college i {
  background: var(--campus-brown) !important;
}

/* Sidebar profile box */

.sidebarProfileProgress {
  display: flex;
  flex-direction: column;
  align-items: center;

  margin: 14px 7px;
  padding: 20px 16px;

  border: 1px solid var(--campus-border);
  border-radius: 13px;

  background: #fbf1df;

  text-align: center;
}

.sidebarProfileIcon {
  display: grid;
  place-items: center;

  width: 42px;
  height: 42px;

  margin-bottom: 11px;

  border-radius: 50%;

  background: #fff9ee;
  color: var(--campus-brown);

