/* BRANCHES */

.branchCards {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
  padding: 20px 24px 24px;
}

.branchCards > button {
  display: grid;
  grid-template-columns: 44px 1fr auto;
  align-items: center;
  gap: 12px;

  min-height: 76px;
  padding: 14px;

  border: 1px solid #e2e7ef;
  border-radius: 12px;

  background: #fff;
  cursor: pointer;
  text-align: left;

  transition:
    border-color .18s ease,
    box-shadow .18s ease,
    transform .18s ease,
    background .18s ease;
}

.branchCards > button:hover {
  transform: translateY(-2px);
  border-color: #c9d3e6;
  box-shadow: 0 8px 24px rgba(26, 43, 75, .07);
}

.branchCards > button.selected {
  border-color: #3159d9;
  background: #f7f9ff;
  box-shadow: inset 0 0 0 1px rgba(49, 89, 217, .08);
}

.branchCards > button > i {
  display: grid;
  place-items: center;

  width: 44px;
  height: 44px;

  border-radius: 11px;
  background: #edf2ff;

  color: #3159d9;

  font-size: 11px;
  font-style: normal;
  font-weight: 900;
}

.branchCards > button.selected > i {
  background: #3159d9;
  color: #fff;
}

.branchCards > button > span {
  min-width: 0;
}

.branchCards > button b {
  display: block;
  color: #24324a;
  font-size: 13px;
}

.branchCards > button small {
  display: block;
  margin-top: 4px;

  color: #8c97a8;
  font-size: 10px;
}

.branchCards > button em {
  color: #a5afbd;
  font-size: 16px;
  font-style: normal;
}

.branchCards > button.selected em {
  color: #3159d9;
}


/* SEMESTER AREA */

.semesterNavigator {
  padding: 22px 24px 25px;
  border-top: 1px solid #e9edf3;
  background: #fafbfd;
}

.semesterNavigatorHeading {
  display: flex;
  align-items: flex-start;
  gap: 18px;
  margin-bottom: 17px;
}

.semesterNavigatorHeading > span {
  margin-top: 4px;

  color: #3159d9;
  font-size: 9px;
  font-weight: 900;
  letter-spacing: .13em;
}

.semesterNavigatorHeading h4 {
  margin: 0;
  color: #24324a;
  font-size: 15px;
}

.semesterNavigatorHeading p {
  margin: 4px 0 0;

  color: #8994a5;
  font-size: 11px;
}

.semesterButtons {
  display: grid;
  grid-template-columns: repeat(8, minmax(70px, 1fr));
  gap: 8px;
}

.semesterButtons > button {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;

  min-height: 82px;
  padding: 10px 6px;

  border: 1px solid #e0e5ed;
  border-radius: 10px;

  background: #fff;
  cursor: pointer;

  transition:
    border-color .18s ease,
    background .18s ease,
    transform .18s ease,
    box-shadow .18s ease;
}

.semesterButtons > button:hover {
  transform: translateY(-1px);
  border-color: #c8d2e5;
}

.semesterButtons > button.selected {
  border-color: #3159d9;
  background: #3159d9;
  box-shadow: 0 7px 18px rgba(49, 89, 217, .18);
}

.semesterButtons span {
  color: #99a3b1;
  font-size: 8px;
  font-weight: 700;
  text-transform: uppercase;
}

.semesterButtons b {
  margin: 3px 0;

  color: #293750;
  font-size: 21px;
  line-height: 1;
}

.semesterButtons small {
  color: #9aa4b2;
  font-size: 8px;
}

.semesterButtons > button.selected span,
.semesterButtons > button.selected b,
.semesterButtons > button.selected small {
  color: #fff;
}


