   --------------------------------------------------------- */

.branchCards {
  display: grid !important;
  grid-template-columns: repeat(3, minmax(0, 1fr)) !important;
  gap: 14px !important;
  padding: 24px 30px 28px !important;
}

.branchCardWrapper {
  position: relative;
  min-width: 0;
}

.branchCardWrapper > button:first-child,
.branchCards > button {
  position: relative;
  display: grid !important;
  grid-template-columns: 48px minmax(0, 1fr) 28px !important;
  align-items: center !important;
  gap: 14px !important;

  width: 100% !important;
  min-height: 116px !important;
