    0 0 0 3px rgba(49, 92, 219, 0.07),
    0 12px 30px rgba(49, 92, 219, 0.08);
}

.branchCardWrapper > button:first-child > i,
.branchCards > button > i {
  display: grid !important;
  place-items: center !important;
  width: 48px !important;
  height: 48px !important;
  margin: 0 !important;
  border-radius: 13px !important;
  background: #eef3ff !important;
  color: #315cdb !important;
  font-size: 12px !important;
  font-style: normal !important;
  font-weight: 850 !important;
  letter-spacing: 0.04em !important;
}

.branchCardWrapper > button:first-child.selected > i,
.branchCards > button.selected > i {
  background: #315cdb !important;
  color: #ffffff !important;
}

.branchCardWrapper > button:first-child > span,
.branchCards > button > span {
  display: flex !important;
  flex-direction: column !important;
  align-items: flex-start !important;
  gap: 4px !important;
  min-width: 0 !important;
  margin: 0 !important;
}

.branchCardWrapper > button:first-child > span > b,
.branchCards > button > span > b {
  display: block !important;
  width: 100% !important;
  overflow: hidden !important;
  margin: 0 !important;
  color: #17233d !important;
  font-size: 14px !important;
  line-height: 1.35 !important;
  font-weight: 760 !important;
  white-space: nowrap !important;
  text-overflow: ellipsis !important;
}

.branchCardWrapper > button:first-child > span > small,
.branchCards > button > span > small {
  display: block !important;
  width: 100% !important;
  overflow: hidden !important;
  margin: 0 !important;
  color: #8a95a8 !important;
  font-size: 11px !important;
  line-height: 1.4 !important;
  white-space: nowrap !important;
  text-overflow: ellipsis !important;
}

.branchCardWrapper > button:first-child > span > small + small {
  color: #a0a8b6 !important;
  font-size: 10px !important;
}

.branchCardWrapper > button:first-child > em,
.branchCards > button > em {
  display: grid !important;
  place-items: center !important;
  width: 28px !important;
  height: 28px !important;
  margin: 0 !important;
  border-radius: 50% !important;
  background: #f4f6fa !important;
  color: #516078 !important;
  font-style: normal !important;
  font-size: 14px !important;
}

.branchDeleteButton {
  position: absolute !important;
  z-index: 4;
  top: 8px !important;
  right: 8px !important;
  display: grid !important;
  place-items: center !important;
  width: 25px !important;
  height: 25px !important;
  padding: 0 !important;
  border: 0 !important;
  border-radius: 50% !important;
  background: rgba(255,255,255,0.96) !important;
  color: #c74343 !important;
  font-size: 15px !important;
  box-shadow: 0 3px 10px rgba(15,23,42,0.08);
