  transition: opacity .18s ease, transform .18s ease !important;
}

.branchCardWrapper:hover .branchDeleteButton {
  opacity: 1;
}

.branchDeleteButton:hover {
  transform: scale(1.06);
}


/* ---------------------------------------------------------
