/* =========================================================
   CAMPUSCONNECT MESSENGER
   ========================================================= */

.campusMessenger {
  display: grid;
  grid-template-columns: 340px minmax(0, 1fr);
  min-height: calc(100vh - 150px);
  max-height: calc(100vh - 110px);
  overflow: hidden;
  border: 1px solid #e5e9f0;
  border-radius: 22px;
  background: #fff;
  box-shadow: 0 16px 45px rgba(15,23,42,.06);
