  display: grid;
  grid-template-columns: 47px minmax(0,1fr) 36px;
  align-items: center;
  gap: 12px;
  min-height: 72px;
  padding: 10px 18px;
  border-bottom: 1px solid #e5e9ef;
  background: rgba(255,255,255,.96);
}

.messengerConversationHeader h3 {
  margin: 0;
  color: #17233c;
  font-size: 14px;
}

.messengerConversationHeader span {
  display: block;
  margin-top: 3px;
  color: #8490a3;
  font-size: 10px;
}

.messageArea {
  flex: 1;
  overflow-y: auto;
  padding: 22px 34px;
}

.chatMessageRow {
  display: flex;
  justify-content: flex-start;
  margin: 5px 0;
}

.chatMessageRow.mine {
  justify-content: flex-end;
}

.chatBubble {
  position: relative;
  max-width: min(66%, 610px);
  padding: 9px 12px 7px;
  border: 1px solid #e6e9ef;
  border-radius: 12px 12px 12px 3px;
  background: #fff;
  box-shadow: 0 2px 5px rgba(15,23,42,.025);
}

.chatMessageRow.mine .chatBubble {
  border-color: #d8e1fb;
  border-radius: 12px 12px 3px 12px;
  background: #eaf0ff;
}

.chatBubble > strong {
  display: block;
  margin-bottom: 3px;
  color: #315cdb;
  font-size: 9px;
}

.chatBubble p {
  margin: 0 34px 0 0;
  color: #26334a;
  font-size: 12px;
  line-height: 1.55;
  white-space: pre-wrap;
  word-break: break-word;
}

.chatBubble > time {
  display: block;
  margin-top: 4px;
  color: #8c97a8;
  font-size: 7px;
  text-align: right;
}

.messageComposerBar {
  display: grid;
  grid-template-columns: 42px minmax(0,1fr) auto;
  align-items: center;
  gap: 9px;
  min-height: 67px;
  padding: 10px 17px;
  border-top: 1px solid #e4e8ef;
  background: #fff;
}

.messageComposerBar > input {
  width: 100%;
  min-height: 42px;
  padding: 0 15px;
  border: 1px solid #e1e6ed;
  border-radius: 999px;
  outline: none;
  background: #f7f8fa;
  color: #26334a;
  font-size: 11px;
}

.messageComposerBar > input:focus {
  border-color: #bbc9ee;
  background: #fff;
}

.chatAttachButton {
  display: grid;
  place-items: center;
  width: 39px;
  height: 39px;
  border-radius: 50%;
  color: #657087;
  font-size: 23px;
  cursor: pointer;
}

.chatAttachButton:hover {
  background: #f0f2f5;
}

.messageComposerBar > button {
  min-height: 39px;
  padding: 0 18px;
  border: 0;
  border-radius: 999px;
  background: #315cdb;
  color: #fff;
  font-size: 10px;
  font-weight: 750;
  cursor: pointer;
}

.chatFilePreview {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
  padding: 8px 18px;
  border-top: 1px solid #e5e8ee;
  background: #fff;
  color: #5e6c83;
  font-size: 10px;
}

.chatFilePreview button {
  border: 0;
  background: none;
  cursor: pointer;
}

.chatAttachment {
  display: flex;
  align-items: center;
  gap: 9px;
  min-width: 210px;
  margin: 6px 0;
  padding: 8px;
  border: 1px solid rgba(93,111,149,.12);
  border-radius: 9px;
  background: rgba(255,255,255,.55);
  text-align: left;
  cursor: pointer;
}

.chatAttachment i {
  display: grid;
  place-items: center;
  width: 37px;
  height: 37px;
  border-radius: 8px;
  background: #fff;
  color: #315cdb;
  font-size: 8px;
  font-style: normal;
  font-weight: 850;
}

.chatAttachment span {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.chatAttachment b {
  color: #35425a;
  font-size: 9px;
}

.chatAttachment small {
  color: #8b96a7;
  font-size: 7px;
}

.messengerWelcome {
  display: grid;
  place-items: center;
  align-content: center;
  flex: 1;
  padding: 40px;
  text-align: center;
}

.messengerWelcome > div {
  display: grid;
  place-items: center;
  width: 76px;
  height: 76px;
  border-radius: 24px;
  background: #315cdb;
  color: #fff;
  font-size: 21px;
  font-weight: 850;
}

.messengerWelcome h2 {
  margin: 20px 0 7px;
  color: #1c2942;
  font-size: 22px;
}

.messengerWelcome p {
  max-width: 420px;
  margin: 0 0 20px;
  color: #8691a3;
  font-size: 12px;
  line-height: 1.7;
}

.messengerEmpty {
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding: 35px 20px;
  color: #8994a5;
  text-align: center;
}

.messengerEmpty b {
  color: #4f5c72;
  font-size: 11px;
}

.messengerEmpty span {
  font-size: 9px;
}

.messengerModalScrim {
  position: fixed;
  z-index: 1000;
  inset: 0;
  display: grid;
  place-items: center;
  padding: 20px;
  background: rgba(15,23,42,.38);
  backdrop-filter: blur(5px);
}

.messengerModal {
  width: min(520px, 100%);
  max-height: min(720px, 92vh);
  overflow-y: auto;
  padding: 22px;
  border-radius: 20px;
  background: #fff;
  box-shadow: 0 30px 90px rgba(15,23,42,.22);
}

.messengerModal > header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 19px;
}

.messengerModal header span {
  color: #315cdb;
  font-size: 9px;
  font-weight: 850;
  letter-spacing: .15em;
}

.messengerModal header h3 {
  margin: 4px 0 0;
  color: #1c2941;
  font-size: 20px;
}

.messengerModal header > button {
  width: 32px;
  height: 32px;
  border: 0;
  border-radius: 50%;
  background: #f2f4f7;
  cursor: pointer;
}

.uidSearchForm {
  display: grid;
  grid-template-columns: minmax(0,1fr) auto;
  gap: 8px;
}

.uidSearchForm input,
.groupModal input,
.groupModal textarea {
  width: 100%;
  min-height: 42px;
  padding: 0 12px;
  border: 1px solid #dfe4ec;
  border-radius: 10px;
  outline: none;
  color: #28354c;
  font-size: 11px;
}

.groupModal textarea {
  min-height: 83px;
  padding-top: 10px;
  resize: vertical;
}

.groupModal form > label {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-top: 13px;
  color: #5f6d83;
  font-size: 10px;
  font-weight: 700;
}

.foundCampusUser {
  display: grid;
  grid-template-columns: 48px minmax(0,1fr) auto;
  align-items: center;
  gap: 12px;
  margin-top: 16px;
  padding: 13px;
  border: 1px solid #e5e9f0;
  border-radius: 13px;
  background: #fafbfc;
}

.foundCampusUser > div:nth-child(2) {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 3px;
}

.foundCampusUser b {
  color: #26334a;
  font-size: 12px;
}

.foundCampusUser span {
  color: #7e899b;
  font-size: 9px;
}

.foundCampusUser small {
  color: #315cdb;
  font-size: 8px;
  font-weight: 700;
}

.groupUserResults {
  max-height: 245px;
  overflow-y: auto;
  margin: 9px 0;
}

.groupUserResults > button {
  display: grid;
  grid-template-columns: 37px minmax(0,1fr) 25px;
  align-items: center;
  gap: 9px;
  width: 100%;
  padding: 8px;
  border: 0;
  border-bottom: 1px solid #eff1f4;
  background: #fff;
  text-align: left;
  cursor: pointer;
}

.groupUserResults > button.selected {
  background: #f0f4ff;
}

.groupUserResults i {
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  border-radius: 50%;
  background: #eef3ff;
  color: #315cdb;
  font-size: 8px;
  font-style: normal;
  font-weight: 850;
}

.groupUserResults span {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.groupUserResults b {
  color: #29364c;
  font-size: 10px;
}

.groupUserResults small {
  color: #8994a5;
  font-size: 8px;
}

.groupUserResults em {
  font-style: normal;
  color: #315cdb;
}

.createGroupButton {
  width: 100%;
  margin-top: 16px;
}

.messengerStatus {
  margin: 12px 0 0;
  padding: 9px 11px;
  border-radius: 9px;
  background: #f3f6ff;
  color: #526684;
  font-size: 9px;
}

@media (max-width: 850px) {
  .campusMessenger {
    grid-template-columns: 290px minmax(0,1fr);
  }

  .messageArea {
    padding: 18px;
  }

  .chatBubble {
    max-width: 82%;
  }
}

@media (max-width: 660px) {
  .campusMessenger {
    display: block;
    max-height: none;
    min-height: 700px;
  }

  .messengerSidebar {
    min-height: 700px;
    border-right: 0;
  }

  .messengerConversation {
    min-height: 700px;
  }
}

/* =====================================================
   CampusConnect Messenger - Connection Requests
   ===================================================== */

.connectionRequestsBox {
  margin: 10px 12px 4px;
  padding: 10px;
  border: 1px solid #e6e9ef;
  border-radius: 12px;
  background: #ffffff;
}

.connectionRequestsHeader {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 8px;
}

.connectionRequestsHeader span {
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.08em;
  color: #667085;
}

.connectionRequestsHeader b {
  display: grid;
  place-items: center;
  min-width: 21px;
  height: 21px;
  padding: 0 6px;
  border-radius: 999px;
  background: #3157d5;
  color: #ffffff;
  font-size: 10px;
}

.connectionRequestItem {
  display: grid;
  grid-template-columns: 38px minmax(0, 1fr);
  gap: 9px;
  padding: 10px 0;
  border-top: 1px solid #eef0f4;
}

.connectionRequestItem:first-of-type {
  border-top: none;
}

.connectionRequestInfo {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 2px;
}

.connectionRequestInfo > b {
  overflow: hidden;
  color: #202939;
  font-size: 11px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.connectionRequestInfo > small {
  color: #8a94a6;
  font-size: 9px;
}

.connectionRequestInfo > span {
  margin-top: 2px;
  color: #3157d5;
  font-size: 9px;
  font-weight: 700;
}

.connectionRequestActions {
  display: flex;
  gap: 6px;
  margin-top: 7px;
}

.connectionRequestActions button {
  min-height: 29px;
  padding: 0 11px;
  border-radius: 7px;
  font-size: 9px;
  font-weight: 750;
  cursor: pointer;
  transition:
    transform 0.15s ease,
    background 0.15s ease,
    border-color 0.15s ease;
}

.connectionRequestActions button:hover {
  transform: translateY(-1px);
}

.acceptRequestButton {
  border: 1px solid #3157d5;
  background: #3157d5;
  color: #ffffff;
}

.acceptRequestButton:hover {
  background: #284bc0;
}

.rejectRequestButton {
  border: 1px solid #dde2ea;
  background: #ffffff;
  color: #667085;
}

.rejectRequestButton:hover {
  border-color: #cbd2dc;
  background: #f7f8fa;
}


/* =========================================================
   CampusConnect Messenger - Friends / Requests / Sent
   ========================================================= */

.messengerPeople {
  margin: 10px 12px 8px;
  border: 1px solid #e5e9f0;
  border-radius: 14px;
  background: #ffffff;
  overflow: hidden;
}

.messengerPeopleTabs {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  padding: 5px;
  background: #f6f8fb;
  border-bottom: 1px solid #edf0f5;
}

.messengerPeopleTabs button {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  min-height: 34px;
  padding: 0 8px;
  border: 0;
  border-radius: 9px;
  background: transparent;
  color: #7b8496;
  font-size: 9px;
  font-weight: 750;
  cursor: pointer;
  transition:
    background .15s ease,
    color .15s ease,
    box-shadow .15s ease;
}

.messengerPeopleTabs button.active {
  background: #ffffff;
  color: #253b70;
  box-shadow:
    0 1px 5px rgba(25, 39, 70, .08);
}

.messengerPeopleTabs button > b {
  display: grid;
  place-items: center;
  min-width: 17px;
  height: 17px;
  padding: 0 4px;
  border-radius: 999px;
  background: #e8edf7;
  color: #53627c;
  font-size: 8px;
}

.messengerPeopleTabs button.active > b {
  background: #3157d5;
  color: #ffffff;
}

.messengerPeopleTabs .requestNotificationCount {
  background: #3157d5;
  color: #ffffff;
}

.friendDirectory,
.sentRequestDirectory {
  max-height: 245px;
  overflow-y: auto;
}

.friendRow,
.sentRequestRow {
  width: 100%;
  display: grid;
  grid-template-columns:
    38px
    minmax(0, 1fr)
    auto;
  align-items: center;
  gap: 9px;
  padding: 10px 11px;
  border: 0;
  border-bottom: 1px solid #f0f2f5;
  background: #ffffff;
  text-align: left;
}

.friendRow {
  cursor: pointer;
}

.friendRow:hover {
  background: #f8faff;
}

.friendRow:last-child,
.sentRequestRow:last-child {
  border-bottom: 0;
}

.friendAvatar {
  display: grid;
  place-items: center;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background:
    linear-gradient(
      145deg,
      #e9efff,
      #f4f7ff
    );
  color: #3157d5;
  font-size: 10px;
  font-weight: 800;
}

.friendRow > span,
.sentRequestRow > span {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 2px;
}

.friendRow > span > b,
.sentRequestRow > span > b {
  overflow: hidden;
  color: #263248;
  font-size: 10px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.friendRow > span > small,
.sentRequestRow > span > small {
  color: #8791a3;
  font-size: 8px;
}

.friendRow > span > em,
.sentRequestRow > span > em {
  color: #3157d5;
  font-size: 8px;
  font-style: normal;
  font-weight: 700;
}

.friendRow > strong {
  color: #3157d5;
  font-size: 9px;
  font-weight: 750;
}

.sentRequestRow > div:last-child {
  display: flex;
  align-items: flex-end;
  flex-direction: column;
  gap: 5px;
}

.sentRequestRow > div:last-child > strong {
  color: #b7791f;
  font-size: 8px;
  font-weight: 800;
}

.sentRequestRow > div:last-child > button {
  min-height: 25px;
  padding: 0 8px;
  border: 1px solid #e0e4eb;
  border-radius: 6px;
  background: #ffffff;
  color: #6e7789;
  font-size: 8px;
  font-weight: 700;
  cursor: pointer;
}

.sentRequestRow > div:last-child > button:hover {
  background: #f6f7f9;
}

.peopleEmpty {
  display: flex;
  align-items: center;
  flex-direction: column;
  justify-content: center;
  min-height: 100px;
  padding: 20px;
  text-align: center;
}

.peopleEmpty b {
  color: #344054;
  font-size: 10px;
}

.peopleEmpty span {
  max-width: 210px;
  margin-top: 4px;
  color: #98a2b3;
  font-size: 8px;
  line-height: 1.5;
}


/* CampusConnect Messenger presence + read receipts */

.messageMeta {
  display: inline-flex;
  align-items: center;
  justify-content: flex-end;
  gap: 4px;
  margin-left: 7px;
}

.messageTicks {
  color: #8b95a7;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: -3px;
  line-height: 1;
}

.messageTicks.read {
  color: #2f78e8;
}

.messengerConversationHeader span {
  display: inline-flex;
  align-items: center;
  gap: 5px;
}

.messengerConversationHeader span::before {
  content: "";
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #a7afbd;
}


/* =====================================================
   Messenger conversation previews + unread messages
   ===================================================== */

.conversationList > button {
  grid-template-columns:
    40px
    minmax(0, 1fr)
    auto;
}

.conversationList > button > span {
  min-width: 0;
}

.conversationList > button > span small {
  display: block;
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.conversationMeta {
  display: flex;
  align-items: flex-end;
  flex-direction: column;
  gap: 6px;
}

.conversationMeta time {
  color: #98a2b3;
  font-size: 8px;
}

.chatUnreadBadge {
  display: grid;
  place-items: center;
  min-width: 18px;
  height: 18px;
  padding: 0 5px;
  border-radius: 999px;
  background: #3157d5;
  color: #fff;
  font-size: 8px;
  font-weight: 800;
}

.deletedMessage {
  display: inline-flex !important;
  align-items: center;
  gap: 6px;
  color: #8992a3 !important;
  font-style: italic;
}

.deletedMessage i {
  font-style: normal;
  font-size: 12px;
}

.chatBubble {
  position: relative;
}

.chatMessageDelete {
  margin-top: 4px;
  padding: 0;
  border: 0;
  background: transparent;
  color: #8d96a5;
  font-size: 8px;
  font-weight: 650;
  cursor: pointer;
}

.chatMessageDelete:hover {
  color: #d14343;
}


/* =====================================================
   Messenger replies, reactions and typing
   ===================================================== */

.chatReplyQuote {
  margin-bottom: 7px;
  padding: 7px 9px;
  border-left: 3px solid #3157d5;
  border-radius: 6px;
  background: rgba(49, 87, 213, 0.07);
}

.chatReplyQuote b,
.chatReplyQuote span {
  display: block;
}

.chatReplyQuote b {
  font-size: 9px;
  color: #3157d5;
}

.chatReplyQuote span {
  margin-top: 2px;
  max-width: 260px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: #667085;
  font-size: 9px;
}

.composerReplyPreview {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 8px 16px;
  border-top: 1px solid #e6eaf0;
  background: #f8faff;
}

.composerReplyPreview div {
  min-width: 0;
}

.composerReplyPreview b,
.composerReplyPreview span {
  display: block;
}

.composerReplyPreview b {
  font-size: 9px;
  color: #3157d5;
}

.composerReplyPreview span {
  margin-top: 2px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: #667085;
  font-size: 9px;
}

.composerReplyPreview button {
  border: 0;
  background: transparent;
  cursor: pointer;
  font-size: 18px;
  color: #667085;
}

.chatMessageReply,
.chatMessageDelete {
  border: 0;
  background: transparent;
  cursor: pointer;
  font-size: 8px;
  color: #7b8494;
  margin-right: 7px;
}

.chatMessageReply:hover {
  color: #3157d5;
}

.messageReactionBar {
  display: flex;
  gap: 3px;
  margin-top: 5px;
  opacity: 0;
  transition: opacity 0.15s ease;
}

.chatBubble:hover .messageReactionBar {
  opacity: 1;
}

.messageReactionBar button {
  padding: 2px 4px;
  border: 0;
  border-radius: 6px;
  background: transparent;
  cursor: pointer;
  font-size: 11px;
}

.messageReactionBar button:hover {
  background: rgba(49, 87, 213, 0.08);
}

.messageReactions {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  margin-top: 5px;
}

.messageReactions span {
  padding: 2px 5px;
  border: 1px solid #e5e9f0;
  border-radius: 999px;
  background: #fff;
  font-size: 9px;
}


/* =====================================================
   CampusConnect Messenger - Group Information
   ===================================================== */

.groupInfoModal {
  width: min(560px, calc(100vw - 28px));
  max-height: min(820px, calc(100vh - 40px));
  overflow-y: auto;
}

.groupInfoIdentity {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 4px 0 18px;
  border-bottom: 1px solid #e8ebf0;
}

.groupInfoAvatar {
  width: 54px;
  height: 54px;
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  border-radius: 18px;
  background: #eef2ff;
  color: #3157d5;
  font-size: 16px;
  font-weight: 800;
}

.groupInfoIdentity > div:last-child {
  display: grid;
  gap: 3px;
}

.groupInfoIdentity b {
  color: #182230;
  font-size: 15px;
}

.groupInfoIdentity span {
  color: #7d8796;
  font-size: 10px;
}

.groupInfoEdit {
  display: grid;
  gap: 12px;
  padding: 18px 0;
  border-bottom: 1px solid #e8ebf0;
}

.groupInfoEdit label {
  display: grid;
  gap: 6px;
  color: #596274;
  font-size: 9px;
  font-weight: 700;
}

.groupInfoEdit input,
.groupInfoEdit textarea,
.groupAddMember input {
  width: 100%;
  border: 1px solid #dfe4eb;
  border-radius: 10px;
  background: #fff;
  color: #182230;
  outline: none;
}

.groupInfoEdit input,
.groupAddMember input {
  min-height: 39px;
  padding: 0 11px;
}

.groupInfoEdit textarea {
  min-height: 82px;
  padding: 10px 11px;
  resize: vertical;
}

.groupInfoEdit input:focus,
.groupInfoEdit textarea:focus,
.groupAddMember input:focus {
  border-color: #3157d5;
  box-shadow: 0 0 0 3px rgba(49, 87, 213, 0.08);
}

.groupInfoDescription {
  padding: 15px 0;
  color: #667085;
  line-height: 1.55;
  font-size: 10px;
}

.groupAddMember {
  display: grid;
  gap: 9px;
  padding: 18px 0;
  border-bottom: 1px solid #e8ebf0;
}

.groupAddMember > span,
.groupMemberHeading > span {
  color: #8d96a5;
  font-size: 8px;
  font-weight: 800;
  letter-spacing: .08em;
}

.groupInfoSearchResults {
  display: grid;
  gap: 5px;
  max-height: 220px;
  overflow-y: auto;
}

.groupInfoPerson,
.groupMemberRow {
  display: flex;
  align-items: center;
  gap: 10px;
}

.groupInfoPerson {
  padding: 9px;
  border: 1px solid #eaedf2;
  border-radius: 11px;
  background: #fff;
}

.groupInfoPerson > i,
.groupMemberRow > i {
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  border-radius: 50%;
  background: #eef2ff;
  color: #3157d5;
  font-size: 9px;
  font-style: normal;
  font-weight: 800;
}

.groupInfoPerson > span,
.groupMemberRow > span {
  min-width: 0;
  display: grid;
  gap: 2px;
  flex: 1;
}

.groupInfoPerson b,
.groupMemberRow b {
  overflow: hidden;
  color: #202938;
  font-size: 10px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.groupInfoPerson small,
.groupMemberRow small {
  color: #8a94a3;
  font-size: 8px;
}

.groupInfoPerson > button {
  min-height: 30px;
  padding: 0 11px;
  border: 1px solid #dce3ee;
  border-radius: 8px;
  background: #fff;
  color: #3157d5;
  cursor: pointer;
  font-size: 9px;
  font-weight: 750;
}

.groupMemberSection {
  padding: 18px 0;
}

.groupMemberHeading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 9px;
}

.groupMemberHeading > b {
  color: #667085;
  font-size: 9px;
}

.groupMemberList {
  display: grid;
  gap: 4px;
}

.groupMemberRow {
  min-height: 52px;
  padding: 8px 2px;
  border-bottom: 1px solid #f0f2f5;
}

.groupMemberRow > em {
  padding: 4px 7px;
  border-radius: 999px;
  background: #f0f4ff;
  color: #3157d5;
  font-size: 7px;
  font-style: normal;
  font-weight: 750;
}

.groupMemberActions {
  display: flex;
  gap: 5px;
}

.groupMemberActions button {
  min-height: 29px;
  padding: 0 8px;
  border: 1px solid #dde3ec;
  border-radius: 7px;
  background: #fff;
  color: #596274;
  cursor: pointer;
  font-size: 8px;
  font-weight: 700;
}

.groupMemberActions button:hover {
  border-color: #3157d5;
  color: #3157d5;
}

.groupMemberActions button.danger:hover {
  border-color: #e0aaaa;
  background: #fff6f6;
  color: #c43c3c;
}

.leaveGroupButton {
  width: 100%;
  min-height: 40px;
  margin-top: 5px;
  border: 1px solid #edcccc;
  border-radius: 10px;
  background: #fff8f8;
  color: #c33d3d;
  cursor: pointer;
  font-size: 10px;
  font-weight: 750;
}

.leaveGroupButton:hover {
  background: #fff1f1;
}

@media (max-width: 640px) {
  .groupMemberRow {
    align-items: flex-start;
    flex-wrap: wrap;
  }

  .groupMemberActions {
    width: 100%;
    padding-left: 44px;
  }
}


/* =====================================================
   Messenger - group creation fixes
   ===================================================== */

.selectedGroupMembers {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 38px;
  margin: 4px 0 8px;
  padding: 0 11px;
  border: 1px solid #e2e7ef;
  border-radius: 10px;
  background: #f8faff;
}

.selectedGroupMembers span {
  color: #667085;
  font-size: 9px;
  font-weight: 650;
}

.selectedGroupMembers b {
  display: grid;
  place-items: center;
  min-width: 22px;
  height: 22px;
  padding: 0 6px;
  border-radius: 999px;
  background: #3157d5;
  color: #fff;
  font-size: 8px;
}

.createGroupButton:disabled {
  cursor: not-allowed;
  opacity: .55;
}


.groupSelectionSummary {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 38px;
  margin: 8px 0;
  padding: 0 12px;
  border: 1px solid #e3e8ef;
  border-radius: 10px;
  background: #f8faff;
}

.groupSelectionSummary span {
  color: #667085;
  font-size: 10px;
  font-weight: 650;
}

.groupSelectionSummary b {
  display: grid;
  place-items: center;
  min-width: 24px;
  height: 24px;
  padding: 0 7px;
  border-radius: 999px;
  background: #3157d5;
  color: #fff;
  font-size: 9px;
}

.createGroupButton:disabled {
  cursor: not-allowed;
  opacity: .5;
}


/* =====================================================
   GROUP MEMBER SELECTION
   ===================================================== */

.selectedGroupUserList {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin: 8px 0 12px;
}

.selectedGroupUser {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 7px 9px;
  border: 1px solid #e1e7f0;
  border-radius: 12px;
  background: #fff;
}

.selectedGroupAvatar {
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: #eef3ff;
  color: #3157d5;
  font-size: 9px;
  font-weight: 800;
}

.selectedGroupUser > div:nth-child(2) {
  display: flex;
  flex-direction: column;
}

.selectedGroupUser b {
  font-size: 10px;
  color: #172033;
}

.selectedGroupUser small {
  margin-top: 2px;
  font-size: 8px;
  color: #7b8497;
}

.selectedGroupUser button {
  width: 22px;
  height: 22px;
  border: 0;
  border-radius: 50%;
  background: #f1f3f7;
  cursor: pointer;
  color: #667085;
}

.groupUserResults {
  max-height: 220px;
  overflow-y: auto;
}

.groupUserResults > button {
  width: 100%;
  cursor: pointer;
}

.groupUserResults > button.selected {
  border-color: #3157d5;
  background: #f1f5ff;
}


.groupDangerZone {
  display: grid;
  gap: 8px;
  margin-top: 14px;
  padding-top: 14px;
  border-top: 1px solid #eaecf0;
}

.deleteGroupButton {
  min-height: 42px;
  border: 1px solid #f3c4c4;
  border-radius: 10px;
  background: #fff7f7;
  color: #b42318;
  font-weight: 700;
  cursor: pointer;
}

.deleteGroupButton:hover {
  background: #fff0f0;
}

.deleteGroupButton:disabled,
.leaveGroupButton:disabled {
  cursor: not-allowed;
  opacity: .55;
}

.groupInfoAvatar,
.conversationAvatar {
  overflow: hidden;
}

.groupInfoAvatar img,
.conversationAvatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.groupAvatarControls {
  display: flex;
  align-items: end;
  gap: 10px;
  padding: 12px 0;
}

.groupAvatarControls label {
  flex: 1;
  display: grid;
  gap: 6px;
}

.groupAvatarControls label span {
  font-size: 11px;
  font-weight: 700;
}

.groupInfoTabs {
  display: flex;
  gap: 6px;
  margin: 16px 0 12px;
  padding: 4px;
  background: #f4f6fa;
  border-radius: 12px;
}

.groupInfoTabs button {
  flex: 1;
  min-height: 36px;
  border: 0;
  border-radius: 9px;
  background: transparent;
  cursor: pointer;
  font-size: 11px;
  font-weight: 700;
  color: #667085;
}

.groupInfoTabs button.active {
  background: #fff;
  color: #3157d5;
  box-shadow: 0 1px 4px rgba(0,0,0,.06);
}

.sharedContentGrid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.sharedMediaItem {
  min-height: 90px;
  border: 1px solid #e5e9f1;
  border-radius: 12px;
  background: #f8faff;
  cursor: pointer;
  display: grid;
  place-items: center;
  gap: 4px;
}

.sharedMediaItem span {
  font-size: 18px;
}

.sharedMediaItem b {
  width: 100%;
  padding: 0 8px 8px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 10px;
}

.sharedDocumentList {
  display: grid;
  gap: 8px;
}

.sharedDocumentList > button {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  padding: 10px;
  border: 1px solid #e5e9f1;
  border-radius: 11px;
  background: #fff;
  cursor: pointer;
  text-align: left;
}

.sharedDocumentList i {
  font-size: 9px;
  font-style: normal;
  font-weight: 800;
}

.sharedDocumentList span {
  flex: 1;
  display: grid;
  gap: 2px;
}

.sharedDocumentList small {
  color: #8b93a4;
}

.sharedDocumentList em {
  font-size: 10px;
  font-style: normal;
  color: #3157d5;
}

.sharedLinkList {
  display: grid;
  gap: 8px;
}

.sharedLinkList a {
  display: grid;
  gap: 4px;
  padding: 10px;
  border: 1px solid #e5e9f1;
  border-radius: 10px;
  text-decoration: none;
  background: #fff;
}

.sharedLinkList span {
  color: #8b93a4;
  font-size: 9px;
}

.sharedLinkList b {
  color: #3157d5;
  font-size: 10px;
  word-break: break-all;
}

.groupSharedEmpty {
  padding: 28px 12px;
  text-align: center;
  color: #8b93a4;
  font-size: 11px;
}

@media (max-width: 700px) {
  .sharedContentGrid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

/* =========================================================
   CAMPUSCONNECT — PROFESSIONAL PROFILE
========================================================= */

.professionalProfile {
  display: grid;
  gap: 18px;
  animation: profileEnter .28s ease both;
}

@keyframes profileEnter {
  from {
    opacity: 0;
    transform: translateY(5px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}


/* HERO */

.professionalProfileHero {
  position: relative;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 30px;
  min-height: 190px;
  padding: 30px 32px;
  border: 1px solid #dfe5ef;
  border-radius: 18px;
  background:
    radial-gradient(
      circle at 92% 5%,
      rgba(49,89,217,.10),
      transparent 29%
    ),
    linear-gradient(
      135deg,
      #ffffff 0%,
      #f8faff 62%,
      #f2f6ff 100%
    );
  box-shadow: 0 16px 42px rgba(24,39,75,.07);
}

.professionalProfileHero::after {
  content: "";
  position: absolute;
  right: -95px;
  bottom: -145px;
  width: 280px;
  height: 280px;
  border: 1px solid rgba(49,89,217,.08);
  border-radius: 50%;
  box-shadow:
    0 0 0 45px rgba(49,89,217,.025),
    0 0 0 90px rgba(49,89,217,.014);
}

.profileHeroIdentity,
.profileHeroRight {
  position: relative;
  z-index: 1;
}

.profileHeroIdentity {
  display: flex;
  align-items: center;
  gap: 20px;
  min-width: 0;
}

.profileAvatarLarge {
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  width: 82px;
  height: 82px;
  border: 5px solid #fff;
  border-radius: 23px;
  background:
    linear-gradient(
      145deg,
      #1d3474,
      #3159d9
    );
  color: #fff;
  font-size: 23px;
  font-weight: 850;
  letter-spacing: -.03em;
  box-shadow:
    0 13px 30px rgba(49,89,217,.22);
}

.profileHeroContent {
  min-width: 0;
}

.profileRoleLine {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 7px;
}

.profileVerifiedBadge,
.profileRoleBadge {
  display: inline-flex;
  align-items: center;
  min-height: 25px;
  padding: 0 9px;
  border-radius: 999px;
  font-size: 8px;
  font-weight: 800;
}

.profileVerifiedBadge {
  border: 1px solid #cfeadd;
  background: #edf9f3;
  color: #14734f;
}

.profileRoleBadge {
  border: 1px solid #dce4fb;
  background: #edf2ff;
  color: #3159d9;
}

.profileHeroContent h2 {
  margin: 11px 0 4px;
  color: #17243a;
  font-size: clamp(24px, 3vw, 31px);
  line-height: 1.08;
  letter-spacing: -.04em;
}

.profileHeroContent > p {
  overflow: hidden;
  margin: 0;
  color: #68758a;
  font-size: 10px;
  text-overflow: ellipsis;
}

.profileMetaLine {
  display: flex;
  align-items: center;
  gap: 9px;
  margin-top: 12px;
  color: #4c5b72;
  font-size: 9px;
  font-weight: 700;
}

.profileMetaLine i {
  width: 3px;
  height: 3px;
  border-radius: 50%;
  background: #9da8b8;
}

.profileHeroRight {
  display: flex;
  align-items: center;
  gap: 14px;
}

.profileCompletionBlock {
  width: 210px;
  padding: 17px;
  border: 1px solid #e2e7ef;
  border-radius: 14px;
  background: rgba(255,255,255,.82);
  box-shadow: 0 8px 24px rgba(30,44,72,.05);
  backdrop-filter: blur(8px);
}

.profileCompletionBlock > span {
  color: #7f8b9d;
  font-size: 7px;
  font-weight: 850;
  letter-spacing: .12em;
}

.profileCompletionBlock > div:nth-child(2) {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
  margin-top: 7px;
}

.profileCompletionBlock strong {
  color: #17243a;
  font-size: 25px;
  letter-spacing: -.04em;
}

.profileCompletionBlock small {
  color: #748095;
  font-size: 8px;
}

.profileCompletionBar {
  overflow: hidden;
  height: 6px;
  margin-top: 11px;
  border-radius: 999px;
  background: #e8edf5;
}

.profileCompletionBar span {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: #3159d9;
  transition: width .35s ease;
}

.professionalProfileEdit {
  min-height: 41px;
  padding: 0 17px;
}


/* MAIN */

.profileMainGrid {
  display: grid;
  grid-template-columns:
    minmax(0, 1.45fr)
    minmax(285px, .55fr);
  gap: 18px;
  align-items: start;
}

.profileMainColumn,
.profileSideColumn {
  display: grid;
  gap: 18px;
}

.professionalProfileCard {
  padding: 22px;
  border: 1px solid #e3e8f0;
  border-radius: 17px;
  background: #fff;
  box-shadow:
    0 9px 28px rgba(31,47,78,.045);
}

.profileSectionHeader {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 20px;
}

.profileSectionHeader.compact {
  margin-bottom: 14px;
}

.profileSectionHeader > div > span {
  display: block;
  color: #3159d9;
  font-size: 7px;
  font-weight: 850;
  letter-spacing: .13em;
}

.profileSectionHeader h3 {
  margin: 6px 0 4px;
  color: #1b2940;
  font-size: 16px;
  letter-spacing: -.02em;
}

.profileSectionHeader p {
  margin: 0;
  color: #7b8799;
  font-size: 9px;
  line-height: 1.55;
}

.profileSecurityMark {
  display: grid;
  place-items: center;
  width: 35px;
  height: 35px;
  border-radius: 10px;
  background: #edf9f3;
  color: #16805a;
  font-size: 13px;
  font-weight: 900;
}

.profileInfoGrid {
  display: grid;
  grid-template-columns:
    repeat(2, minmax(0, 1fr));
  border-top: 1px solid #edf0f5;
  border-left: 1px solid #edf0f5;
  border-radius: 12px;
  overflow: hidden;
}

.profileInfoItem {
  min-height: 79px;
  padding: 15px 16px;
  border-right: 1px solid #edf0f5;
  border-bottom: 1px solid #edf0f5;
  background: #fcfdff;
}

.profileInfoItem small {
  display: block;
  color: #8c97a8;
  font-size: 7px;
  font-weight: 750;
  letter-spacing: .07em;
  text-transform: uppercase;
}

.profileInfoItem strong {
  display: block;
  overflow: hidden;
  margin-top: 7px;
  color: #27364d;
  font-size: 10px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.profileBioSection {
  margin-top: 17px;
  padding: 16px;
  border: 1px solid #e8ecf2;
  border-radius: 12px;
  background: #fafbfe;
}

.profileBioSection small {
  color: #3159d9;
  font-size: 7px;
  font-weight: 850;
  letter-spacing: .12em;
}

.profileBioSection p {
  margin: 8px 0 0;
  color: #5f6d81;
  font-size: 10px;
  line-height: 1.7;
}


/* EDIT */

.profileEditPanel {
  border-color: #dce4f6;
}

.profileEditGrid {
  display: grid;
  grid-template-columns:
    1fr 1fr;
  gap: 13px;
}

.profileEditPanel .moduleField {
  margin-bottom: 13px;
}

.profileEditPanel
.moduleField input,
.profileEditPanel
.moduleField textarea {
  width: 100%;
  border: 1px solid #dfe5ee;
  border-radius: 10px;
  background: #fbfcfe;
  outline: 0;
}

.profileEditPanel
.moduleField input:focus,
.profileEditPanel
.moduleField textarea:focus {
  border-color: #3159d9;
  box-shadow:
    0 0 0 3px rgba(49,89,217,.08);
}

.profileEditActions {
  display: flex;
  justify-content: flex-end;
  gap: 9px;
  padding-top: 4px;
}

.profileEditActions button {
  min-height: 39px;
  padding: 0 16px;
}


/* SKILLS */

.profileCountBadge {
  display: grid;
  place-items: center;
  min-width: 29px;
  height: 29px;
  border-radius: 8px;
  background: #edf2ff;
  color: #3159d9;
  font-size: 9px;
}

.profileSkillCloud {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.profileSkillCloud span {
  display: inline-flex;
  align-items: center;
  min-height: 31px;
  padding: 0 11px;
  border: 1px solid #dce4f5;
  border-radius: 9px;
  background: #f6f8ff;
  color: #385181;
  font-size: 9px;
  font-weight: 750;
}

.profileSkillsEmpty {
  display: flex;
  align-items: center;
  gap: 12px;
  min-height: 86px;
  padding: 14px;
  border: 1px dashed #d7deea;
  border-radius: 12px;
  background: #fafbfc;
}

.profileSkillsEmpty > i {
  display: grid;
  place-items: center;
  width: 36px;
  height: 36px;
  border-radius: 10px;
  background: #edf2ff;
  color: #3159d9;
  font-style: normal;
  font-size: 16px;
}

.profileSkillsEmpty > div {
  flex: 1;
}

.profileSkillsEmpty strong,
.profileSkillsEmpty span {
  display: block;
}

.profileSkillsEmpty strong {
  color: #26354b;
  font-size: 10px;
}

.profileSkillsEmpty span {
  margin-top: 4px;
  color: #8590a1;
  font-size: 8px;
}

.profileSkillsEmpty button {
  border: 0;
  background: transparent;
  color: #3159d9;
  font-size: 8px;
  font-weight: 850;
}


/* UID CARD */

.campusUidCard {
  position: relative;
  overflow: hidden;
  background:
    linear-gradient(
      145deg,
      #172748,
      #27478f
    );
  color: #fff;
  border: 0;
}

.campusUidCard::after {
  content: "";
  position: absolute;
  right: -48px;
  bottom: -65px;
  width: 150px;
  height: 150px;
  border: 1px solid rgba(255,255,255,.14);
  border-radius: 50%;
  box-shadow:
    0 0 0 28px rgba(255,255,255,.035);
}

.uidCardIcon {
  position: relative;
  z-index: 1;
  display: grid;
  place-items: center;
  width: 40px;
  height: 40px;
  margin-bottom: 23px;
  border: 1px solid rgba(255,255,255,.15);
  border-radius: 11px;
  background: rgba(255,255,255,.1);
  font-size: 11px;
  font-weight: 900;
}

.campusUidCard > span,
.campusUidCard h3,
.campusUidCard p,
.campusUidCard button {
  position: relative;
  z-index: 1;
}

.campusUidCard > span {
  color: #bfcdf0;
  font-size: 7px;
  font-weight: 850;
  letter-spacing: .13em;
}

.campusUidCard h3 {
  margin: 8px 0 9px;
  color: #fff;
  font-family:
    ui-monospace,
    SFMono-Regular,
    Menlo,
    monospace;
  font-size: 20px;
  letter-spacing: .035em;
}

.campusUidCard p {
  margin: 0;
  color: #d2dcf4;
  font-size: 9px;
  line-height: 1.65;
}

.campusUidCard button {
  width: 100%;
  min-height: 38px;
  margin-top: 19px;
  border: 1px solid rgba(255,255,255,.18);
  border-radius: 9px;
  background: rgba(255,255,255,.10);
  color: #fff;
  font-size: 9px;
  font-weight: 800;
}

.campusUidCard button:hover {
  background: rgba(255,255,255,.17);
}


/* ACCOUNT STATUS */

.accountStatusRows {
  display: grid;
}

.accountStatusRows > div {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 0;
  border-top: 1px solid #edf0f4;
}

.accountStatusRows > div:first-child {
  border-top: 0;
}

.accountStatusRows > div > i {
  display: block;
  flex: 0 0 auto;
  width: 8px;
