  overflow: hidden;
  cursor: pointer;
}

.professionalFilePicker input {
  position: absolute;
  width: 1px;
  height: 1px;
  opacity: 0;
}

.professionalFilePicker > span {
  display: flex;
  align-items: center;
  gap: 11px;
  height: 48px;
  padding: 0 13px;
  border: 1px dashed #cfd7e5;
  border-radius: 10px;
