.professionalFilePicker > span > i {
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  width: 29px;
  height: 29px;
  border-radius: 8px;
  background: #eaf0ff;
  color: #3159d9;
  font-style: normal;
  font-weight: 900;
}

.professionalFilePicker b,
.professionalFilePicker small {
  display: block;
}

.professionalFilePicker b {
  overflow: hidden;
  max-width: 420px;
  color: #35435a;
  font-size: 9px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.professionalFilePicker small {
  margin-top: 3px;
  color: #8b95a5;
  font-size: 7px;
}

.professionalUploadRow > button {
  min-height: 48px;
}

.professionalDocumentList {
  display: grid;
}

.professionalDocumentRow {
  display: grid;
