.documentFileIcon {
  display: grid;
  place-items: center;
  width: 40px;
  height: 40px;
  border-radius: 10px;
  background: #edf2ff;
  color: #3159d9;
  font-size: 8px;
  font-weight: 900;
}

.documentFileInfo {
  min-width: 0;
}

.documentFileInfo strong,
.documentFileInfo span {
  display: block;
}

.documentFileInfo strong {
  overflow: hidden;
  color: #2c3a50;
  font-size: 10px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.documentFileInfo span {
  margin-top: 5px;
  color: #8994a5;
  font-size: 8px;
}

.documentActions {
  display: flex;
  gap: 7px;
}

.documentActions button {
  min-height: 31px;
  padding: 0 10px;
  border: 1px solid #dfe5ee;
  border-radius: 8px;
  background: #fff;
  color: #526177;
  font-size: 8px;
  font-weight: 800;
}

.documentActions button:hover {
  border-color: #3159d9;
  color: #3159d9;
}

.documentActions button.danger:hover {
  border-color: #e7bfc3;
  background: #fff6f7;
  color: #bd3d49;
}

.professionalDocumentEmpty {
  display: grid;
