}

.professionalDocumentEmpty > div {
  display: grid;
  place-items: center;
  width: 43px;
  height: 43px;
  border-radius: 12px;
  background: #edf2ff;
  color: #3159d9;
  font-size: 13px;
}

.professionalDocumentEmpty h4 {
  margin: 12px 0 5px;
  color: #2b394f;
  font-size: 11px;
}

.professionalDocumentEmpty p {
  max-width: 410px;
  margin: 0;
  color: #8691a2;
  font-size: 8px;
