/* =========================================================
   PUBLIC PROFILE PREVIEW
========================================================= */

.publicProfileModalScrim {
  position: fixed;
  z-index: 9999;
  inset: 0;
  display: grid;
  place-items: center;
  padding: 28px;
  background: rgba(14,23,40,.62);
  backdrop-filter: blur(7px);
  animation: publicProfileFade .18s ease;
}

@keyframes publicProfileFade {
  from {
    opacity: 0;
  }

  to {
    opacity: 1;
  }
}

.publicProfileModal {
  position: relative;
  overflow: hidden;
  width: min(100%, 650px);
  max-height: calc(100vh - 56px);
  border: 1px solid rgba(255,255,255,.18);
  border-radius: 22px;
  background: #fff;
  box-shadow:
    0 34px 90px rgba(5,15,35,.30);
  overflow-y: auto;
  animation: publicProfileOpen .22s ease;
}

@keyframes publicProfileOpen {
  from {
    opacity: 0;
    transform: translateY(12px) scale(.985);
  }

  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

.publicProfileClose {
  position: absolute;
  z-index: 5;
  top: 13px;
  right: 13px;
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  border: 1px solid rgba(255,255,255,.2);
  border-radius: 50%;
  background: rgba(10,20,40,.45);
  color: #fff;
  cursor: pointer;
  font-size: 17px;
  backdrop-filter: blur(8px);
}

.publicProfileCover {
  height: 175px;
  background:
    radial-gradient(
      circle at 85% 10%,
      rgba(92,126,255,.45),
      transparent 35%
    ),
    linear-gradient(
      135deg,
      #17294f,
      #3159d9
    );
}

.publicProfileCover.hasImage {
  background-position: center;
  background-size: cover;
}

.publicProfileBody {
  position: relative;
  padding: 0 30px 30px;
}

.publicProfileTop {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  min-height: 54px;
}

.publicProfileAvatar {
  display: grid;
  place-items: center;
  overflow: hidden;
  width: 94px;
  height: 94px;
  margin-top: -48px;
