}

/* CAMPUSCONNECT MESSENGER UI FIX START */

/* =========================================================
   MAIN MESSENGER FRAME
========================================================= */

.campusMessenger {
  display: grid;
  grid-template-columns: minmax(300px, 360px) minmax(0, 1fr);
  width: 100%;
  height: calc(100vh - 250px);
  min-height: 620px;
  max-height: 860px;
  overflow: hidden;
  border: 1px solid #e5e7eb;
  border-radius: 22px;
  background: #ffffff;
}


/* =========================================================
   LEFT SIDEBAR
========================================================= */

.campusMessenger .messengerSidebar {
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
  border-right: 1px solid #e7eaf0;
  background: #ffffff;
}

.campusMessenger .conversationList {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  overflow-x: hidden;
}

.campusMessenger .conversationList > button {
  width: 100%;
  min-height: 74px;
}

.campusMessenger .conversationList > button.active {
  background: #eef4ff;
}


/* =========================================================
   RIGHT CONVERSATION AREA
========================================================= */

.campusMessenger .messengerConversation {
  position: relative;
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
  background: #f7f8fb;
}


/* =========================================================
   CONVERSATION HEADER
========================================================= */

.campusMessenger .messengerConversationHeader {
  position: relative;
  z-index: 20;
  display: flex;
  align-items: center;
  gap: 12px;
  min-height: 72px;
  padding: 10px 18px;
  flex: 0 0 auto;
  border-bottom: 1px solid #e5e8ee;
  background: rgba(255, 255, 255, 0.98);
}

.campusMessenger .messengerConversationHeader > div:nth-child(2) {
  min-width: 0;
  flex: 1;
}

.campusMessenger .messengerConversationHeader h3 {
  margin: 0;
  overflow: hidden;
  color: #172033;
  font-size: 15px;
  font-weight: 750;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.campusMessenger .conversationPresence {
  display: block;
  margin-top: 3px;
  color: #778196;
  font-size: 11px;
}


/* =========================================================
   MESSAGE SCROLL AREA
========================================================= */

.campusMessenger .messageArea {
  position: relative;
  display: flex;
  flex: 1 1 auto;
  flex-direction: column;
  gap: 4px;
  min-height: 0;
  overflow-y: auto;
  overflow-x: hidden;
  padding: 24px 28px 30px;
  scroll-behavior: smooth;
}


/* =========================================================
   MESSAGE ROW
========================================================= */

.campusMessenger .chatMessageRow {
  display: flex;
  width: 100%;
  padding: 2px 0;
  justify-content: flex-start;
}

.campusMessenger .chatMessageRow.mine {
  justify-content: flex-end;
}


/* =========================================================
   MESSAGE BUBBLE
========================================================= */

.campusMessenger .chatBubble {
  position: relative;
  display: inline-flex;
  flex-direction: column;
  align-items: flex-start;
  width: fit-content;
  min-width: 76px;
  max-width: min(620px, 68%);
  min-height: 0 !important;
  height: auto !important;
  margin: 0 !important;
  padding: 10px 12px 7px;
  border: 1px solid #e3e7ed;
  border-radius: 15px 15px 15px 5px;
  background: #ffffff;
  box-shadow: 0 1px 2px rgba(16, 24, 40, 0.04);
}

.campusMessenger .chatMessageRow.mine .chatBubble {
  align-items: flex-end;
  border-color: #d8e3f7;
  border-radius: 15px 15px 5px 15px;
  background: #eaf1ff;
}

.campusMessenger .chatBubble > p {
  width: auto;
  max-width: 100%;
  margin: 0;
  color: #283246;
  font-size: 13px;
  line-height: 1.45;
  overflow-wrap: anywhere;
  white-space: pre-wrap;
}

.campusMessenger .chatBubble > strong {
  display: block;
  margin-bottom: 5px;
  color: #335ca8;
  font-size: 11px;
}


/* =========================================================
   TIME + DELIVERY STATUS
========================================================= */

.campusMessenger .chatBubble > time {
  align-self: flex-end;
  margin-top: 5px;
  color: #8b94a5;
  font-size: 9px;
  line-height: 1;
}

.campusMessenger .chatMessageStatus {
  position: absolute;
  right: 8px;
  bottom: 6px;
  margin: 0;
  color: #8993a4;
  font-size: 11px;
  font-weight: 700;
}

.campusMessenger .chatBubble:has(.chatMessageStatus) > time {
  margin-right: 22px;
}

.campusMessenger .chatMessageStatus.read {
  color: #3677d9;
}


/* =========================================================
   ATTACHMENTS
========================================================= */

.campusMessenger .chatAttachment {
  display: flex;
  align-items: center;
  gap: 10px;
  width: min(100%, 360px);
  min-width: 230px;
  margin: 3px 0 2px;
  padding: 10px;
  border: 1px solid rgba(100, 116, 139, 0.18);
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.8);
  text-align: left;
}

.campusMessenger .chatAttachment > i {
  display: grid;
  flex: 0 0 40px;
  width: 40px;
  height: 40px;
  place-items: center;
  border-radius: 10px;
  background: #f1f5ff;
  color: #3568c8;
  font-size: 9px;
  font-style: normal;
  font-weight: 800;
}

.campusMessenger .chatAttachment > span {
  display: grid;
  min-width: 0;
  gap: 2px;
}

.campusMessenger .chatAttachment b {
  overflow: hidden;
  max-width: 270px;
  color: #29364c;
  font-size: 11px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.campusMessenger .chatAttachment small {
  color: #8a93a3;
  font-size: 9px;
}


/* =========================================================
   REPLY QUOTE
========================================================= */

.campusMessenger .chatReplyQuote {
  width: 100%;
  margin-bottom: 7px;
  padding: 7px 9px;
  border-left: 3px solid #6f92cf;
  border-radius: 7px;
  background: rgba(255, 255, 255, 0.58);
}

.campusMessenger .chatReplyQuote b,
.campusMessenger .chatReplyQuote span {
  display: block;
}

.campusMessenger .chatReplyQuote b {
  margin-bottom: 2px;
  font-size: 10px;
}

.campusMessenger .chatReplyQuote span {
  overflow: hidden;
  color: #697386;
  font-size: 10px;
  text-overflow: ellipsis;
  white-space: nowrap;
}


/* =========================================================
   MESSAGE ACTIONS
   Keep conversation clean until user hovers a message.
========================================================= */

.campusMessenger .chatMessageReply,
.campusMessenger .chatMessageDelete,
.campusMessenger .messageReactionBar {
  opacity: 0;
  pointer-events: none;
  transition: opacity 120ms ease;
}

.campusMessenger .chatBubble:hover .chatMessageReply,
.campusMessenger .chatBubble:hover .chatMessageDelete,
.campusMessenger .chatBubble:hover .messageReactionBar {
  opacity: 1;
  pointer-events: auto;
}

.campusMessenger .chatMessageReply,
.campusMessenger .chatMessageDelete {
  margin-top: 6px;
  padding: 0;
  border: 0;
  background: transparent;
  font-size: 9px;
  cursor: pointer;
}

.campusMessenger .chatMessageReply {
  color: #637087;
}

.campusMessenger .chatMessageDelete {
  color: #a94a43;
}

.campusMessenger .messageReactionBar {
  display: flex;
  gap: 3px;
  margin-top: 6px;
}

.campusMessenger .messageReactionBar button {
  display: grid;
  width: 25px;
  height: 25px;
  padding: 0;
  place-items: center;
  border: 1px solid #e7eaf0;
  border-radius: 8px;
  background: #ffffff;
  cursor: pointer;
  font-size: 13px;
}


/* =========================================================
   EXISTING REACTIONS
========================================================= */

.campusMessenger .messageReactions {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  margin-top: 5px;
}

.campusMessenger .messageReactions span {
  padding: 3px 7px;
  border: 1px solid #e2e7ef;
  border-radius: 999px;
  background: #ffffff;
  color: #566176;
  font-size: 10px;
}


/* =========================================================
   DELETED MESSAGE
========================================================= */

.campusMessenger .deletedMessage {
  display: flex;
  align-items: center;
  gap: 5px;
  color: #8c95a4 !important;
  font-style: italic;
}


/* =========================================================
   FILE + REPLY PREVIEW
========================================================= */

.campusMessenger .chatFilePreview,
.campusMessenger .composerReplyPreview {
  flex: 0 0 auto;
  margin: 0;
  padding: 8px 18px;
  border-top: 1px solid #e7eaf0;
  background: #ffffff;
}


/* =========================================================
   MESSAGE COMPOSER
========================================================= */

.campusMessenger .messageComposerBar {
  position: relative;
  z-index: 15;
  display: flex;
  flex: 0 0 auto;
  align-items: center;
  gap: 9px;
  width: 100%;
  margin: 0;
  padding: 12px 16px;
  border-top: 1px solid #e2e6ec;
  background: #ffffff;
}

.campusMessenger .messageComposerBar > input {
  flex: 1;
  min-width: 0;
  height: 42px;
  padding: 0 15px;
  border: 1px solid #dde3eb;
  border-radius: 13px;
  outline: none;
  background: #f7f9fc;
  color: #202a3c;
  font-size: 13px;
}

.campusMessenger .messageComposerBar > input:focus {
  border-color: #9bb6df;
  background: #ffffff;
}

.campusMessenger .chatAttachButton {
  display: grid;
  flex: 0 0 42px;
  width: 42px;
  height: 42px;
  place-items: center;
  border: 1px solid #dfe5ed;
  border-radius: 12px;
  background: #ffffff;
  color: #526178;
  cursor: pointer;
  font-size: 20px;
}

.campusMessenger .messageComposerBar > button[type="submit"] {
  flex: 0 0 auto;
  min-width: 76px;
  height: 42px;
  padding: 0 17px;
  border: 0;
  border-radius: 12px;
  background: #244d91;
  color: #ffffff;
  font-size: 12px;
  font-weight: 750;
  cursor: pointer;
}

.campusMessenger .messageComposerBar > button[type="submit"]:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}


/* =========================================================
   AVATARS
========================================================= */

.campusMessenger .messengerUserAvatar,
.campusMessenger .conversationAvatar,
.campusMessenger .friendAvatar {
  overflow: hidden;
}

.campusMessenger .messengerUserAvatar img,
.campusMessenger .conversationAvatar img,
.campusMessenger .friendAvatar img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}


/* =========================================================
   EMPTY CONVERSATION
========================================================= */

.campusMessenger .messengerWelcome {
  display: grid;
  flex: 1;
  place-content: center;
  justify-items: center;
  padding: 40px;
  text-align: center;
}


/* =========================================================
   RESPONSIVE
========================================================= */

@media (max-width: 900px) {
  .campusMessenger {
    grid-template-columns: 290px minmax(0, 1fr);
    height: calc(100vh - 190px);
  }

  .campusMessenger .messageArea {
    padding: 18px 16px 24px;
  }

  .campusMessenger .chatBubble {
    max-width: 78%;
  }
}

@media (max-width: 680px) {
  .campusMessenger {
    grid-template-columns: 1fr;
    min-height: 650px;
  }

  .campusMessenger .messengerSidebar {
    display: none;
  }

  .campusMessenger .chatBubble {
    max-width: 86%;
  }
}

/* CAMPUSCONNECT MESSENGER UI FIX END */

/* =========================================================
   CAMPUS HUB — PROFESSIONAL UI V2
========================================================= */

.campusHub {
  display: grid;
  gap: 22px;
  width: 100%;
  padding-bottom: 36px;
}

/* HERO */

.campusHubHero {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1.45fr) minmax(300px, .65fr);
  gap: 36px;
  overflow: hidden;
  padding: 42px;
  border: 1px solid #e7ded3;
  border-radius: 28px;
  background:
    radial-gradient(circle at 88% 15%, rgba(194, 152, 102, .18), transparent 30%),
    radial-gradient(circle at 7% 92%, rgba(54, 70, 102, .08), transparent 28%),
    linear-gradient(135deg, #fffaf4 0%, #f5eee5 55%, #eee4d8 100%);
  box-shadow: 0 18px 50px rgba(41, 49, 66, .08);
}

.campusHubHero::after {
  content: "";
  position: absolute;
  width: 260px;
  height: 260px;
  right: -85px;
  bottom: -115px;
  border: 1px solid rgba(128, 90, 50, .14);
  border-radius: 50%;
}

.campusHubHero > div:first-child {
  position: relative;
  z-index: 2;
}

.campusHubEyebrow {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 6px 10px;
  border: 1px solid rgba(133, 88, 43, .16);
  border-radius: 999px;
  background: rgba(255, 255, 255, .58);
  color: #855126;
  font-size: 9px;
  font-weight: 850;
  letter-spacing: .13em;
}

.campusHubHero h1 {
  max-width: 760px;
  margin: 17px 0 12px;
  color: #1f2533;
  font-family: Georgia, "Times New Roman", serif;
  font-size: clamp(40px, 4.2vw, 62px);
  font-weight: 600;
  line-height: .98;
  letter-spacing: -.045em;
}

.campusHubHero > div:first-child > p {
  max-width: 650px;
  margin: 0;
  color: #6f7580;
  font-size: 13px;
  line-height: 1.75;
}

.campusHubIdentity {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 21px;
}

.campusHubIdentity span {
  padding: 6px 10px;
  border: 1px solid #e1d7ca;
  border-radius: 999px;
  background: rgba(255,255,255,.66);
  color: #66513d;
  font-size: 9px;
  font-weight: 700;
}

.campusHubActions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 24px;
}

/* HERO STATS */

.campusHubStats {
  position: relative;
  z-index: 2;
  display: grid;
  align-content: center;
  gap: 10px;
}

.campusHubStats article {
  display: grid;
  grid-template-columns: 1fr auto;
  align-items: center;
  gap: 5px 16px;
  padding: 18px 19px;
  border: 1px solid rgba(255,255,255,.9);
  border-radius: 18px;
  background: rgba(255, 255, 255, .68);
  box-shadow: 0 12px 30px rgba(63, 54, 44, .06);
  backdrop-filter: blur(14px);
}

.campusHubStats small {
  color: #8b765f;
  font-size: 8px;
  font-weight: 850;
  letter-spacing: .12em;
}

.campusHubStats strong {
  grid-row: span 2;
  color: #252b38;
  font-family: Georgia, serif;
  font-size: 30px;
}

.campusHubStats article::after {
  content: "Live";
  color: #8d96a4;
  font-size: 8px;
}

/* TOOLBAR */

.campusHubToolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 8px;
  border: 1px solid #e5e9ef;
  border-radius: 16px;
  background: #fff;
  box-shadow: 0 8px 26px rgba(28, 39, 58, .05);
}

.campusHubToolbar > div {
  display: flex;
  gap: 4px;
}

.campusHubToolbar button {
  padding: 10px 15px;
  border: 0;
  border-radius: 10px;
  background: transparent;
  color: #778090;
  font-size: 10px;
  font-weight: 750;
  cursor: pointer;
}

.campusHubToolbar button:hover {
  background: #f7f5f2;
}

.campusHubToolbar button.active {
  background: #efe7dd;
  color: #78491f;
}

.campusHubToolbar > input {
  width: min(330px, 100%);
  height: 39px;
  padding: 0 13px;
  border: 1px solid #e2e6ec;
  border-radius: 11px;
  outline: 0;
  background: #f8f9fb;
  color: #2d3748;
  font-size: 11px;
}

.campusHubToolbar > input:focus {
  border-color: #b5c0d0;
  background: #fff;
}

/* FEATURED EVENT */

.campusFeaturedEvent {
  display: grid;
  grid-template-columns: minmax(280px, .8fr) minmax(0, 1.2fr);
  min-height: 320px;
  overflow: hidden;
  padding: 0 !important;
  border-radius: 24px !important;
  box-shadow: 0 15px 40px rgba(25, 35, 52, .07);
}

.campusFeaturedVisual {
  min-height: 320px;
  overflow: hidden;
  background: #e9ded0;
}

.campusFeaturedVisual img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.campusFeaturedFallback {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  height: 100%;
  min-height: 320px;
  padding: 26px;
  background:
    radial-gradient(circle at 80% 20%, rgba(255,255,255,.34), transparent 30%),
    linear-gradient(150deg, #e9dac7, #cbb294);
}

.campusFeaturedFallback small {
  color: #73502f;
  font-size: 9px;
  font-weight: 850;
  letter-spacing: .14em;
  text-transform: uppercase;
}

.campusFeaturedFallback strong {
  color: rgba(88, 55, 29, .32);
  font-family: Georgia, serif;
  font-size: 150px;
  line-height: .75;
}

.campusFeaturedContent {
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 36px 40px;
}

.campusFeaturedContent > span {
  color: #8b5828;
  font-size: 8px;
  font-weight: 850;
  letter-spacing: .16em;
}

.campusFeaturedContent h2 {
  margin: 9px 0;
  color: #232a38;
  font-family: Georgia, serif;
  font-size: 32px;
  line-height: 1.08;
}

.campusFeaturedContent > p {
  max-width: 650px;
  margin: 0;
  color: #77808d;
  font-size: 12px;
  line-height: 1.7;
}

.campusFeaturedMeta {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: 18px;
}

.campusFeaturedMeta span {
  padding: 6px 9px;
  border-radius: 8px;
  background: #f4f6f8;
  color: #677285;
  font-size: 9px;
}

.campusFeaturedActions {
  display: flex;
  gap: 9px;
  margin-top: 22px;
}

.campusFeaturedActions a {
  display: inline-flex;
  align-items: center;
  text-decoration: none;
}

/* OVERVIEW */

.campusOverviewGrid {
  display: grid;
  grid-template-columns: minmax(0, 1.55fr) minmax(285px, .65fr);
  gap: 18px;
}

.campusUpdates,
.campusQuickLinks,
.campusCommunitySection,
.campusEventDirectory {
  border-radius: 20px !important;
  box-shadow: 0 10px 32px rgba(26, 37, 55, .05);
}

.campusUpdates,
.campusQuickLinks {
  padding: 22px !important;
}

.campusUpdates > header,
.campusCommunitySection > header,
.campusEventDirectory > header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 15px;
}

.campusUpdates > header span,
.campusCommunitySection > header span,
.campusEventDirectory > header span,
.campusQuickLinks > span {
  color: #926030;
  font-size: 8px;
  font-weight: 850;
  letter-spacing: .14em;
}

.campusUpdates h2,
.campusCommunitySection h2,
.campusEventDirectory h2,
.campusQuickLinks h2 {
  margin: 5px 0 0;
  color: #2b3240;
  font-family: Georgia, serif;
}

.campusUpdates h2,
.campusQuickLinks h2 {
  font-size: 20px;
}

.campusUpdates > header > button,
.campusCommunitySection > header > button {
  border: 0;
  background: transparent;
  color: #895527;
  font-size: 9px;
  font-weight: 800;
  cursor: pointer;
}

/* ANNOUNCEMENTS */

.campusUpdateRow {
  display: grid;
  grid-template-columns: 40px minmax(0, 1fr) auto;
  align-items: center;
  gap: 11px;
  width: 100%;
  padding: 13px 2px;
  border: 0;
  border-bottom: 1px solid #edf0f3;
  background: transparent;
  text-align: left;
  cursor: pointer;
}

.campusUpdateRow:last-child {
  border-bottom: 0;
}

.campusUpdateRow:hover {
  background: #fafafa;
}

.campusUpdateRow > i {
  display: grid;
  width: 37px;
  height: 37px;
  place-items: center;
  border-radius: 11px;
  background: #f2e8dc;
  color: #915a2a;
  font-size: 10px;
  font-style: normal;
  font-weight: 850;
}

.campusUpdateRow > span {
  display: grid;
  gap: 3px;
  min-width: 0;
}

.campusUpdateRow b {
  overflow: hidden;
  color: #333b49;
  font-size: 11px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.campusUpdateRow small {
  color: #929aa7;
  font-size: 9px;
}

.campusUpdateRow em {
  padding: 4px 6px;
  border-radius: 6px;
  background: #fff3dd;
  color: #9b621e;
  font-size: 7px;
  font-style: normal;
  font-weight: 850;
}

/* QUICK LINKS */

.campusQuickLinks {
  display: flex;
  flex-direction: column;
}

.campusQuickLinks h2 {
  margin-bottom: 13px;
}

.campusQuickLinks > button {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  width: 100%;
  padding: 13px 4px;
  border: 0;
  border-bottom: 1px solid #edf0f3;
  background: transparent;
  color: #3b4556;
  text-align: left;
  cursor: pointer;
}

.campusQuickLinks > button:last-child {
  border-bottom: 0;
}

.campusQuickLinks > button:hover {
  padding-left: 8px;
}

.campusQuickLinks > button span {
  font-size: 10px;
  font-weight: 700;
}

.campusQuickLinks > button b {
  color: #9aa3af;
}

/* COMMUNITIES */

.campusCommunitySection {
  padding: 24px !important;
}

.campusCommunitySection h2,
.campusEventDirectory h2 {
  font-size: 23px;
}

.campusCommunityGrid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 13px;
  margin-top: 20px;
}

.campusCommunityGrid.directory {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.campusCommunityCard {
  position: relative;
  overflow: hidden;
  padding: 18px;
  border: 1px solid #e6e9ee;
  border-radius: 17px;
  background:
    linear-gradient(180deg, #fff 0%, #fafbfc 100%);
  transition:
    transform .18s ease,
    box-shadow .18s ease,
    border-color .18s ease;
}

.campusCommunityCard:hover {
  transform: translateY(-3px);
  border-color: #d8dce3;
  box-shadow: 0 12px 28px rgba(31, 42, 60, .08);
}

.campusCommunityCard > i {
  display: grid;
  width: 44px;
  height: 44px;
  margin-bottom: 14px;
  place-items: center;
  border-radius: 13px;
  background: #ede2d4;
  color: #825127;
  font-size: 11px;
  font-style: normal;
  font-weight: 850;
}

.campusCommunityCard > span {
  color: #96632f;
  font-size: 7px;
  font-weight: 850;
  letter-spacing: .11em;
  text-transform: uppercase;
}

.campusCommunityCard h3 {
  margin: 6px 0;
  color: #303846;
  font-size: 12px;
}

.campusCommunityCard p {
  min-height: 39px;
  margin: 0;
  color: #858e9c;
  font-size: 9px;
  line-height: 1.55;
}

.campusCommunityCard footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 15px;
}

.campusCommunityCard footer small {
  color: #8d96a3;
  font-size: 8px;
}

.campusCommunityCard footer button {
  border: 0;
  background: transparent;
  color: #885427;
  font-size: 8px;
  font-weight: 850;
  cursor: pointer;
}

/* EVENTS DIRECTORY */

.campusEventDirectory {
  padding: 24px !important;
}

.campusEventDirectory > header > b {
  display: grid;
  min-width: 44px;
  height: 44px;
  place-items: center;
  border-radius: 12px;
  background: #efe6dc;
  color: #855126;
  font-size: 12px;
}

.campusEventList {
  display: grid;
  gap: 10px;
  margin-top: 20px;
}

.campusEventRow {
  display: grid;
  grid-template-columns: 64px minmax(0, 1fr) auto;
  align-items: center;
  gap: 16px;
  padding: 16px;
  border: 1px solid #e7eaf0;
  border-radius: 15px;
  background: #fbfcfd;
  transition:
    border-color .16s ease,
    transform .16s ease,
    box-shadow .16s ease;
}

.campusEventRow:hover {
  transform: translateY(-2px);
  border-color: #d8dde5;
  box-shadow: 0 9px 24px rgba(31, 43, 61, .06);
}

.campusEventDate {
  display: grid;
  width: 58px;
  height: 62px;
  place-items: center;
  align-content: center;
  border-radius: 13px;
  background: #efe3d5;
}

.campusEventDate strong {
  color: #4a3422;
  font-family: Georgia, serif;
  font-size: 21px;
  line-height: 1;
}

.campusEventDate span {
  margin-top: 3px;
  color: #925c2d;
  font-size: 8px;
  font-weight: 850;
  text-transform: uppercase;
}

.campusEventRow > section {
  display: grid;
  gap: 3px;
  min-width: 0;
}

.campusEventRow > section small {
  color: #956331;
  font-size: 7px;
  font-weight: 850;
  letter-spacing: .08em;
  text-transform: uppercase;
}

.campusEventRow > section h3 {
  margin: 0;
  color: #303846;
  font-size: 12px;
}

.campusEventRow > section p {
  margin: 2px 0;
  color: #7f8997;
  font-size: 9px;
}

.campusEventRow > section > span {
  color: #929aa7;
  font-size: 8px;
}

.campusEventRow > button {
  padding: 8px 12px;
  border: 1px solid #dfd3c5;
  border-radius: 9px;
  background: #fff9f2;
  color: #845023;
  font-size: 8px;
  font-weight: 800;
  cursor: pointer;
}

/* EMPTY STATES */

.campusEmpty {
  padding: 26px 10px;
  color: #929aa7;
  font-size: 10px;
  text-align: center;
}

/* RESPONSIVE */

@media (max-width: 1080px) {
  .campusHubHero,
  .campusFeaturedEvent,
  .campusOverviewGrid {
    grid-template-columns: 1fr;
  }

  .campusHubStats {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .campusCommunityGrid,
  .campusCommunityGrid.directory {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 720px) {
  .campusHubHero {
    padding: 27px 21px;
    border-radius: 22px;
  }

  .campusHubHero h1 {
    font-size: 38px;
  }

  .campusHubStats {
    grid-template-columns: 1fr;
  }

  .campusHubToolbar {
    align-items: stretch;
    flex-direction: column;
  }

  .campusHubToolbar > div {
    overflow-x: auto;
  }

  .campusHubToolbar > input {
    width: 100%;
  }

  .campusCommunityGrid,
  .campusCommunityGrid.directory {
    grid-template-columns: 1fr;
  }

  .campusEventRow {
    grid-template-columns: 58px minmax(0, 1fr);
  }

  .campusEventRow > button {
    grid-column: 2;
    justify-self: start;
  }

  .campusFeaturedContent {
    padding: 26px 21px;
  }
}

/* =========================================================
   CAMPUS — INSTITUTIONAL / IIT-INSPIRED LAYER
========================================================= */

.campusHub {
  --institution-navy: #17233b;
  --institution-ink: #202735;
  --institution-muted: #747d8c;
  --institution-gold: #9a6c37;
  --institution-cream: #f5efe7;
  --institution-line: #e4e6e9;
}


/* ---------------------------------------------------------
   HERO — LESS DASHBOARD, MORE UNIVERSITY
--------------------------------------------------------- */

.campusHubHero {
  min-height: 420px;
  align-items: end;
  padding: 52px 54px;
  border: 0;
  border-radius: 4px;
  background:
    linear-gradient(
      100deg,
      rgba(20, 31, 52, .97) 0%,
      rgba(25, 38, 63, .94) 48%,
      rgba(42, 50, 67, .88) 100%
    );
  box-shadow: none;
}

.campusHubHero::before {
  content: "RNSIT";
  position: absolute;
  right: 30px;
  bottom: -55px;

  color: rgba(255,255,255,.035);

  font-family:
    Georgia,
    "Times New Roman",
    serif;

  font-size: clamp(
    140px,
    19vw,
    280px
  );

  font-weight: 700;
  line-height: 1;
}

.campusHubHero::after {
  width: 1px;
  height: 62%;
  top: 20%;
  right: 36%;

  border: 0;
  border-left:
    1px solid
    rgba(255,255,255,.12);

  border-radius: 0;
}

.campusHubEyebrow {
  padding: 0;
  border: 0;
  background: transparent;

  color: #dbc7a5;

  font-size: 9px;
  letter-spacing: .2em;
}

.campusHubHero h1 {
  max-width: 820px;

  margin:
    21px 0 18px;

  color: #ffffff;

  font-size:
    clamp(
      44px,
      5vw,
      72px
    );

  line-height: .98;
}

.campusHubHero > div:first-child > p {
  max-width: 650px;

  color:
    rgba(
      255,
      255,
      255,
      .68
    );

  font-size: 13px;
}

.campusHubIdentity span {
  border:
    1px solid
    rgba(
      255,
      255,
      255,
      .16
    );

  background:
    rgba(
      255,
      255,
      255,
      .06
    );

  color:
    rgba(
      255,
      255,
      255,
      .78
    );
}


/* ---------------------------------------------------------
   HERO NUMBERS
--------------------------------------------------------- */

.campusHubStats {
  gap: 0;
}

.campusHubStats article {
  padding:
    22px 0;

  border: 0;

  border-bottom:
    1px solid
    rgba(
      255,
      255,
      255,
      .12
    );

  border-radius: 0;

  background:
    transparent;

  box-shadow: none;
  backdrop-filter: none;
}

.campusHubStats article:last-child {
  border-bottom: 0;
}

.campusHubStats small {
  color:
    rgba(
      255,
      255,
      255,
      .48
    );
}

.campusHubStats strong {
  color: #ffffff;

  font-size: 37px;
}

.campusHubStats article::after {
  color:
    rgba(
      255,
      255,
      255,
      .4
    );
}


/* ---------------------------------------------------------
   CAMPUS NAV
--------------------------------------------------------- */

.campusHubToolbar {
  position: sticky;
  top: 0;
  z-index: 30;

  padding: 7px 9px;

  border-radius: 3px;

  box-shadow:
    0 6px 22px
    rgba(
      23,
      35,
      59,
      .06
    );
}

.campusHubToolbar button {
  border-radius: 2px;

  text-transform: uppercase;

  letter-spacing: .07em;
}

.campusHubToolbar button.active {
  background:
    var(
      --institution-navy
    );

  color: #fff;
}


/* ---------------------------------------------------------
   INSTITUTIONAL SECTION HEADINGS
--------------------------------------------------------- */

.instituteSectionHeading {
  display: flex;

  align-items: flex-end;
  justify-content:
    space-between;

  gap: 35px;

  margin-bottom: 30px;

  padding-bottom: 24px;

  border-bottom:
    1px solid
    var(
      --institution-line
    );
}

.instituteSectionHeading > div {
  max-width: 700px;
}

.instituteSectionHeading span {
  color:
    var(
      --institution-gold
    );

  font-size: 9px;

  font-weight: 850;

  letter-spacing: .18em;
}

.instituteSectionHeading h2 {
  margin:
    9px 0 10px;

  color:
    var(
      --institution-ink
    );

  font-family:
    Georgia,
    "Times New Roman",
    serif;

  font-size:
    clamp(
      34px,
      4vw,
      54px
    );

  font-weight: 500;

  line-height: 1;
}

.instituteSectionHeading p {
  max-width: 570px;

  margin: 0;

  color:
    var(
      --institution-muted
    );

  font-size: 11px;

  line-height: 1.7;
}

.instituteSectionHeading > strong {
  display: grid;

  min-width: 145px;

  color:
    var(
      --institution-navy
    );

  font-family:
    Georgia,
    serif;

  font-size: 38px;
}

.instituteSectionHeading > strong small {
  margin-top: 5px;

  color: #89919d;

  font-family:
    Arial,
    sans-serif;

  font-size: 8px;

  font-weight: 700;

  letter-spacing: .08em;

  text-transform:
    uppercase;
}


/* ---------------------------------------------------------
   ACHIEVEMENT PAGE
--------------------------------------------------------- */

.instituteAchievements {
  padding:
    36px 0 10px;
}


/* ---------------------------------------------------------
   FEATURED ACHIEVEMENT
--------------------------------------------------------- */

.achievementFeature {
  display: grid;

  grid-template-columns:
    minmax(
      300px,
      .9fr
    )
    minmax(
      0,
      1.1fr
    );

  min-height: 390px;

  margin-bottom: 32px;

  background:
    var(
      --institution-navy
    );
}

.achievementFeatureImage {
  min-height: 390px;

  overflow: hidden;

  background: #ded5c8;
}

.achievementFeatureImage img {
  display: block;

  width: 100%;
  height: 100%;

  object-fit: cover;
}

.achievementFeatureImage > div {
  display: flex;

  flex-direction: column;

  justify-content:
    space-between;

  min-height: 390px;

  padding: 30px;

  background:
    linear-gradient(
      145deg,
      #e8ded0,
      #baa386
    );
}

.achievementFeatureImage span {
  color: #6e4a29;

  font-size: 9px;

  font-weight: 850;

  letter-spacing: .16em;
}

.achievementFeatureImage strong {
  color:
    rgba(
      69,
      47,
      28,
      .28
    );

  font-family:
    Georgia,
    serif;

  font-size: 190px;

  line-height: .68;
}

.achievementFeatureContent {
  display: flex;

  flex-direction: column;

  justify-content:
    center;

  padding:
    45px 48px;
}

.achievementFeatureContent > span {
  color: #d6bb91;

  font-size: 8px;

  font-weight: 850;

  letter-spacing: .18em;
}

.achievementFeatureContent h3 {
  margin:
    13px 0 14px;

  color: #ffffff;

  font-family:
    Georgia,
    serif;

  font-size:
    clamp(
      28px,
      3vw,
      45px
    );

  font-weight: 500;

  line-height: 1.05;
}

.achievementFeatureContent > p {
  max-width: 600px;

  margin: 0;

  color:
    rgba(
      255,
      255,
      255,
      .65
    );

  font-size: 11px;

  line-height: 1.8;
}

.achievementFeatureMeta {
  display: flex;

  flex-wrap: wrap;

  gap: 8px;

  margin-top: 20px;
}

.achievementFeatureMeta b,
.achievementFeatureMeta small {
  padding:
    6px 9px;

  border:
    1px solid
    rgba(
      255,
      255,
      255,
      .13
    );

  color:
    rgba(
      255,
      255,
      255,
      .78
    );

  font-size: 8px;
}

.achievementFeatureContent > a {
  align-self:
    flex-start;

  margin-top: 24px;

  color: #e0c7a1;

  font-size: 9px;

  font-weight: 800;

  text-decoration: none;
}


/* ---------------------------------------------------------
   ACHIEVEMENT GRID
--------------------------------------------------------- */

.achievementGrid {
  display: grid;

  grid-template-columns:
    repeat(
      3,
      minmax(
        0,
        1fr
      )
    );

  gap: 1px;

  background:
    #dfe2e6;

  border:
    1px solid
    #dfe2e6;
}

.achievementCard {
  display: flex;

  flex-direction: column;

  min-height: 245px;

  padding:
    25px 24px;

  background: #ffffff;

  transition:
    background .18s ease;
}

.achievementCard:hover {
  background: #faf7f2;
}

.achievementCardTop {
  display: flex;

  align-items: center;

  justify-content:
    space-between;

  gap: 10px;
}

.achievementCardTop span {
  color:
    var(
      --institution-gold
    );

  font-size: 8px;

  font-weight: 850;

  letter-spacing: .12em;

  text-transform:
    uppercase;
}

.achievementCardTop small {
  color: #959ca7;

  font-size: 8px;
}

.achievementCard h3 {
  margin:
    17px 0 10px;

  color:
    var(
      --institution-ink
    );

  font-family:
    Georgia,
    serif;

  font-size: 20px;

  font-weight: 500;

  line-height: 1.18;
}

.achievementCard > p {
  flex: 1;

  margin: 0;

  color: #7d8592;

  font-size: 9px;

  line-height: 1.65;
}

.achievementCard footer {
  display: flex;

  align-items:
    flex-end;

  justify-content:
    space-between;

  gap: 12px;

  margin-top: 22px;

  padding-top: 14px;

  border-top:
    1px solid #eceef1;
}

.achievementCard footer > div {
  display: grid;

  gap: 2px;
}

.achievementCard footer b {
  color: #444c5b;

  font-size: 9px;
}

.achievementCard footer small {
  color: #969da7;

  font-size: 8px;
}

.achievementCard footer a {
  display: grid;

  width: 29px;
  height: 29px;

  place-items: center;

  border:
    1px solid
    #dde1e6;

  color:
    var(
      --institution-navy
    );

  text-decoration: none;
}


/* ---------------------------------------------------------
   OVERVIEW ALSO MORE INSTITUTIONAL
--------------------------------------------------------- */

.campusFeaturedEvent {
  border-radius: 3px !important;

  box-shadow: none;
}

.campusFeaturedContent h2 {
  font-size: 37px;
}

.campusUpdates,
.campusQuickLinks,
.campusCommunitySection,
.campusEventDirectory {
  border-radius:
    3px !important;

  box-shadow: none;
}

.campusCommunityCard {
  border-radius: 2px;

  background: #ffffff;

  box-shadow: none;
}

.campusCommunityCard:hover {
  transform: none;

  border-color:
    #cfd4db;

  box-shadow: none;
}

.campusEventRow {
  border-radius: 2px;

  background: #ffffff;
}


/* ---------------------------------------------------------
   EMPTY ACHIEVEMENT STATE
--------------------------------------------------------- */

.instituteEmptyState {
  display: grid;

  justify-items: center;

  padding:
    70px 25px;

  border:
    1px solid
    var(
      --institution-line
    );

  text-align: center;
}

.instituteEmptyState > span {
  color: #a3835c;

  font-size: 24px;
}

.instituteEmptyState h3 {
  margin:
    12px 0 5px;

  color:
    var(
      --institution-ink
    );

  font-family:
    Georgia,
    serif;

  font-size: 22px;

  font-weight: 500;
}

.instituteEmptyState p {
  max-width: 430px;

  margin: 0;

  color:
    var(
      --institution-muted
    );

  font-size: 9px;

  line-height: 1.7;
}


/* ---------------------------------------------------------
   RESPONSIVE
--------------------------------------------------------- */

@media (
  max-width: 1000px
) {

  .achievementFeature {
    grid-template-columns:
      1fr;
  }

  .achievementGrid {
    grid-template-columns:
      repeat(
        2,
        minmax(
          0,
          1fr
        )
      );
  }

}


@media (
  max-width: 680px
) {

  .campusHubHero {
    min-height: 0;

    padding:
      36px 23px;
  }

  .campusHubHero::after {
    display: none;
  }

  .achievementGrid {
    grid-template-columns:
      1fr;
  }

  .achievementFeatureContent {
    padding:
      30px 24px;
  }

  .instituteSectionHeading {
    align-items:
      flex-start;

    flex-direction:
      column;
  }

}

/* =========================================================
   CAMPUS — RESEARCH & INNOVATION
========================================================= */

.campusResearchSection {
  padding: 36px 0 12px;
}

.researchFeature {
  display: grid;
  grid-template-columns: minmax(300px, .9fr) minmax(0, 1.1fr);
  min-height: 390px;
  margin-bottom: 28px;
  background: #16243d;
}

.researchFeatureVisual {
  min-height: 390px;
  overflow: hidden;
  background: #d9dfe4;
}

.researchFeatureVisual img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.researchFeatureVisual > div {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  min-height: 390px;
  padding: 30px;
  background:
    radial-gradient(
      circle at 75% 18%,
      rgba(255,255,255,.28),
      transparent 28%
    ),
    linear-gradient(
      145deg,
      #d9dee4,
      #aab4c2
    );
}

.researchFeatureVisual span {
  color: #34465e;
  font-size: 9px;
  font-weight: 850;
  letter-spacing: .15em;
  text-transform: uppercase;
}

.researchFeatureVisual strong {
  color: rgba(35, 50, 69, .2);
  font-family: Georgia, serif;
  font-size: 185px;
  line-height: .72;
}

.researchFeatureContent {
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 46px 48px;
}

.researchFeatureContent > span {
  color: #d0b589;
  font-size: 8px;
  font-weight: 850;
  letter-spacing: .18em;
}

.researchFeatureContent h3 {
  margin: 13px 0;
  color: #fff;
  font-family: Georgia, serif;
  font-size: clamp(29px, 3vw, 44px);
  font-weight: 500;
  line-height: 1.05;
}

.researchFeatureContent > p {
  margin: 0;
  max-width: 610px;
  color: rgba(255,255,255,.65);
  font-size: 11px;
  line-height: 1.8;
}

.researchMetadata {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
  margin-top: 20px;
}

.researchMetadata small {
  padding: 6px 9px;
  border: 1px solid rgba(255,255,255,.13);
  color: rgba(255,255,255,.76);
  font-size: 8px;
}

.researchFeatureContent > a {
  align-self: flex-start;
  margin-top: 24px;
  color: #e2c9a4;
  font-size: 9px;
  font-weight: 800;
  text-decoration: none;
}


/* RESEARCH NUMBERS */

.researchMetrics {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  margin-bottom: 28px;
  border-top: 1px solid #dde1e6;
  border-bottom: 1px solid #dde1e6;
}

.researchMetrics article {
  padding: 24px;
  border-right: 1px solid #dde1e6;
}

.researchMetrics article:last-child {
  border-right: 0;
}

.researchMetrics span {
  color: #906234;
  font-size: 8px;
  font-weight: 850;
  letter-spacing: .14em;
}

.researchMetrics strong {
  display: block;
  margin: 7px 0 4px;
  color: #1e2a3c;
  font-family: Georgia, serif;
  font-size: 34px;
}

.researchMetrics small {
  color: #8d96a3;
  font-size: 8px;
}


/* RESEARCH GRID */

.researchGrid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1px;
  border: 1px solid #dfe2e6;
  background: #dfe2e6;
}

.researchCard {
  display: flex;
  min-height: 255px;
  flex-direction: column;
  padding: 25px;
  background: #fff;
}

.researchCard:hover {
  background: #f9f7f3;
}

.researchCardHead {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.researchCardHead span {
  color: #926433;
  font-size: 8px;
  font-weight: 850;
  letter-spacing: .12em;
  text-transform: uppercase;
}

.researchCardHead small {
  color: #969da7;
  font-size: 8px;
}

.researchCard h3 {
  margin: 18px 0 10px;
  color: #232c3b;
