   SELECT
--------------------------------------------------------- */

.campusCreateForm select {
  appearance: auto !important;

  cursor: pointer !important;
}


/* ---------------------------------------------------------
   CHECKBOX FEATURED
--------------------------------------------------------- */

.campusCreateForm .campusFeaturedToggle {
  grid-column: 1 / -1 !important;

  display: flex !important;
  flex-direction: row !important;

  align-items: center !important;

  gap: 10px !important;

  width: 100% !important;

  padding: 13px 14px !important;

  border: 1px solid #e1e6ed !important;
  border-radius: 10px !important;

  background: #f8fafc !important;
}

.campusCreateForm .campusFeaturedToggle input {
  flex: 0 0 auto !important;

  width: 16px !important;
  height: 16px !important;

  min-width: 16px !important;

  margin: 0 !important;
  padding: 0 !important;

  accent-color: #315fba !important;
}

.campusCreateForm .campusFeaturedToggle span {
  margin: 0 !important;

  color: #425168 !important;

  font-size: 11px !important;
  font-weight: 650 !important;
}


/* ---------------------------------------------------------
   ERROR
--------------------------------------------------------- */

.campusCreateForm .authError {
  grid-column: 1 / -1 !important;

  margin: 0 !important;

  padding: 10px 12px !important;

  border: 1px solid #fecaca !important;
  border-radius: 9px !important;

  background: #fff7f7 !important;

  color: #b42318 !important;

  font-size: 11px !important;
}


/* ---------------------------------------------------------
   FOOTER
--------------------------------------------------------- */

.campusCreateForm > footer {
  grid-column: 1 / -1 !important;

  display: flex !important;

  align-items: center !important;
  justify-content: flex-end !important;

  gap: 10px !important;

  width: 100% !important;

  margin: 4px 0 0 !important;

  padding: 20px 0 0 !important;

  border-top: 1px solid #e6eaf0 !important;

  background: transparent !important;
}


/* footer buttons */

.campusCreateForm > footer > button {
  display: inline-flex !important;

  align-items: center !important;
  justify-content: center !important;

  width: auto !important;
  min-width: 112px !important;
  height: 41px !important;

  margin: 0 !important;

  padding: 0 18px !important;

  border-radius: 9px !important;

  font-family:
    Inter,
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    sans-serif !important;

  font-size: 11px !important;
  line-height: 1 !important;

  font-weight: 720 !important;

  cursor: pointer !important;
}


/* cancel */

.campusCreateForm > footer > .ghost {
  border: 1px solid #d8e0e9 !important;

  background: #ffffff !important;

  color: #475569 !important;
}

.campusCreateForm > footer > .ghost:hover {
  background: #f7f9fb !important;

  border-color: #c5d0dc !important;
}


/* publish */

.campusCreateForm > footer > .primary {
  border: 1px solid #315fba !important;

  background: #315fba !important;

  color: #ffffff !important;

  box-shadow:
    0 5px 15px rgba(49, 95, 186, 0.20) !important;
}

.campusCreateForm > footer > .primary:hover {
  border-color: #264f9d !important;

  background: #264f9d !important;
}

.campusCreateForm > footer > button:disabled {
  opacity: 0.55 !important;

  cursor: not-allowed !important;
}


/* ---------------------------------------------------------
   SCROLLBAR
--------------------------------------------------------- */

.campusCreateForm::-webkit-scrollbar {
  width: 7px !important;
}

.campusCreateForm::-webkit-scrollbar-track {
  background: transparent !important;
}

.campusCreateForm::-webkit-scrollbar-thumb {
  border-radius: 20px !important;

  background: #cbd5e1 !important;
}


/* ---------------------------------------------------------
   TABLET
--------------------------------------------------------- */

@media (max-width: 820px) {

  .campusContentModalScrim {
    padding: 18px !important;
  }

  .campusCreateFormModal {
    width: 100% !important;

    max-height: calc(100vh - 36px) !important;
  }

}


/* ---------------------------------------------------------
   MOBILE
--------------------------------------------------------- */

@media (max-width: 650px) {

  .campusContentModalScrim {
    align-items: flex-end !important;

    padding: 10px !important;
  }

  .campusCreateFormModal {
    width: 100% !important;

    max-height: calc(100vh - 20px) !important;

    border-radius: 17px !important;
  }


  .campusCreateFormModal > header {
    padding:
      21px
      20px
      18px !important;
  }


  .campusCreateFormModal > header h2 {
    font-size: 21px !important;
  }


  .campusCreateForm {
    grid-template-columns:
      minmax(0, 1fr) !important;

    gap: 15px !important;

    padding:
      20px
      20px
      24px !important;
  }


  .campusCreateForm > label,
  .campusCreateForm > label.full {
    grid-column: 1 !important;
  }


  .campusCreateForm .campusFeaturedToggle {
    grid-column: 1 !important;
  }


  .campusCreateForm .authError {
    grid-column: 1 !important;
  }


  .campusCreateForm > footer {
    grid-column: 1 !important;
  }

}


/* ---------------------------------------------------------
   SMALL MOBILE
--------------------------------------------------------- */

@media (max-width: 430px) {

  .campusCreateForm > footer {
    flex-direction: column-reverse !important;
  }

  .campusCreateForm > footer > button {
    width: 100% !important;
  }

}


.campusCreateForm .campusFileField {
  padding: 16px !important;
  border: 1px dashed #cbd5e1 !important;
  border-radius: 12px !important;
  background: #f8fafc !important;
}

.campusCreateForm .campusFileField input[type="file"] {
  height: auto !important;
  padding: 10px !important;
  border: 1px solid #dce3eb !important;
  border-radius: 8px !important;
  background: #fff !important;
  cursor: pointer !important;
}

.campusCreateForm .campusFileField small {
  color: #64748b !important;
  font-size: 10px !important;
}

/* =========================================================
   CAMPUS — PUBLISHED CONTENT
========================================================= */

.campusPublishedAchievements,
.campusPublishedResearch {
  padding: 30px 0 40px;
}


/* section heading */

.campusContentSectionHeader {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;

  gap: 25px;

  margin-bottom: 24px;
  padding-bottom: 20px;

  border-bottom: 1px solid #dfe4ea;
}

.campusContentSectionHeader > div {
  max-width: 680px;
}

.campusContentSectionHeader span {
  display: block;

  margin-bottom: 7px;

  color: #93602e;

  font-size: 9px;
  font-weight: 850;

  letter-spacing: .16em;
}

.campusContentSectionHeader h2 {
  margin: 0;

  color: #202a39;

  font-family: Georgia, serif;

  font-size: clamp(28px, 3vw, 41px);
  font-weight: 500;

  line-height: 1.08;
}

.campusContentSectionHeader p {
  margin: 9px 0 0;

  color: #7c8592;

  font-size: 11px;
  line-height: 1.65;
}


/* add button */

.campusSectionAddButton {
  height: 40px;

  padding: 0 16px;

  flex: 0 0 auto;

  border: 0;
  border-radius: 8px;

  background: #1c2e49;

  color: #fff;

  font-size: 10px;
  font-weight: 750;

  cursor: pointer;
}

.campusSectionAddButton:hover {
  background: #294668;
}


/* =========================================================
   ACHIEVEMENTS GRID
========================================================= */

.campusAchievementGrid,
.campusResearchGrid {
  display: grid;

  grid-template-columns:
    repeat(3, minmax(0, 1fr));

  gap: 18px;
}


/* cards */

.campusAchievementCard,
.campusResearchPublishedCard {
  overflow: hidden;

  border: 1px solid #dfe4ea;
  border-radius: 15px;

  background: #fff;

  box-shadow:
    0 5px 20px
    rgba(26, 39, 59, .045);

  transition:
    transform .2s ease,
    box-shadow .2s ease,
    border-color .2s ease;
}

.campusAchievementCard:hover,
.campusResearchPublishedCard:hover {
  transform: translateY(-3px);

  border-color: #ccd4df;

  box-shadow:
    0 14px 35px
    rgba(26, 39, 59, .09);
}

.campusAchievementCard.featured,
.campusResearchPublishedCard.featured {
  border-color: #d9bd94;
}


/* =========================================================
   MEDIA
========================================================= */

.campusAchievementMedia,
.campusResearchPublishedMedia {
  position: relative;

  height: 210px;

  overflow: hidden;

  background: #eef2f6;
}

.campusAchievementMedia img,
.campusResearchPublishedMedia img {
  width: 100%;
  height: 100%;

  object-fit: cover;

  display: block;
}

.campusAchievementPlaceholder,
.campusResearchPlaceholder {
  display: grid;

  width: 100%;
  height: 100%;

  place-items: center;

  background:
    radial-gradient(
      circle at 75% 20%,
      rgba(255,255,255,.8),
      transparent 28%
    ),
    linear-gradient(
      140deg,
      #edf1f5,
      #dce3ea
    );
}

.campusAchievementPlaceholder span,
.campusResearchPlaceholder span {
  color: rgba(34, 51, 74, .18);

  font-family: Georgia, serif;

  font-size: 92px;
  font-weight: 600;
}


/* featured badge */

.campusFeaturedBadge {
  position: absolute;

  top: 14px;
  left: 14px;

  padding: 6px 8px;

  border-radius: 5px;

  background: rgba(25, 40, 62, .92);

  color: #fff;

  font-size: 7px;
  font-weight: 850;

  letter-spacing: .13em;
}


/* =========================================================
   BODY
========================================================= */

.campusAchievementBody,
.campusResearchPublishedBody {
  padding: 21px;
}


/* meta row */

.campusAchievementMeta {
  display: flex;

  align-items: center;
  justify-content: space-between;

  gap: 10px;
}

.campusAchievementMeta span {
  color: #956331;

  font-size: 8px;
  font-weight: 850;

  letter-spacing: .12em;

  text-transform: uppercase;
}

.campusAchievementMeta small {
  color: #959eaa;

  font-size: 8px;
}


/* title */

.campusAchievementBody h3,
.campusResearchPublishedBody h3 {
  margin: 11px 0 8px;

  color: #253044;

  font-family: Georgia, serif;

  font-size: 20px;
  font-weight: 500;

  line-height: 1.22;
}


/* description */

.campusAchievementBody > p,
.campusResearchPublishedBody > p {
  margin: 0;

  color: #7e8794;

  font-size: 9px;
  line-height: 1.7;
}


/* =========================================================
   DETAILS
========================================================= */

.campusAchievementDetails,
.campusResearchDetails {
  display: grid;

  grid-template-columns:
    repeat(2, minmax(0,1fr));

  gap: 10px;

  margin-top: 18px;
  padding-top: 16px;

  border-top: 1px solid #edf0f3;
}

.campusAchievementDetails > div,
.campusResearchDetails > div {
  display: grid;

  gap: 3px;
}

.campusAchievementDetails small,
.campusResearchDetails small {
  color: #99a1ad;

  font-size: 7px;
  font-weight: 750;

  letter-spacing: .08em;
}

.campusAchievementDetails b,
.campusResearchDetails b {
  overflow: hidden;

  color: #445064;

  font-size: 9px;
  font-weight: 650;

  text-overflow: ellipsis;
  white-space: nowrap;
}


/* =========================================================
   EXTERNAL LINK
========================================================= */

.campusContentExternalLink {
  display: inline-flex;

  margin-top: 17px;

  color: #2f5f9f;

  font-size: 9px;
  font-weight: 750;

  text-decoration: none;
}

.campusContentExternalLink:hover {
  text-decoration: underline;
}


/* =========================================================
   EMPTY STATE
========================================================= */

.campusContentEmpty {
  display: grid;

  min-height: 300px;

  place-items: center;

  align-content: center;

  padding: 40px;

  text-align: center;

  border: 1px dashed #d7dde5;
  border-radius: 14px;

  background: #fafbfc;
}

.campusContentEmpty > span {
  color: #a4acb7;

  font-size: 30px;
}

.campusContentEmpty h3 {
  margin: 13px 0 5px;

  color: #344055;

  font-family: Georgia, serif;

  font-size: 21px;
  font-weight: 500;
}

.campusContentEmpty p {
  max-width: 430px;

  margin: 0;

  color: #89929f;

  font-size: 10px;
  line-height: 1.65;
}

.campusContentEmpty button {
  margin-top: 17px;

  height: 38px;

  padding: 0 15px;

  border: 0;
  border-radius: 7px;

  background: #1c2e49;

  color: #fff;

  font-size: 9px;
  font-weight: 750;

  cursor: pointer;
}


/* =========================================================
   RESPONSIVE
========================================================= */

@media (max-width: 1100px) {

  .campusAchievementGrid,
  .campusResearchGrid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

}

@media (max-width: 720px) {

  .campusContentSectionHeader {
    align-items: flex-start;
    flex-direction: column;
  }

  .campusAchievementGrid,
  .campusResearchGrid {
    grid-template-columns: 1fr;
  }

}


/* =========================================================
   ACHIEVEMENT MANAGEMENT
========================================================= */

.campusAchievementImageButton {
  display: block;
  width: 100%;
  height: 100%;
  padding: 0;
  border: 0;
  background: transparent;
  cursor: zoom-in;
  overflow: hidden;
}

.campusAchievementImageButton img {
  transition: transform .28s ease;
}

.campusAchievementImageButton:hover img {
  transform: scale(1.035);
}


/* footer */

.campusAchievementFooter {
  display: flex;
  align-items: center;
  justify-content: space-between;

  gap: 12px;

  margin-top: 18px;
  padding-top: 15px;

  border-top: 1px solid #edf0f3;
}

.campusAchievementFooter .campusContentExternalLink {
  margin-top: 0;
}


/* actions */

.campusAchievementActions {
  display: flex;
  align-items: center;
  gap: 6px;

  margin-left: auto;
}

.campusAchievementActions button {
  height: 30px;

  padding: 0 10px;

  border: 1px solid #dce2e9;
  border-radius: 7px;

  background: #fff;

  color: #4c596d;

  font-size: 8px;
  font-weight: 750;

  cursor: pointer;
}

.campusAchievementActions button:hover {
  border-color: #bfc9d5;
  background: #f8fafc;
  color: #1f2b3d;
}

.campusAchievementActions button.danger {
  border-color: #f0d3d3;
  color: #b42318;
}

.campusAchievementActions button.danger:hover {
  border-color: #eab8b8;
  background: #fff7f7;
}

.campusAchievementActions button:disabled {
  opacity: .5;
  cursor: not-allowed;
}


/* =========================================================
   FULLSCREEN IMAGE LIGHTBOX
========================================================= */

.campusImageLightbox {
  position: fixed;
  inset: 0;

  z-index: 1000000;

  display: flex;
  align-items: center;
  justify-content: center;

  padding: 34px;

  background: rgba(5, 10, 20, .91);

  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);

  cursor: zoom-out;
}

.campusImageLightbox img {
  display: block;

  max-width: min(1200px, calc(100vw - 80px));
  max-height: calc(100vh - 80px);

  width: auto;
  height: auto;

  object-fit: contain;

  border-radius: 10px;

  background: #fff;

  box-shadow:
    0 30px 100px
    rgba(0,0,0,.46);

  cursor: default;
}

.campusImageLightboxClose {
  position: fixed;

  top: 22px;
  right: 25px;

  z-index: 2;

  display: grid;

  width: 43px;
  height: 43px;

  place-items: center;

  padding: 0;

  border: 1px solid rgba(255,255,255,.24);
  border-radius: 50%;

  background: rgba(255,255,255,.12);

  color: #fff;

  font-size: 28px;
  line-height: 1;

  cursor: pointer;

  backdrop-filter: blur(10px);
}

.campusImageLightboxClose:hover {
  background: rgba(255,255,255,.22);
}


/* =========================================================
   RESPONSIVE
========================================================= */

@media (max-width: 600px) {

  .campusAchievementFooter {
    align-items: flex-start;
    flex-direction: column;
  }

  .campusAchievementActions {
    width: 100%;
    margin-left: 0;
  }

  .campusAchievementActions button {
    flex: 1;
  }

  .campusImageLightbox {
    padding: 15px;
  }

  .campusImageLightbox img {
    max-width: calc(100vw - 30px);
    max-height: calc(100vh - 70px);
  }

  .campusImageLightboxClose {
    top: 15px;
    right: 15px;
  }

}


