  letter-spacing: .17em;
}


.roleDashboardIdentity h2 {
  margin:
    7px
    0
    6px;

  color: #181d25;

  font-size: 28px;
  font-weight: 650;

  letter-spacing: -.04em;
}


.roleDashboardIdentity p {
  margin: 0;

  color: #7b818b;

  font-size: 10px;
}


/* =========================================================
   METRICS
========================================================= */

.roleDashboardMetrics {
  display: grid;

  grid-template-columns:
    repeat(
      4,
      minmax(0,1fr)
    );

  gap: 14px;

  margin-bottom: 17px;
}


.roleDashboardMetric {
  position: relative;

  min-width: 0;

  overflow: hidden;

  padding: 22px;

  border:
    1px solid
    rgba(255,255,255,.75);

  border-radius: 22px;

  background:
    rgba(255,255,255,.72);

  box-shadow:
    0 12px 34px
    rgba(24,31,43,.055);

  backdrop-filter:
    blur(22px);

  transition:
    transform .2s ease,
    box-shadow .2s ease;
}


.roleDashboardMetric::after {
  content: "";

  position: absolute;

  right: -30px;
  bottom: -39px;

  width: 110px;
  height: 110px;

  border-radius: 50%;

  background:
    var(--role-soft);
}


.roleDashboardMetric:hover {
  transform:
    translateY(-4px);

  box-shadow:
    0 22px 48px
    rgba(24,31,43,.1);
}


.roleDashboardMetric small {
  position: relative;
  z-index: 2;

  color: #7b818b;

  font-size: 7px;
  font-weight: 780;

  letter-spacing: .13em;
}


.roleDashboardMetric strong {
  position: relative;
  z-index: 2;

  display: block;

  margin:
    12px
    0
    7px;

  color: #171b22;

  font-size: 38px;
  font-weight: 630;

  letter-spacing: -.055em;
}


.roleDashboardMetric > span {
  position: relative;
  z-index: 2;

  color: #828892;

  font-size: 9px;
}


/* =========================================================
   MAIN GRID
========================================================= */

.roleDashboardMainGrid {
  display: grid;

  grid-template-columns:
    minmax(0,1.55fr)
    minmax(300px,.72fr);

  gap: 16px;

  align-items: start;
}


.roleDashboardMainColumn,
.roleDashboardSideColumn {
  display: grid;

  gap: 16px;

  min-width: 0;
}


.roleDashboardPanel {
  min-width: 0;

  padding: 24px;

  border:
    1px solid
    rgba(255,255,255,.76);

  border-radius: 24px;

  background:
    rgba(255,255,255,.72);

  box-shadow:
    0 14px 40px
    rgba(24,31,43,.055);

  backdrop-filter:
    blur(22px);
}


.roleDashboardPanel.floating {
  box-shadow:
    0 18px 52px
    rgba(24,31,43,.085);

  transition:
    transform .2s ease,
    box-shadow .2s ease;
}

.roleDashboardPanel.floating:hover {
  transform:
    translateY(-3px);

  box-shadow:
    0 24px 58px
    rgba(24,31,43,.115);
}


.roleDashboardPanelHeader {
  display: flex;

  align-items: center;
  justify-content: space-between;

  margin-bottom: 18px;
}


.roleDashboardPanelHeader span {
  color: var(--role-accent);

  font-size: 7px;
  font-weight: 820;

  letter-spacing: .16em;
}


.roleDashboardPanelHeader h3 {
  margin:
    5px
    0
    0;

  color: #21262f;

  font-size: 17px;
  font-weight: 650;

  letter-spacing: -.025em;
}


/* =========================================================
   PRIORITY TASKS
========================================================= */

.roleDashboardTaskList {
  display: grid;

  gap: 9px;
}


.roleDashboardTask {
  display: grid;

  grid-template-columns:
    42px
    minmax(0,1fr)
    auto;

  align-items: center;

  gap: 12px;

  width: 100%;

  padding:
    12px
    13px;

  border:
    1px solid
    rgba(18,20,24,.065);

  border-radius: 15px;

  background:
    rgba(255,255,255,.48);

  color: inherit;

  text-align: left;

  cursor: pointer;

  transition:
    transform .18s ease,
    background .18s ease;
}


.roleDashboardTask:hover {
  transform:
    translateX(3px);

  background:
    rgba(255,255,255,.92);
}


.roleDashboardTask > i {
  display: grid;

  width: 40px;
  height: 40px;

  place-items: center;

  border-radius: 13px;

  background:
    var(--role-soft);

  color:
    var(--role-accent);

  font-size: 10px;
  font-style: normal;
  font-weight: 850;
}


.roleDashboardTask > span b {
  display: block;

  margin-bottom: 4px;

  color: #252a32;

  font-size: 10px;
}


.roleDashboardTask > span small {
  display: block;

  color: #818791;

  font-size: 8px;
  line-height: 1.45;
}


.roleDashboardTask > em {
  padding:
    6px
    8px;

  border-radius: 999px;

  background:
    var(--role-soft);

  color:
    var(--role-accent);

  font-size: 7px;
  font-style: normal;
  font-weight: 800;

  white-space: nowrap;
}


/* =========================================================
   PROGRESS
========================================================= */

.roleDashboardProgress {
  margin:
    16px
    0;
}


.roleDashboardProgress p {
  display: flex;

  justify-content: space-between;

  margin:
    0
    0
    8px;

  color: #737a85;

  font-size: 9px;
}


.roleDashboardProgress p b {
  color: #303640;
}


.roleDashboardProgress > i {
  display: block;

  height: 6px;

  overflow: hidden;

  border-radius: 999px;

  background:
    rgba(17,19,23,.07);
}


.roleDashboardProgress > i > span {
  display: block;

  height: 100%;

  border-radius: inherit;

  background:
    linear-gradient(
      90deg,
      var(--role-accent),
      color-mix(
        in srgb,
        var(--role-accent) 55%,
        #9bc2ff
      )
    );
}


/* =========================================================
   QUICK ACTIONS
========================================================= */

.roleDashboardQuickGrid {
  display: grid;

  grid-template-columns:
    repeat(
      2,
      minmax(0,1fr)
    );

  gap: 10px;
}


.roleDashboardQuickGrid button {
  min-height: 104px;

  padding: 15px;

  border:
    1px solid
    rgba(18,20,24,.07);

  border-radius: 17px;

  background:
    rgba(255,255,255,.53);

  color: #222730;

  text-align: left;

  cursor: pointer;

  transition:
    transform .18s ease,
    box-shadow .18s ease,
    background .18s ease;
}


.roleDashboardQuickGrid button:hover {
  transform:
    translateY(-3px);

  background: #fff;

  box-shadow:
    0 13px 30px
    rgba(25,31,43,.085);
}


.roleDashboardQuickGrid i {
  display: block;

  color:
    var(--role-accent);

  font-size: 17px;
  font-style: normal;
  font-weight: 760;
}


.roleDashboardQuickGrid b {
  display: block;

  margin:
    10px
    0
    5px;

  font-size: 10px;
}


.roleDashboardQuickGrid small {
  display: block;

  color: #858b94;

  font-size: 8px;
  line-height: 1.4;
}


/* =========================================================
   PROFILE
========================================================= */

.roleDashboardIdentityCard {
  display: flex;

  align-items: center;

  gap: 12px;

  padding:
    14px;

  border:
    1px solid
    rgba(18,20,24,.06);

  border-radius: 16px;

  background:
    rgba(255,255,255,.48);
}


.roleDashboardAvatar {
  display: grid;

  width: 46px;
  height: 46px;

  place-items: center;

  flex: 0 0 auto;

  border-radius: 14px;

  background:
    var(--role-soft);

  color:
    var(--role-accent);

  font-size: 16px;
  font-weight: 800;
}


.roleDashboardIdentityCard > div:last-child {
  display: grid;

  gap: 2px;
}


.roleDashboardIdentityCard b {
  color: #292f38;

  font-size: 10px;
}


.roleDashboardIdentityCard span {
  color:
    var(--role-accent);

  font-size: 8px;
  font-weight: 700;
}


.roleDashboardIdentityCard small {
  color: #8a9099;

  font-size: 8px;
}


.roleDashboardProfileButton {
  display: flex;

  align-items: center;
  justify-content: space-between;

  width: 100%;

  min-height: 38px;

  margin-top: 10px;

  padding:
    0
    12px;

  border: 0;

  border-radius: 11px;

  background:
    rgba(17,19,23,.045);

  color: #4c535d;

  font-size: 9px;
  font-weight: 700;

  cursor: pointer;
}


/* =========================================================
   FLOATING CARDS
========================================================= */

.roleDashboardFloatingDock {
  display: grid;

  grid-template-columns:
    repeat(
      3,
      minmax(0,1fr)
    );

  gap: 14px;

  margin-top: 18px;
}


.roleDashboardFloatCard {
  position: relative;

  min-height: 150px;

  overflow: hidden;

  padding: 21px;

  border:
    1px solid
    rgba(255,255,255,.8);

  border-radius: 23px;

  background:
    linear-gradient(
      145deg,
      rgba(255,255,255,.83),
      rgba(255,255,255,.56)
    );

  color: inherit;

  text-align: left;

  box-shadow:
    0 17px 43px
    rgba(22,29,41,.07);

  backdrop-filter:
    blur(22px);

  cursor: pointer;

  transition:
    transform .2s ease,
    box-shadow .2s ease;
}


.roleDashboardFloatCard::before {
  content: "";

  position: absolute;

  top: 0;
  left: 21px;

  width: 60px;
  height: 3px;

  border-radius:
    0
    0
    5px
    5px;

  background:
    linear-gradient(
      90deg,
      var(--role-accent),
      transparent
    );
}


.roleDashboardFloatCard::after {
  content: "";

  position: absolute;

  right: -60px;
  bottom: -75px;

  width: 150px;
  height: 150px;

  border-radius: 50%;

  background:
    var(--role-soft);
}


.roleDashboardFloatCard:hover {
  transform:
    translateY(-5px);

  box-shadow:
    0 24px 58px
    rgba(22,29,41,.12);
}


.roleDashboardFloatCard small,
.roleDashboardFloatCard h3,
.roleDashboardFloatCard p,
.roleDashboardFloatCard > span {
  position: relative;
  z-index: 2;
}


.roleDashboardFloatCard small {
  color: #858b94;

  font-size: 7px;
  font-weight: 750;

  letter-spacing: .13em;
}


.roleDashboardFloatCard h3 {
  margin:
    14px
    0
    7px;

  color: #262c35;

  font-size: 13px;
  font-weight: 650;
}


.roleDashboardFloatCard p {
  max-width: 87%;

  margin: 0;

  color: #858b95;

  font-size: 8px;
  line-height: 1.6;
}


.roleDashboardFloatCard > span {
  display: block;

  margin-top: 15px;

  color:
    var(--role-accent);

  font-size: 8px;
  font-weight: 750;
}


/* =========================================================
   FLOATING DRAWER
========================================================= */

.roleDashboardDrawerScrim {
  position: fixed;

  inset: 0;

  z-index: 10000;

  background:
    rgba(8,12,19,.38);

  backdrop-filter:
    blur(9px);
}


.roleDashboardDrawer {
  position: absolute;

  top: 14px;
  right: 14px;
  bottom: 14px;

  width:
    min(
      440px,
      calc(100vw - 28px)
    );

  overflow-y: auto;

  border:
    1px solid
    rgba(255,255,255,.75);

  border-radius: 24px;

  background:
    rgba(250,251,252,.94);

  box-shadow:
    -20px
    20px
    70px
    rgba(13,20,31,.22);

  backdrop-filter:
    blur(28px);

  animation:
    roleDrawerIn
    .25s
    ease;
}


@keyframes roleDrawerIn {
  from {
    opacity: 0;

    transform:
      translateX(30px);
  }

  to {
    opacity: 1;

    transform:
      translateX(0);
  }
}


.roleDashboardDrawer > header {
  display: flex;

  align-items: flex-start;
  justify-content: space-between;

  gap: 20px;

  padding:
    28px
    28px
    22px;

  border-bottom:
    1px solid
    rgba(20,25,33,.08);
}


.roleDashboardDrawer header span {
  color:
    var(--role-accent);

  font-size: 8px;
  font-weight: 800;

  letter-spacing: .15em;
}


.roleDashboardDrawer header h2 {
  margin:
    7px
    0
    0;

  color: #1d222a;

  font-size: 24px;

  letter-spacing: -.035em;
}


.roleDashboardDrawer header button {
  display: grid;

  width: 36px;
  height: 36px;

  place-items: center;

  border:
    1px solid
    rgba(20,25,33,.08);

  border-radius: 50%;

  background: #fff;

  color: #626873;

  font-size: 22px;

  cursor: pointer;
}


.roleDashboardDrawerBody {
  padding: 25px 28px;
}


.roleDashboardDrawerStatus {
  display: flex;

  gap: 13px;

  padding: 16px;

  border:
    1px solid
    rgba(20,25,33,.07);

  border-radius: 16px;

  background: #fff;
}


.roleDashboardDrawerStatus > i {
  width: 9px;
  height: 9px;

  margin-top: 4px;

  flex: 0 0 auto;

  border-radius: 50%;

  background: #42c978;

  box-shadow:
    0 0 0 5px
    rgba(66,201,120,.11);
}


.roleDashboardDrawerStatus b {
  color: #252b34;

  font-size: 10px;
}


.roleDashboardDrawerStatus p {
  margin:
    5px
    0
    0;

  color: #818893;

  font-size: 9px;
  line-height: 1.6;
}


.roleDashboardDrawerActions {
  display: grid;

  gap: 9px;

  margin-top: 18px;
}


.roleDashboardDrawerActions button {
  display: flex;

  align-items: center;
  justify-content: space-between;

  min-height: 45px;

  padding:
    0
    14px;

  border:
    1px solid
    rgba(20,25,33,.08);

  border-radius: 12px;

  background: #fff;

  color: #343a44;

  font-size: 9px;
  font-weight: 700;

  cursor: pointer;
}


.roleDashboardDrawerActions button:hover {
  background:
    #f4f6f8;
}


.roleDashboardDrawerMessage {
  margin-top: 15px;

  color: #267453;

  font-size: 9px;
  font-weight: 700;
}


/* =========================================================
   RESPONSIVE
========================================================= */

@media (max-width: 1050px) {

  .roleDashboardMetrics {
    grid-template-columns:
      repeat(
        2,
        minmax(0,1fr)
      );
  }

  .roleDashboardMainGrid {
    grid-template-columns:
      1fr;
  }

  .roleDashboardFloatingDock {
    grid-template-columns:
      repeat(
        2,
        minmax(0,1fr)
      );
  }

}


@media (max-width: 720px) {

  .roleDashboardHero {
    min-height: 390px;

    padding:
      25px
      20px
      45px;
  }

  .roleDashboardHeroContent {
    align-items: flex-start;

    flex-direction: column;

    margin-top: 48px;
  }

  .roleDashboardHeroContent h1 {
    font-size: 44px;
  }

  .roleDashboardWorkspace {
    padding:
      36px
      18px
      55px;
  }

  .roleDashboardIdentity h2 {
    font-size: 24px;
  }

  .roleDashboardFloatingDock {
    grid-template-columns:
      1fr;
  }

}


@media (max-width: 500px) {

  .roleDashboardMetrics {
    grid-template-columns:
      1fr;
  }

  .roleDashboardQuickGrid {
    grid-template-columns:
      1fr;
  }

  .roleDashboardTask {
    grid-template-columns:
      40px
      minmax(0,1fr);
  }

  .roleDashboardTask > em {
    grid-column: 2;

    justify-self: start;
  }

  .roleDashboardHeroContent h1 {
    font-size: 38px;
  }

}


/* =========================================================
   CAMPUS — TOP RECRUITERS SHOWCASE
========================================================= */

.campusRecruiterShowcase {
  position: relative;
  overflow: hidden;
  margin: 0 0 28px;
  padding: 34px 0 30px;
  border: 1px solid rgba(255,255,255,.08);
  border-radius: 28px;
  background:
    radial-gradient(
      circle at 18% 15%,
      rgba(57,82,255,.18),
      transparent 34%
    ),
    radial-gradient(
      circle at 82% 70%,
      rgba(111,57,255,.17),
      transparent 32%
    ),
    linear-gradient(
      135deg,
      #080b15,
      #0d1120 48%,
      #080a12
    );
  box-shadow:
    0 28px 70px
    rgba(15,20,35,.18);
  color: #fff;
}

.campusRecruiterGlow {
  position: absolute;
  width: 260px;
  height: 260px;
  border-radius: 50%;
  pointer-events: none;
  filter: blur(90px);
  opacity: .38;
}

.campusRecruiterGlowOne {
  top: -150px;
  left: 10%;
  background: #4260ff;
}

.campusRecruiterGlowTwo {
  right: 3%;
  bottom: -170px;
  background: #7a45ff;
}

.campusRecruiterHeader {
  position: relative;
  z-index: 2;
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 22px;
  padding: 0 30px 25px;
}

.campusRecruiterHeader > div:first-child > span {
  color: #8da0ff;
  font-size: 8px;
  font-weight: 800;
  letter-spacing: .17em;
}

.campusRecruiterHeader h2 {
  margin: 7px 0 5px;
  color: #fff;
  font-size: clamp(25px,3vw,38px);
  letter-spacing: -.05em;
}

.campusRecruiterHeader p {
  max-width: 580px;
  margin: 0;
  color: #969cab;
  font-size: 10px;
  line-height: 1.7;
}

.campusRecruiterControls {
  display: flex;
  align-items: center;
  gap: 7px;
}

.campusRecruiterControls > button {
  display: grid;
  width: 38px;
  height: 38px;
  place-items: center;
  border: 1px solid rgba(255,255,255,.13);
  border-radius: 50%;
  background: rgba(255,255,255,.06);
  color: #fff;
  cursor: pointer;
  backdrop-filter: blur(12px);
  transition:
    transform .18s ease,
    background .18s ease;
}

.campusRecruiterControls > button:hover {
  transform: translateY(-2px);
  background: rgba(255,255,255,.12);
}

.campusRecruiterControls .campusRecruiterAdd {
  display: inline-flex;
  width: auto;
  min-width: 105px;
  padding: 0 14px;
  border-radius: 999px;
  background: #fff;
  color: #111827;
  font-size: 8px;
  font-weight: 800;
}


/* SLIDER */

.campusRecruiterViewport {
  position: relative;
  z-index: 2;
  overflow: hidden;
  width: 100%;
}

.campusRecruiterTrack {
  display: flex;
  width: max-content;
  transition:
    transform .65s
    cubic-bezier(.22,.8,.25,1);
  will-change: transform;
}

.campusRecruiterCard {
  width: 260px;
  min-height: 260px;
  margin-right: 12px;
  overflow: hidden;
  flex: 0 0 260px;
  border: 1px solid rgba(255,255,255,.08);
  border-radius: 20px;
  background:
    linear-gradient(
      145deg,
      rgba(255,255,255,.09),
      rgba(255,255,255,.025)
    );
  box-shadow:
    inset 0 1px 0
    rgba(255,255,255,.08);
  backdrop-filter: blur(16px);
}

.campusRecruiterCard:first-child {
  margin-left: 30px;
}

.campusRecruiterLogo {
  display: grid;
  height: 105px;
  place-items: center;
  padding: 20px;
  border-bottom:
    1px solid
    rgba(255,255,255,.07);
  background:
    rgba(255,255,255,.035);
}

.campusRecruiterLogo img {
  max-width: 150px;
  max-height: 62px;
  object-fit: contain;
  filter:
    drop-shadow(
      0 6px 15px
      rgba(0,0,0,.22)
    );
}

.campusRecruiterLogo strong {
  display: grid;
  width: 65px;
  height: 65px;
  place-items: center;
  border-radius: 18px;
  background:
    linear-gradient(
      145deg,
      #fff,
      #dce2ff
    );
  color: #101425;
  font-size: 20px;
  letter-spacing: -.04em;
}

.campusRecruiterInfo {
  padding: 17px;
}

.campusRecruiterInfo > span {
  color: #8f98ab;
  font-size: 7px;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
}

.campusRecruiterInfo h3 {
  margin: 5px 0 4px;
  color: #fff;
  font-size: 16px;
  letter-spacing: -.025em;
}

.campusRecruiterInfo > p {
  min-height: 28px;
  margin: 0;
  overflow: hidden;
  color: #9299a8;
  font-size: 8px;
  line-height: 1.65;
}

.campusRecruiterStats {
  display: grid;
  grid-template-columns:
    repeat(2,minmax(0,1fr));
  gap: 7px;
  margin-top: 14px;
}

.campusRecruiterStats > div {
  padding: 9px;
  border: 1px solid rgba(255,255,255,.07);
  border-radius: 10px;
  background: rgba(255,255,255,.035);
}

.campusRecruiterStats b {
  display: block;
  color: #fff;
  font-size: 11px;
}

.campusRecruiterStats small {
  display: block;
  margin-top: 2px;
  color: #7f8798;
  font-size: 6px;
}

.campusRecruiterFooter {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-top: 13px;
}

.campusRecruiterFooter button,
.campusRecruiterFooter span {
  border: 0;
  background: none;
  color: #a8b5ff;
  font-size: 7px;
  font-weight: 700;
}

.campusRecruiterFooter button {
  padding: 0;
  cursor: pointer;
}

.campusRecruiterFooter .campusRecruiterDelete {
  color: #d88a8a;
}


/* DOTS */

.campusRecruiterDots {
  position: relative;
  z-index: 2;
  display: flex;
  justify-content: center;
  gap: 6px;
  margin-top: 24px;
}

.campusRecruiterDots button {
  width: 5px;
  height: 5px;
  padding: 0;
  border: 0;
  border-radius: 999px;
  background: rgba(255,255,255,.2);
  cursor: pointer;
  transition:
    width .2s ease,
    background .2s ease;
}

.campusRecruiterDots button.active {
  width: 20px;
  background: #fff;
}


/* EMPTY */

.campusRecruiterEmpty {
  position: relative;
  z-index: 2;
  display: grid;
  min-height: 235px;
  place-items: center;
  align-content: center;
  padding: 30px;
  text-align: center;
}

.campusRecruiterEmpty > div {
  display: grid;
  width: 65px;
  height: 65px;
  place-items: center;
  border-radius: 18px;
  background: rgba(255,255,255,.08);
  color: #fff;
  font-size: 15px;
  font-weight: 800;
}

.campusRecruiterEmpty h3 {
  margin: 13px 0 5px;
  color: #fff;
  font-size: 18px;
}

.campusRecruiterEmpty p {
  max-width: 420px;
  margin: 0;
  color: #8d94a4;
  font-size: 9px;
}

.campusRecruiterEmpty button {
  margin-top: 15px;
  min-height: 36px;
  padding: 0 14px;
  border: 0;
  border-radius: 999px;
  background: #fff;
  color: #111827;
  font-size: 8px;
  font-weight: 800;
  cursor: pointer;
}


/* MODAL */

.campusRecruiterModalScrim {
  position: fixed;
  inset: 0;
  z-index: 15000;
  display: grid;
  place-items: center;
  padding: 22px;
  background: rgba(8,11,18,.56);
  backdrop-filter: blur(10px);
}

.campusRecruiterModal {
  width: min(720px,100%);
  max-height: calc(100vh - 44px);
  overflow-y: auto;
  padding: 25px;
  border: 1px solid #e2e7e5;
  border-radius: 23px;
  background: #fff;
  box-shadow:
    0 35px 100px
    rgba(10,18,15,.3);
}

.campusRecruiterModal > header {
  display: flex;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 22px;
}

.campusRecruiterModal > header span {
  color: #5564c9;
  font-size: 7px;
  font-weight: 800;
  letter-spacing: .13em;
}

.campusRecruiterModal > header h2 {
  margin: 5px 0;
  color: #26322e;
  font-size: 24px;
}

.campusRecruiterModal > header p {
  margin: 0;
  color: #858e8b;
  font-size: 8px;
}

.campusRecruiterModal > header > button {
  display: grid;
  width: 34px;
  height: 34px;
  place-items: center;
  border: 1px solid #e2e6e4;
  border-radius: 50%;
  background: #fff;
  color: #68716d;
  font-size: 18px;
  cursor: pointer;
}

.campusRecruiterFormGrid {
  display: grid;
  grid-template-columns:
    repeat(2,minmax(0,1fr));
  gap: 11px;
}

.campusRecruiterModal label {
  display: grid;
  gap: 5px;
}

.campusRecruiterModal label > span {
  color: #7d8783;
  font-size: 7px;
  font-weight: 800;
  letter-spacing: .08em;
}

.campusRecruiterModal input {
  width: 100%;
  min-height: 40px;
  padding: 0 11px;
  border: 1px solid #dfe5e2;
  border-radius: 9px;
  outline: none;
  font-size: 9px;
}

.campusRecruiterModal input:focus {
  border-color: #8d9be7;
}

.campusRecruiterRoles {
  margin-top: 11px;
}

.campusRecruiterFeatured {
  display: flex !important;
  align-items: center;
  grid-template-columns: auto 1fr;
  gap: 8px !important;
  margin-top: 14px;
}

.campusRecruiterFeatured input {
  width: 15px;
  min-height: 15px;
}

.campusRecruiterModal > footer {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  margin-top: 22px;
}


/* RESPONSIVE */

@media (max-width: 700px) {

  .campusRecruiterShowcase {
    border-radius: 20px;
  }

  .campusRecruiterHeader {
    align-items: flex-start;
    flex-direction: column;
    padding:
      0 20px 20px;
  }

  .campusRecruiterCard {
    width: 225px;
    flex-basis: 225px;
  }

  .campusRecruiterCard:first-child {
    margin-left: 20px;
  }

  .campusRecruiterFormGrid {
    grid-template-columns: 1fr;
  }

}


/* =========================================================
   CAMPUS RECRUITERS — CLICKABLE COMPANY CARDS
========================================================= */

.campusRecruiterCard.clickable {
  cursor: pointer;
  transition:
    transform .22s ease,
    border-color .22s ease,
    background .22s ease,
    box-shadow .22s ease;
}

.campusRecruiterCard.clickable:hover {
  transform: translateY(-5px);
  border-color: rgba(255,255,255,.17);
  background:
    linear-gradient(
      145deg,
      rgba(255,255,255,.13),
      rgba(255,255,255,.045)
    );
  box-shadow:
    0 22px 50px
    rgba(0,0,0,.22);
}

.campusRecruiterCard.clickable:focus-visible {
  outline: 2px solid rgba(164,178,255,.95);
  outline-offset: 3px;
}

.campusRecruiterCard.clickable .campusRecruiterLogo img {
  transition: transform .25s ease;
}

.campusRecruiterCard.clickable:hover
.campusRecruiterLogo img {
  transform: scale(1.045);
}


/* =========================================================
   CAMPUS RECRUITERS — PLACED STUDENTS
========================================================= */

.campusRecruiterSelectedFile {
  display: block;
  margin-top: 5px;
  color: #67726d;
  font-size: 7px;
}


/* -------------------------
   STUDENT EDITOR
------------------------- */

.campusRecruiterStudentEditor {
  margin-top: 22px;
  padding: 18px;
  border: 1px solid #e5e9e7;
  border-radius: 16px;
  background: #f8faf9;
}

.campusRecruiterStudentEditor > header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 18px;
  margin-bottom: 14px;
}

.campusRecruiterStudentEditor > header span {
  color: #5564c9;
  font-size: 7px;
  font-weight: 800;
  letter-spacing: .13em;
}

.campusRecruiterStudentEditor > header h3 {
  margin: 5px 0 4px;
  color: #25302c;
  font-size: 15px;
}

.campusRecruiterStudentEditor > header p {
  max-width: 430px;
  margin: 0;
  color: #858e8b;
  font-size: 8px;
  line-height: 1.6;
}

.campusRecruiterStudentEditor > header > button {
  min-height: 34px;
  padding: 0 12px;
  border: 1px solid #dfe5e2;
  border-radius: 999px;
  background: #fff;
  color: #27312d;
  font-size: 8px;
  font-weight: 750;
  cursor: pointer;
}

.campusRecruiterStudentDraft {
  margin-top: 12px;
  padding: 14px;
  border: 1px solid #e2e7e5;
  border-radius: 13px;
  background: #fff;
}

.campusRecruiterStudentDraftHead {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 11px;
}

.campusRecruiterStudentDraftHead strong {
  color: #26312d;
  font-size: 9px;
}

.campusRecruiterStudentDraftHead button {
  border: 0;
  background: none;
  color: #b84d4d;
  font-size: 7px;
  font-weight: 750;
  cursor: pointer;
}

.campusRecruiterStudentPhotoInput {
  grid-column: 1 / -1;
}

.campusRecruiterStudentPhotoInput small {
  color: #7a8580;
  font-size: 7px;
}

.campusRecruiterAddFirstStudent {
  width: 100%;
  min-height: 42px;
  margin-top: 4px;
  border: 1px dashed #cfd7d3;
  border-radius: 11px;
  background: #fff;
  color: #55645e;
  font-size: 8px;
  font-weight: 750;
  cursor: pointer;
}


/* -------------------------
   SHOW STUDENTS TOGGLE
------------------------- */

.campusRecruiterPlacedStudents {
  margin-top: 13px;
  border-top:
    1px solid
    rgba(255,255,255,.07);
  padding-top: 11px;
}

.campusRecruiterStudentToggle {
  display: grid;
  width: 100%;
  min-height: 36px;
  grid-template-columns:
    minmax(0,1fr)
    auto
    auto;
  align-items: center;
  gap: 8px;
  padding: 0 10px;
  border:
    1px solid
    rgba(255,255,255,.08);
  border-radius: 10px;
  background:
    rgba(255,255,255,.04);
  color: #d6daea;
  cursor: pointer;
  text-align: left;
  transition:
    background .18s ease,
    border-color .18s ease;
}

.campusRecruiterStudentToggle:hover,
.campusRecruiterStudentToggle.active {
  border-color:
    rgba(163,177,255,.25);
  background:
    rgba(137,153,255,.09);
}

.campusRecruiterStudentToggle span {
  font-size: 7px;
  font-weight: 750;
}

.campusRecruiterStudentToggle b {
  display: grid;
  min-width: 20px;
  height: 20px;
  place-items: center;
  border-radius: 999px;
  background:
    rgba(255,255,255,.08);
  color: #fff;
  font-size: 7px;
}

.campusRecruiterStudentToggle i {
  color: #9aa8ff;
  font-size: 9px;
  font-style: normal;
}


/* -------------------------
   EXPANDED STUDENT LIST
------------------------- */

.campusRecruiterStudentList {
  display: grid;
  gap: 7px;
  margin-top: 8px;
}

.campusRecruiterStudent {
  display: grid;
  grid-template-columns:
    34px
    minmax(0,1fr)
    auto;
  align-items: center;
  gap: 9px;
  padding: 8px;
  border:
    1px solid
    rgba(255,255,255,.065);
  border-radius: 10px;
  background:
    rgba(255,255,255,.035);
}

.campusRecruiterStudentAvatar {
  width: 34px;
  height: 34px;
  overflow: hidden;
  border-radius: 50%;
  background:
    linear-gradient(
      145deg,
      #eef1ff,
      #cfd7ff
    );
}

.campusRecruiterStudentAvatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.campusRecruiterStudentAvatar span {
  display: grid;
  width: 100%;
  height: 100%;
  place-items: center;
  color: #172038;
  font-size: 10px;
  font-weight: 850;
}

.campusRecruiterStudentIdentity {
  min-width: 0;
}

.campusRecruiterStudentIdentity strong {
  display: block;
  overflow: hidden;
  color: #fff;
  font-size: 8px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.campusRecruiterStudentIdentity small {
  display: block;
  overflow: hidden;
  margin-top: 3px;
  color: #858da0;
  font-size: 6px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.campusRecruiterStudentPackage {
  text-align: right;
}

.campusRecruiterStudentPackage b {
  display: block;
  color: #a9b5ff;
  font-size: 8px;
}

.campusRecruiterStudentPackage small {
  display: block;
  margin-top: 2px;
  color: #6f7788;
  font-size: 5px;
}


/* cards must expand when student list opens */

.campusRecruiterCard {
  align-self: flex-start;
}


/* smooth expanded list */

.campusRecruiterStudentList {
  animation:
    campusRecruiterStudentReveal
    .22s ease both;
}

@keyframes campusRecruiterStudentReveal {

  from {
    opacity: 0;
    transform:
      translateY(-5px);
  }

  to {
    opacity: 1;
    transform:
      translateY(0);
  }

}


@media (max-width: 700px) {

  .campusRecruiterStudentEditor > header {
    flex-direction: column;
  }

  .campusRecruiterStudentDraft
  .campusRecruiterFormGrid {
    grid-template-columns: 1fr;
  }

}


/* =========================================================
   CAMPUSCONNECT PRO — ACADEMICS
========================================================= */

.academicCenterPro {
  display: grid;
  gap: 20px;
}


/* HERO */

.academicProHero {
  position: relative;
  display: grid;
  grid-template-columns:
    minmax(0,1fr)
    300px;
  min-height: 320px;
  overflow: hidden;
  border-radius: 28px;
  color: #fff;
  background:
    radial-gradient(
      circle at 84% 10%,
      rgba(83,113,255,.27),
      transparent 30%
    ),
    radial-gradient(
      circle at 10% 100%,
      rgba(53,178,151,.15),
      transparent 34%
    ),
    linear-gradient(
      135deg,
      #09111e,
      #111d32 50%,
      #071018
    );
  box-shadow:
    0 28px 75px
    rgba(15,25,43,.17);
}

.academicProHeroGlow {
  position: absolute;
  width: 320px;
  height: 320px;
  top: -165px;
  right: 25%;
  border-radius: 50%;
  background:
    rgba(83,111,255,.2);
  filter: blur(85px);
}

.academicProHeroContent {
  position: relative;
  z-index: 2;
  align-self: center;
  padding: 48px;
}

.academicProHeroContent > span {
  color: #95a5ff;
  font-size: 8px;
  font-weight: 850;
  letter-spacing: .17em;
}

.academicProHeroContent h1 {
  max-width: 760px;
  margin: 14px 0 16px;
  font-size:
    clamp(35px,4.4vw,58px);
  font-weight: 620;
  line-height: .99;
  letter-spacing: -.055em;
}

.academicProHeroContent > p {
  max-width: 610px;
  margin: 0;
  color: #9ea9b9;
  font-size: 10px;
  line-height: 1.8;
}

.academicProIdentity {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 9px;
  margin-top: 25px;
  color: #bdc6d5;
  font-size: 8px;
}

.academicProIdentity i {
  width: 3px;
  height: 3px;
  border-radius: 50%;
  background: #616c7e;
}


/* CONNECTION */

.academicProConnection {
  position: relative;
  z-index: 2;
  display: grid;
  align-content: center;
  gap: 10px;
  padding: 30px;
}

.academicConnectionStatus {
  padding: 21px;
  border:
    1px solid
    rgba(255,255,255,.1);
  border-radius: 18px;
  background:
    rgba(255,255,255,.055);
  backdrop-filter:
    blur(18px);
}

.academicConnectionStatus > span {
  display: flex;
  align-items: center;
  gap: 7px;
  color: #929dad;
  font-size: 7px;
  font-weight: 800;
  letter-spacing: .1em;
}

.academicConnectionStatus
> span i {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #707a8a;
}

.academicConnectionStatus.connected
> span i {
  background: #48d48a;
  box-shadow:
    0 0 0 4px
    rgba(72,212,138,.11);
}

.academicConnectionStatus strong {
  display: block;
  margin: 15px 0 5px;
  color: #fff;
  font-size: 15px;
}

.academicConnectionStatus small {
  display: block;
  color: #8f99aa;
  font-size: 8px;
  line-height: 1.65;
}

.academicProConnection > button {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 44px;
  padding: 0 15px;
  border: 0;
  border-radius: 12px;
  background: #fff;
  color: #142034;
  font-size: 8px;
  font-weight: 800;
  cursor: pointer;
}

.academicProConnection
> button span {
  font-size: 15px;
}


/* TOOLBAR */

.academicProToolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.academicProTabs {
  display: flex;
  gap: 4px;
  padding: 5px;
  overflow-x: auto;
  border:
    1px solid #e1e6ed;
  border-radius: 14px;
  background: #fff;
}

.academicProTabs button {
  min-height: 36px;
  padding: 0 14px;
  border: 0;
  border-radius: 9px;
  background: transparent;
  color: #778294;
  font-size: 8px;
  font-weight: 750;
  white-space: nowrap;
  cursor: pointer;
}

.academicProTabs button.active {
  background: #172338;
  color: #fff;
  box-shadow:
    0 6px 16px
    rgba(23,35,56,.16);
}

.academicProFilters {
  display: flex;
  gap: 8px;
}

.academicProFilters select {
  min-height: 40px;
  padding: 0 31px 0 11px;
  border: 1px solid #e0e5ec;
  border-radius: 10px;
  background: #fff;
  color: #566176;
  font-size: 8px;
}

.academicProFilters label {
  display: flex;
  align-items: center;
  gap: 7px;
  min-width: 220px;
  min-height: 40px;
  padding: 0 11px;
  border: 1px solid #e0e5ec;
  border-radius: 10px;
  background: #fff;
}

.academicProFilters label span {
  color: #929cac;
}

.academicProFilters input {
  width: 100%;
  border: 0;
  outline: 0;
  background: transparent;
  color: #28364b;
  font-size: 8px;
}


/* METRICS */

.academicProMetrics {
  display: grid;
  grid-template-columns:
    repeat(4,minmax(0,1fr));
  gap: 13px;
}

.academicProMetrics article {
  min-height: 138px;
  padding: 20px;
  border: 1px solid #e5e9ef;
  border-radius: 18px;
  background:
    linear-gradient(
      145deg,
      #fff,
      #fbfcfe
    );
  box-shadow:
    0 12px 32px
    rgba(22,34,55,.045);
}

.academicProMetrics article.attention {
  background:
    linear-gradient(
      145deg,
      #fff,
      #fff9f9
    );
}

.academicProMetrics article > span {
  color: #8a95a6;
  font-size: 7px;
  font-weight: 850;
  letter-spacing: .12em;
}

.academicProMetrics strong {
  display: block;
  margin: 12px 0 5px;
  color: #172238;
  font-size: 29px;
  letter-spacing: -.045em;
}

.academicProMetrics p {
  margin: 0;
  color: #8792a3;
  font-size: 7px;
}

.academicProMetrics
article > div {
  height: 4px;
  margin-top: 15px;
  overflow: hidden;
  border-radius: 999px;
  background: #edf0f4;
}

.academicProMetrics
article > div i {
  display: block;
  height: 100%;
  border-radius: inherit;
  background:
    linear-gradient(
      90deg,
      #3159d9,
      #6c85e6
    );
}


/* OVERVIEW */

.academicProOverview {
  display: grid;
  grid-template-columns:
    minmax(0,1.55fr)
    minmax(280px,.7fr);
  gap: 16px;
}

.academicProOverview > main,
.academicProOverview > aside {
  display: grid;
  align-content: start;
  gap: 16px;
}

.academicProPanel {
  padding: 22px;
  border: 1px solid #e4e8ee;
  border-radius: 19px;
  background: #fff;
  box-shadow:
    0 13px 34px
    rgba(22,34,55,.045);
}

.academicProPanel > header {
  display: flex;
  align-items: center;
  justify-content:
    space-between;
  gap: 15px;
  margin-bottom: 17px;
}

.academicProPanel
> header span {
  color: #3159d9;
  font-size: 7px;
  font-weight: 850;
  letter-spacing: .12em;
}

.academicProPanel
> header h2 {
  margin: 5px 0 0;
  color: #1e2b41;
  font-size: 15px;
}

.academicProPanel
> header button {
  border: 0;
  background: none;
  color: #3159d9;
  font-size: 7px;
  font-weight: 750;
  cursor: pointer;
}


/* TODAY */

.academicTodaySchedule {
  display: grid;
}

.academicTodaySchedule article {
  display: grid;
  grid-template-columns:
    58px
    minmax(0,1fr)
    auto;
  align-items: center;
  gap: 12px;
  min-height: 66px;
  border-top:
    1px solid #edf0f4;
}

.academicTodaySchedule time {
  color: #3159d9;
  font-size: 8px;
  font-weight: 850;
}

.academicTodaySchedule
article > div strong {
  display: block;
  color: #26344a;
  font-size: 9px;
}

.academicTodaySchedule
article > div small {
  display: block;
  margin-top: 4px;
  color: #8a95a6;
  font-size: 7px;
}

.academicTodaySchedule
article > span {
  color: #7e899a;
  font-size: 7px;
}


/* ATTENDANCE */

.academicAttendanceRows {
  display: grid;
}

.academicAttendanceRows article {
  display: grid;
  grid-template-columns:
    minmax(160px,.9fr)
    minmax(120px,1fr)
    50px;
  align-items: center;
  gap: 15px;
  padding: 13px 0;
  border-top:
    1px solid #edf0f4;
}

.academicAttendanceRows
article > div:first-child
strong {
  display: block;
  color: #29364a;
  font-size: 9px;
}

.academicAttendanceRows
article > div:first-child
small {
  display: block;
  margin-top: 3px;
  color: #8b95a5;
  font-size: 7px;
}

.academicAttendanceTrack i,
.academicMarksProgress i {
  display: block;
  height: 5px;
  overflow: hidden;
  border-radius: 999px;
  background: #edf0f4;
}

.academicAttendanceTrack
i span,
.academicMarksProgress
i span {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: #3159d9;
}

.academicAttendanceRows b {
  text-align: right;
  font-size: 10px;
}

.academicAttendanceRows b.safe {
  color: #17815b;
}

.academicAttendanceRows b.risk {
  color: #c14d59;
}


/* UPCOMING */

.academicUpcoming {
  display: grid;
}

.academicUpcoming article {
  display: grid;
  grid-template-columns:
    38px
    minmax(0,1fr);
  gap: 11px;
  padding: 12px 0;
  border-top:
    1px solid #edf0f4;
}

.academicUpcoming time {
  display: grid;
  width: 36px;
  height: 43px;
  align-content: center;
  border-radius: 9px;
  background: #f0f3fb;
  text-align: center;
}

.academicUpcoming time strong {
  color: #3159d9;
  font-size: 12px;
}

.academicUpcoming time small {
  color: #8390a4;
  font-size: 5px;
}

.academicUpcoming
article > div > span {
  color: #3159d9;
  font-size: 6px;
  font-weight: 850;
}

.academicUpcoming
article > div > strong {
  display: block;
  margin-top: 4px;
  color: #29364a;
  font-size: 8px;
}

.academicUpcoming
article > div > small {
  display: block;
  margin-top: 3px;
  color: #8c96a6;
  font-size: 6px;
}


/* FEE SNAPSHOT */

.academicProFeeStatus
> strong {
  display: block;
  color: #1c293e;
  font-size: 36px;
}

.academicProFeeStatus > p {
  margin: 5px 0 16px;
  color: #8590a2;
  font-size: 8px;
}

.academicProFeeStatus
> button {
  padding: 0;
  border: 0;
  background: none;
  color: #3159d9;
  font-size: 8px;
  font-weight: 750;
  cursor: pointer;
}


/* SECTION */

.academicProSection {
  padding: 25px;
  border: 1px solid #e4e8ee;
  border-radius: 20px;
  background: #fff;
  box-shadow:
    0 14px 38px
    rgba(22,34,55,.045);
}

.academicProSectionHeading {
  display: flex;
  align-items: flex-end;
  justify-content:
    space-between;
  gap: 18px;
  margin-bottom: 23px;
}

.academicProSectionHeading
span {
  color: #3159d9;
  font-size: 7px;
  font-weight: 850;
  letter-spacing: .13em;
}

.academicProSectionHeading h2 {
  margin: 5px 0;
  color: #1e2a40;
  font-size: 20px;
}

.academicProSectionHeading p {
  margin: 0;
  color: #8490a2;
  font-size: 8px;
}

.academicProSectionHeading
> strong {
  padding: 7px 10px;
  border-radius: 999px;
  background: #edf2ff;
  color: #3159d9;
  font-size: 7px;
}


/* SUBJECT CARDS */

.academicSubjectCards {
  display: grid;
  grid-template-columns:
    repeat(3,minmax(0,1fr));
  gap: 12px;
}

.academicSubjectCards
> article {
  padding: 18px;
  border: 1px solid #e4e8ed;
  border-radius: 17px;
  background:
    linear-gradient(
      145deg,
      #fff,
      #fafbfe
    );
  transition:
    transform .2s ease,
    box-shadow .2s ease;
}

.academicSubjectCards
> article:hover {
  transform:
    translateY(-3px);
  box-shadow:
    0 17px 38px
    rgba(24,38,65,.08);
}

.academicSubjectCards
article > header {
  display: flex;
  align-items: center;
  justify-content:
    space-between;
}

.academicSubjectCards
header span {
  color: #3159d9;
  font-size: 6px;
  font-weight: 850;
  letter-spacing: .09em;
}

.academicSubjectCards
header code {
  color: #7a8596;
  font-size: 7px;
}

.academicSubjectCards h3 {
  min-height: 36px;
  margin: 18px 0 5px;
  color: #223047;
  font-size: 13px;
  line-height: 1.35;
}

.academicSubjectCards
> article > p {
  min-height: 25px;
  margin: 0;
  color: #8994a5;
  font-size: 7px;
}

.academicSubjectStats {
  display: grid;
  grid-template-columns:
    repeat(3,1fr);
  gap: 6px;
  margin-top: 18px;
}

.academicSubjectStats > div {
  padding: 9px;
  border-radius: 9px;
  background: #f5f7fb;
}

.academicSubjectStats small {
  display: block;
  color: #929baa;
  font-size: 5px;
}

.academicSubjectStats strong {
  display: block;
  margin-top: 5px;
  color: #273449;
  font-size: 10px;
}


/* MARKS */

.academicMarksProTable {
  overflow: hidden;
  border: 1px solid #e5e8ed;
  border-radius: 14px;
}

.academicMarksProTable
> header,
.academicMarksProTable
> article {
  display: grid;
  grid-template-columns:
    minmax(180px,1.4fr)
    minmax(100px,.8fr)
    100px
    minmax(120px,.8fr);
  align-items: center;
  gap: 14px;
  padding: 12px 15px;
}

.academicMarksProTable
> header {
  background: #f7f8fb;
  color: #8691a2;
  font-size: 6px;
  font-weight: 850;
  letter-spacing: .09em;
}

.academicMarksProTable
> article {
  border-top:
    1px solid #edf0f4;
}

.academicMarksProTable
article > div:first-child
strong {
  display: block;
  color: #29364a;
  font-size: 9px;
}

.academicMarksProTable
article > div:first-child
small {
  display: block;
  margin-top: 3px;
  color: #8590a1;
  font-size: 7px;
}

.academicMarksProTable
article > span {
  color: #8590a1;
  font-size: 7px;
}

.academicMarksProTable
article > strong {
  color: #243148;
  font-size: 9px;
}

.academicMarksProgress {
  display: grid;
  grid-template-columns:
    minmax(0,1fr)
    32px;
  align-items: center;
  gap: 8px;
}

.academicMarksProgress small {
  color: #7d8899;
  font-size: 7px;
}


/* RESULTS */

.academicResultCards {
  display: grid;
  grid-template-columns:
    repeat(3,minmax(0,1fr));
  gap: 12px;
}

.academicResultCards
> article {
  overflow: hidden;
  border:
    1px solid #e2e7ed;
  border-radius: 17px;
  background: #fff;
}

.academicResultCards
article > header {
  display: flex;
  align-items: center;
  justify-content:
    space-between;
  padding: 17px;
  background:
    linear-gradient(
      135deg,
      #f4f7ff,
      #fff
    );
}

.academicResultCards
header small {
  display: block;
  color: #8490a3;
  font-size: 6px;
  font-weight: 850;
}

.academicResultCards
header strong {
  display: block;
  margin-top: 4px;
  color: #233149;
  font-size: 25px;
}

.academicResultCards
header > span {
  padding: 5px 8px;
  border-radius: 999px;
  background: #e9f8f1;
  color: #16815a;
  font-size: 6px;
  font-weight: 800;
}

.academicResultStats {
  display: grid;
  grid-template-columns:
    repeat(3,1fr);
  padding: 16px;
}

.academicResultStats > div {
  text-align: center;
}

.academicResultStats
> div:not(:last-child) {
  border-right:
    1px solid #edf0f4;
}

.academicResultStats small {
  display: block;
  color: #9099a7;
  font-size: 5px;
}

.academicResultStats strong {
  display: block;
  margin-top: 5px;
  color: #26344a;
  font-size: 15px;
}

.academicResultCards footer {
  display: flex;
  justify-content:
    space-between;
  align-items: center;
  padding: 11px 16px;
  border-top:
    1px solid #edf0f4;
  color: #8590a2;
  font-size: 7px;
}


/* TIMETABLE */

.academicWeek {
  display: grid;
}

.academicDay {
  display: grid;
  grid-template-columns:
    115px
    minmax(0,1fr);
  border-top:
    1px solid #edf0f4;
}

.academicDay > header {
  padding: 18px 12px 18px 0;
}

.academicDay
> header strong {
  display: block;
  color: #263449;
  font-size: 10px;
}

.academicDay
> header small {
  display: block;
  margin-top: 4px;
  color: #919baa;
  font-size: 6px;
}

.academicDay > div {
  display: grid;
}

.academicDay article {
  display: grid;
  grid-template-columns:
    72px
    minmax(0,1fr);
  gap: 15px;
  padding: 15px;
  border-left:
    1px solid #edf0f4;
  border-bottom:
    1px solid #edf0f4;
}

.academicDay time strong,
.academicDay time small {
  display: block;
}

.academicDay time strong {
  color: #3159d9;
  font-size: 8px;
}

.academicDay time small {
  margin-top: 4px;
  color: #929cab;
  font-size: 6px;
}

.academicDay
article > div > span {
  color: #3159d9;
  font-size: 6px;
  font-weight: 850;
}

.academicDay h3 {
  margin: 5px 0 3px;
  color: #26344a;
  font-size: 10px;
}

.academicDay p {
  margin: 0;
  color: #8792a3;
  font-size: 7px;
}


/* FEES */

.academicFeeRows {
  display: grid;
}

.academicFeeRows article {
  display: grid;
  grid-template-columns:
    42px
    minmax(0,1fr)
    auto
    auto;
  align-items: center;
  gap: 14px;
  min-height: 80px;
  border-top:
    1px solid #edf0f4;
}

.academicFeeRows
article > i {
  display: grid;
  width: 38px;
  height: 38px;
  place-items: center;
  border-radius: 11px;
  background: #edf2ff;
  color: #3159d9;
  font-size: 12px;
  font-style: normal;
  font-weight: 850;
}

.academicFeeRows
article > div:nth-child(2)
> span {
  color: #3159d9;
  font-size: 6px;
  font-weight: 850;
}

.academicFeeRows h3 {
  margin: 4px 0 2px;
  color: #26344a;
  font-size: 10px;
}

.academicFeeRows p {
  margin: 0;
  color: #8b95a5;
  font-size: 7px;
}

.academicFeeValue {
  text-align: right;
}

.academicFeeValue strong {
  display: block;
  color: #253249;
  font-size: 11px;
}

.academicFeeValue span {
  display: inline-block;
  margin-top: 5px;
  padding: 4px 7px;
  border-radius: 999px;
  font-size: 6px;
  font-weight: 850;
}

.academicFeeValue
span.paid {
  background: #e9f8f1;
  color: #16815a;
}

.academicFeeValue
span.pending {
  background: #fff1f2;
  color: #b54250;
}

.academicFeeRows a {
  color: #3159d9;
  font-size: 7px;
  font-weight: 750;
  text-decoration: none;
}


/* EMPTY / LOADING */

.academicProLoading {
  display: grid;
  min-height: 260px;
  place-items: center;
  align-content: center;
  gap: 12px;
  border:
    1px solid #e4e8ef;
  border-radius: 18px;
  background: #fff;
}

.academicProLoading i {
  width: 27px;
  height: 27px;
  border: 3px solid #e4e9f2;
  border-top-color: #3159d9;
  border-radius: 50%;
  animation:
    academicProSpin
    .7s linear infinite;
}

.academicProLoading span {
  color: #7f8a9b;
  font-size: 8px;
}

@keyframes academicProSpin {
  to {
    transform: rotate(360deg);
  }
}


/* STAFF */

.academicStaffHero {
  display: flex;
  align-items: center;
  justify-content:
    space-between;
  gap: 25px;
  min-height: 220px;
  padding: 35px;
  border-radius: 24px;
  color: #fff;
  background:
    radial-gradient(
      circle at 84% 12%,
      rgba(83,192,153,.2),
      transparent 32%
    ),
    linear-gradient(
      135deg,
      #0b1916,
      #173329
    );
}

.academicStaffHero
> div:first-child > span {
  color: #76d2ad;
  font-size: 7px;
  font-weight: 850;
  letter-spacing: .13em;
}

.academicStaffHero h2 {
  margin: 8px 0;
  font-size: 27px;
  letter-spacing: -.03em;
}

.academicStaffHero p {
  max-width: 620px;
  margin: 0;
  color: #a3b7b0;
  font-size: 9px;
  line-height: 1.75;
}

.academicStaffHeroActions {
  display: flex;
  gap: 8px;
}

.academicStaffActionGrid {
  display: grid;
  grid-template-columns:
    repeat(3,1fr);
  gap: 14px;
}

.academicStaffActionGrid
> button {
  display: grid;
  grid-template-columns:
    42px
    minmax(0,1fr)
    auto;
  align-items: center;
  gap: 12px;
  padding: 20px;
  border: 0;
  text-align: left;
  cursor: pointer;
}

.academicStaffActionGrid
> button > i {
  display: grid;
  width: 40px;
  height: 40px;
  place-items: center;
  border-radius: 11px;
  background: #e5f3ed;
  color: #26735c;
  font-style: normal;
  font-weight: 850;
}

.academicStaffActionGrid span {
  color: #26735c;
  font-size: 6px;
  font-weight: 850;
}

.academicStaffActionGrid h3 {
  margin: 4px 0;
  color: #22332d;
  font-size: 11px;
}

.academicStaffActionGrid p {
  margin: 0;
  color: #7f8d88;
  font-size: 7px;
  line-height: 1.55;
}

.academicStaffActionGrid
> button > strong {
  color: #26735c;
}


/* RESPONSIVE */

@media(max-width:1050px) {

  .academicProHero {
    grid-template-columns:
      minmax(0,1fr)
      260px;
  }

  .academicProMetrics {
    grid-template-columns:
      repeat(2,1fr);
  }

  .academicSubjectCards,
  .academicResultCards {
    grid-template-columns:
      repeat(2,1fr);
  }

}

@media(max-width:850px) {

  .academicProHero {
    grid-template-columns: 1fr;
  }

  .academicProConnection {
    padding-top: 0;
  }

  .academicProOverview {
    grid-template-columns: 1fr;
  }

  .academicProToolbar {
    align-items: stretch;
    flex-direction: column;
  }

  .academicStaffActionGrid {
    grid-template-columns: 1fr;
  }

}

@media(max-width:650px) {

  .academicProHeroContent {
    padding:
      32px 24px 22px;
  }

  .academicProConnection {
    padding:
      0 24px 25px;
  }

  .academicProMetrics {
    grid-template-columns:
      repeat(2,1fr);
  }

  .academicProFilters {
    flex-direction: column;
  }

  .academicProFilters label {
    min-width: 0;
  }

  .academicSubjectCards,
  .academicResultCards {
    grid-template-columns: 1fr;
  }

  .academicMarksProTable
  > header {
    display: none;
  }

  .academicMarksProTable
  > article {
    grid-template-columns:
      minmax(0,1fr)
      auto;
  }

  .academicMarksProgress {
    grid-column: 1 / -1;
  }

  .academicDay {
    grid-template-columns: 1fr;
  }

  .academicDay > header {
    padding: 15px 0;
  }

  .academicFeeRows article {
    grid-template-columns:
      40px
      minmax(0,1fr);
    padding: 13px 0;
  }

  .academicFeeValue,
  .academicFeeRows a {
    grid-column: 2;
    justify-self: start;
    text-align: left;
  }

  .academicStaffHero {
    align-items: flex-start;
    flex-direction: column;
  }

}

@media(max-width:430px) {

  .academicProMetrics {
    grid-template-columns: 1fr;
  }

  .academicAttendanceRows
  article {
    grid-template-columns:
      minmax(0,1fr)
      50px;
  }

  .academicAttendanceTrack {
    grid-column: 1 / -1;
    grid-row: 2;
  }

}


/* =========================================================
   CAMPUS — FESTIVAL SECTION
========================================================= */

.campusFestivalSection {
  display: grid;
  gap: 22px;
  margin-top: 4px;
}


.campusFestivalHeading {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 22px;
  padding: 5px 2px;
}


.campusFestivalHeading > div > span {
  color: #a15527;
  font-size: 7px;
  font-weight: 850;
  letter-spacing: .16em;
}


.campusFestivalHeading h2 {
  margin: 7px 0 6px;
  color: #25211e;
  font-size: clamp(
    24px,
    3vw,
    36px
  );
  font-weight: 620;
  letter-spacing: -.045em;
}


.campusFestivalHeading p {
  max-width: 650px;
  margin: 0;
  color: #8b837c;
  font-size: 9px;
  line-height: 1.7;
}


.campusFestivalHeading > strong {
  padding: 8px 11px;
  border: 1px solid #eadfd4;
  border-radius: 999px;
  background: #fffaf5;
  color: #945027;
  font-size: 7px;
}


/* GRID */

.campusFestivalGrid {
  display: grid;
  grid-template-columns:
    repeat(
      2,
      minmax(0,1fr)
    );
  gap: 17px;
}


/* FESTIVAL CARD */

.campusFestivalCard {
  position: relative;
  overflow: hidden;
  border:
    1px solid
    rgba(118,85,59,.13);
  border-radius: 24px;
  background:
    radial-gradient(
      circle at 90% 0%,
      rgba(240,177,82,.13),
      transparent 35%
    ),
    linear-gradient(
      145deg,
      #fffdf9,
      #fff8ef
    );
  box-shadow:
    0 20px 55px
    rgba(91,62,39,.07);
}


.campusFestivalCard.hasBanner {
  background: #fff;
}


.campusFestivalImage {
  display: block;
  width: 100%;
  height: 245px;
  padding: 0;
  overflow: hidden;
  border: 0;
  background: #f5eee6;
  cursor: zoom-in;
}


.campusFestivalImage img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
  transition:
    transform .5s
    cubic-bezier(
      .22,.8,.25,1
    );
}


.campusFestivalImage:hover img {
  transform: scale(1.025);
}


/* CONTENT */

.campusFestivalContent {
  padding: 24px;
}


.campusFestivalMeta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}


.campusFestivalMeta > span {
  color: #ad5b2a;
  font-size: 7px;
  font-weight: 900;
  letter-spacing: .17em;
}


.campusFestivalMeta time {
  color: #9b9188;
  font-size: 7px;
}


.campusFestivalContent h3 {
  margin: 16px 0 9px;
  color: #28221e;
  font-size: 20px;
  font-weight: 640;
  letter-spacing: -.035em;
}


.campusFestivalContent > p {
  min-height: 42px;
  margin: 0;
  color: #81776f;
  font-size: 9px;
  line-height: 1.75;
}


.campusFestivalContent footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
  margin-top: 22px;
  padding-top: 17px;
  border-top:
    1px solid
    rgba(104,82,65,.09);
}


.campusFestivalContent
footer > div small {
  display: block;
  color: #aaa097;
  font-size: 6px;
}


.campusFestivalContent
footer > div strong {
  display: block;
  margin-top: 3px;
  color: #514841;
  font-size: 8px;
}


.campusFestivalContent footer a {
  display: inline-flex;
  align-items: center;
  min-height: 34px;
  padding: 0 12px;
  border-radius: 999px;
  background: #2c2825;
  color: #fff;
  font-size: 7px;
  font-weight: 800;
  text-decoration: none;
}


/* EMPTY */

.campusFestivalEmpty {
  display: grid;
  min-height: 320px;
  place-items: center;
  align-content: center;
  padding: 40px;
  border:
    1px dashed
    #ddcfc1;
  border-radius: 24px;
  background:
    linear-gradient(
      145deg,
      #fffdf9,
      #fff8ef
    );
  text-align: center;
}


.campusFestivalEmpty > div {
  display: grid;
  width: 58px;
  height: 58px;
  place-items: center;
  border-radius: 18px;
  background:
    #f4e4d4;
  color: #9f592f;
  font-size: 22px;
}


.campusFestivalEmpty h3 {
  margin: 16px 0 6px;
  color: #372f29;
  font-size: 17px;
}


.campusFestivalEmpty p {
  max-width: 430px;
  margin: 0;
  color: #8d8278;
  font-size: 8px;
  line-height: 1.7;
}


.campusFestivalEmpty button {
  margin-top: 18px;
  min-height: 38px;
  padding: 0 15px;
  border: 0;
  border-radius: 999px;
  background: #2c2825;
  color: #fff;
  font-size: 7px;
  font-weight: 800;
  cursor: pointer;
}


/* MOBILE */

@media(max-width:800px) {

  .campusFestivalGrid {
    grid-template-columns: 1fr;
  }

}


@media(max-width:560px) {

  .campusFestivalHeading {
    align-items: flex-start;
    flex-direction: column;
  }

  .campusFestivalImage {
    height: 190px;
  }

  .campusFestivalContent {
    padding: 19px;
  }

}


/* =========================================================
   CAMPUSCONNECT — FESTIVAL PUBLISHING
========================================================= */

