  font-size: 17px;
}

.festivalPublishControls > header p {
  margin: 0;
  color: #887e75;
  font-size: 8px;
}

.festivalControlGrid,
.festivalToggleGrid {
  display: grid;
  grid-template-columns:
    repeat(
