  margin: 0;
  color: #75695f;
  font-size: 11px;
  line-height: 1.75;
}

.dashboardFestivalFooter {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  margin-top: 28px;
}

.dashboardFestivalFooter > small {
  color: #95887c;
  font-size: 8px;
}

.dashboardFestivalFooter > div {
  display: flex;
  align-items: center;
  gap: 7px;
