/* =========================================================
   FESTIVAL WELCOME POPUP
========================================================= */

.festivalWelcomeToast {
  position: fixed;
  top: 92px;
  left: 50%;
  z-index: 18000;
  width:
    min(
      520px,
      calc(
        100vw - 30px
      )
    );
  padding: 24px 52px 24px 24px;
  border: 1px solid rgba(255,255,255,.5);
  border-radius: 20px;
  background:
    rgba(
      29,
      24,
      20,
      .94
    );
  box-shadow:
    0 28px 90px
    rgba(0,0,0,.28);
  color: #fff;
  backdrop-filter:
    blur(24px);
  transform:
    translateX(-50%);
  animation:
    campusFestivalWelcome
    .45s
    cubic-bezier(
      .22,
      .8,
      .25,
      1
    );
}

.festivalWelcomeToast > span {
  color: #f8c170;
  font-size: 7px;
  font-weight: 850;
  letter-spacing: .15em;
}

.festivalWelcomeToast strong {
  display: block;
  margin: 8px 0 7px;
  font-size: 18px;
}

.festivalWelcomeToast p {
  margin: 0;
  color: rgba(255,255,255,.66);
  font-size: 9px;
  line-height: 1.65;
}

.festivalWelcomeToast button {
  position: absolute;
  top: 14px;
  right: 14px;
  display: grid;
  width: 29px;
  height: 29px;
  place-items: center;
  border: 1px solid rgba(255,255,255,.12);
  border-radius: 50%;
  background: rgba(255,255,255,.08);
  color: #fff;
  font-size: 16px;
  cursor: pointer;
}


/* =========================================================
   CELEBRATION BURST
========================================================= */

.festivalCelebrationBurst {
  position: fixed;
  inset: 0;
  z-index: 17000;
  overflow: hidden;
  pointer-events: none;
}

.festivalCelebrationBurst i {
  --festival-x: 50vw;
  --festival-delay: 0s;
  --festival-duration: 3s;
  --festival-rotate: 360deg;

  position: absolute;
  top: -20px;
  left: var(--festival-x);
  width: 9px;
  height: 14px;
  border-radius: 3px;
  background:
    hsl(
      calc(
        var(--festival-x) * 3
      ),
      72%,
      58%
    );
  animation:
    campusFestivalConfetti
    var(--festival-duration)
    var(--festival-delay)
    ease-in
    forwards;
}

.festivalCelebrationBurst i:nth-child(3n) {
  border-radius: 50%;
}

.festivalCelebrationBurst i:nth-child(4n) {
  width: 12px;
  height: 6px;
}

@keyframes campusFestivalConfetti {
  0% {
    transform:
      translateY(-20px)
      rotate(0deg);
    opacity: 0;
  }

  10% {
    opacity: 1;
  }

  100% {
    transform:
      translateY(
        calc(
          100vh + 50px
        )
      )
      rotate(
        var(--festival-rotate)
      );
    opacity: .8;
  }
}

@keyframes campusFestivalWelcome {
  from {
    opacity: 0;
    transform:
      translateX(-50%)
      translateY(-15px)
      scale(.97);
  }

  to {
    opacity: 1;
    transform:
      translateX(-50%)
      translateY(0)
      scale(1);
  }
}


@media(max-width:820px) {

  .dashboardFestivalBanner {
    grid-template-columns:
      1fr;
  }

  .dashboardFestivalArtwork {
    min-height: 220px;
    max-height: 280px;
  }

  .dashboardFestivalArtwork img {
    min-height: 220px;
  }

  .festivalControlGrid,
  .festivalToggleGrid {
    grid-template-columns:
      1fr;
  }

}


@media(max-width:560px) {

  .dashboardFestivalBody {
    padding: 23px;
  }

  .dashboardFestivalFooter {
    align-items:
      flex-start;
    flex-direction:
      column;
  }

}


/* =========================================================
   CAMPUSCONNECT — ANNOUNCEMENT ACTION LAYOUT FIX
========================================================= */

/*
  Keep every announcement card self-contained.
  This prevents Edit / Pin / Delete from escaping the card.
*/

.campusAnnouncementsSection article,
.campusAnnouncementCard,
.announcementCard,
.campusAnnouncementItem {
  position: relative !important;
  min-width: 0 !important;
  overflow: hidden !important;
}


/* Known / detected action wrappers */

.announcementCardActionsFixed,
.campusAnnouncementActions,
.announcementActions,
.announcementCardActions,
.campusAnnouncementCardActions {
  position: static !important;

  inset: auto !important;
  top: auto !important;
  right: auto !important;
  bottom: auto !important;
  left: auto !important;

  display: flex !important;
  align-items: center !important;
  justify-content: flex-end !important;
  flex-wrap: wrap !important;

  width: 100% !important;

  gap: 7px !important;

  margin: 16px 0 0 !important;
  padding: 14px 0 0 !important;

  border-top:
    1px solid
    rgba(80,67,55,.09) !important;

  transform: none !important;
}


/*
  Your current JSX places the management button container near
  the bottom of each announcement article. This catches it even
  when the original class name differs.
*/

.campusAnnouncementsSection
article
> div:last-child:has(> button) {
  position: static !important;

  inset: auto !important;

  display: flex !important;
  align-items: center !important;
  justify-content: flex-end !important;
  flex-wrap: wrap !important;

  width: 100% !important;

  gap: 7px !important;

  margin-top: 15px !important;
  padding-top: 13px !important;

  transform: none !important;
}


/* Actual buttons */

.campusAnnouncementsSection
article
button {
  max-width: 100%;
}


.campusAnnouncementsSection
article
> div:last-child:has(> button)
> button,

.announcementCardActionsFixed
button,

.campusAnnouncementActions
button,

.announcementActions
button,

.announcementCardActions
button,

.campusAnnouncementCardActions
button {
  position: static !important;

  inset: auto !important;

  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;

  width: auto !important;
  min-width: 58px !important;
  min-height: 32px !important;

  margin: 0 !important;

  padding:
    0
    11px !important;

  border:
    1px solid
    #e5ddd4 !important;

  border-radius:
    9px !important;

  background:
    #fff !important;

  color:
    #65584d !important;

  font-size:
    7px !important;

  font-weight:
    800 !important;

  white-space:
    nowrap !important;

  transform:
    none !important;

  cursor:
    pointer !important;
}


.campusAnnouncementsSection
article
> div:last-child:has(> button)
> button:hover,

.announcementCardActionsFixed
button:hover {
  background:
    #f7f2ec !important;

  border-color:
    #d8c9ba !important;
}


/* Delete stays clearly destructive */

.campusAnnouncementsSection
article
button[class*="delete" i],

.campusAnnouncementsSection
article
button[class*="danger" i],

.announcementCardActionsFixed
button:last-child {
  color:
    #b14b42 !important;

  border-color:
    #edd3cf !important;

  background:
    #fffafa !important;
}


