 */

.activityCenter.activityClubPageMode
> .activityHero,

.activityCenter.activityClubPageMode
> .activityTabs,

.activityCenter.activityClubPageMode
> .activityDiscovery,

.activityCenter.activityClubPageMode
> .activityClubGrid,

.activityCenter.activityClubPageMode
> .activityLoading,

.activityCenter.activityClubPageMode
> .activitySportsWorkspace {
