.facultyCardInfo {
  padding:
    20px 19px
    17px;
}


.facultyCardInfo > span {
  color: #ac7137;

  font-size: 7px;

  font-weight: 800;

  letter-spacing: .14em;
}


.facultyCardInfo h3 {
