    #e6ddd2;

  border-radius: 9px;

  outline: none;

  background:
    #fffcf8;

  color: #3f372f;

  font: inherit;

  font-size: 8px;
}


.facultyEditorGrid textarea {
  resize: vertical;
}


.facultyEditorFull {
  grid-column:
    1 / -1;
}


.facultyEditorChecks {
  display: flex;

  flex-wrap: wrap;

  gap: 15px;

  margin-top: 18px;
}


.facultyEditorChecks label {
  display: flex;

  align-items: center;

  gap: 7px;

  color: #64594f;

  font-size: 8px;
}


.facultyEditor > footer {
  display: flex;

  justify-content:
    flex-end;

  gap: 9px;

  margin-top: 25px;

  padding-top: 18px;

  border-top:
    1px solid
    #eee6dc;
}


.facultyEditor > footer button {
  min-height: 40px;

  padding:
    0 16px;

  border:
    1px solid
    #e1d7ca;

  border-radius: 9px;

  background: #fff;

  color: #605346;

  font-size: 8px;

  font-weight: 700;

  cursor: pointer;
}


.facultyEditor > footer
.facultySaveButton {
  border-color: #633b1d;

  background: #633b1d;

  color: #fff;
}


.facultyStatus {
  padding:
    11px 14px;

  border:
    1px solid
    #d8e8d9;

  border-radius: 10px;

  background: #eff8ef;

  color: #397243;

  font-size: 8px;
}


.facultyLoading,
.facultyEmpty {
  padding:
    70px 25px;

  border:
    1px dashed
    #dfd3c5;

  border-radius: 20px;

  color: #8f8276;

  text-align: center;
}


.facultyEmpty strong {
  display: block;

  margin-bottom: 6px;

  color: #53483d;
