/* RESPONSIVE */

@media (
  max-width: 1100px
) {

  .facultyGrid {
    grid-template-columns:
      repeat(
        2,
        minmax(0,1fr)
      );
  }


  .facultyHero {
    grid-template-columns:
      1fr;
  }


  .facultyHeroMark {
    display: none;
  }

}


@media (
  max-width: 760px
) {

  .facultyGrid {
    grid-template-columns:
      1fr;
  }


  .facultyFilters {
    align-items: stretch;
    flex-direction: column;
  }


  .facultySearch {
    width: 100%;
  }


  .facultyProfileModal {
    grid-template-columns:
      1fr;
  }


  .facultyProfilePhoto {
    min-height: 420px;
  }


  .facultyProfileFacts {
    grid-template-columns:
      1fr;
  }


  .facultyEditorGrid {
    grid-template-columns:
      1fr;
  }


  .facultyEditorFull {
    grid-column: auto;
  }


  .facultyHeroStats {
    flex-wrap: wrap;
  }

}


