  width: 34px;
  height: 34px;

  border: 1px solid #e2d8cc;
  border-radius: 50%;

  background: #fff;

  cursor: pointer;
}


.facultyBranchEditorGrid {
  display: grid;

  grid-template-columns:
    repeat(2, minmax(0, 1fr));

  gap: 14px;
}


.facultyBranchEditorGrid label {
  display: grid;
  gap: 6px;
}


.facultyBranchEditorGrid label > span {
  color: #77695d;

  font-size: 7px;
  font-weight: 750;
}


.facultyBranchEditorGrid input,
.facultyBranchEditorGrid textarea,
.facultyBranchEditorGrid select {
  width: 100%;

  border: 1px solid #e0d5c8;
  border-radius: 10px;

  outline: none;

  background: #fff;

  color: #342b24;

  font-size: 8px;
}


.facultyBranchEditorGrid input,
.facultyBranchEditorGrid select {
  min-height: 42px;

  padding: 0 11px;
}


.facultyBranchEditorGrid textarea {
  padding: 11px;

  resize: vertical;
}


.facultyBranchEditorFull {
  grid-column: 1 / -1;
}


.facultyBranchEditor > footer {
  display: flex;

  justify-content: flex-end;

  gap: 8px;

  margin-top: 20px;

  padding-top: 16px;

  border-top: 1px solid #eee5dc;
}


.facultyBranchEditor > footer button {
  min-height: 39px;

  padding: 0 14px;

  border-radius: 10px;

  cursor: pointer;
