/* ============================================================
   CAMPUSCONNECT — MOBILE / TABLET RESPONSIVE SYSTEM
   ============================================================
   Desktop      : > 1024px
   Tablet       : 768px - 1024px
   Mobile       : < 768px
   Small mobile : < 480px
============================================================ */


/* ============================================================
   GLOBAL RESPONSIVE SAFETY
============================================================ */

html,
body {
  max-width: 100%;
  overflow-x: hidden;
}

img,
video,
canvas,
svg {
  max-width: 100%;
}

button,
input,
textarea,
select {
  max-width: 100%;
}

.workspace,
.content {
  min-width: 0;
}


/* ============================================================
   TABLET
============================================================ */

@media (max-width: 1100px) {

  .workspaceHeader {
    gap: 12px;
    padding-left: 16px;
    padding-right: 16px;
  }

  .campusSearchTrigger {
    min-width: 0 !important;
    max-width: 390px !important;
  }

  .headerProfileText {
    display: none;
  }

  .headerProfileChevron {
    display: none;
  }

  .headerProfileIdentity {
    padding: 4px;
  }

  .content {
    padding-left: 20px;
    padding-right: 20px;
  }

}


/* ============================================================
   MOBILE SHELL
============================================================ */

