  body {
    overscroll-behavior-x: none;
  }


  /* ---------------------------------------------------------
     SIDEBAR
  --------------------------------------------------------- */

  .shell {
    display: block !important;
    width: 100%;
    min-height: 100vh;
  }

  .shell > aside {
    position: fixed !important;

    z-index: 10000;

    top: 0;
    bottom: 0;
    left: 0;

    width: min(84vw, 310px) !important;
    height: 100dvh;

    transform: translateX(-105%);

    transition:
      transform .24s ease,
      box-shadow .24s ease;

    overflow-y: auto;

    box-shadow:
      18px 0 60px
      rgba(45,31,20,.18);
  }


  .shell:not(.sidebarCollapsed) > aside {
    transform: translateX(0);
  }


  .sidebarCollapsed > aside {
