@media(max-width:1180px){
  .resumeBuilderGrid{
    grid-template-columns:210px minmax(0,1fr);
  }

  .resumeInsightPanel{
    grid-column:1/-1;
  }

  .resumeChecks{
    grid-template-columns:repeat(2,minmax(0,1fr));
    gap:0 24px;
  }
}

@media(max-width:900px){
  .resumeHero{
    grid-template-columns:1fr;
    padding:36px;
  }

  .resumeBuilderGrid{
    grid-template-columns:1fr;
  }

  .resumeBuilderSidebar nav{
    grid-template-columns:repeat(2,minmax(0,1fr));
  }

  .resumeTopActions,
  .resumePreviewHeader{
    align-items:flex-start;
    flex-direction:column;
  }

  .professionalResumePaper{
    padding:45px;
  }
}

@media(max-width:600px){
  .resumeHero{
    padding:28px 22px;
    border-radius:22px;
  }

  .resumeHero h1{
    font-size:38px;
  }

  .resumeScoreCard{
    align-items:flex-start;
    flex-direction:column;
  }

  .resumeTopActions{
    align-items:stretch;
  }

  .resumeTemplatePicker{
    overflow-x:auto;
  }

  .resumeActionButtons button{
    flex:1;
  }

  .resumeFormGrid,
  .resumeChecks,
  .resumeBuilderSidebar nav{
    grid-template-columns:1fr;
  }

  .resumeEditorBody{
    padding:22px 18px;
  }

  .resumePreviewSection{
    padding:18px 10px;
  }

  .professionalResumePaper{
    min-height:900px;
    padding:32px 24px;
  }

  .professionalResumeHeader,
  .resumePreviewRow{
    flex-direction:column;
    gap:14px;
  }

  .professionalResumeContact,
  .resumePreviewRow>div:last-child{
    text-align:left;
  }
}

@media print{
  body *{
    visibility:hidden !important;
  }

  .professionalResumePaper,
  .professionalResumePaper *{
    visibility:visible !important;
  }

  .professionalResumePaper{
    position:absolute;
    inset:0;
    width:100%;
    min-height:0;
    margin:0;
    padding:42px 52px;
    box-shadow:none;
  }

  @page{
    size:A4;
    margin:0;
  }
}


