  padding: 0 11px;
}

.placementOpsForm textarea {
  min-height: 95px;
  padding: 10px 11px;
  resize: vertical;
}

.placementOpsDirectory,
.placementOpsFiles,
.placementOpsOffers {
  display: grid;
  gap: 10px;
  margin-top: 17px;
}

.placementOpsDirectory article {
  display: grid;

  grid-template-columns:
    46px minmax(0,1fr) auto;

  gap: 13px;
  align-items: center;

  padding: 15px;

  border:
    1px solid #e8ebf0;

  border-radius: 13px;

  background: #fff;
}

.placementOpsDirectory article > i {
  display: grid;
  place-items: center;

  width: 44px;
  height: 44px;

  border-radius: 12px;

  background: #eaf1fb;
  color: #315f9f;

  font-size: 9px;
  font-style: normal;
  font-weight: 850;
}

.placementOpsDirectory h3 {
  margin:
    4px 0 3px;

  color: #26364b;
  font-size: 11px;
}

.placementOpsDirectory article > div > span {
  color: #315f9f;
  font-size: 7px;
  font-weight: 750;
}

.placementOpsDirectory p,
.placementOpsDirectory small {
  margin: 0;

  color: #8691a0;
  font-size: 8px;
}

.placementOpsDirectory blockquote {
  margin:
    8px 0 0;

  color: #758195;

  font-size: 8px;
  font-style: normal;
}

.placementOpsDirectory aside {
  text-align: right;
}

.placementOpsDirectory aside small,
.placementOpsDirectory aside strong {
  display: block;
}

.placementOpsDirectory aside small {
  color: #9aa3af;
  font-size: 6px;
}

.placementOpsDirectory aside strong {
  margin-top: 5px;

  color: #435269;
  font-size: 8px;
}

.placementOpsFiles article {
  display: grid;

  grid-template-columns:
    44px minmax(0,1fr) auto;

  gap: 13px;
  align-items: center;

  padding: 15px;

  border:
    1px solid #e7ebf0;

  border-radius: 13px;
}

.placementOpsFiles article > i {
  display: grid;
  place-items: center;

  width: 42px;
  height: 42px;

  border-radius: 11px;

  background: #edf1f5;
  color: #4a586b;

  font-size: 8px;
  font-style: normal;
  font-weight: 850;
}

.placementOpsFiles h3 {
  margin:
    4px 0 3px;

  color: #26364b;
  font-size: 10px;
}

.placementOpsFiles small {
  color: #315f9f;

  font-size: 7px;
  font-weight: 750;
}

.placementOpsFiles p,
.placementOpsFiles span {
  display: block;
  margin: 0;

  color: #8993a2;
  font-size: 8px;
}

.placementOpsFiles span {
  margin-top: 5px;
}

.placementOpsFiles aside {
  display: flex;
  gap: 6px;
}

.placementOpsFiles aside button {
  min-height: 31px;
  padding: 0 10px;

  border:
    1px solid #dce3ec;

  border-radius: 8px;

  background: #fff;
  color: #315f9f;

  font-size: 7px;
  font-weight: 750;
}

.placementOpsFiles aside button.danger {
  color: #ad4550;
}

.placementOpsTable {
  margin-top: 17px;

  overflow-x: auto;

  border:
    1px solid #e7ebf0;

  border-radius: 13px;
}

.placementOpsTableHead,
.placementOpsTableRow {
  display: grid;

  grid-template-columns:
    1.2fr
    1fr
    1fr
    1fr
    140px;

  gap: 12px;
  align-items: center;

  min-width: 740px;

  padding:
    12px 15px;
}

.placementOpsTableHead {
  background: #f6f8fb;

  color: #8993a3;

  font-size: 7px;
  font-weight: 800;
  letter-spacing: .08em;
}

.placementOpsTableRow {
  border-top:
    1px solid #edf0f4;

  color: #69768a;

  font-size: 8px;
}

.placementOpsTableRow strong {
  color: #26364b;
  font-size: 9px;
}

.placementOpsTableRow select {
  min-height: 33px;

  border:
    1px solid #dfe5ed;

  border-radius: 8px;

  background: #fff;

  color: #435168;

  font-size: 8px;
}

.placementOpsOffers article {
  display: grid;

  grid-template-columns:
    minmax(170px,1.5fr)
    130px
    130px
    130px;

  gap: 14px;
  align-items: center;

  padding: 15px;

  border:
    1px solid #e7ebf0;

  border-radius: 13px;
}

.placementOpsOffers h3 {
  margin:
    4px 0 3px;

  color: #26364b;

  font-size: 11px;
}

.placementOpsOffers article > div:first-child span {
  color: #315f9f;

  font-size: 7px;
  font-weight: 750;
}

.placementOpsOffers p {
  margin: 0;

  color: #8993a2;
  font-size: 8px;
}

.placementOpsOffers article > div small,
.placementOpsOffers article > div strong {
  display: block;
}

.placementOpsOffers article > div small {
  color: #9aa3b0;
  font-size: 6px;
}

.placementOpsOffers article > div strong {
  margin-top: 5px;

  color: #35445a;
  font-size: 9px;
}

.placementOpsOffers select {
  min-height: 34px;

  border:
    1px solid #dfe5ed;

  border-radius: 8px;

  background: #fff;

  color: #435168;

  font-size: 8px;
}

@media (max-width: 1050px) {

  .placementOpsMetrics {
    grid-template-columns:
      repeat(2,minmax(0,1fr));
  }

  .placementOpsGrid {
    grid-template-columns:
      1fr;
  }

  .placementOpsHero {
    grid-template-columns:
      1fr 240px;
  }

}

@media (max-width: 760px) {

  .placementOpsHero {
    grid-template-columns:
      1fr;

    padding:
      27px 22px;
  }

  .placementOpsHero aside {
    max-width: 350px;
  }

  .placementOpsPanel > header {
    flex-direction: column;
  }

  .placementOpsForm > div {
    grid-template-columns:
      1fr;
  }

  .placementOpsDirectory article,
  .placementOpsFiles article {
    grid-template-columns:
      44px minmax(0,1fr);
  }

  .placementOpsDirectory aside,
  .placementOpsFiles aside {
    grid-column:
      2;
    text-align: left;
  }

  .placementOpsOffers article {
    grid-template-columns:
      1fr 1fr;
  }

}

@media (max-width: 520px) {

  .placementOpsMetrics {
    grid-template-columns:
      1fr;
  }

  .placementOpsOffers article {
    grid-template-columns:
      1fr;
  }

}


/* =========================================================
   PLACEMENT CELL — APPLICANT PROFILE
========================================================= */

.placementApplicantOverlay {
  position: fixed;
  inset: 0;
  z-index: 20000;

  display: flex;
  justify-content: flex-end;

  padding: 18px;

  background:
    rgba(10, 18, 32, .48);

  backdrop-filter:
    blur(9px);
}

.placementApplicantDrawer {
  width: min(650px, 100%);
  height: 100%;

  padding: 24px;

  overflow-y: auto;

  border:
    1px solid rgba(255,255,255,.72);

  border-radius: 22px;

  background:
    #f7f9fc;

  box-shadow:
    0 35px 90px
    rgba(9, 20, 40, .28);
}

.placementApplicantHeader {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;

  padding-bottom: 20px;

  border-bottom:
    1px solid #e5eaf1;
}

.placementApplicantIdentity {
  display: flex;
  align-items: center;
  gap: 14px;
}

.placementApplicantAvatar {
  display: grid;
  place-items: center;

  width: 58px;
  height: 58px;

  flex: 0 0 auto;

  border-radius: 16px;

  background:
    #e7f0fb;

  color:
    #245da8;

  font-size: 14px;
  font-weight: 850;
}

.placementApplicantIdentity span {
  color:
    #245da8;

  font-size: 8px;
  font-weight: 850;
  letter-spacing: .13em;
}

.placementApplicantIdentity h2 {
  margin:
    5px 0 4px;

  color:
    #172238;

  font-size:
    21px;

  letter-spacing:
    -.03em;
}

.placementApplicantIdentity p {
  margin: 0;

  color:
    #7b8797;

  font-size:
    9px;
}

.placementApplicantClose {
  width: 36px;
  height: 36px;

  border: 0;
  border-radius: 11px;

  background:
    #e9edf2;

  color:
    #3d4859;

  font-size:
    18px;

  cursor: pointer;
}

.placementApplicantSummary {
  display: grid;

  grid-template-columns:
    repeat(4, minmax(0,1fr));

  gap: 9px;

  margin-top: 18px;
}

.placementApplicantSummary article,
.placementApplicantInfoGrid article {
  padding: 14px;

  border:
    1px solid #e5eaf1;

  border-radius: 13px;

  background:
    #fff;
}

.placementApplicantSummary small,
.placementApplicantInfoGrid small {
  display: block;

  color:
    #8a95a5;

  font-size:
    7px;

  font-weight:
    750;

  letter-spacing:
    .08em;
}

.placementApplicantSummary strong,
.placementApplicantInfoGrid strong {
  display: block;

  margin-top:
    6px;

  color:
    #233249;

  font-size:
    10px;

  overflow-wrap:
    anywhere;
}

.placementApplicantSection {
  margin-top:
    16px;

  padding:
    19px;

  border:
    1px solid #e4e9f0;

  border-radius:
    16px;

  background:
    #fff;
}

.placementApplicantSection header span,
.placementApplicantResume span {
  color:
    #245da8;

  font-size:
    7px;

  font-weight:
    850;

  letter-spacing:
    .13em;
}

.placementApplicantSection header h3,
.placementApplicantResume h3 {
  margin:
    5px 0 13px;

  color:
    #1c2a40;

  font-size:
    14px;
}

.placementApplicantInfoGrid {
  display: grid;

  grid-template-columns:
    repeat(2, minmax(0,1fr));

  gap:
    9px;
}

.placementApplicantHeadline {
  display: block;

  margin-bottom:
    8px;

  color:
    #243249;

  font-size:
    11px;
}

.placementApplicantBio,
.placementApplicantMuted {
  margin:
    0;

  color:
    #718096;

  font-size:
    9px;

  line-height:
    1.65;
}

.placementApplicantSkills {
  display:
    flex;

  flex-wrap:
    wrap;

  gap:
    7px;

  margin-top:
    14px;
}

.placementApplicantSkills span {
  padding:
    7px 9px;

  border-radius:
    999px;

  background:
    #eaf2fd;

  color:
    #245da8;

  font-size:
    8px;

  font-weight:
    750;
}

.placementApplicantLinks {
  display:
    flex;

  flex-wrap:
    wrap;

  gap:
    8px;
}

.placementApplicantLinks button {
  min-height:
    35px;

  padding:
    0 12px;

  border:
    1px solid #dce4ee;

  border-radius:
    999px;

  background:
    #f8fafc;

  color:
    #245da8;

  font-size:
    8px;

  font-weight:
    750;

  cursor:
    pointer;
}

.placementApplicantLinks span {
  color:
    #8490a0;

  font-size:
    9px;
}

.placementApplicantResume {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;

  margin-top:
    16px;

  padding:
    20px;

  border:
    1px solid #dbe5f1;

  border-radius:
    17px;

  background:
    linear-gradient(
      135deg,
      #f8fbff,
      #eef5fd
    );
}

.placementApplicantResume h3 {
  margin-bottom:
    5px;
}

.placementApplicantResume p {
  max-width:
    390px;

  margin:
    0;

  color:
    #718096;

  font-size:
    9px;

  line-height:
    1.55;
}

.placementApplicantResume button {
  flex:
    0 0 auto;

  min-height:
    38px;

  padding:
    0 14px;

  border:
    0;

  border-radius:
    999px;

  background:
    #172238;

  color:
    #fff;

  font-size:
    8px;

  font-weight:
    750;

  cursor:
    pointer;
}

.placementApplicantLoading,
.placementApplicantError {
  margin-top:
    18px;

  padding:
    25px;

  border:
    1px solid #e4e9ef;

  border-radius:
    15px;

  background:
    #fff;

  color:
    #718096;

  font-size:
    10px;

  text-align:
    center;
}

@media (max-width: 700px) {

  .placementApplicantOverlay {
    padding:
      7px;
  }

  .placementApplicantDrawer {
    padding:
      18px;

    border-radius:
      18px;
  }

  .placementApplicantSummary {
    grid-template-columns:
      repeat(2, minmax(0,1fr));
  }

  .placementApplicantInfoGrid {
    grid-template-columns:
      1fr;
  }

  .placementApplicantResume {
    align-items:
      stretch;

    flex-direction:
      column;
  }

  .placementApplicantResume button {
    width:
      100%;
  }
}

/* Placement Cell clickable candidates */

.applicationTicket.placementApplicantTicket {
  cursor: pointer;

  transition:
    transform .18s ease,
    box-shadow .18s ease,
    border-color .18s ease;
}

.applicationTicket.placementApplicantTicket:hover {
  transform:
    translateY(-2px);

  border-color:
    #cbd9eb;

  box-shadow:
    0 12px 28px
    rgba(31, 53, 82, .09);
}

.applicationTicket.placementApplicantTicket > small {
  color:
    #245da8;

  font-weight:
    700;
}


/* =========================================================
   PLACEMENT CELL — READ ONLY RESUME PDF
========================================================= */

.placementResumePdfAction {
  display: grid;

  gap: 7px;

  justify-items: end;
}


.placementResumePdfAction button {
  min-width: 110px;

  min-height: 38px;

  padding:
    0 15px;

  border:
    0;

  border-radius:
    10px;

  background:
    #18365f;

  color:
    #ffffff;

  font-size:
    9px;

  font-weight:
    750;

  cursor:
    pointer;

  transition:
    transform .18s ease,
    box-shadow .18s ease,
    opacity .18s ease;
}


.placementResumePdfAction button:hover:not(:disabled) {
  transform:
    translateY(-1px);

  box-shadow:
    0 8px 22px
    rgba(28,63,107,.18);
}


.placementResumePdfAction button:disabled {
  cursor:
    wait;

  opacity:
    .55;
}


.placementResumePdfAction small {
  max-width:
    260px;

  color:
    #b42318;

  font-size:
    8px;

  line-height:
    1.45;

  text-align:
    right;
}


@media (max-width: 700px) {

  .placementResumePdfAction {
    width:
      100%;

    justify-items:
      stretch;
  }


  .placementResumePdfAction button {
    width:
      100%;
  }


  .placementResumePdfAction small {
    max-width:
      none;

    text-align:
      left;
  }

}


/* ============================================================
   CAMPUSCONNECT — SGPA / CGPA CALCULATOR
============================================================ */

.campusGradePage {
  position: fixed;
  z-index: 30000;
  inset: 0;

  overflow-y: auto;

  background:
    radial-gradient(
      circle at 9% 2%,
      rgba(69,111,184,.11),
      transparent 27%
    ),
    radial-gradient(
      circle at 92% 13%,
      rgba(255,255,255,.95),
      transparent 27%
    ),
    #f3f6fa;

  color: #172238;
}


.campusGradeShell {
  width: min(1440px, 100%);
  margin: 0 auto;

  padding:
    28px
    clamp(20px, 4vw, 58px)
    60px;
}


.campusGradeTopbar {
  display: flex;
  align-items: center;
  justify-content: space-between;

  gap: 20px;

  margin-bottom: 22px;
  padding: 16px 18px;

  border:
    1px solid
    rgba(18,31,50,.08);

  border-radius: 20px;

  background:
    rgba(255,255,255,.87);

  box-shadow:
    0 16px 45px
    rgba(24,37,57,.07);

  backdrop-filter:
    blur(22px);
}


.campusGradeBrand {
  display: flex;
  align-items: center;

  gap: 12px;
}


.campusGradeLogo {
  display: grid;
  place-items: center;

  width: 42px;
  height: 42px;

  border-radius: 13px;

  background:
    #142238;

  color: #fff;

  font-size: 11px;
  font-weight: 900;

  box-shadow:
    0 8px 20px
    rgba(20,34,56,.16);
}


.campusGradeBrand small {
  display: block;

  color: #315f9c;

  font-size: 8px;
  font-weight: 850;

  letter-spacing: .14em;
}


.campusGradeBrand h2 {
  margin:
    4px 0 0;

  color:
    #162237;

  font-size:
    20px;

  letter-spacing:
    -.035em;
}


.campusGradeBack {
  min-height: 40px;

  border: 0;
  border-radius: 999px;

  padding:
