.campusGradeHeroMain h1 {
  position:
    relative;

  z-index:
    1;

  max-width:
    780px;

  margin:
    11px 0 14px;

  color:
    #111c2e;

  font-size:
    clamp(
      34px,
      4vw,
      54px
    );

  font-weight:
    680;

  line-height:
    1.02;

  letter-spacing:
    -.055em;
