.campusGradeHeroMain p {
  position:
    relative;

  z-index:
    1;

  max-width:
    760px;

  margin:
    0;

  color:
    #718096;

  font-size:
    11px;

  line-height:
    1.75;
}


.campusGradeHeroTags {
  display:
    flex;

  flex-wrap:
    wrap;

  gap:
    8px;

  margin-top:
    22px;
