.campusGradeCard {
  border:
    1px solid
    rgba(255,255,255,.9);

  border-radius:
    24px;

  padding:
    22px;

  background:
    rgba(255,255,255,.92);

  box-shadow:
    0 16px 48px
    rgba(30,47,68,.07);
