.campusGradeSectionHead {
  display:
    flex;

  justify-content:
    space-between;

  align-items:
    center;

  gap:
    18px;

  padding-bottom:
    18px;

  margin-bottom:
    16px;

  border-bottom:
    1px solid
    #e8edf3;
}


.campusGradeSectionHead span,
.campusGradeGuide > span {
  color:
    #315f9c;

  font-size:
    7px;

  font-weight:
    900;

  letter-spacing:
    .14em;
}


.campusGradeSectionHead h3,
.campusGradeGuide h3 {
  margin:
    5px 0 0;

  color:
    #1a293f;

  font-size:
    18px;

  letter-spacing:
    -.03em;
}


.campusGradeTabs {
  display:
    flex;

  gap:
    5px;

