/* ============================================================
   CAMPUSCONNECT — PROFESSIONAL READINESS SIGNAL
============================================================ */

.readinessSignalCard,
.overallSignalCard,
.roleDashboardSignal {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;

  padding: 17px 18px;

  border: 1px solid rgba(18, 20, 24, 0.07);
  border-radius: 18px;

  background:
    linear-gradient(
      145deg,
      #ffffff,
      rgba(255, 255, 255, 0.7)
    );

  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.85),
    0 8px 24px rgba(24, 31, 43, 0.05);
}


.readinessSignalCard small,
.overallSignalCard small,
.roleDashboardSignal small {
  display: block;

  color: #7a8492;

  font-size: 8px;
  font-weight: 800;

  letter-spacing: 0.13em;
  text-transform: uppercase;
}


.readinessSignalCard strong,
.overallSignalCard strong,
.roleDashboardSignal strong {
  display: block;

  margin-top: 6px;

  font-size: 15px;
  font-weight: 800;

  letter-spacing: -0.02em;
}


.readinessSignalCard span,
.overallSignalCard span,
.roleDashboardSignal span {
  display: block;

  margin-top: 4px;

  color: #7c8796;

  font-size: 9px;
}


.readinessSignalScore,
.overallSignalScore,
.roleDashboardSignalScore {
  display: grid;

  place-items: center;

  min-width: 78px;
  height: 52px;

  padding: 0 14px;

  border: 1px solid transparent;
  border-radius: 15px;

  font-size: 16px;
  font-weight: 850;

  letter-spacing: -0.03em;
}


/* BELOW 60 — NEEDS FOCUS */

.signal-low .readinessSignalScore,
.signal-low .overallSignalScore,
.signal-low .roleDashboardSignalScore {
  color: #b4233c;
  background: #fff1f2;
  border-color: #fecdd3;
}

.signal-low strong {
  color: #b4233c;
}


/* 60–69 — WATCH */

.signal-watch .readinessSignalScore,
.signal-watch .overallSignalScore,
.signal-watch .roleDashboardSignalScore {
  color: #c2410c;
  background: #fff7ed;
  border-color: #fed7aa;
}

.signal-watch strong {
  color: #c2410c;
}


/* 70–79 — STEADY */

.signal-steady .readinessSignalScore,
.signal-steady .overallSignalScore,
.signal-steady .roleDashboardSignalScore {
  color: #1d4ed8;
  background: #eff6ff;
  border-color: #bfdbfe;
}

.signal-steady strong {
  color: #1d4ed8;
}


/* 80–89 — STRONG */

.signal-strong .readinessSignalScore,
.signal-strong .overallSignalScore,
.signal-strong .roleDashboardSignalScore {
  color: #047857;
  background: #ecfdf5;
  border-color: #a7f3d0;
}

.signal-strong strong {
  color: #047857;
}


/* 90+ — EXCELLENT */

.signal-excellent .readinessSignalScore,
.signal-excellent .overallSignalScore,
.signal-excellent .roleDashboardSignalScore {
  color: #166534;
  background: #f0fdf4;
  border-color: #bbf7d0;

  box-shadow:
    0 8px 24px rgba(22, 101, 52, 0.08);
}

.signal-excellent strong {
  color: #166534;
}


@media (max-width: 600px) {

  .readinessSignalCard,
  .overallSignalCard,
  .roleDashboardSignal {
    align-items: flex-start;
  }

  .readinessSignalScore,
  .overallSignalScore,
  .roleDashboardSignalScore {
    min-width: 68px;
    height: 48px;
  }
}


/* ============================================================
   CAMPUSCONNECT — STUDENT OVERALL SIGNAL
============================================================ */

.studentOverallSignal {
  position: relative;

  min-width: 150px;

  padding:
    13px 15px;

  border:
    1px solid rgba(35, 48, 67, 0.08);

  border-radius:
    16px;

  background:
    rgba(255,255,255,.74);

  transition:
    background .25s ease,
    border-color .25s ease,
    box-shadow .25s ease,
    transform .25s ease;
}


.studentOverallSignal::before {
  position: absolute;

  top: 12px;
  left: 0;

  width: 3px;
  height: calc(100% - 24px);

  border-radius:
    0 999px 999px 0;

  content: "";
}


.studentOverallSignal > span {
  display: block;

  margin: 0 0 6px;

  color:
    #788596;

  font-size:
    7px;

  font-weight:
    850;

  letter-spacing:
    .14em;
}


.studentOverallSignal > b {
  display: block;

  font-size:
    15px;

  font-weight:
    850;

  line-height:
    1.15;

  letter-spacing:
    -.025em;

  transition:
    color .2s ease;
}


.studentOverallSignal > small {
  display: block;

  margin-top:
    5px;

  color:
    #7b8795;

  font-size:
    8px;

  line-height:
    1.45;
}


/* ============================================================
   0–59 — NEEDS FOCUS
============================================================ */

.studentOverallSignal.signalFocus {
  border-color:
    rgba(190, 18, 60, .13);

  background:
    linear-gradient(
      135deg,
      #fff,
      #fff5f6
    );

  box-shadow:
    0 8px 25px rgba(190,18,60,.055);
}

.studentOverallSignal.signalFocus::before {
  background:
    #be123c;
}

.studentOverallSignal.signalFocus > b {
  color:
    #b4233c;
}


/* ============================================================
   60–69 — NEEDS ATTENTION
============================================================ */

.studentOverallSignal.signalAttention {
  border-color:
    rgba(194, 65, 12, .14);

  background:
    linear-gradient(
      135deg,
      #fff,
      #fff8f1
    );

  box-shadow:
    0 8px 25px rgba(194,65,12,.055);
}

.studentOverallSignal.signalAttention::before {
  background:
    #d97706;
}

.studentOverallSignal.signalAttention > b {
  color:
    #b45309;
}


/* ============================================================
   70–79 — BUILDING
============================================================ */

.studentOverallSignal.signalBuilding {
  border-color:
    rgba(37, 99, 235, .13);

  background:
    linear-gradient(
      135deg,
      #fff,
      #f3f7ff
    );

  box-shadow:
    0 8px 25px rgba(37,99,235,.055);
}

.studentOverallSignal.signalBuilding::before {
  background:
    #2563eb;
}

.studentOverallSignal.signalBuilding > b {
  color:
    #1d4ed8;
}


/* ============================================================
   80–89 — STRONG
============================================================ */

.studentOverallSignal.signalStrong {
  border-color:
    rgba(5, 150, 105, .14);

  background:
    linear-gradient(
      135deg,
      #fff,
      #f0fbf7
    );

  box-shadow:
    0 8px 25px rgba(5,150,105,.06);
}

.studentOverallSignal.signalStrong::before {
  background:
    #059669;
}

.studentOverallSignal.signalStrong > b {
  color:
    #047857;
}


/* ============================================================
   90–100 — EXCELLENT
============================================================ */

.studentOverallSignal.signalExcellent {
  border-color:
    rgba(22, 101, 52, .15);

  background:
    linear-gradient(
      135deg,
      #ffffff,
      #f1fbf4
    );

  box-shadow:
    0 10px 30px rgba(22,101,52,.075);
}

.studentOverallSignal.signalExcellent::before {
  background:
    linear-gradient(
      180deg,
      #16a34a,
      #15803d
    );
}

.studentOverallSignal.signalExcellent > b {
  color:
    #166534;
}


@media (hover:hover) {

  .studentOverallSignal:hover {
    transform:
      translateY(-1px);
  }

}


@media (max-width: 640px) {

  .studentOverallSignal {
    min-width:
      130px;

    padding:
      11px 13px;
  }

  .studentOverallSignal > b {
    font-size:
      13px;
  }

}


/* ==========================================================
   CAMPUSCONNECT PROFESSIONAL ROLE DASHBOARD
========================================================== */

.proRoleDashboard {
  --pro-blue: #245da8;
  --pro-navy: #071426;
  --pro-bg: #f2f5f9;
  --pro-text: #172238;
  --pro-muted: #748196;
  --pro-line: rgba(27, 42, 64, .09);

  min-height: 100%;
  margin:
    -22px
    -28px
    0;

  padding-bottom:
    60px;

  background:
    radial-gradient(
      circle at 8% 14%,
      rgba(36, 93, 168, .08),
      transparent 26%
    ),
    radial-gradient(
      circle at 92% 22%,
      rgba(255, 255, 255, .9),
      transparent 25%
    ),
    var(--pro-bg);

  color:
    var(--pro-text);

  overflow:
    hidden;
}


.proDashboardHero {
  position:
    relative;

  min-height:
    300px;

  display:
    flex;

  align-items:
    flex-end;

  justify-content:
    space-between;

  gap:
    28px;

  padding:
    52px
    clamp(28px, 5vw, 72px)
    50px;

  overflow:
    hidden;

  color:
    white;

  background:
    linear-gradient(
      145deg,
      #05080d 0%,
      #08192e 52%,
      #101824 100%
    );
}


.proDashboardHero::after {
  content:
    "";

  position:
    absolute;

  right:
    8%;

  bottom:
    -90px;

  width:
    420px;

  height:
    180px;

  border:
    1px solid rgba(
      255,
      255,
      255,
      .08
    );

  border-radius:
    50%;

  transform:
    rotate(-8deg);
}


.proDashboardOrb {
  position:
    absolute;

  border-radius:
    50%;

  pointer-events:
    none;

  filter:
    blur(3px);
}


.proDashboardOrbOne {
  top:
    -150px;

  right:
    -70px;

  width:
    470px;

  height:
    470px;

  background:
    radial-gradient(
      circle,
      rgba(49, 105, 190, .33),
      transparent 68%
    );

  animation:
    proOrbFloat
    9s
    ease-in-out
    infinite;
}


.proDashboardOrbTwo {
  left:
    18%;

  bottom:
    -220px;

  width:
    410px;

  height:
    410px;

  background:
    radial-gradient(
      circle,
      rgba(65, 169, 255, .09),
      transparent 70%
    );

  animation:
    proOrbFloat
    12s
    ease-in-out
    infinite reverse;
}


@keyframes proOrbFloat {
  0%,
  100% {
    transform:
      translate3d(
        0,
        0,
        0
      );
  }

  50% {
    transform:
      translate3d(
        -18px,
        16px,
        0
      );
  }
}


.proDashboardHeroContent {
  position:
    relative;

  z-index:
    2;

  max-width:
    900px;
}


.proDashboardHeroContent > span {
  display:
    block;

  color:
    #79aef5;

  font-size:
    9px;

  font-weight:
    850;

  letter-spacing:
    .2em;
}


.proDashboardHeroContent h1 {
  max-width:
    850px;

  margin:
    13px 0 17px;

  font-size:
