.dashboardDailyBrief {
  position: relative;
  z-index: 3;
  display: grid;
  gap: 14px;
  width: 100%;
  margin-top: 22px;
  padding: 18px;
  overflow: hidden;
  border: 1px solid rgba(72, 57, 40, 0.14);
  border-radius: 20px;
  background:
    linear-gradient(
      135deg,
      rgba(255, 252, 247, 0.96),
      rgba(248, 241, 230, 0.92)
    );
  box-shadow:
    0 18px 50px rgba(40, 31, 23, 0.07),
    inset 0 1px 0 rgba(255, 255, 255, 0.9);
}

.dashboardDailyBrief::before {
  content: "";
  position: absolute;
  top: 0;
  right: 0;
  width: 180px;
  height: 180px;
  pointer-events: none;
  border-radius: 50%;
  background:
    radial-gradient(
      circle,
      rgba(132, 83, 39, 0.08),
      transparent 68%
    );
  transform: translate(45%, -45%);
}

.dashboardDailyBriefHeader {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
}

.dashboardDailyBriefHeader > div {
  display: grid;
  gap: 5px;
}

.dashboardDailyBriefHeader span {
  font-size: 10px;
  font-weight: 800;
  line-height: 1;
  letter-spacing: 0.16em;
  color: #8b5d35;
}

.dashboardDailyBriefHeader strong {
  font-family: Georgia, "Times New Roman", serif;
  font-size: clamp(18px, 1.7vw, 24px);
  font-weight: 600;
  line-height: 1.15;
  color: #183049;
}

.dashboardDailyBriefHeader > small {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  flex: 0 0 auto;
  padding: 7px 10px;
  border: 1px solid rgba(49, 91, 69, 0.14);
  border-radius: 999px;
  background: rgba(237, 247, 240, 0.72);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.05em;
  color: #315b45;
}

.dashboardDailyBriefHeader > small::before {
  content: "";
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
  box-shadow: 0 0 0 4px rgba(49, 91, 69, 0.08);
}

.dashboardDailyBriefBody {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 12px;
  align-items: stretch;
}

.dashboardDailyBriefSignals {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 9px;
  min-width: 0;
}

.dashboardDailyBriefSignal {
  position: relative;
  display: grid;
  gap: 6px;
  min-width: 0;
  min-height: 76px;
  padding: 12px 13px;
  border: 1px solid rgba(76, 61, 45, 0.12);
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.72);
  text-align: left;
  cursor: pointer;
  transition:
    transform 160ms ease,
    border-color 160ms ease,
    background 160ms ease,
    box-shadow 160ms ease;
}

.dashboardDailyBriefSignal:hover {
  transform: translateY(-2px);
  border-color: rgba(77, 58, 38, 0.24);
  background: rgba(255, 255, 255, 0.95);
  box-shadow: 0 10px 24px rgba(38, 30, 22, 0.07);
}

.dashboardDailyBriefSignal small {
  overflow: hidden;
  font-size: 9px;
  font-weight: 800;
  line-height: 1.1;
  letter-spacing: 0.12em;
  color: #766958;
  text-overflow: ellipsis;
  text-transform: uppercase;
  white-space: nowrap;
}

.dashboardDailyBriefSignal strong {
  overflow: hidden;
  font-size: 12px;
  font-weight: 700;
  line-height: 1.35;
  color: #21364a;
  text-overflow: ellipsis;
}

.dashboardDailyBriefSignal::after {
  content: "";
  position: absolute;
  top: 12px;
  right: 12px;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #647382;
}

.dashboardDailyBriefSignal.critical {
  border-color: rgba(167, 45, 57, 0.2);
  background:
    linear-gradient(
      135deg,
      rgba(255, 248, 248, 0.96),
      rgba(255, 242, 243, 0.76)
    );
}

.dashboardDailyBriefSignal.critical::after {
  background: #a72d39;
}

.dashboardDailyBriefSignal.attention {
  border-color: rgba(170, 111, 48, 0.2);
}

.dashboardDailyBriefSignal.attention::after {
  background: #aa6f30;
}

.dashboardDailyBriefSignal.normal::after {
  background: #315b45;
}

.dashboardDailyBriefPrimary {
  display: grid;
  align-content: center;
  gap: 5px;
  width: 145px;
  padding: 13px 15px;
  border: 1px solid #183049;
  border-radius: 14px;
  background: #183049;
  text-align: left;
  cursor: pointer;
  box-shadow: 0 10px 24px rgba(24, 48, 73, 0.15);
  transition:
    transform 160ms ease,
    box-shadow 160ms ease;
}

.dashboardDailyBriefPrimary:hover {
  transform: translateY(-2px);
  box-shadow: 0 14px 30px rgba(24, 48, 73, 0.2);
}

.dashboardDailyBriefPrimary span {
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.13em;
  color: rgba(255, 255, 255, 0.56);
}

.dashboardDailyBriefPrimary strong {
  overflow: hidden;
  font-size: 13px;
  font-weight: 700;
  line-height: 1.25;
  color: #fff;
  text-overflow: ellipsis;
}

.dashboardDailyBriefPrimary small {
  margin-top: 3px;
  font-size: 10px;
  font-weight: 700;
  color: #e5c99f;
}

.dashboardDailyBriefClear {
  grid-column: 1 / -1;
  display: flex;
  align-items: center;
  gap: 12px;
  min-height: 76px;
  padding: 13px 15px;
  border: 1px solid rgba(49, 91, 69, 0.14);
  border-radius: 14px;
  background: rgba(238, 247, 241, 0.62);
}

.dashboardDailyBriefClear > span {
  display: grid;
  flex: 0 0 auto;
  width: 34px;
  height: 34px;
  place-items: center;
  border-radius: 50%;
  background: rgba(49, 91, 69, 0.11);
  font-size: 14px;
  font-weight: 800;
  color: #315b45;
}

.dashboardDailyBriefClear > div {
  display: grid;
  gap: 3px;
}

.dashboardDailyBriefClear strong {
  font-size: 12px;
  color: #21364a;
}

.dashboardDailyBriefClear small {
  font-size: 10px;
  line-height: 1.4;
  color: #7a7065;
}

@media (max-width: 1100px) {
  .dashboardDailyBriefBody {
    grid-template-columns: 1fr;
  }

  .dashboardDailyBriefPrimary {
    width: 100%;
