========================================================= */

/* ---------------------------------------------------------
   DASHBOARD PAGE RHYTHM
--------------------------------------------------------- */

.studentDashboard {
  --cc-dashboard-border: rgba(46, 53, 59, 0.10);
  --cc-dashboard-text: #203448;
  --cc-dashboard-muted: #80776e;
  --cc-dashboard-accent: #8a603d;
  --cc-dashboard-surface: rgba(255, 255, 255, 0.92);

  display: flex !important;
  flex-direction: column !important;
  gap: 22px !important;
}

/*
 * The sections already have their own internal spacing.
 * Keep the overall page disciplined instead of allowing
 * different modules to create random vertical gaps.
 */

.studentDashboard > section,
.studentDashboard > .dashboardNotice {
  margin-top: 0 !important;
  margin-bottom: 0 !important;
}


/* ---------------------------------------------------------
   DASHBOARD KPI GRID
--------------------------------------------------------- */

.studentDashboardStats {
  display: grid !important;
  grid-template-columns:
    repeat(4, minmax(0, 1fr)) !important;

  gap: 12px !important;

  width: 100% !important;
  margin: 0 !important;
}


/* ---------------------------------------------------------
   KPI CARD
--------------------------------------------------------- */

.studentDashboardStats .dashboardStatCard {
  position: relative !important;

  display: grid !important;
  grid-template-columns:
    minmax(0, 1fr) auto !important;

  grid-template-rows:
    auto 1fr !important;

  align-items: center !important;

  min-width: 0 !important;
  min-height: 118px !important;

  padding:
    17px 18px !important;

  overflow: hidden !important;

  border:
    1px solid
    var(--cc-dashboard-border) !important;

  border-radius:
    15px !important;

  background:
    linear-gradient(
      145deg,
      rgba(255, 255, 255, 0.98),
      rgba(251, 249, 246, 0.94)
    ) !important;

  box-shadow:
    0 8px 24px
    rgba(31, 37, 42, 0.045) !important;

  text-align: left !important;

  transition:
    transform 160ms ease,
    border-color 160ms ease,
    box-shadow 160ms ease,
    background 160ms ease !important;
}


/* remove decorative effects from older versions */

.studentDashboardStats .dashboardStatCard::before {
  opacity: 0.35 !important;
}

.studentDashboardStats .dashboardStatCard::after {
  content: "" !important;

  position: absolute !important;

  left: 18px !important;
  right: auto !important;
  bottom: 0 !important;

  width: 32px !important;
  height: 2px !important;

  border-radius:
    999px 999px 0 0 !important;

  background:
    #9a704d !important;

  opacity: 0.55 !important;

  transition:
    width 180ms ease,
    opacity 180ms ease !important;
}


/* ---------------------------------------------------------
   KPI HOVER
--------------------------------------------------------- */

.studentDashboardStats .dashboardStatCard:hover {
  transform:
    translateY(-2px) !important;

  border-color:
    rgba(74, 67, 59, 0.18) !important;

  background:
    #ffffff !important;

  box-shadow:
    0 14px 34px
    rgba(29, 35, 41, 0.075) !important;
}

.studentDashboardStats .dashboardStatCard:hover::after {
  width:
    54px !important;

  opacity:
    0.9 !important;
}


/* ---------------------------------------------------------
   KPI CONTENT
--------------------------------------------------------- */

.studentDashboardStats .dashboardStatCard > div {
  min-width: 0 !important;

  display: grid !important;

  gap: 6px !important;
}

.studentDashboardStats .dashboardStatCard small {
  display: block !important;

  overflow: hidden !important;

  font-size:
    9px !important;

  font-weight:
    800 !important;

  line-height:
    1.2 !important;

  letter-spacing:
    0.11em !important;

  text-transform:
    uppercase !important;

  text-overflow:
    ellipsis !important;

  white-space:
    nowrap !important;

  color:
    #8a8076 !important;
}

.studentDashboardStats .dashboardStatCard > strong {
  align-self:
    start !important;

  margin-left:
    16px !important;

  font-family:
    Georgia,
    "Times New Roman",
    serif !important;

  font-size:
    clamp(
      27px,
      2.2vw,
      35px
    ) !important;

  font-weight:
    500 !important;

  line-height:
    1 !important;

  letter-spacing:
    -0.035em !important;

  color:
    var(--cc-dashboard-text) !important;
}

.studentDashboardStats .dashboardStatCard p {
  grid-column:
    1 / -1 !important;

  max-width:
    94% !important;

  margin:
    6px 0 0 !important;

  font-size:
    10px !important;

  line-height:
    1.45 !important;

  color:
    var(--cc-dashboard-muted) !important;
}


/* ---------------------------------------------------------
   INDIVIDUAL KPI ACCENTS

   Very subtle. We avoid bright dashboard colors.
--------------------------------------------------------- */

.studentDashboardStats
.dashboardStatCard:nth-child(1)::after {
  background:
    #547766 !important;
}

.studentDashboardStats
.dashboardStatCard:nth-child(2)::after {
  background:
    #8b6846 !important;
}

.studentDashboardStats
.dashboardStatCard:nth-child(3)::after {
  background:
    #546f87 !important;
}

.studentDashboardStats
.dashboardStatCard:nth-child(4)::after {
  background:
    #76617b !important;
}


/* ---------------------------------------------------------
   PRIMARY DASHBOARD GRID
--------------------------------------------------------- */

.studentDashboardMainGrid {
  display: grid !important;

  grid-template-columns:
    minmax(0, 1.7fr)
    minmax(280px, 0.7fr) !important;

  gap:
    18px !important;

  align-items:
    start !important;

