 * Student / Faculty / Placement / Coordinator / Volunteer
 * dashboards are intentionally untouched.
 */

.professionalRoleDashboard.admin {
  --role-accent: #2563eb !important;
  --role-soft: #eff6ff !important;
  --role-bg: #f5f7fb !important;
  --role-dark: #0f172a !important;

  --admin-enterprise-navy: #0f172a;
  --admin-enterprise-ink: #1e293b;
  --admin-enterprise-muted: #64748b;
  --admin-enterprise-soft: #94a3b8;
  --admin-enterprise-border: #e2e8f0;
  --admin-enterprise-blue: #2563eb;
  --admin-enterprise-blue-dark: #1d4ed8;
  --admin-enterprise-blue-soft: #eff6ff;
  --admin-enterprise-surface: #ffffff;
  --admin-enterprise-canvas: #f5f7fb;

  background:
    linear-gradient(
      180deg,
      #f8fafc 0%,
      #f5f7fb 45%,
      #f3f6fa 100%
    ) !important;

  color: var(--admin-enterprise-ink) !important;
}


/* =========================================================
   REMOVE OLD BEIGE / SERIF ADMIN LANGUAGE
========================================================= */

.professionalRoleDashboard.admin,
.professionalRoleDashboard.admin button,
.professionalRoleDashboard.admin input,
.professionalRoleDashboard.admin select,
.professionalRoleDashboard.admin textarea {
  font-family:
    Inter,
    ui-sans-serif,
    system-ui,
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    sans-serif !important;
}

.professionalRoleDashboard.admin h1,
.professionalRoleDashboard.admin h2,
.professionalRoleDashboard.admin h3,
.professionalRoleDashboard.admin h4,
.professionalRoleDashboard.admin strong,
.professionalRoleDashboard.admin b {
  font-family:
    Inter,
    ui-sans-serif,
    system-ui,
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    sans-serif !important;
}


/* =========================================================
   HERO — ENTERPRISE COMMAND CENTER
========================================================= */

.professionalRoleDashboard.admin .roleDashboardHero {
  position: relative;

  min-height: 330px;

  padding:
    34px
    clamp(28px, 5vw, 76px)
    48px !important;

  overflow: hidden;

  border-bottom:
    1px solid
    rgba(148, 163, 184, .16);

  background:
    radial-gradient(
      circle at 90% 15%,
      rgba(59, 130, 246, .18),
      transparent 30%
    ),
    radial-gradient(
      circle at 72% 100%,
      rgba(37, 99, 235, .09),
      transparent 28%
    ),
    linear-gradient(
      135deg,
      #08111f 0%,
      #0f172a 54%,
      #16233a 100%
    ) !important;

  color: #fff !important;
}

.professionalRoleDashboard.admin .roleDashboardHero::before {
  content: "";

  position: absolute;
  inset: 0;

  opacity: .16;

  background-image:
    linear-gradient(
      rgba(255,255,255,.055) 1px,
      transparent 1px
    ),
    linear-gradient(
      90deg,
      rgba(255,255,255,.055) 1px,
      transparent 1px
    );

  background-size:
    42px 42px;

  mask-image:
    linear-gradient(
      90deg,
      transparent,
      #000 35%,
      #000
    );

  pointer-events: none;
}

.professionalRoleDashboard.admin .roleDashboardHeroGlow {
  width: 620px;
  height: 620px;

  top: -360px;
  right: -120px;

  opacity: .55 !important;

  background:
    radial-gradient(
      circle,
      rgba(59, 130, 246, .5),
      rgba(37, 99, 235, .12) 42%,
      transparent 70%
    ) !important;
}

.professionalRoleDashboard.admin .roleDashboardHeroTop {
  position: relative;
  z-index: 3;
}

.professionalRoleDashboard.admin .roleDashboardBrandMark {
  width: 44px;
  height: 44px;

  border:
    1px solid
    rgba(255,255,255,.14) !important;

  border-radius: 12px !important;

  background:
    rgba(255,255,255,.07) !important;

  box-shadow:
    inset 0 1px 0
    rgba(255,255,255,.08);

  backdrop-filter:
    blur(16px);
}

.professionalRoleDashboard.admin .roleDashboardSystemState {
  padding: 8px 12px;

  border:
    1px solid
    rgba(255,255,255,.11) !important;

  background:
    rgba(255,255,255,.055) !important;

  color:
    rgba(226,232,240,.76) !important;

  box-shadow:
    inset 0 1px 0
    rgba(255,255,255,.04);
}

.professionalRoleDashboard.admin
.roleDashboardSystemState i {
  background: #22c55e !important;

  box-shadow:
    0 0 0 4px
    rgba(34,197,94,.10) !important;
}

.professionalRoleDashboard.admin
.roleDashboardHeroContent {
  position: relative;
  z-index: 3;

  margin-top: 62px;
}

.professionalRoleDashboard.admin
.roleDashboardHeroContent > div > span {
  color: #93c5fd !important;

  font-size: 8px !important;
  font-weight: 800 !important;

  letter-spacing: .17em !important;
}

.professionalRoleDashboard.admin
.roleDashboardHeroContent h1 {
  max-width: 850px;

  margin:
    14px 0 16px !important;

  color: #f8fafc !important;

  font-size:
    clamp(
      42px,
      5vw,
      67px
    ) !important;

  font-weight: 680 !important;

  line-height: 1.01 !important;

  letter-spacing: -.048em !important;
}

.professionalRoleDashboard.admin
.roleDashboardHeroContent p {
  max-width: 670px;

  color:
    rgba(226,232,240,.67) !important;

  font-size: 11px !important;

  line-height: 1.75 !important;
}

.professionalRoleDashboard.admin
.roleDashboardPrimaryAction {
  min-height: 44px;

  padding: 0 18px;

  border:
    1px solid
    rgba(147,197,253,.28) !important;

  border-radius: 10px !important;

  background:
    rgba(37,99,235,.92) !important;

  color: #fff !important;

  box-shadow:
    0 10px 28px
    rgba(37,99,235,.24);

  backdrop-filter: none !important;

  transition:
    transform .18s ease,
    background .18s ease,
    box-shadow .18s ease !important;
}

.professionalRoleDashboard.admin
.roleDashboardPrimaryAction:hover {
  transform:
    translateY(-2px) !important;

  background:
    #2563eb !important;

  box-shadow:
    0 14px 34px
    rgba(37,99,235,.3) !important;
}


/* =========================================================
   MAIN WORKSPACE
========================================================= */

.professionalRoleDashboard.admin
.roleDashboardWorkspace {
  max-width: 1500px;

  padding:
    38px
    clamp(24px, 5vw, 74px)
    80px !important;

  background:
    transparent !important;
}


/* =========================================================
   IDENTITY / GREETING
========================================================= */

.professionalRoleDashboard.admin
.roleDashboardIdentity {
  align-items: flex-end;

  margin-bottom: 25px;

  padding-bottom: 22px;

  border-bottom:
    1px solid
    var(--admin-enterprise-border);
}

.professionalRoleDashboard.admin
.roleDashboardIdentity > div > span {
  color:
    var(--admin-enterprise-blue) !important;

  font-size: 7px !important;

  font-weight: 850 !important;

  letter-spacing: .15em !important;
}

.professionalRoleDashboard.admin
.roleDashboardIdentity h2 {
  margin:
    8px 0 7px !important;

  color:
    var(--admin-enterprise-navy) !important;

  font-size:
    clamp(
      25px,
      3vw,
      34px
    ) !important;

  font-weight: 720 !important;

  letter-spacing: -.035em !important;
}

.professionalRoleDashboard.admin
.roleDashboardIdentity p {
  color:
    var(--admin-enterprise-muted) !important;

  font-size: 9px !important;
}


/* =========================================================
   ADMIN METRICS
========================================================= */

.professionalRoleDashboard.admin
.roleDashboardMetrics {
  gap: 14px !important;

  margin-bottom: 18px !important;
}

.professionalRoleDashboard.admin
.roleDashboardMetric {
  position: relative;

  min-height: 132px;

  padding: 20px !important;

  overflow: hidden;

  border:
    1px solid
    var(--admin-enterprise-border) !important;

  border-radius: 15px !important;

  background:
    #fff !important;

  box-shadow:
    0 1px 2px
    rgba(15,23,42,.025),
    0 8px 22px
    rgba(15,23,42,.035) !important;

  backdrop-filter: none !important;

  transition:
    transform .18s ease,
    border-color .18s ease,
    box-shadow .18s ease !important;
}

.professionalRoleDashboard.admin
.roleDashboardMetric::before {
  content: "";

  position: absolute;

  top: 0;
  left: 20px;
  right: 20px;

  height: 2px;

  border-radius: 0 0 999px 999px;

  background:
    linear-gradient(
      90deg,
      #2563eb,
      rgba(37,99,235,.16)
    );
}

.professionalRoleDashboard.admin
.roleDashboardMetric::after {
  width: 95px !important;
  height: 95px !important;

  right: -35px !important;
  bottom: -45px !important;

  opacity: .55;

  background:
    #eff6ff !important;
}

.professionalRoleDashboard.admin
.roleDashboardMetric:hover {
  transform:
    translateY(-2px) !important;

  border-color:
    #cbd8ea !important;

  box-shadow:
    0 12px 30px
    rgba(15,23,42,.07) !important;
}

.professionalRoleDashboard.admin
.roleDashboardMetric small {
  color:
    var(--admin-enterprise-muted) !important;

  font-size: 7px !important;
}

.professionalRoleDashboard.admin
.roleDashboardMetric strong {
  margin:
    12px 0 6px !important;

  color:
    var(--admin-enterprise-navy) !important;

  font-size: 32px !important;

  font-weight: 720 !important;
}

.professionalRoleDashboard.admin
.roleDashboardMetric > span {
  color:
    var(--admin-enterprise-soft) !important;

  font-size: 8px !important;
}


/* =========================================================
   GRID
========================================================= */

.professionalRoleDashboard.admin
.roleDashboardMainGrid {
  grid-template-columns:
    minmax(0,1.55fr)
    minmax(310px,.72fr);

  gap: 16px !important;
}

.professionalRoleDashboard.admin
.roleDashboardMainColumn,
.professionalRoleDashboard.admin
.roleDashboardSideColumn {
  gap: 16px !important;
}


/* =========================================================
   PANELS
========================================================= */

.professionalRoleDashboard.admin
.roleDashboardPanel {
  padding: 22px !important;

  border:
    1px solid
    var(--admin-enterprise-border) !important;

  border-radius: 16px !important;

  background:
    #fff !important;

  box-shadow:
    0 1px 2px
    rgba(15,23,42,.025),
    0 8px 26px
    rgba(15,23,42,.035) !important;

  backdrop-filter: none !important;
}

.professionalRoleDashboard.admin
.roleDashboardPanel.floating {
  box-shadow:
    0 8px 28px
    rgba(15,23,42,.045) !important;
}

.professionalRoleDashboard.admin
.roleDashboardPanel.floating:hover {
  transform:
    translateY(-2px) !important;

  box-shadow:
    0 13px 35px
    rgba(15,23,42,.075) !important;
}

.professionalRoleDashboard.admin
.roleDashboardPanelHeader {
  margin-bottom: 17px !important;

  padding-bottom: 14px;

  border-bottom:
    1px solid
    #eef2f7;
}

.professionalRoleDashboard.admin
.roleDashboardPanelHeader span {
  color:
    var(--admin-enterprise-blue) !important;

  font-size: 7px !important;

  font-weight: 850 !important;
}

.professionalRoleDashboard.admin
.roleDashboardPanelHeader h3 {
  margin:
    6px 0 0 !important;

  color:
    var(--admin-enterprise-navy) !important;

  font-size: 16px !important;

  font-weight: 720 !important;
}


/* =========================================================
   PRIORITY / ACTION TASKS
========================================================= */

.professionalRoleDashboard.admin
.roleDashboardTaskList {
  gap: 8px !important;
}

.professionalRoleDashboard.admin
.roleDashboardTask {
  grid-template-columns:
    40px
    minmax(0,1fr)
    auto;

  min-height: 66px;

  padding:
    11px 12px !important;

  border:
    1px solid
    #e8edf4 !important;

  border-radius: 11px !important;

  background:
    #fbfcfe !important;

  box-shadow:
    none !important;
}

.professionalRoleDashboard.admin
.roleDashboardTask:hover {
  transform:
    translateX(2px) !important;

  border-color:
    #d4dfed !important;

  background:
    #f8fbff !important;
}

.professionalRoleDashboard.admin
.roleDashboardTask > i {
  width: 38px !important;
  height: 38px !important;

  border-radius: 9px !important;

  background:
    var(--admin-enterprise-blue-soft) !important;

  color:
    var(--admin-enterprise-blue) !important;
}

.professionalRoleDashboard.admin
.roleDashboardTask > span b {
  color:
    var(--admin-enterprise-navy) !important;

  font-size: 9px !important;
}

.professionalRoleDashboard.admin
.roleDashboardTask > span small {
  color:
    var(--admin-enterprise-muted) !important;

  font-size: 7px !important;
}


