}

.professionalRoleDashboard.admin
.roleDashboardProgress p b {
  color:
    var(--admin-enterprise-ink) !important;
}

.professionalRoleDashboard.admin
.roleDashboardProgress > i {
  overflow: hidden;

  background:
    #e8edf5 !important;
}

.professionalRoleDashboard.admin
.roleDashboardProgress > i > span {
  background:
    linear-gradient(
      90deg,
      #2563eb,
      #3b82f6
    ) !important;
}


