    #1d4ed8 !important;
}


/* =========================================================
   EDITABLE ADMIN HERO FIELDS
========================================================= */

.professionalRoleDashboard.admin
.proAdminHeroInput,
.professionalRoleDashboard.admin
.proAdminHeroEyebrow,
.professionalRoleDashboard.admin
.proAdminHeroTitle,
