/* =========================================================
   ANY NESTED GENERIC CARDS
========================================================= */

.professionalRoleDashboard.admin
.card {
  border-color:
    var(--admin-enterprise-border) !important;
}


/* =========================================================
   SUBTLE ADMIN MOTION
========================================================= */

@keyframes adminEnterpriseReveal {
  from {
    opacity: 0;
    transform:
      translateY(7px);
  }

  to {
    opacity: 1;
    transform:
      translateY(0);
  }
}

.professionalRoleDashboard.admin
.roleDashboardIdentity,
.professionalRoleDashboard.admin
.roleDashboardMetrics,
.professionalRoleDashboard.admin
.roleDashboardMainGrid {
  animation:
    adminEnterpriseReveal
    .4s
    cubic-bezier(.2,.72,.3,1)
    both;
}

.professionalRoleDashboard.admin
.roleDashboardMetrics {
  animation-delay: .04s;
}

.professionalRoleDashboard.admin
.roleDashboardMainGrid {
  animation-delay: .08s;
}


/* =========================================================
   RESPONSIVE
========================================================= */

@media (max-width: 1050px) {
  .professionalRoleDashboard.admin
  .roleDashboardMetrics {
    grid-template-columns:
      repeat(2,minmax(0,1fr)) !important;
  }

  .professionalRoleDashboard.admin
  .roleDashboardMainGrid {
    grid-template-columns:
      1fr !important;
  }
}

@media (max-width: 760px) {
  .professionalRoleDashboard.admin
  .roleDashboardHero {
    min-height: auto;

    padding:
      26px 20px
      36px !important;
  }

  .professionalRoleDashboard.admin
  .roleDashboardHeroContent {
    align-items: flex-start;

    flex-direction: column;

    margin-top: 42px;
  }

  .professionalRoleDashboard.admin
  .roleDashboardHeroContent h1 {
    font-size:
      clamp(
        34px,
        10vw,
        48px
      ) !important;
  }

  .professionalRoleDashboard.admin
  .roleDashboardWorkspace {
    padding:
      28px 17px
      65px !important;
  }

  .professionalRoleDashboard.admin
  .roleDashboardIdentity {
    align-items: flex-start;

    flex-direction: column;

    gap: 15px;
  }
}

@media (max-width: 520px) {
  .professionalRoleDashboard.admin
  .roleDashboardMetrics {
    grid-template-columns:
      1fr !important;
  }

  .professionalRoleDashboard.admin
  .roleDashboardPanel {
    padding: 18px !important;
  }
}

@media (prefers-reduced-motion: reduce) {
  .professionalRoleDashboard.admin
  .roleDashboardIdentity,
  .professionalRoleDashboard.admin
  .roleDashboardMetrics,
  .professionalRoleDashboard.admin
  .roleDashboardMainGrid {
