/* =========================================================
   MOTION
========================================================= */

@keyframes staffDashboardReveal {
  from {
    opacity: 0;

    transform:
      translateY(8px);
  }

  to {
    opacity: 1;

    transform:
      translateY(0);
  }
}

.proRoleDashboard:not(.proRoleDashboard-student)
.proDashboardGreeting,

.proRoleDashboard:not(.proRoleDashboard-student)
.proDashboardMetrics,

.proRoleDashboard:not(.proRoleDashboard-student)
.proDashboardGrid {
  animation:
    staffDashboardReveal
    .42s
    cubic-bezier(.2,.72,.3,1)
    both;
}

.proRoleDashboard:not(.proRoleDashboard-student)
.proDashboardMetrics {
  animation-delay: .05s;
}

.proRoleDashboard:not(.proRoleDashboard-student)
.proDashboardGrid {
  animation-delay: .09s;
}


/* =========================================================
   RESPONSIVE
========================================================= */

@media (max-width: 1100px) {

  .proRoleDashboard:not(.proRoleDashboard-student)
