    padding:
      0 16px !important;

    scrollbar-width: none;
  }

  .proRoleDashboard:not(.proRoleDashboard-student)
  .proDashboardRail::-webkit-scrollbar {
    display: none;
  }

  .proRoleDashboard:not(.proRoleDashboard-student)
