  }

  .proRoleDashboard:not(.proRoleDashboard-student)
  .proDashboardGreeting {
    align-items: flex-start;

    flex-direction: column;
  }
}

@media (max-width: 520px) {

  .proRoleDashboard:not(.proRoleDashboard-student)
  .proDashboardHeroMetrics {
    grid-template-columns: 1fr;
  }

  .proRoleDashboard:not(.proRoleDashboard-student)
  .proDashboardMetrics {
    grid-template-columns: 1fr;
  }

  .proRoleDashboard:not(.proRoleDashboard-student)
