/* =========================================================
   HERO — KEEP EVERYTHING INSIDE VIEWPORT
========================================================= */

html body
.proRoleDashboard:not(.proRoleDashboard-student)
.proDashboardHero {
  box-sizing: border-box !important;

  width: 100% !important;
  max-width: 100% !important;

  min-height: 420px !important;

  display: grid !important;

  grid-template-columns:
    minmax(0, 1.25fr)
    minmax(360px, 460px) !important;

  align-items: center !important;

  gap: clamp(36px, 5vw, 72px) !important;

  padding:
    46px
    clamp(28px, 5vw, 72px) !important;

  margin: 0 !important;

  overflow: hidden !important;

  background:
    linear-gradient(
      125deg,
      #081426 0%,
      #0b1b32 58%,
      #14325d 100%
