/* =========================================================
   CAMPUSCONNECT — GLOBAL BACK TO DASHBOARD
   ========================================================= */

.globalBackBar {
  width: 100%;
  display: flex;
  align-items: center;
  margin: 0 0 18px;
}

.globalBackToDashboard {
  appearance: none;
  border: 1px solid rgba(15, 23, 42, 0.11);
  background: rgba(255, 255, 255, 0.96);
  border-radius: 14px;
  min-height: 48px;
  padding: 7px 14px 7px 8px;
  display: inline-flex;
  align-items: center;
  gap: 10px;
  cursor: pointer;
  color: #0f172a;
  font: inherit;
  text-align: left;
  box-shadow:
    0 1px 2px rgba(15, 23, 42, 0.04),
    0 6px 20px rgba(15, 23, 42, 0.045);
  transition:
    transform 160ms ease,
    border-color 160ms ease,
    box-shadow 160ms ease,
    background 160ms ease;
}

.globalBackToDashboard:hover {
  transform: translateY(-1px);
  border-color: rgba(37, 99, 235, 0.25);
  background: #ffffff;
  box-shadow:
    0 2px 4px rgba(15, 23, 42, 0.05),
    0 10px 28px rgba(15, 23, 42, 0.07);
}

.globalBackToDashboard:active {
  transform: translateY(0);
}

.globalBackToDashboard:focus-visible {
  outline: 3px solid rgba(37, 99, 235, 0.18);
  outline-offset: 2px;
}

.globalBackIcon {
  width: 34px;
  height: 34px;
  border-radius: 10px;
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  background: #f1f5f9;
  color: #1e3a8a;
  font-size: 19px;
  font-weight: 700;
  line-height: 1;
  transition:
    transform 160ms ease,
    background 160ms ease;
}

.globalBackToDashboard:hover .globalBackIcon {
  transform: translateX(-2px);
  background: #eaf1ff;
}

.globalBackCopy {
  display: flex;
  flex-direction: column;
  gap: 1px;
  line-height: 1.2;
}

.globalBackCopy strong {
  font-size: 13px;
  font-weight: 700;
  letter-spacing: -0.01em;
  color: #172033;
}

.globalBackCopy small {
  font-size: 10px;
  font-weight: 500;
  color: #7c8799;
}

/* Mobile */
@media (max-width: 768px) {
  .globalBackBar {
    margin-bottom: 12px;
  }

  .globalBackToDashboard {
    min-height: 42px;
    padding: 5px 10px 5px 6px;
    border-radius: 12px;
  }

  .globalBackIcon {
    width: 30px;
    height: 30px;
    border-radius: 9px;
    font-size: 17px;
  }

  .globalBackCopy strong {
    font-size: 12px;
  }

  .globalBackCopy small {
    display: none;
  }
}

/* =========================================================
   CAMPUSCONNECT — SIDEBAR NAV VISIBILITY FIX
   Keeps all navigation items accessible without allowing
   the entire sidebar layout to overflow the viewport.
   ========================================================= */

.shell > aside {
  overflow: hidden !important;
  min-height: 0;
}

.shell > aside > nav {
  flex: 1 1 auto;
  min-height: 0;
  overflow-y: auto;
  overflow-x: hidden;
  padding-right: 5px;
  overscroll-behavior: contain;
  scrollbar-width: thin;
  scrollbar-color: #d5dce8 transparent;
}

.shell > aside > nav::-webkit-scrollbar {
  width: 5px;
}

.shell > aside > nav::-webkit-scrollbar-track {
  background: transparent;
}

.shell > aside > nav::-webkit-scrollbar-thumb {
  background: #d5dce8;
  border-radius: 999px;
}

.shell > aside > nav::-webkit-scrollbar-thumb:hover {
  background: #b8c3d4;
}

/* Keep logo / college identity / profile footer fixed */
.shell > aside > .brand,
.shell > aside > .brandLogo,
.shell > aside > .college,
.shell > aside > .sidebarProfileProgress,
.shell > aside > .strength,
.shell > aside > .me {
  flex-shrink: 0;
}


