  border:1px solid #e8ebf0;
  border-radius:10px;

  background:#fafbfc;
}

.resumeJobKeywordStats strong,
.resumeJobKeywordStats span{
  display:block;
}

.resumeJobKeywordStats strong{
  color:#1b2a40;

  font-size:19px;
}

.resumeJobKeywordStats span{
  margin-top:3px;

  color:#8791a0;

  font-size:7px;
}


