}

.resumeJobChips span.missing{
  border:1px solid #f0d9ca;

  background:#fff7f0;

  color:#a85b28;
}

.resumeJobChips span.neutral{
  border:1px solid #dce4f2;

  background:#f4f7fc;

  color:#55709b;
}

.resumeJobChips p{
  margin:0 !important;

  color:#98a1ae !important;

  font-size:8px !important;
}

.resumeJobDisclaimer{
  margin-top:15px;

  color:#929dab;

  font-size:7px;

  line-height:1.5;

  text-align:center;
}


@media(max-width:1000px){

