/* ============================================================
   CAMPUSCONNECT MESSENGER — REMOVE / DELETE PERSON
   ============================================================ */

.friendRowWithActions{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:10px;
}

.friendMainAction{
  min-width:0;
  flex:1;

  display:flex;
  align-items:center;
  gap:10px;

  border:0;
  padding:0;

  background:transparent;
  text-align:left;
  cursor:pointer;
}

.friendMainAction>span{
  min-width:0;
  display:grid;
}

.friendMainAction b{
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
}

.friendRowActions{
  flex:none;

  display:flex;
  align-items:center;
  gap:6px;
}

.friendMessageButton,
.friendRemoveButton,
.restoreConnectionButton,
.deletePersonButton{
  min-height:31px;
  padding:0 10px;

  border-radius:8px;

  font-size:8px;
  font-weight:750;

  cursor:pointer;
}

.friendMessageButton{
  border:1px solid rgba(68,105,218,.18);
  background:rgba(68,105,218,.08);
  color:#4566c8;
}

.friendRemoveButton{
  border:1px solid rgba(193,116,54,.18);
  background:rgba(193,116,54,.07);
  color:#a2612d;
}

.removedFriendDirectory{
  display:grid;
  gap:8px;
}

.removedFriendRow{
  display:flex;
  align-items:center;
  justify-content:space-between;

  gap:12px;

  padding:11px;

  border:1px solid rgba(127,139,156,.15);
  border-radius:11px;

  background:rgba(127,139,156,.045);
}

.removedFriendIdentity{
  min-width:0;

  display:flex;
  align-items:center;

  gap:10px;
}

.removedFriendIdentity>span{
  min-width:0;
  display:grid;
}

.removedFriendIdentity b{
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
}

.removedFriendIdentity small{
  color:var(--muted);
}

.removedFriendIdentity em{
  margin-top:2px;

  color:var(--muted);
  font-size:7px;
  font-style:normal;
}

.removedFriendActions{
  flex:none;

  display:flex;
  gap:6px;
}

.restoreConnectionButton{
  border:1px solid rgba(68,105,218,.18);

  background:rgba(68,105,218,.08);

  color:#4566c8;
}

.deletePersonButton{
  border:1px solid rgba(202,67,67,.18);

  background:rgba(202,67,67,.07);

  color:#b43f3f;
}

.friendMessageButton:hover,
.restoreConnectionButton:hover{
  background:rgba(68,105,218,.14);
}

.friendRemoveButton:hover{
  background:rgba(193,116,54,.12);
}

.deletePersonButton:hover{
  background:rgba(202,67,67,.13);
}

.friendMessageButton:disabled,
.friendRemoveButton:disabled,
.restoreConnectionButton:disabled,
.deletePersonButton:disabled{
  opacity:.55;
  cursor:not-allowed;
