@media(max-width:720px){

  .friendRowWithActions,
  .removedFriendRow{
    align-items:stretch;
    flex-direction:column;
  }

  .friendRowActions,
  .removedFriendActions{
    width:100%;
  }

  .friendRowActions button,
  .removedFriendActions button{
    flex:1;
  }
}

