  display:flex;
  align-items:center;

  gap:16px;

  padding-bottom:17px;

  border-bottom:1px solid #edf0f4;
}

.resumeJobScoreRing{
  --job-progress:0deg;

  flex:0 0 76px;

  width:76px;
  height:76px;

  display:grid;
  place-items:center;

  border-radius:50%;

  background:
    conic-gradient(
      #3159d9
