  padding:12px;

  border:1px solid #e8ebf0;
  border-radius:10px;

  background:#fafbfc;
}

.resumeJobKeywordStats strong,
.resumeJobKeywordStats span{
  display:block;
}

.resumeJobKeywordStats strong{
  color:#1b2a40;

  font-size:19px;
}

.resumeJobKeywordStats span{
  margin-top:3px;

  color:#8791a0;

  font-size:7px;
}


/* KEYWORDS */

.resumeJobKeywordSection{
  padding:15px 0;

  border-top:1px solid #edf0f4;
}

.resumeJobKeywordSection>div:first-child{
  display:flex;
  align-items:center;
  justify-content:space-between;

  gap:15px;

  margin-bottom:9px;
}

.resumeJobKeywordSection>div:first-child>span{
  color:#546176;

  font-size:7px;
  font-weight:850;

  letter-spacing:.11em;
}

.resumeJobKeywordSection>div:first-child>small{
  color:#9aa3b0;

  font-size:7px;
}

.resumeJobChips{
  display:flex;
  flex-wrap:wrap;

  gap:6px;
}

.resumeJobChips span{
  padding:6px 8px;

  border-radius:7px;

  font-size:7px;
  font-weight:750;
}

.resumeJobChips span.matched{
  border:1px solid #ccebdd;

  background:#edf9f3;

  color:#1d8055;
}

.resumeJobChips span.missing{
  border:1px solid #f0d9ca;

  background:#fff7f0;

  color:#a85b28;
}

.resumeJobChips span.neutral{
  border:1px solid #dce4f2;

  background:#f4f7fc;

  color:#55709b;
}

.resumeJobChips p{
  margin:0 !important;

  color:#98a1ae !important;

  font-size:8px !important;
}

.resumeJobDisclaimer{
  margin-top:15px;

  color:#929dab;

  font-size:7px;

  line-height:1.5;

  text-align:center;
}


@media(max-width:1000px){

