  padding: 14px 16px;
  border: 1px solid #e2e7ec;
  border-radius: 13px;
  background: rgba(255, 255, 255, 0.85);
  text-align: center;
}

.linkedinNetworkTopStats strong {
  display: block;
  color: #0a66c2;
  font-size: 21px;
}

.linkedinNetworkTopStats span {
  display: block;
  margin-top: 2px;
  color: #69737d;
  font-size: 10px;
  font-weight: 700;
}

.linkedinNetworkStatus {
  width: min(1360px, 100%);
  margin: 0 auto 16px;
}

.linkedinNetworkLayout {
  display: grid;
  grid-template-columns:
    minmax(220px, 270px)
    minmax(0, 1fr)
    minmax(250px, 310px);
  gap: 18px;
  width: min(1360px, 100%);
  margin: 0 auto;
  align-items: start;
}

.linkedinNetworkLeft,
.linkedinNetworkRight {
  display: grid;
  gap: 16px;
  position: sticky;
  top: 18px;
}

.linkedinProfileCard,
.linkedinNetworkMenu,
.linkedinNetworkSearch,
.linkedinPersonCard,
.linkedinInvitationCard,
.linkedinNetworkInfo,
.linkedinNetworkEmpty {
  overflow: hidden;
  border: 1px solid #dfe3e8;
  border-radius: 14px;
  background: #ffffff;
  box-shadow:
    0 3px 12px rgba(20, 36, 52, 0.04);
}

.linkedinProfileCover {
  position: relative;
  height: 74px;
  background:
    radial-gradient(
      circle at 80% 30%,
      rgba(255, 255, 255, 0.2),
      transparent 24%
    ),
    linear-gradient(
      135deg,
      #0a66c2,
      #4f82b8 55%,
      #769bc2
    );
}

.linkedinProfileCover span {
  position: absolute;
  right: 14px;
  bottom: 9px;
  color: rgba(255, 255, 255, 0.25);
  font-size: 27px;
  font-weight: 900;
}

.linkedinProfileIdentity {
  padding: 0 18px;
  text-align: center;
}

.linkedinProfileIdentity > .avatar {
  width: 76px;
  height: 76px;
  margin-top: -38px;
  border: 4px solid #fff;
  box-shadow: 0 4px 16px rgba(16, 36, 54, 0.13);
}

.linkedinProfileIdentity h2 {
  margin: 10px 0 3px;
  color: #191919;
  font-size: 18px;
  line-height: 1.2;
}

.linkedinProfileIdentity p {
  margin: 0;
  color: #4d555d;
  font-size: 12px;
  line-height: 1.5;
}

.linkedinProfileIdentity small {
  display: block;
  margin-top: 3px;
  color: #7a838c;
  font-size: 10px;
}

.linkedinProfileBio {
  margin: 14px 18px 0;
  color: #626b73;
  font-size: 11px;
  line-height: 1.6;
  text-align: center;
}

.linkedinProfileSkills {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 6px;
  padding: 14px 16px;
}

.linkedinProfileSkills span,
.linkedinPersonSkills span {
  border: 1px solid #d6e5f4;
  border-radius: 999px;
  padding: 5px 9px;
  background: #f5f9fd;
  color: #275f94;
  font-size: 9px;
  font-weight: 700;
}

.linkedinProfileMetrics {
  display: grid;
  grid-template-columns: 1fr 1fr;
  border-top: 1px solid #e7eaed;
}

.linkedinProfileMetrics div {
  padding: 13px;
}

.linkedinProfileMetrics div + div {
  border-left: 1px solid #e7eaed;
}

.linkedinProfileMetrics span {
  display: block;
  color: #737b83;
  font-size: 9px;
  font-weight: 700;
}

.linkedinProfileMetrics strong {
  display: block;
  margin-top: 3px;
  color: #0a66c2;
  font-size: 15px;
}

.linkedinNetworkMenu {
  padding: 16px;
}

.linkedinNetworkMenu header {
  margin-bottom: 7px;
}

.linkedinNetworkMenu p {
  display: grid;
  grid-template-columns: 26px 1fr auto;
  align-items: center;
  gap: 8px;
  margin: 0;
  padding: 9px 2px;
  color: #4c555e;
  font-size: 11px;
}

.linkedinNetworkMenu p + p {
  border-top: 1px solid #f0f1f2;
}

.linkedinNetworkMenu p b {
  font-weight: 700;
}

.linkedinNetworkMenu p strong {
  color: #0a66c2;
  font-size: 11px;
}

.linkedinMenuIcon {
  display: grid;
  width: 24px;
  height: 24px;
  place-items: center;
  border-radius: 7px;
  background: #eef5fb;
  color: #0a66c2;
  font-size: 12px;
}

.linkedinNetworkMain {
  min-width: 0;
}

.linkedinNetworkSearch {
  padding: 20px;
  margin-bottom: 16px;
}

.linkedinNetworkSearchHeading {
  display: flex;
  justify-content: space-between;
  gap: 20px;
  align-items: flex-start;
}

.linkedinNetworkSearchHeading h2 {
  margin: 0;
  color: #191919;
  font-size: 21px;
  letter-spacing: -0.02em;
}

.linkedinNetworkSearchHeading p {
  margin: 5px 0 0;
  color: #69737c;
  font-size: 11px;
}

.linkedinNetworkSearchHeading > strong {
  flex: 0 0 auto;
  border-radius: 999px;
  padding: 6px 10px;
  background: #eef5fb;
  color: #0a66c2;
  font-size: 10px;
}

.linkedinSearchInput {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: 17px;
  padding: 0 14px;
  border: 1px solid #ccd5dd;
  border-radius: 8px;
  background: #fff;
}

.linkedinSearchInput:focus-within {
  border-color: #0a66c2;
  box-shadow: 0 0 0 2px rgba(10, 102, 194, 0.1);
}

.linkedinSearchInput > span {
  color: #687078;
  font-size: 21px;
}

.linkedinSearchInput input {
  flex: 1;
  min-width: 0;
  height: 44px;
  border: 0;
  outline: 0;
  background: transparent;
  color: #252a2f;
  font: inherit;
  font-size: 12px;
}

.linkedinSearchInput button {
  border: 0;
  background: transparent;
  color: #66717a;
  cursor: pointer;
  font-size: 20px;
}

.linkedinRoleFilters {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
  margin-top: 13px;
}

.linkedinRoleFilters button {
  border: 1px solid #c9d1d9;
  border-radius: 999px;
  padding: 7px 12px;
  background: #fff;
  color: #505962;
  cursor: pointer;
  font-size: 10px;
  font-weight: 700;
  transition:
    border-color 160ms ease,
    background 160ms ease,
    color 160ms ease;
}

.linkedinRoleFilters button:hover {
  border-color: #0a66c2;
  background: #f4f9fd;
  color: #0a66c2;
}

.linkedinRoleFilters button.active {
  border-color: #0a66c2;
  background: #0a66c2;
  color: #fff;
}

.linkedinPeopleGrid {
  display: grid;
  grid-template-columns:
    repeat(2, minmax(0, 1fr));
  gap: 14px;
}

.linkedinPersonCard {
  min-width: 0;
}

.linkedinPersonCover {
  position: relative;
  height: 72px;
  padding: 12px;
  background:
    radial-gradient(
      circle at 85% 20%,
      rgba(255, 255, 255, 0.36),
      transparent 25%
    ),
    linear-gradient(
      135deg,
      #dceaf7,
      #edf4fa 45%,
      #e8eef5
    );
}

.linkedinPersonCover span {
  position: absolute;
  right: 13px;
  top: 12px;
  max-width: 70%;
  color: #52708d;
  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.06em;
  text-align: right;
  text-transform: uppercase;
}

.linkedinPersonBody {
  position: relative;
  padding: 0 17px 17px;
}

.linkedinPersonAvatar {
  height: 34px;
}

.linkedinPersonAvatar > .avatar {
  width: 68px;
  height: 68px;
  transform: translateY(-34px);
  border: 4px solid #fff;
  box-shadow: 0 4px 15px rgba(25, 42, 58, 0.13);
}

.linkedinPersonHeading h3 {
  display: flex;
  align-items: center;
  gap: 5px;
  margin: 6px 0 3px;
  color: #1b1f23;
  font-size: 16px;
  line-height: 1.25;
}

.linkedinPersonHeading h3 > span {
  display: inline-grid;
  width: 16px;
  height: 16px;
  place-items: center;
  border-radius: 50%;
  background: #0a66c2;
  color: #fff;
  font-size: 9px;
}

.linkedinPersonHeading p {
  margin: 0;
  color: #4e5862;
  font-size: 10px;
  line-height: 1.5;
}

.linkedinPersonHeading small {
  display: block;
  margin-top: 3px;
  color: #7a828a;
  font-size: 9px;
}

.linkedinPersonBio {
  min-height: 48px;
  margin: 12px 0;
  color: #626b73;
  font-size: 10px;
  line-height: 1.55;
}

.linkedinPersonSkills {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
  min-height: 28px;
}

.linkedinPersonActions {
  display: flex;
  gap: 8px;
  margin-top: 15px;
}

.linkedinPersonActions button,
.linkedinInvitations button {
  flex: 1;
  min-height: 34px;
  border-radius: 999px;
  padding: 7px 13px;
  cursor: pointer;
  font-size: 10px;
  font-weight: 800;
}

.linkedinPrimaryButton {
  border: 1px solid #0a66c2;
  background: #0a66c2;
  color: #fff;
}

.linkedinPrimaryButton:hover {
  background: #004182;
}

.linkedinSecondaryButton {
  border: 1px solid #6b737b;
  background: #fff;
  color: #555d64;
}

.linkedinSecondaryButton:hover {
  border-color: #25292d;
  background: #f4f4f4;
}

.linkedinPendingButton,
.linkedinConnectedButton {
  border: 1px solid #b7c2cc;
  background: #f5f7f8;
  color: #59636c;
  cursor: default !important;
}

.linkedinConnectedButton {
  border-color: #8fb79b;
  background: #f1f8f3;
  color: #337045;
}

.linkedinInvitationCard {
  padding: 17px;
}

.linkedinInvitationCard > header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 8px;
}

.linkedinInvitationCard h3 {
  margin: 0;
  color: #22272b;
  font-size: 15px;
}

.linkedinInvitationCard > header > strong {
  display: grid;
  min-width: 28px;
  height: 28px;
  place-items: center;
  border-radius: 999px;
  background: #eef5fb;
  color: #0a66c2;
  font-size: 11px;
}

.linkedinInvitations article {
  display: grid;
  grid-template-columns: 42px 1fr;
  gap: 10px;
  padding: 13px 0;
  border-top: 1px solid #eef0f2;
}

.linkedinInvitations article > .avatar {
  width: 42px;
  height: 42px;
}

.linkedinInvitations b {
  display: block;
  color: #25292d;
  font-size: 11px;
}

.linkedinInvitations small {
  display: block;
  margin-top: 2px;
  color: #747d85;
  font-size: 9px;
  line-height: 1.4;
}

.linkedinInvitations article > div > div {
  display: flex;
  gap: 6px;
  margin-top: 8px;
}

.linkedinInvitations button {
  min-height: 29px;
  padding: 5px 9px;
  font-size: 9px;
}

.linkedinNoInvitations {
  padding: 23px 10px 12px;
  text-align: center;
}

.linkedinNoInvitations > span {
  display: grid;
  width: 42px;
  height: 42px;
  margin: 0 auto 9px;
  place-items: center;
  border-radius: 50%;
  background: #edf7f0;
  color: #438254;
  font-size: 17px;
  font-weight: 900;
}

.linkedinNoInvitations b {
  display: block;
  color: #394049;
  font-size: 11px;
}

.linkedinNoInvitations p {
  margin: 5px auto 0;
  color: #7b838b;
  font-size: 9px;
  line-height: 1.5;
}

.linkedinNetworkInfo {
  padding: 18px;
}

.linkedinNetworkInfo h3 {
  margin: 0;
  color: #20252a;
  font-size: 15px;
}

.linkedinNetworkInfo p {
  margin: 9px 0 14px;
  color: #6a737b;
  font-size: 10px;
  line-height: 1.65;
}

.linkedinNetworkInfo > div {
  display: grid;
  gap: 7px;
}

.linkedinNetworkInfo > div span {
  position: relative;
  padding-left: 17px;
  color: #4e5963;
  font-size: 9px;
  font-weight: 700;
}

.linkedinNetworkInfo > div span::before {
  position: absolute;
  left: 0;
  content: "✓";
  color: #0a66c2;
  font-weight: 900;
}

.linkedinNetworkEmpty {
  grid-column: 1 / -1;
  padding: 48px 24px;
  text-align: center;
}

.linkedinNetworkEmpty > span {
  display: block;
  color: #7c8994;
  font-size: 37px;
}

.linkedinNetworkEmpty h3 {
  margin: 8px 0 3px;
  color: #31363b;
  font-size: 16px;
}

.linkedinNetworkEmpty p {
  margin: 0;
  color: #737d86;
  font-size: 10px;
}

.linkedinNetworkLoader {
  width: 30px;
  height: 30px;
  margin: 0 auto 14px;
  border: 3px solid #d9e6f1;
  border-top-color: #0a66c2;
  border-radius: 50%;
  animation: linkedinNetworkSpin 800ms linear infinite;
}

@keyframes linkedinNetworkSpin {
  to {
    transform: rotate(360deg);
  }
}

@media (max-width: 1180px) {
  .linkedinNetworkLayout {
    grid-template-columns:
      minmax(210px, 250px)
      minmax(0, 1fr);
  }

  .linkedinNetworkRight {
    position: static;
    grid-column: 1 / -1;
    grid-template-columns: 1fr 1fr;
  }
}

@media (max-width: 900px) {
  .linkedinNetworkPage {
    padding: 18px;
  }

  .linkedinNetworkTopbar {
    align-items: stretch;
    flex-direction: column;
  }

  .linkedinNetworkTopStats {
    width: 100%;
  }

  .linkedinNetworkTopStats article {
    flex: 1;
    min-width: 0;
  }

  .linkedinNetworkLayout {
    grid-template-columns: 1fr;
  }

  .linkedinNetworkLeft,
  .linkedinNetworkRight {
    position: static;
  }

  .linkedinNetworkLeft {
    grid-template-columns: 1fr 1fr;
  }

  .linkedinPeopleGrid {
    grid-template-columns: 1fr 1fr;
  }
}

@media (max-width: 650px) {
  .linkedinNetworkPage {
    padding: 12px;
  }

  .linkedinNetworkTopbar {
    padding: 21px 18px;
    border-radius: 14px;
  }

  .linkedinNetworkTopStats {
    gap: 6px;
  }

  .linkedinNetworkTopStats article {
    padding: 11px 6px;
  }

  .linkedinNetworkLayout,
  .linkedinNetworkLeft,
  .linkedinNetworkRight,
  .linkedinPeopleGrid {
    grid-template-columns: 1fr;
  }

  .linkedinNetworkSearchHeading {
    flex-direction: column;
  }

  .linkedinPersonCover {
    height: 80px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .linkedinNetworkLoader {
    animation: none;
  }
}


