.linkedinNetworkTabs {
  display: grid;
  grid-template-columns: 1fr 1fr;
  margin-bottom: 16px;
  padding: 5px;
  overflow: hidden;
  border: 1px solid #dfe3e8;
  border-radius: 14px;
  background: #ffffff;
}

.linkedinNetworkTabs button {
  position: relative;
  display: flex;
  min-height: 54px;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 2px;
  border: 0;
  border-radius: 10px;
  background: transparent;
  color: #5f6871;
  cursor: pointer;
  transition:
    background 160ms ease,
    color 160ms ease;
}

.linkedinNetworkTabs button:hover {
  background: #f4f7f9;
