}

.marketplaceSearch {
  display: grid;
  grid-template-columns: minmax(260px, 1fr) 190px 170px;
  gap: 10px;
  padding: 13px;
  border: 1px solid var(--market-line);
  border-radius: 16px;
  background: var(--market-surface);
}

.marketplaceSearch input,
.marketplaceSearch select {
  width: 100%;
  min-height: 43px;
  padding: 11px 13px;
  border: 1px solid rgba(86, 97, 112, .15);
  border-radius: 10px;
  background: #fff;
  color: var(--market-ink);
  font: inherit;
  font-size: 10px;
  outline: none;
  transition: border-color .18s ease, box-shadow .18s ease;
}

.marketplaceSearch input:focus,
.marketplaceSearch select:focus {
  border-color: rgba(91, 124, 153, .45);
  box-shadow: 0 0 0 3px rgba(91, 124, 153, .08);
}

.marketplaceGrid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 16px;
}

.marketplaceCard {
  overflow: hidden;
  border: 1px solid var(--market-line);
  border-radius: 19px;
  background: var(--market-surface);
  box-shadow: 0 8px 22px rgba(31, 41, 51, .045);
  transition: transform .18s ease, box-shadow .18s ease;
}

.marketplaceCard:nth-child(4n + 1) {
  background: linear-gradient(180deg, #fffdf9 0%, #fcf8f1 100%);
}

.marketplaceCard:nth-child(4n + 2) {
  background: linear-gradient(180deg, #fffdf9 0%, #f4f8fa 100%);
}

.marketplaceCard:nth-child(4n + 3) {
  background: linear-gradient(180deg, #fffdf9 0%, #f4f7f3 100%);
}

.marketplaceCard:nth-child(4n + 4) {
  background: linear-gradient(180deg, #fffdf9 0%, #f8f3f7 100%);
}

.marketplaceCard:hover {
  transform: translateY(-4px);
  box-shadow: 0 18px 34px rgba(31, 41, 51, .09);
}

.marketplaceCardPhoto {
  position: relative;
  display: block;
  width: calc(100% - 16px);
  height: 210px;
  margin: 8px;
  padding: 0;
  overflow: hidden;
  border: 0;
  border-radius: 14px;
  background: #eee9e1;
  cursor: pointer;
}

.marketplaceCardPhoto img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform .25s ease;
}

.marketplaceCard:hover .marketplaceCardPhoto img {
  transform: scale(1.025);
}

.marketplaceStatusBadge {
  position: absolute;
  top: 10px;
  left: 10px;
  padding: 6px 8px;
  border-radius: 999px;
  backdrop-filter: blur(10px);
  background: rgba(255, 255, 255, .92);
  color: #4a5561;
  font-size: 8px;
  font-weight: 800;
  box-shadow: 0 4px 12px rgba(31, 41, 51, .09);
}

.marketplaceStatusBadge.available {
  background: rgba(237, 243, 238, .95);
  color: #55705d;
}

.marketplaceStatusBadge.reserved {
  background: rgba(251, 240, 221, .96);
  color: #996820;
}

.marketplaceStatusBadge.sold {
  background: rgba(66, 72, 81, .9);
  color: #fff;
}

.marketplaceCardBody {
  display: grid;
  gap: 10px;
  padding: 10px 15px 16px;
}

.marketplacePriceRow {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.marketplacePriceRow strong {
  font-size: 20px;
  letter-spacing: -.02em;
}

.marketplacePriceRow button {
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  border: 1px solid rgba(86, 97, 112, .12);
  border-radius: 50%;
  background: #fff;
  color: #8c7b72;
  cursor: pointer;
  font-size: 20px;
}

.marketplacePriceRow button.saved {
  background: var(--market-terracotta-soft);
  color: #a9533b;
  border-color: rgba(185, 104, 75, .16);
}

.marketplaceTitleButton {
  padding: 0;
  border: 0;
  background: transparent;
  text-align: left;
  color: var(--market-ink);
  cursor: pointer;
  font-size: 12px;
  font-weight: 800;
  line-height: 1.45;
}

.marketplaceChips {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.marketplaceChips span {
  padding: 5px 8px;
  border-radius: 999px;
  background: var(--market-blue-soft);
  color: #526f87;
  font-size: 8px;
  font-weight: 750;
}

.marketplaceChips span:nth-child(2) {
  background: var(--market-amber-soft);
  color: #94651f;
}

.marketplaceChips span:nth-child(3) {
  background: var(--market-sage-soft);
  color: #58705f;
}

.marketplaceCardBody > small {
  color: var(--market-muted);
  font-size: 8px;
}

.marketplaceSellerMini {
  display: grid;
  gap: 3px;
  padding: 10px 0 0;
  border: 0;
  border-top: 1px solid var(--market-line);
  background: transparent;
  text-align: left;
  cursor: pointer;
}

.marketplaceSellerMini b {
  color: #415260;
  font-size: 9px;
}

.marketplaceSellerMini span {
  color: var(--market-muted);
  font-size: 8px;
}

.marketplaceOwnerActions {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 6px;
  margin-top: 3px;
}

.marketplaceOwnerActions button {
  padding: 8px 6px;
  border: 1px solid rgba(86, 97, 112, .13);
  border-radius: 8px;
  background: #fff;
  color: #485663;
  cursor: pointer;
  font-size: 8px;
  font-weight: 700;
}

.marketplaceOwnerActions button:nth-child(1) {
  background: var(--market-blue-soft);
  color: #4f708a;
}

.marketplaceOwnerActions button:nth-child(2) {
  background: var(--market-amber-soft);
  color: #956821;
}

.marketplaceOwnerActions button:nth-child(3) {
  background: var(--market-sage-soft);
  color: #55715d;
}

.marketplaceOwnerActions button.danger {
  background: var(--market-terracotta-soft);
  color: #a65740;
}

.marketplaceSellForm {
  display: grid;
  gap: 18px;
  max-width: 960px;
  padding: 28px;
  border: 1px solid var(--market-line);
  border-radius: 22px;
  background:
    linear-gradient(135deg, rgba(255, 253, 249, .98), rgba(248, 244, 238, .9));
  box-shadow: 0 18px 40px rgba(31, 41, 51, .05);
}

.marketplaceSellForm header {
  padding-bottom: 15px;
  border-bottom: 1px solid var(--market-line);
}

.marketplaceSellForm header > span {
  display: inline-flex;
  width: fit-content;
  margin-bottom: 9px;
  padding: 5px 8px;
  border-radius: 999px;
  background: var(--market-lavender-soft);
  color: #75688e;
}

.marketplaceSellForm header h3 {
  margin: 0;
  font-size: 24px;
  letter-spacing: -.025em;
}

.marketplaceSellForm header p {
  margin: 8px 0 0;
  max-width: 620px;
  color: var(--market-muted);
  font-size: 10px;
  line-height: 1.6;
}

.marketplaceSellForm label {
  display: grid;
  gap: 7px;
}

.marketplaceSellForm label > span:first-child {
  color: #495663;
  font-size: 9px;
  font-weight: 800;
}

.marketplaceSellForm input,
.marketplaceSellForm select,
.marketplaceSellForm textarea {
  width: 100%;
  padding: 12px 13px;
  border: 1px solid rgba(86, 97, 112, .15);
  border-radius: 10px;
  background: rgba(255, 255, 255, .88);
  color: var(--market-ink);
  font: inherit;
  outline: none;
  transition: border-color .18s ease, box-shadow .18s ease;
}

.marketplaceSellForm input:focus,
.marketplaceSellForm select:focus,
.marketplaceSellForm textarea:focus {
  border-color: rgba(91, 124, 153, .42);
  box-shadow: 0 0 0 3px rgba(91, 124, 153, .075);
}

.marketplaceSellForm textarea {
  min-height: 150px;
  resize: vertical;
}

.marketplaceFormGrid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
}

.marketplaceNegotiable {
  display: flex !important;
  align-items: flex-start;
  gap: 11px !important;
  padding: 13px;
  border: 1px solid rgba(197, 138, 58, .16);
  border-radius: 12px;
  background: var(--market-amber-soft);
}

.marketplaceNegotiable input {
  width: auto;
  margin-top: 3px;
}

.marketplaceNegotiable > span {
  display: grid;
  gap: 2px;
}

.marketplaceNegotiable b {
  color: #7d5a24;
  font-size: 9px;
}

.marketplaceNegotiable small {
  color: #8a7352;
  font-size: 8px;
}

.marketplacePhotoUpload {
  min-height: 110px;
  place-items: center;
  padding: 18px;
  border: 1.5px dashed rgba(91, 124, 153, .32);
  border-radius: 16px;
  background: rgba(234, 241, 246, .55);
  cursor: pointer;
  text-align: center;
}

.marketplacePhotoUpload input {
  display: none;
}

.marketplacePhotoUpload > span {
  display: grid;
  gap: 5px;
}

.marketplacePhotoUpload b {
  color: #536f86;
}

.marketplacePhotoUpload small {
  color: var(--market-muted);
  font-size: 8px;
}

.marketplaceSelectedPhotos {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
}

.marketplaceSelectedPhotos > div {
  position: relative;
  height: 140px;
  overflow: hidden;
  border: 1px solid var(--market-line);
  border-radius: 12px;
  background: var(--market-soft);
}

.marketplaceSelectedPhotos img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.marketplaceSelectedPhotos button {
  position: absolute;
  top: 7px;
  right: 7px;
  width: 28px;
  height: 28px;
  border: 0;
  border-radius: 50%;
  background: rgba(49, 54, 61, .76);
  color: #fff;
  cursor: pointer;
}

.marketplaceSellForm footer {
  display: flex;
  justify-content: flex-end;
  gap: 9px;
  padding-top: 3px;
}

.marketplaceSellForm footer button {
  padding: 10px 15px;
  border: 1px solid var(--market-line);
  border-radius: 10px;
  background: #fff;
  color: #53606d;
  font-weight: 750;
  cursor: pointer;
}

.marketplaceSellForm footer .primary {
  border: 0;
  background: #5b7c99;
  color: #fff;
}

.marketplaceEmpty {
  display: grid;
  place-items: center;
  gap: 7px;
  min-height: 240px;
  padding: 30px;
  border: 1px dashed rgba(86, 97, 112, .18);
  border-radius: 16px;
  background: linear-gradient(135deg, #fffaf3, #f5f8fb);
  text-align: center;
  color: var(--market-muted);
}

.marketplaceEmpty b {
  color: var(--market-ink);
  font-size: 13px;
}

.marketplaceModalScrim {
  position: fixed;
  inset: 0;
  z-index: 1000;
  display: grid;
  place-items: center;
  padding: 24px;
  background: rgba(28, 35, 43, .63);
  backdrop-filter: blur(9px);
}

.marketplaceDetailsModal {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1.08fr) minmax(340px, .92fr);
  width: min(1100px, 100%);
  max-height: 92vh;
  overflow: auto;
  border: 1px solid rgba(255, 255, 255, .35);
  border-radius: 24px;
  background: #fffdf9;
  box-shadow: 0 30px 80px rgba(17, 24, 39, .25);
}

.marketplaceModalClose {
  position: absolute;
  top: 13px;
  right: 13px;
  z-index: 4;
  width: 37px;
  height: 37px;
  border: 0;
  border-radius: 50%;
  background: rgba(50, 57, 66, .82);
  color: white;
  cursor: pointer;
  font-size: 19px;
}

.marketplaceGallery {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  align-content: start;
  gap: 5px;
  min-height: 520px;
  padding: 6px;
  background: #f1ece5;
}

.marketplaceGallery img {
  width: 100%;
  height: 260px;
  object-fit: cover;
  border-radius: 10px;
}

.marketplaceGallery img:first-child {
  grid-column: 1 / -1;
  height: 365px;
}

.marketplaceDetailsBody {
  display: grid;
  align-content: start;
  gap: 15px;
  padding: 32px;
}

.marketplaceDetailsBody > span {
  width: fit-content;
  padding: 6px 9px;
  border-radius: 999px;
  background: var(--market-blue-soft);
  color: #56738c;
  font-size: 8px;
  font-weight: 800;
  letter-spacing: .08em;
}

.marketplaceDetailsBody h2 {
  margin: 0;
  font-size: 27px;
  line-height: 1.2;
  letter-spacing: -.025em;
}

.marketplaceDetailsBody > strong {
  color: #273849;
  font-size: 30px;
}

.marketplaceDetailsBody > p {
  margin: 4px 0;
  white-space: pre-wrap;
  color: #56616d;
  line-height: 1.75;
  font-size: 11px;
}

.marketplacePickup {
  background: var(--market-amber-soft);
}

.marketplaceSellerBox {
  background: var(--market-sage-soft);
}

.marketplacePickup,
.marketplaceSellerBox {
  display: grid;
  gap: 5px;
  padding: 15px;
  border: 1px solid var(--market-line);
  border-radius: 13px;
}

.marketplacePickup small,
.marketplaceSellerBox small {
  color: var(--market-muted);
  font-size: 8px;
}

.marketplaceSellerBox > span {
  color: #5f7866;
}

.marketplaceSellerBox > div {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 9px;
}

.marketplaceSellerBox button {
  padding: 9px 12px;
  border: 1px solid rgba(86, 97, 112, .14);
  border-radius: 9px;
  background: #fff;
  color: #50606c;
  cursor: pointer;
  font-size: 9px;
  font-weight: 750;
}

.marketplaceSellerBox button.primary {
  border: 0;
  background: #5b7c99;
  color: #fff;
}

.marketplaceReport {
  justify-self: start;
  border: 0;
  background: transparent;
  color: #a65640;
  cursor: pointer;
  font-size: 9px;
  font-weight: 700;
}

@media (max-width: 1100px) {
  .marketplaceGrid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

@media (max-width: 800px) {
  .marketplaceGrid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .marketplaceSearch {
    grid-template-columns: 1fr;
  }

  .marketplaceDetailsModal {
    grid-template-columns: 1fr;
  }

  .marketplaceHero {
    align-items: flex-start;
    flex-direction: column;
  }
}

@media (max-width: 560px) {
  .marketplaceGrid {
    grid-template-columns: 1fr;
  }

  .marketplaceFormGrid,
  .marketplaceSelectedPhotos {
    grid-template-columns: 1fr 1fr;
  }

  .marketplaceOwnerActions {
    grid-template-columns: 1fr 1fr;
  }

  .marketplaceGallery {
    grid-template-columns: 1fr;
  }

  .marketplaceGallery img:first-child {
    grid-column: auto;
  }

  .marketplaceHero,
  .marketplaceSellForm {
    padding: 21px;
  }
}

/* =========================================================
   CAMPUSCONNECT — PROFESSIONAL ANNOUNCEMENT STUDIO
========================================================= */

.announcementStudio {
  --announce-navy: #30495d;
  --announce-navy-dark: #243847;
  --announce-blue: #66829a;
  --announce-blue-soft: #edf3f6;
  --announce-gold: #b58a52;
  --announce-gold-soft: #f8f0e4;
  --announce-sage: #78917d;
  --announce-sage-soft: #edf3ee;
  --announce-terracotta: #ad6852;
  --announce-terracotta-soft: #f7ebe6;
  --announce-burgundy: #875964;
  --announce-burgundy-soft: #f4eaed;
  --announce-lavender: #81768e;
  --announce-lavender-soft: #f0edf3;
  --announce-cream: #fffdf9;
  --announce-soft: #f8f6f2;
  --announce-line: #e5e0d8;
  --announce-ink: #29343d;
  --announce-muted: #727b82;

  display: grid;
  gap: 20px;
}


/* HERO */

.announcementHero {
  position: relative;
  display: grid;
  grid-template-columns:
    minmax(0, 1.2fr)
    minmax(310px, .8fr);
  gap: 34px;
  min-height: 300px;
  padding: clamp(30px, 5vw, 58px);
  overflow: hidden;
  border: 1px solid rgba(48, 73, 93, .1);
  border-radius: 28px;
  background:
    radial-gradient(
      circle at 83% 15%,
      rgba(181, 138, 82, .18),
      transparent 27%
    ),
    radial-gradient(
      circle at 62% 100%,
      rgba(120, 145, 125, .16),
      transparent 34%
    ),
    linear-gradient(
      135deg,
      #f9f5ef 0%,
      #f4f6f4 49%,
      #edf2f4 100%
    );
  box-shadow:
    0 24px 60px rgba(45, 58, 68, .08);
}

.announcementHero::before {
  content: "";
  position: absolute;
  top: -80px;
  right: 27%;
  width: 170px;
  height: 170px;
  border:
    1px solid rgba(48, 73, 93, .08);
  border-radius: 50%;
}

.announcementHeroCopy {
  position: relative;
  z-index: 2;
  align-self: center;
}

.announcementHeroEyebrow {
  display: inline-flex;
  align-items: center;
  min-height: 28px;
  padding: 0 11px;
  border:
    1px solid rgba(48, 73, 93, .11);
  border-radius: 999px;
  background: rgba(255, 253, 249, .72);
  color: #61798d;
  font-size: 9px;
  font-weight: 850;
  letter-spacing: .12em;
}

.announcementHero h2 {
  margin: 18px 0 0;
  color: var(--announce-navy-dark);
  font-family:
    Georgia,
    "Times New Roman",
    serif;
  font-size: clamp(32px, 4.8vw, 56px);
  font-weight: 500;
  line-height: .98;
  letter-spacing: -.045em;
}

.announcementHeroCopy > p {
  max-width: 590px;
  margin: 19px 0 0;
  color: #68747d;
  font-size: 12px;
  line-height: 1.75;
}

.announcementHeroAccent {
  display: flex;
  gap: 5px;
  width: 145px;
  height: 5px;
  margin-top: 23px;
}

.announcementHeroAccent span {
  flex: 1;
  border-radius: 999px;
}

.announcementHeroAccent span:nth-child(1) {
  background: var(--announce-navy);
}

.announcementHeroAccent span:nth-child(2) {
  background: var(--announce-gold);
}

.announcementHeroAccent span:nth-child(3) {
  background: var(--announce-sage);
}

.announcementHeroAccent span:nth-child(4) {
  background: var(--announce-terracotta);
}


/* HERO VISUAL */

.announcementHeroVisual {
  position: relative;
  min-height: 230px;
}

.announcementHeroPaper {
  position: absolute;
  width: 235px;
  min-height: 150px;
  padding: 20px;
  border:
    1px solid rgba(48, 73, 93, .1);
  border-radius: 18px;
  background: rgba(255, 253, 249, .96);
  box-shadow:
    0 22px 45px rgba(40, 54, 65, .11);
}

.announcementHeroPaper span {
  display: block;
  color: var(--announce-gold);
  font-size: 8px;
  font-weight: 900;
  letter-spacing: .13em;
}

.announcementHeroPaper b {
  display: block;
  margin-top: 9px;
  color: #364957;
  font-family:
    Georgia,
    "Times New Roman",
    serif;
  font-size: 18px;
  font-weight: 500;
}

.announcementHeroPaper i {
  display: block;
  width: 100%;
  height: 5px;
  margin-top: 11px;
  border-radius: 99px;
  background: #e6e8e7;
}

.announcementHeroPaper i:nth-of-type(2) {
  width: 75%;
}

.announcementHeroPaper i:nth-of-type(3) {
  width: 52%;
}

.paperOne {
  top: 14px;
  left: 5%;
  transform: rotate(-5deg);
}

.paperTwo {
  right: 1%;
  bottom: 10px;
  transform: rotate(5deg);
}

.paperTwo span {
  color: var(--announce-sage);
}

.announcementHeroSeal {
  position: absolute;
  z-index: 4;
  top: 50%;
  left: 50%;
  width: 79px;
  height: 79px;
  display: grid;
  place-content: center;
  text-align: center;
  border:
    6px solid rgba(255, 253, 249, .9);
  border-radius: 50%;
  background:
    linear-gradient(
      145deg,
      #5f788c,
      #3e596d
    );
  color: white;
  transform:
    translate(-50%, -50%);
  box-shadow:
    0 14px 30px rgba(45, 62, 75, .21);
}

.announcementHeroSeal strong {
  font-size: 20px;
  line-height: 1;
}

.announcementHeroSeal small {
  display: block;
  margin-top: 4px;
  color: #dce6eb;
  font-size: 7px;
  font-weight: 800;
  letter-spacing: .11em;
}


/* OVERVIEW */

.announcementOverview {
  display: grid;
  grid-template-columns:
    repeat(4, minmax(0, 1fr));
  gap: 12px;
}

.announcementOverviewCard {
  display: flex;
  align-items: center;
  gap: 13px;
  min-height: 82px;
  padding: 15px;
  border: 1px solid var(--announce-line);
  border-radius: 17px;
  background: var(--announce-cream);
  box-shadow:
    0 10px 26px rgba(43, 54, 62, .045);
}

.announcementOverviewIcon {
  flex: 0 0 auto;
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  border-radius: 13px;
  font-size: 11px;
  font-weight: 900;
}

.announcementOverviewCard.navy
.announcementOverviewIcon {
  background: var(--announce-blue-soft);
  color: var(--announce-navy);
}

.announcementOverviewCard.gold
.announcementOverviewIcon {
  background: var(--announce-gold-soft);
  color: #986f3d;
}

.announcementOverviewCard.sage
.announcementOverviewIcon {
  background: var(--announce-sage-soft);
  color: #5b7461;
}

.announcementOverviewCard.terracotta
.announcementOverviewIcon {
  background: var(--announce-terracotta-soft);
  color: #975743;
}

.announcementOverviewCard strong {
  display: block;
  color: var(--announce-ink);
  font-size: 20px;
  line-height: 1;
}

.announcementOverviewCard small {
  display: block;
  margin-top: 5px;
  color: var(--announce-muted);
  font-size: 8px;
}


/* SECTION HEADING */

.announcementSectionHeader {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 20px;
  padding: 8px 2px 0;
}

.announcementSectionHeader > div:first-child > span {
  color: #78909e;
  font-size: 8px;
  font-weight: 900;
  letter-spacing: .13em;
}

.announcementSectionHeader h3 {
  margin: 6px 0 0;
  color: #2e3d48;
  font-family:
    Georgia,
    "Times New Roman",
    serif;
  font-size: 27px;
  font-weight: 500;
}

.announcementSectionHeader p {
  margin: 6px 0 0;
  color: var(--announce-muted);
  font-size: 9px;
}

.announcementResultCount {
  min-width: 82px;
  padding: 10px 14px;
  border: 1px solid var(--announce-line);
  border-radius: 14px;
  background: var(--announce-cream);
  text-align: center;
}

.announcementResultCount strong {
  display: block;
  color: var(--announce-navy);
  font-size: 17px;
}

.announcementResultCount small {
  color: var(--announce-muted);
  font-size: 7px;
}


/* FEED */

.professionalAnnouncementFeed {
  display: grid;
  gap: 14px;
}

.professionalAnnouncementCard {
  position: relative !important;
  display: block !important;
  padding: 0 !important;
  overflow: hidden !important;
  border:
    1px solid var(--announce-line) !important;
  border-radius: 20px !important;
  background:
    var(--announce-cream) !important;
  box-shadow:
    0 12px 32px rgba(39, 51, 59, .055) !important;
  transition:
    transform .18s ease,
    box-shadow .18s ease,
    border-color .18s ease;
}

.professionalAnnouncementCard:hover {
  transform: translateY(-2px);
  border-color:
    rgba(77, 103, 122, .2) !important;
  box-shadow:
    0 20px 44px rgba(39, 51, 59, .08) !important;
}

.professionalAnnouncementCard.pinned {
  border-color:
    rgba(181, 138, 82, .28) !important;
  background:
    linear-gradient(
      135deg,
      #fffdf9,
      #fcf8f0
    ) !important;
}

.announcementCardStripe {
  height: 4px;
  background: var(--announce-blue);
}

.professionalAnnouncementCard.academic
.announcementCardStripe {
  background: var(--announce-blue);
}

.professionalAnnouncementCard.placement
.announcementCardStripe {
  background: var(--announce-sage);
}

.professionalAnnouncementCard.campus
.announcementCardStripe {
  background: var(--announce-gold);
}

.professionalAnnouncementCard.exam
.announcementCardStripe {
  background: var(--announce-lavender);
}

.professionalAnnouncementCard.emergency
.announcementCardStripe {
  background: var(--announce-terracotta);
}

.professionalAnnouncementCard.festival
.announcementCardStripe {
  background:
    linear-gradient(
      90deg,
      var(--announce-gold),
      var(--announce-terracotta),
      var(--announce-lavender)
    );
}

.professionalAnnouncementCard.featured
.announcementCardStripe {
  background:
    linear-gradient(
      90deg,
      var(--announce-navy),
      var(--announce-gold)
    );
}


/* CARD HEADER */

.announcementCardHeader {
  display: grid;
  grid-template-columns:
    46px minmax(0, 1fr) auto;
  gap: 13px;
  align-items: start;
  padding: 20px 20px 0;
}

.announcementCategoryIcon {
  width: 44px;
  height: 44px;
  display: grid;
  place-items: center;
  border-radius: 13px;
  background: var(--announce-blue-soft);
  color: var(--announce-navy);
  font-size: 12px;
  font-weight: 900;
}

.announcementCategoryIcon.placement {
  background: var(--announce-sage-soft);
  color: #607864;
}

.announcementCategoryIcon.campus {
  background: var(--announce-gold-soft);
  color: #98703e;
}

.announcementCategoryIcon.exam {
  background: var(--announce-lavender-soft);
  color: #70647e;
}

.announcementCategoryIcon.emergency {
  background: var(--announce-terracotta-soft);
  color: #9b5945;
}

.announcementCategoryIcon.festival {
  background: #f8efe5;
  color: #a56d45;
}

.announcementCategoryIcon.featured {
  background: var(--announce-burgundy-soft);
  color: var(--announce-burgundy);
}

.announcementBadgeRow {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.announcementCategoryBadge,
.announcementTypeBadge,
.announcementPinnedBadge {
  min-height: 23px;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 0 8px;
  border-radius: 999px;
  font-size: 7px;
  font-weight: 850;
  letter-spacing: .04em;
}

.announcementCategoryBadge {
  background: var(--announce-blue-soft);
  color: #5d7589;
}

.announcementCategoryBadge.placement {
  background: var(--announce-sage-soft);
  color: #607763;
}

.announcementCategoryBadge.campus {
  background: var(--announce-gold-soft);
  color: #916b3d;
}

.announcementCategoryBadge.exam {
  background: var(--announce-lavender-soft);
  color: #71677b;
}

.announcementCategoryBadge.emergency {
  background: var(--announce-terracotta-soft);
  color: #965746;
}

.announcementTypeBadge.featured {
  background: var(--announce-burgundy-soft);
  color: #805461;
}

.announcementTypeBadge.festival {
  background: var(--announce-gold-soft);
  color: #93683c;
}

.announcementTypeBadge.emergency {
  background: var(--announce-terracotta-soft);
  color: #954f3e;
}

.announcementPinnedBadge {
  background: #f7f0e5;
  color: #9a723f;
}

.announcementPinnedBadge span {
  font-size: 6px;
}

.announcementCardHeading h3 {
  margin: 9px 0 0;
  color: #2d3b45;
  font-family:
    Georgia,
    "Times New Roman",
    serif;
  font-size: 19px;
  font-weight: 500;
  line-height: 1.28;
}

.announcementCardDate {
  min-width: 96px;
  padding-top: 2px;
  color: #63717b;
  text-align: right;
}

.announcementCardDate span {
  display: block;
  font-size: 8px;
  font-weight: 750;
}

.announcementCardDate small {
  display: block;
  margin-top: 3px;
  color: #92999f;
  font-size: 7px;
}


/* BODY */

.announcementCardBody {
  padding:
    16px
    20px
    17px
    79px;
}

.announcementCardBody p {
  margin: 0;
  max-width: 950px;
  color: #626e76;
  font-size: 10px;
  line-height: 1.72;
  white-space: pre-wrap;
}


/* METADATA */

.announcementMetadata {
  display: grid;
  grid-template-columns:
    repeat(3, minmax(0, 1fr));
  gap: 8px;
  margin:
    0
    20px
    17px
    79px;
}

.announcementMetadata > div {
  display: flex;
  align-items: center;
  gap: 9px;
  min-width: 0;
  padding: 9px 10px;
  border:
    1px solid #ece7df;
  border-radius: 11px;
  background: #fbf9f5;
}

.announcementMetaIcon {
  flex: 0 0 auto;
  width: 28px;
  height: 28px;
  display: grid;
  place-items: center;
  border-radius: 8px;
  background: #edf2f4;
  color: #60788c;
  font-size: 8px;
  font-weight: 900;
}

.announcementMetadata p {
  min-width: 0;
  margin: 0;
}

.announcementMetadata small {
  display: block;
  color: #92989c;
  font-size: 6px;
  font-weight: 800;
  letter-spacing: .06em;
}

.announcementMetadata b {
  display: block;
  overflow: hidden;
  margin-top: 2px;
  color: #4a565e;
  font-size: 8px;
  text-overflow: ellipsis;
  white-space: nowrap;
}


/* ATTACHMENTS */

.announcementAttachments {
  margin:
    0
    20px
    17px
    79px;
  padding: 13px;
  border:
    1px solid #e8e1d8;
  border-radius: 13px;
  background: #faf7f2;
}

.announcementAttachments > header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 9px;
}

.announcementAttachments > header span {
  color: #73818a;
  font-size: 7px;
  font-weight: 900;
  letter-spacing: .11em;
}

.announcementAttachments > header small {
  color: #969b9e;
  font-size: 7px;
}

.announcementAttachmentGrid {
  display: grid;
  grid-template-columns:
    repeat(2, minmax(0, 1fr));
  gap: 7px;
}

.announcementAttachmentGrid button {
  display: grid !important;
  grid-template-columns:
    34px minmax(0, 1fr) auto;
  align-items: center;
  gap: 8px;
  width: 100% !important;
  min-height: 49px !important;
  padding: 7px 9px !important;
  border:
    1px solid #e5ded5 !important;
  border-radius: 10px !important;
  background: #fffdf9 !important;
  color: #46545d !important;
  text-align: left;
  cursor: pointer;
}

.announcementFileIcon {
  width: 32px;
  height: 32px;
  display: grid;
  place-items: center;
  border-radius: 8px;
  background: var(--announce-blue-soft);
  color: #5d768b;
  font-size: 6px;
  font-weight: 900;
}

.announcementAttachmentGrid button b {
  display: block;
  overflow: hidden;
  font-size: 8px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.announcementAttachmentGrid button small {
  display: block;
  margin-top: 2px;
  color: #93999d;
  font-size: 6px;
}

.announcementAttachmentGrid button i {
  color: #87939a;
  font-size: 11px;
  font-style: normal;
}


/* FOOTER */

.announcementCardFooter {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  min-height: 65px;
  padding:
    12px
    20px;
  border-top:
    1px solid #ebe5dd;
  background: #fcfaf6;
}

.announcementVerifiedPublisher {
  display: flex;
  align-items: center;
  gap: 9px;
}

.announcementVerifiedPublisher > span {
  width: 28px;
  height: 28px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: var(--announce-sage-soft);
  color: #617965;
  font-size: 9px;
  font-weight: 900;
}

.announcementVerifiedPublisher p {
  margin: 0;
}

.announcementVerifiedPublisher b {
  display: block;
  color: #536068;
  font-size: 8px;
}

.announcementVerifiedPublisher small {
  display: block;
  margin-top: 2px;
  color: #92989c;
  font-size: 6px;
}


/* Override legacy announcement action fix */

.announcementStudio
.professionalAnnouncementCard
.announcementCardActions {
  position: static !important;
  display: flex !important;
  align-items: center !important;
  justify-content: flex-end !important;
  flex-wrap: wrap !important;
  width: auto !important;
  gap: 6px !important;
  margin: 0 !important;
  padding: 0 !important;
  border: 0 !important;
}

.announcementStudio
.professionalAnnouncementCard
.announcementCardActions button {
  width: auto !important;
  min-width: 58px !important;
  min-height: 31px !important;
  margin: 0 !important;
  padding: 0 10px !important;
  border:
    1px solid #dfd8cf !important;
  border-radius: 8px !important;
  background: #fff !important;
  color: #59656d !important;
  font-size: 7px !important;
  font-weight: 800 !important;
  cursor: pointer;
}

.announcementStudio
.professionalAnnouncementCard
.announcementCardActions button:hover {
  background: #f5f1eb !important;
}

.announcementStudio
.professionalAnnouncementCard
.announcementCardActions button.danger {
  border-color:
    rgba(173, 104, 82, .2) !important;
  background:
    var(--announce-terracotta-soft) !important;
  color: #955642 !important;
}


/* EMPTY */

.announcementEmptyState {
  display: grid;
  justify-items: center;
  padding: 50px 24px;
  border:
    1px dashed #dcd4ca;
  border-radius: 20px;
  background: #fbf8f3;
  text-align: center;
}

.announcementEmptyState > span {
  width: 48px;
  height: 48px;
  display: grid;
  place-items: center;
  border-radius: 14px;
  background: var(--announce-blue-soft);
  color: var(--announce-navy);
  font-size: 13px;
  font-weight: 900;
}

.announcementEmptyState h3 {
  margin: 13px 0 0;
  color: #3f4d56;
  font-family:
    Georgia,
    "Times New Roman",
    serif;
  font-size: 20px;
  font-weight: 500;
}

.announcementEmptyState p {
  max-width: 380px;
  margin: 7px 0 0;
  color: #7f878c;
  font-size: 9px;
  line-height: 1.6;
}


/* RESPONSIVE */

@media (max-width: 1050px) {
  .announcementHero {
    grid-template-columns:
      minmax(0, 1fr)
      300px;
  }

  .announcementOverview {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 760px) {
  .announcementHero {
    grid-template-columns: 1fr;
    min-height: auto;
    padding: 28px;
  }

  .announcementHeroVisual {
    min-height: 210px;
  }

  .announcementCardHeader {
    grid-template-columns:
      42px
      minmax(0, 1fr);
  }

  .announcementCardDate {
    grid-column:
      2;
    text-align: left;
  }

  .announcementCardBody,
  .announcementMetadata,
  .announcementAttachments {
    margin-left: 20px;
    padding-left: 0;
  }

  .announcementMetadata {
    grid-template-columns: 1fr;
  }

  .announcementAttachmentGrid {
    grid-template-columns: 1fr;
  }

  .announcementCardFooter {
    align-items: flex-start;
    flex-direction: column;
  }

  .announcementStudio
  .professionalAnnouncementCard
  .announcementCardActions {
    justify-content:
      flex-start !important;
  }
}

@media (max-width: 520px) {
  .announcementOverview {
    grid-template-columns: 1fr 1fr;
  }

  .announcementHero {
    padding: 22px;
    border-radius: 20px;
  }

  .announcementHero h2 {
    font-size: 34px;
  }

  .announcementHeroPaper {
    width: 200px;
  }

  .announcementSectionHeader {
    align-items: flex-start;
    flex-direction: column;
  }

  .announcementCardHeader {
    padding:
      16px
      16px
      0;
  }

  .announcementCardBody {
    margin: 0;
    padding:
      14px
      16px;
  }

  .announcementMetadata,
  .announcementAttachments {
    margin:
      0
      16px
      14px;
  }

  .announcementCardFooter {
    padding: 13px 16px;
  }
}

/* =========================================================
   CAMPUSCONNECT — PERSONAL NOTES & TASKS
========================================================= */

.personalWorkspace {
  --pw-navy: #314b5f;
  --pw-ink: #293842;
  --pw-muted: #778188;
  --pw-line: #e5e0d8;
  --pw-cream: #fffdf8;
  --pw-sage: #819584;
  --pw-gold: #b68b53;
  --pw-terra: #ad6b56;
  --pw-lavender: #82768f;
  display: grid;
  gap: 18px;
}

.personalWorkspaceHero {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 28px;
  padding: 30px;
  border: 1px solid #e2ddd5;
  border-radius: 24px;
  background:
    radial-gradient(circle at 88% 20%, rgba(182,139,83,.16), transparent 25%),
    radial-gradient(circle at 68% 95%, rgba(129,149,132,.15), transparent 30%),
    linear-gradient(135deg, #fffaf3, #f2f5f3);
  box-shadow: 0 18px 45px rgba(45,57,65,.07);
}

.personalWorkspaceHero > div:first-child > span,
.workspaceSection > header span {
  color: #788a96;
  font-size: 8px;
  font-weight: 900;
  letter-spacing: .13em;
}

.personalWorkspaceHero h2 {
  margin: 7px 0 0;
  color: var(--pw-ink);
  font-family: Georgia, "Times New Roman", serif;
  font-size: clamp(30px,4vw,46px);
  font-weight: 500;
}

.personalWorkspaceHero p {
  max-width: 560px;
  margin: 9px 0 0;
  color: var(--pw-muted);
  font-size: 10px;
  line-height: 1.7;
}

.personalWorkspaceHeroActions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 8px;
}

.personalWorkspaceHeroActions button,
.personalWorkspaceModal footer button {
  min-height: 38px;
  padding: 0 14px;
  border: 1px solid #ddd7ce;
  border-radius: 10px;
  background: #fffdf9;
  color: #53616a;
  font-size: 8px;
  font-weight: 800;
  cursor: pointer;
}

.personalWorkspaceHeroActions button.primary,
.personalWorkspaceModal footer button.primary {
  border-color: #314b5f;
  background: #314b5f;
  color: #fff;
}

.personalWorkspaceStats {
  display: grid;
  grid-template-columns: repeat(4,minmax(0,1fr));
  gap: 10px;
}

.personalWorkspaceStats article {
  padding: 16px;
  border: 1px solid var(--pw-line);
  border-radius: 16px;
  background: var(--pw-cream);
}

.personalWorkspaceStats article.warning {
  background: #fbefeb;
}

.personalWorkspaceStats span {
  display: block;
  color: #8a9297;
  font-size: 7px;
  font-weight: 900;
  letter-spacing: .1em;
}

.personalWorkspaceStats strong {
  display: block;
  margin-top: 7px;
  color: var(--pw-ink);
  font-size: 22px;
}

.personalWorkspaceStats small {
  color: #81898e;
  font-size: 7px;
}

.personalWorkspaceToolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
}

.personalWorkspaceTabs {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.personalWorkspaceTabs button {
  min-height: 32px;
  padding: 0 11px;
  border: 1px solid #e2ddd6;
  border-radius: 999px;
  background: #fff;
  color: #707b82;
  font-size: 7px;
  font-weight: 800;
  cursor: pointer;
}

.personalWorkspaceTabs button.active {
  border-color: #425f73;
  background: #425f73;
  color: #fff;
}

.personalWorkspaceSearch {
  display: flex;
  align-items: center;
  min-width: min(330px,100%);
  min-height: 38px;
  padding: 0 11px;
  border: 1px solid #e1dcd4;
  border-radius: 11px;
  background: #fff;
}

.personalWorkspaceSearch span {
  color: #81909a;
}

.personalWorkspaceSearch input {
  flex: 1;
  min-width: 0;
  border: 0;
  outline: 0;
  padding: 0 9px;
  background: transparent;
  color: #3d4b54;
  font-size: 9px;
}

.personalWorkspaceSearch button {
  border: 0;
  background: transparent;
  color: #899197;
  cursor: pointer;
}

.personalWorkspaceStatus {
  padding: 11px 13px;
  border: 1px solid #e4ddd4;
  border-radius: 11px;
  background: #faf6ef;
  color: #72685e;
  font-size: 8px;
}

.personalWorkspaceContent,
.workspaceSection {
  display: grid;
  gap: 13px;
}

.workspaceSection > header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 14px;
}

.workspaceSection > header h3 {
  margin: 5px 0 0;
  color: #344650;
  font-family: Georgia, "Times New Roman", serif;
  font-size: 22px;
  font-weight: 500;
}

.workspaceSection > header > strong {
  display: grid;
  place-items: center;
  min-width: 38px;
  height: 30px;
  border: 1px solid #e3ded7;
  border-radius: 10px;
  background: #fff;
  color: #66747d;
  font-size: 9px;
}

.workspaceTaskGrid,
.workspaceNoteGrid {
  display: grid;
  grid-template-columns: repeat(3,minmax(0,1fr));
  gap: 12px;
}

.workspaceTaskCard,
.workspaceNoteCard {
  position: relative;
  padding: 17px;
  border: 1px solid #e4ded6;
  border-radius: 17px;
  background: #fffdf9;
  box-shadow: 0 10px 26px rgba(47,56,62,.045);
}

.workspaceTaskCard.priority-high {
  border-top: 4px solid #b48b55;
}

.workspaceTaskCard.priority-urgent {
  border-top: 4px solid #a85d4b;
}

.workspaceTaskCard.priority-medium {
  border-top: 4px solid #718b76;
}

.workspaceTaskCard.priority-low {
  border-top: 4px solid #748a9b;
}

.workspaceTaskCard.overdue {
  background: #fff8f5;
}

.workspaceTaskTop,
.workspaceNoteTop {
  display: flex;
  justify-content: space-between;
  gap: 8px;
}

.workspaceTaskTop span,
.workspaceTaskTop b,
.workspaceNoteTop span,
.workspaceNoteTop b {
  padding: 4px 7px;
  border-radius: 999px;
  background: #f0f3f4;
  color: #697981;
  font-size: 6px;
  font-weight: 850;
}

.workspaceTaskTop b,
.workspaceNoteTop b {
  background: #f7eee2;
  color: #906b3f;
}

.workspaceTaskCard h4,
.workspaceNoteCard h4,
.workspaceReminderCopy h4 {
  margin: 12px 0 0;
  color: #33434d;
  font-size: 12px;
}

.workspaceTaskCard > p,
.workspaceNoteCard > p,
.workspaceReminderCopy p {
  margin: 8px 0 0;
  color: #707b82;
  font-size: 8px;
  line-height: 1.65;
  white-space: pre-wrap;
}

.workspaceTaskMeta {
  display: flex;
  justify-content: space-between;
  gap: 9px;
  margin-top: 15px;
  color: #8b9296;
  font-size: 7px;
}

.workspaceTaskCard footer,
.workspaceNoteCard footer {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 15px;
  padding-top: 12px;
  border-top: 1px solid #eee8e0;
}

.workspaceTaskCard footer button,
.workspaceNoteCard footer button,
.workspaceReminderActions button,
.workspaceCompletedList button {
  min-height: 29px;
  padding: 0 9px;
  border: 1px solid #ddd7ce;
  border-radius: 8px;
  background: #fff;
  color: #64717a;
  font-size: 7px;
  font-weight: 800;
  cursor: pointer;
}

.workspaceTaskCard footer button.danger,
.workspaceNoteCard footer button.danger,
.workspaceReminderActions button.danger {
  border-color: #ead4cc;
  background: #fbefeb;
  color: #965846;
}

.workspaceNoteCard.color-blue {
  background: #f1f6f8;
}

.workspaceNoteCard.color-sage {
  background: #f1f5f0;
}

.workspaceNoteCard.color-gold {
  background: #fbf4e9;
}

.workspaceNoteCard.color-terracotta {
  background: #f9eeea;
}

.workspaceNoteCard.color-lavender {
  background: #f3eff5;
}

.workspaceNoteCard.color-burgundy {
  background: #f6edef;
}

.workspaceTags {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
  margin-top: 13px;
}

.workspaceTags span {
  color: #71808a;
  font-size: 7px;
}

.workspaceReminderList {
  display: grid;
  gap: 8px;
}

.workspaceReminderList article {
  display: grid;
  grid-template-columns: 145px minmax(0,1fr) auto;
  align-items: center;
  gap: 15px;
  padding: 14px;
  border: 1px solid #e4ded7;
  border-radius: 14px;
  background: #fffdf9;
}

.workspaceReminderList article.overdue {
  background: #fff5f1;
}

.workspaceReminderTime span {
  display: block;
  color: #9a7350;
  font-size: 6px;
  font-weight: 900;
  letter-spacing: .08em;
}

.workspaceReminderTime strong {
  display: block;
  margin-top: 4px;
  color: #465660;
  font-size: 8px;
}

.workspaceReminderCopy small {
  display: block;
  margin-top: 6px;
  color: #93999c;
  font-size: 7px;
}

.workspaceReminderActions {
  display: flex;
  gap: 5px;
}

.workspaceCompletedList {
  display: grid;
  gap: 7px;
}

.workspaceCompletedList article {
  display: grid;
  grid-template-columns: 32px minmax(0,1fr) auto;
  align-items: center;
  gap: 10px;
  padding: 11px;
  border: 1px solid #e4dfd8;
  border-radius: 12px;
  background: #fff;
}

.workspaceCompletedList article > span {
  width: 30px;
  height: 30px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: #edf4ee;
  color: #657b69;
}

.workspaceCompletedList b,
.workspaceCompletedList small {
  display: block;
}

.workspaceCompletedList b {
  color: #53616a;
  font-size: 8px;
}

.workspaceCompletedList small {
  margin-top: 2px;
  color: #92999d;
  font-size: 7px;
}

.personalWorkspaceEmpty {
  display: grid;
  justify-items: center;
  padding: 45px 20px;
  border: 1px dashed #ded8d0;
  border-radius: 17px;
  background: #fbf8f3;
  color: #7f888e;
  text-align: center;
  font-size: 9px;
}

.personalWorkspaceEmpty > span {
  font-size: 23px;
}

.personalWorkspaceEmpty h3 {
  margin: 9px 0 0;
  color: #485861;
}

.personalWorkspaceEmpty p {
  margin: 5px 0 0;
}

.personalWorkspaceModalBackdrop {
  position: fixed;
  inset: 0;
  z-index: 10000;
  display: grid;
  place-items: center;
  padding: 20px;
  overflow: auto;
  background: rgba(22,31,38,.52);
  backdrop-filter: blur(8px);
}

.personalWorkspaceModal {
  position: relative;
  width: min(680px,100%);
  max-height: 92vh;
  overflow: auto;
  padding: 24px;
  border: 1px solid #e1dbd3;
  border-radius: 20px;
  background: #fffdf9;
  box-shadow: 0 30px 80px rgba(20,30,37,.24);
}

.personalWorkspaceModalClose {
  position: absolute;
  top: 14px;
  right: 14px;
  width: 32px;
  height: 32px;
  border: 1px solid #ddd7cf;
  border-radius: 50%;
  background: #fff;
  color: #68757d;
  cursor: pointer;
}

.personalWorkspaceModal form {
  display: grid;
  gap: 14px;
}

.personalWorkspaceModal header span {
  color: #81909a;
  font-size: 7px;
  font-weight: 900;
  letter-spacing: .12em;
}

.personalWorkspaceModal header h3 {
  margin: 5px 0 0;
  color: #344650;
  font-family: Georgia, "Times New Roman", serif;
  font-size: 24px;
  font-weight: 500;
}

.personalWorkspaceModal label {
  display: grid;
  gap: 6px;
  color: #68757c;
  font-size: 8px;
  font-weight: 750;
}

.personalWorkspaceModal input,
.personalWorkspaceModal textarea,
.personalWorkspaceModal select {
  width: 100%;
  min-height: 40px;
  padding: 9px 11px;
  border: 1px solid #ddd8d1;
  border-radius: 10px;
  outline: none;
  background: #fff;
  color: #34434d;
  font: inherit;
}

.personalWorkspaceModal textarea {
  min-height: 120px;
  resize: vertical;
}

.personalWorkspaceFormGrid {
  display: grid;
  grid-template-columns: repeat(2,minmax(0,1fr));
  gap: 10px;
}

.personalWorkspaceCheck {
  display: flex !important;
  grid-template-columns: none !important;
  align-items: center;
  gap: 8px !important;
}

.personalWorkspaceCheck input {
  width: 16px;
  min-height: 16px;
}

.personalWorkspaceModal footer {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  padding-top: 6px;
}

@media (max-width: 900px) {
  .workspaceTaskGrid,
  .workspaceNoteGrid {
    grid-template-columns: repeat(2,minmax(0,1fr));
  }

  .personalWorkspaceStats {
    grid-template-columns: repeat(2,minmax(0,1fr));
  }
}

@media (max-width: 650px) {
  .personalWorkspaceHero,
  .personalWorkspaceToolbar {
    align-items: stretch;
    flex-direction: column;
  }

  .personalWorkspaceHeroActions {
    justify-content: flex-start;
  }

  .personalWorkspaceSearch {
    min-width: 100%;
  }

  .workspaceTaskGrid,
  .workspaceNoteGrid {
    grid-template-columns: 1fr;
  }

  .workspaceReminderList article {
    grid-template-columns: 1fr;
  }

  .workspaceReminderActions {
    flex-wrap: wrap;
  }

  .personalWorkspaceFormGrid {
    grid-template-columns: 1fr;
  }
}

.workspaceChecklistProgress {
  display: grid;
  gap: 6px;
  margin-top: 14px;
}

.workspaceChecklistProgress > div:first-child {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  color: #7e898f;
  font-size: 7px;
}

.workspaceChecklistProgress b {
  color: #52626c;
}

.workspaceChecklistBar {
  position: relative;
  height: 5px;
  overflow: hidden;
  border-radius: 999px;
  background: #e8e5df;
}

.workspaceChecklistBar i {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: #718a77;
  transition: width .2s ease;
}

.personalTaskChecklistEditor {
  display: grid;
  gap: 10px;
  padding: 14px;
  border: 1px solid #e2ddd6;
  border-radius: 14px;
  background: #faf8f4;
}

.personalTaskChecklistHeading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.personalTaskChecklistHeading span {
  display: block;
  color: #8a969d;
  font-size: 6px;
  font-weight: 900;
  letter-spacing: .11em;
}

.personalTaskChecklistHeading strong {
  display: block;
  margin-top: 3px;
  color: #50606a;
  font-size: 8px;
}

.personalTaskChecklistHeading > b {
  min-width: 36px;
  padding: 6px 8px;
  border: 1px solid #ded9d1;
  border-radius: 9px;
  background: #fff;
  color: #61717a;
  text-align: center;
  font-size: 8px;
}

.personalTaskChecklistAdd {
  display: grid;
  grid-template-columns: minmax(0,1fr) auto;
  gap: 7px;
}

.personalTaskChecklistAdd button {
  min-width: 60px;
  border: 1px solid #405d70;
  border-radius: 9px;
  background: #405d70;
  color: #fff;
  font-size: 7px;
  font-weight: 850;
  cursor: pointer;
}

.personalTaskChecklistAdd button:disabled {
  cursor: not-allowed;
  opacity: .5;
}

.personalTaskChecklistItems {
  display: grid;
  gap: 6px;
}

.personalTaskChecklistItems > div {
  display: grid;
  grid-template-columns: 26px minmax(0,1fr) 26px;
  align-items: center;
  gap: 8px;
  padding: 8px;
  border: 1px solid #e5e0d9;
  border-radius: 10px;
  background: #fff;
}

.personalTaskChecklistItems > div.completed span {
  color: #91999d;
  text-decoration: line-through;
}

.personalTaskChecklistItems .check {
  width: 24px;
  height: 24px;
  border: 1px solid #cfd8d0;
  border-radius: 7px;
  background: #f2f6f2;
  color: #627a67;
  cursor: pointer;
}

.personalTaskChecklistItems .remove {
  width: 24px;
  height: 24px;
  border: 0;
  border-radius: 7px;
  background: transparent;
  color: #a36e5e;
  cursor: pointer;
}

.personalTaskChecklistItems small {
  padding: 8px 2px;
  color: #929a9e;
  font-size: 7px;
}

.personalTaskChecklistHint {
  padding: 10px 12px;
  border: 1px dashed #ddd6cd;
  border-radius: 10px;
  background: #faf7f1;
  color: #858d91;
  font-size: 7px;
  line-height: 1.5;
}

/* =========================================================
   CAMPUSCONNECT — PROFESSIONAL STAFF ROLE DASHBOARD
   Faculty · Placement · Coordinator · Volunteer · Admin
========================================================= */

.proRoleDashboard {
  --prd-accent: #456375;
  --prd-accent-soft: #edf3f6;
  --prd-accent-rgb: 69, 99, 117;
  --prd-secondary: #a17f55;
  --prd-secondary-soft: #f7f0e6;
  --prd-ink: #263943;
  --prd-body: #607078;
  --prd-muted: #8b959a;
  --prd-line: #e3ded6;
  --prd-card: #fffdf9;
  --prd-surface: #f8f6f1;
  --prd-dark: #273d49;

  display: grid;
  gap: 18px;
  width: 100%;
}

/* FACULTY */
.proRoleDashboard-faculty {
  --prd-accent: #486b7d;
  --prd-accent-soft: #eaf2f6;
  --prd-accent-rgb: 72, 107, 125;
  --prd-secondary: #748d7b;
  --prd-secondary-soft: #eef4ef;
  --prd-dark: #294551;
}

/* PLACEMENT CELL */
.proRoleDashboard-placement-cell {
  --prd-accent: #755d68;
  --prd-accent-soft: #f3ecef;
  --prd-accent-rgb: 117, 93, 104;
  --prd-secondary: #aa8050;
  --prd-secondary-soft: #f8f0e5;
  --prd-dark: #493844;
}

/* COORDINATOR */
.proRoleDashboard-coordinator {
  --prd-accent: #647d69;
  --prd-accent-soft: #edf3ee;
  --prd-accent-rgb: 100, 125, 105;
  --prd-secondary: #98745a;
  --prd-secondary-soft: #f6eee8;
  --prd-dark: #354b3a;
}

/* VOLUNTEER */
.proRoleDashboard-volunteer {
  --prd-accent: #987059;
  --prd-accent-soft: #f7eee9;
  --prd-accent-rgb: 152, 112, 89;
  --prd-secondary: #718694;
  --prd-secondary-soft: #edf2f5;
  --prd-dark: #514038;
}

/* MAIN ADMIN */
.proRoleDashboard-main-admin {
  --prd-accent: #354f62;
  --prd-accent-soft: #eaf0f4;
  --prd-accent-rgb: 53, 79, 98;
  --prd-secondary: #a4814e;
  --prd-secondary-soft: #f7f0e5;
  --prd-dark: #223744;
}


/* =========================================================
   HERO
========================================================= */

.proRoleDashboard .proDashboardHero {
  position: relative;
  display: grid;
  grid-template-columns:
    minmax(0, 1.2fr)
    minmax(320px, .72fr);
  align-items: stretch;
  gap: 25px;

  min-height: 325px;
  padding: 30px;

  overflow: hidden;

  border:
    1px solid
    rgba(255,255,255,.08);

  border-radius: 28px;

  background:
    radial-gradient(
      circle at 88% 12%,
      rgba(226,201,160,.14),
      transparent 27%
    ),
    radial-gradient(
      circle at 43% 110%,
      rgba(177,202,190,.11),
      transparent 34%
    ),
    linear-gradient(
      135deg,
      var(--prd-dark) 0%,
      color-mix(
        in srgb,
        var(--prd-dark) 82%,
        var(--prd-accent)
      ) 55%,
      var(--prd-accent) 145%
    );

  box-shadow:
    0 25px 60px
    rgba(29,44,53,.15);
}

.proRoleDashboard .proDashboardOrb {
  position: absolute;
  pointer-events: none;
  border-radius: 999px;
  filter: blur(1px);
}

.proRoleDashboard .proDashboardOrbOne {
  width: 330px;
  height: 330px;
  top: -220px;
  right: 18%;
  background:
    rgba(255,255,255,.055);
}

.proRoleDashboard .proDashboardOrbTwo {
  width: 240px;
  height: 240px;
  bottom: -175px;
  left: 30%;
  background:
    rgba(255,244,220,.055);
}

.proRoleDashboard .proDashboardHeroContent {
  position: relative;
  z-index: 2;
  display: flex;
  flex-direction: column;
  justify-content: center;
  max-width: 760px;
}

.proRoleDashboard .proDashboardHeroContent > span {
  display: inline-flex;
  width: fit-content;
  align-items: center;
  gap: 7px;

  margin-bottom: 13px;

  color: #dec69e;

  font-size: 7px;
  font-weight: 900;
  letter-spacing: .17em;
}

.proRoleDashboard .proDashboardHeroContent > span::before {
  content: "";
  width: 22px;
  height: 1px;
  background: #dec69e;
}

.proRoleDashboard .proDashboardHeroContent h1 {
  max-width: 720px;
  margin: 0;

  color: #fff;

  font-family:
    Georgia,
    "Times New Roman",
    serif;

  font-size:
    clamp(34px, 4.3vw, 51px);

  font-weight: 500;
  line-height: 1.04;
  letter-spacing: -.03em;
}

.proRoleDashboard .proDashboardHeroContent > p {
  max-width: 640px;
  margin: 15px 0 0;

  color:
    rgba(239,244,246,.7);

  font-size: 10px;
  line-height: 1.75;
}


/* =========================================================
   HERO RIGHT ROLE CARD
========================================================= */

.proRoleDashboard .proDashboardHeroAside {
  position: relative;
  z-index: 2;

  display: flex;
  flex-direction: column;

  padding: 17px;

  border:
    1px solid
    rgba(255,255,255,.14);

  border-radius: 21px;

  background:
    rgba(255,255,255,.075);

  backdrop-filter:
    blur(18px);

  box-shadow:
    inset 0 1px 0
    rgba(255,255,255,.08);
}

.proRoleDashboard .proDashboardHeroAside > header {
  display: grid;
  grid-template-columns:
    42px
    minmax(0,1fr)
    auto;
  align-items: center;
  gap: 10px;

  padding-bottom: 13px;

  border-bottom:
    1px solid
    rgba(255,255,255,.1);
}

.proRoleDashboard .proDashboardRoleMark {
  display: grid;
  place-items: center;

  width: 42px;
  height: 42px;

  border:
    1px solid
    rgba(255,255,255,.15);

  border-radius: 12px;

  background:
    rgba(255,255,255,.09);

  color: #fff2df;

  font-size: 9px;
  font-weight: 900;
}

.proRoleDashboard .proDashboardHeroAside header small {
  display: block;

  color:
    rgba(239,244,246,.47);

  font-size: 6px;
  font-weight: 900;
  letter-spacing: .09em;
}

.proRoleDashboard .proDashboardHeroAside header strong {
  display: block;
  margin-top: 3px;

  color: #fff;

  font-size: 9px;
}

.proRoleDashboard .proDashboardLiveDot {
  width: 7px;
  height: 7px;

  border-radius: 50%;

  background: #bdcdbb;

  box-shadow:
    0 0 0 5px
    rgba(189,205,187,.1);
}


/* =========================================================
   HERO METRICS
========================================================= */

.proRoleDashboard .proDashboardHeroMetrics {
  display: grid;
  grid-template-columns:
    repeat(3, minmax(0,1fr));

  gap: 7px;

  margin-top: 13px;
}

.proRoleDashboard .proDashboardHeroMetrics button {
  min-height: 91px;
  padding: 11px;

  text-align: left;

  border:
    1px solid
    rgba(255,255,255,.1);

  border-radius: 12px;

  background:
    rgba(255,255,255,.055);

  cursor: pointer;

  transition:
    transform .2s ease,
    background .2s ease;
}

.proRoleDashboard .proDashboardHeroMetrics button:hover {
  transform: translateY(-2px);

  background:
    rgba(255,255,255,.09);
}

.proRoleDashboard .proDashboardHeroMetrics small {
  display: block;

  min-height: 18px;

  color:
    rgba(238,244,246,.48);

  font-size: 5.5px;
  font-weight: 900;
  letter-spacing: .08em;
}

.proRoleDashboard .proDashboardHeroMetrics strong {
  display: block;

  margin-top: 8px;

  color: #fff;

  font-size: 22px;
  font-weight: 600;
}


/* =========================================================
   CAMPUS AI HERO BUTTON
========================================================= */

.proRoleDashboard .proDashboardAiAction {
  display: grid;
  grid-template-columns:
    33px
    minmax(0,1fr)
    auto;
  align-items: center;
  gap: 10px;

  width: 100%;
  min-height: 57px;

  margin-top: auto;
  padding: 10px 11px;

  text-align: left;

  border:
    1px solid
    rgba(239,224,196,.18);

  border-radius: 13px;

  background:
    rgba(236,215,180,.085);

  color: #fff;

  cursor: pointer;

  transition: .2s ease;
}

.proRoleDashboard .proDashboardAiAction:hover {
  transform: translateY(-2px);

  background:
    rgba(236,215,180,.13);
}

.proRoleDashboard .proDashboardAiAction > i {
  display: grid;
  place-items: center;

  width: 32px;
  height: 32px;

  border-radius: 9px;

  background: #efe0c8;

  color: #465c67;

  font-size: 10px;
  font-style: normal;
}

.proRoleDashboard .proDashboardAiAction strong,
.proRoleDashboard .proDashboardAiAction small {
  display: block;
}

.proRoleDashboard .proDashboardAiAction strong {
  color: #fff;
  font-size: 8px;
}

.proRoleDashboard .proDashboardAiAction small {
  margin-top: 3px;

  color:
    rgba(238,244,246,.52);

  font-size: 6px;
}

.proRoleDashboard .proDashboardAiAction > b {
  color: #e8d4b4;
  font-size: 12px;
}


/* =========================================================
   DASHBOARD RAIL
========================================================= */

.proRoleDashboard .proDashboardRail {
  display: flex;
  align-items: center;
  flex-wrap: wrap;

  gap: 5px;

  padding: 7px;

  border:
    1px solid
    var(--prd-line);

  border-radius: 14px;

  background:
    rgba(255,253,249,.94);

  box-shadow:
    0 8px 25px
    rgba(45,53,58,.04);
}

.proRoleDashboard .proDashboardRail button {
  display: inline-flex;
  align-items: center;
  gap: 7px;

  min-height: 34px;

  padding: 0 11px;

  border: 0;
  border-radius: 9px;

  background: transparent;

  color: #748087;

  font-size: 7px;
  font-weight: 800;

  cursor: pointer;

  transition: .2s ease;
}

.proRoleDashboard .proDashboardRail button:hover {
  background:
    var(--prd-accent-soft);

  color:
    var(--prd-accent);
}

.proRoleDashboard .proDashboardRail button i {
  color:
    var(--prd-accent);

  font-style: normal;
}

.proRoleDashboard .proDashboardRail > span {
  display: inline-flex;
  align-items: center;
  gap: 6px;

  margin-left: auto;
  padding: 0 7px;

  color: #809086;

  font-size: 6px;
}

.proRoleDashboard .proDashboardRail > span i {
  width: 6px;
  height: 6px;

  border-radius: 50%;

  background: #829b85;
}


/* =========================================================
   MAIN BODY
========================================================= */

.proRoleDashboard .proDashboardBody {
  display: grid;
  gap: 16px;
}

.proRoleDashboard .proDashboardGreeting {
  display: flex;
  align-items: center;
  justify-content: space-between;

  gap: 18px;

  padding:
    4px 2px;
}

.proRoleDashboard .proDashboardGreeting > div > span {
  color:
    var(--prd-accent);

  font-size: 7px;
  font-weight: 900;
  letter-spacing: .12em;
}

.proRoleDashboard .proDashboardGreeting h2 {
  margin: 5px 0 0;

  color:
    var(--prd-ink);

  font-family:
    Georgia,
    "Times New Roman",
    serif;

