  margin: 15px 0 6px;

  color:
    var(--prd-ink);

  font-size: 27px;
  font-weight: 650;
}

.proRoleDashboard .proDashboardMetric > span {
  display: block;

  color:
    var(--prd-muted);

  font-size: 7px;
  line-height: 1.45;
}

.proRoleDashboard .proDashboardMetric > i {
  position: absolute;
  right: 13px;
  bottom: 12px;

  color:
    var(--prd-accent);

  font-size: 10px;
  font-style: normal;
}


/* =========================================================
   TWO COLUMN AREA
========================================================= */

.proRoleDashboard .proDashboardGrid {
  display: grid;
  grid-template-columns:
    minmax(0,1.52fr)
