  gap: 13px;

  align-items: start;
}

.proRoleDashboard .proDashboardMainColumn,
.proRoleDashboard .proDashboardSideColumn {
  display: grid;
  gap: 13px;
}


/* =========================================================
   COMMON PANELS
========================================================= */

.proRoleDashboard .proDashboardPanel {
  overflow: hidden;

  padding: 18px;

  border:
