  justify-content: space-between;

  gap: 12px;

  margin-bottom: 13px;
}

.proRoleDashboard .proDashboardPanel > header span {
  color:
    var(--prd-accent);

  font-size: 6px;
  font-weight: 900;
  letter-spacing: .13em;
}

.proRoleDashboard .proDashboardPanel > header h3 {
