    padding-left .2s ease;
}

.proRoleDashboard .proDashboardPriorityList > button:first-child {
  border-top: 0;
}

.proRoleDashboard .proDashboardPriorityList > button:hover {
  padding-left: 5px;
}

.proRoleDashboard .proDashboardPriorityList > button > i {
  display: grid;
  place-items: center;

  width: 36px;
  height: 36px;

  border-radius: 10px;

  background:
