  color:
    var(--prd-accent);

  font-size: 8px;
  font-style: normal;
  font-weight: 900;
}

.proRoleDashboard .proDashboardPriorityList p {
  margin: 0;
}

.proRoleDashboard .proDashboardPriorityList p strong {
  display: block;

  color:
    #43545d;

  font-size: 9px;
}

.proRoleDashboard .proDashboardPriorityList p small {
  display: block;

  margin-top: 4px;

  color:
    #828b90;

  font-size: 7px;
  line-height: 1.5;
}

.proRoleDashboard .proDashboardPriorityList > button > span {
  padding:
    5px 7px;

  border-radius: 999px;

  background:
    var(--prd-secondary-soft);

  color:
    var(--prd-secondary);

  font-size: 6px;
  font-weight: 800;
}

.proRoleDashboard .proDashboardPriorityList > button > em {
  color:
    var(--prd-accent);

  font-style: normal;
}


/* =========================================================
   READINESS / PERFORMANCE PANEL
========================================================= */

.proRoleDashboard .proDashboardSignal {
  display: grid;
  grid-template-columns:
    auto
    minmax(0,1fr);

  align-items: center;

  gap: 15px;

  padding: 14px;

  border:
    1px solid
    var(--prd-line);

  border-radius: 14px;

  background:
    var(--prd-surface);
}

.proRoleDashboard .proDashboardSignalRing {
  display: grid;
  place-items: center;

  width: 82px;
  height: 82px;

  border-radius: 50%;

  background:
    conic-gradient(
      var(--prd-accent)
      var(--pro-signal),
      #e7e5df
      0deg
    );
}

.proRoleDashboard .proDashboardSignalRing > div {
  display: grid;
  place-items: center;

  width: 66px;
  height: 66px;

  border-radius: 50%;

  background:
    #fffdf9;
}

.proRoleDashboard .proDashboardSignalRing strong {
  color:
    var(--prd-ink);

  font-size: 20px;
}

.proRoleDashboard .proDashboardSignalRing small {
  color:
    var(--prd-muted);

  font-size: 6px;
}

.proRoleDashboard .proDashboardSignal > div:last-child > span {
  display: block;

  color:
    var(--prd-accent);

  font-size: 6px;
  font-weight: 900;
  letter-spacing: .1em;
}

.proRoleDashboard .proDashboardSignal > div:last-child > b {
  display: block;

  margin-top: 6px;

  color:
    var(--prd-ink);

  font-size: 13px;
}

.proRoleDashboard .proDashboardSignal > div:last-child > small {
  display: block;

  margin-top: 3px;

  color:
    var(--prd-muted);

  font-size: 7px;
}

.proRoleDashboard .proDashboardSignalRows {
  display: grid;

  gap: 10px;

  margin-top: 15px;
}

.proRoleDashboard .proDashboardSignalRows > div > p {
  display: flex;
  justify-content: space-between;

  margin:
    0 0 5px;
}

.proRoleDashboard .proDashboardSignalRows p span,
.proRoleDashboard .proDashboardSignalRows p b {
  font-size: 7px;
}

.proRoleDashboard .proDashboardSignalRows p span {
  color:
    #718087;
}

.proRoleDashboard .proDashboardSignalRows p b {
  color:
    var(--prd-accent);
}

.proRoleDashboard .proDashboardSignalRows > div > i {
  display: block;

  height: 5px;

  overflow: hidden;

  border-radius: 999px;

  background:
    #e8e5df;
}

.proRoleDashboard .proDashboardSignalRows > div > i > span {
  display: block;

  height: 100%;

  border-radius: inherit;

  background:
    linear-gradient(
      90deg,
      var(--prd-accent),
      color-mix(
        in srgb,
        var(--prd-accent) 55%,
        var(--prd-secondary)
      )
    );
}


/* =========================================================
   QUICK ACTIONS
========================================================= */

.proRoleDashboard .proDashboardQuickGrid {
  display: grid;
  gap: 7px;
}

.proRoleDashboard .proDashboardQuickGrid > button {
  display: grid;
  grid-template-columns:
    35px
    minmax(0,1fr)
    auto;

  align-items: center;

  gap: 9px;

  min-height: 59px;

  padding: 10px;

  text-align: left;

  border:
    1px solid #e4dfd7;

  border-radius: 12px;

  background:
    #fff;

  cursor: pointer;

  transition:
    transform .2s ease,
    border-color .2s ease;
}

.proRoleDashboard .proDashboardQuickGrid > button:hover {
  transform: translateX(3px);

  border-color:
    rgba(var(--prd-accent-rgb),.27);
}

.proRoleDashboard .proDashboardQuickGrid > button > i {
  display: grid;
  place-items: center;

  width: 33px;
  height: 33px;

  border-radius: 9px;

  background:
    var(--prd-accent-soft);

  color:
    var(--prd-accent);

  font-size: 8px;
  font-style: normal;
  font-weight: 900;
}

.proRoleDashboard .proDashboardQuickGrid b,
.proRoleDashboard .proDashboardQuickGrid small {
  display: block;
}

.proRoleDashboard .proDashboardQuickGrid b {
  color:
    #45565f;

  font-size: 8px;
}

.proRoleDashboard .proDashboardQuickGrid small {
  margin-top: 3px;

  color:
    #899297;

  font-size: 6px;
}

.proRoleDashboard .proDashboardQuickGrid > button > span {
  color:
    var(--prd-accent);
}


/* =========================================================
   INTELLIGENCE CARD
========================================================= */

.proRoleDashboard .proDashboardInsightCard {
  position: relative;

  overflow: hidden;

  padding: 20px;

  border-radius: 19px;

  background:
    radial-gradient(
      circle at 100% 0,
      rgba(255,255,255,.08),
      transparent 35%
    ),
    linear-gradient(
      145deg,
      var(--prd-dark),
      color-mix(
        in srgb,
        var(--prd-dark) 76%,
        var(--prd-accent)
      )
    );

  box-shadow:
    0 16px 35px
    rgba(38,53,62,.11);
}

.proRoleDashboard .proDashboardInsightCard > span {
  color:
    #dcc095;

  font-size: 6px;
  font-weight: 900;
  letter-spacing: .13em;
}

.proRoleDashboard .proDashboardInsightCard h3 {
  margin:
    11px 0 0;

  color: #fff;

  font-family:
    Georgia,
    "Times New Roman",
    serif;

  font-size: 20px;
  font-weight: 500;
  line-height: 1.22;
}

.proRoleDashboard .proDashboardInsightCard > p {
  margin:
    10px 0 0;

  color:
    rgba(239,244,246,.64);

  font-size: 7px;
  line-height: 1.65;
}

.proRoleDashboard .proDashboardInsightPulse {
  display: flex;
  align-items: center;

  gap: 7px;

  margin-top: 18px;

  color:
    rgba(239,244,246,.61);

  font-size: 6px;
}

.proRoleDashboard .proDashboardInsightPulse i {
  width: 7px;
  height: 7px;

  border-radius: 50%;

  background:
    #becdbb;

  box-shadow:
    0 0 0 5px
    rgba(190,205,187,.08);
}


/* =========================================================
   ADMIN HERO EDIT FIELDS
========================================================= */

.proRoleDashboard .proAdminHeroInput {
  width: 100%;

  border:
    1px solid
    rgba(255,255,255,.18);

  border-radius: 10px;

  background:
    rgba(255,255,255,.08);

  color: #fff;

  outline: none;
}

.proRoleDashboard .proAdminHeroEyebrow {
  padding:
    7px 9px;

  font-size: 8px;
}

.proRoleDashboard .proAdminHeroTitle {
  margin-top: 8px;

  padding:
    10px;

  font-family:
    Georgia,
    serif;

  font-size: 29px;
}

.proRoleDashboard .proAdminHeroDescription {
  min-height: 90px;

  margin-top: 9px;

  padding:
    10px;

  resize: vertical;

  font-size: 9px;
}


/* =========================================================
   MICRO MOTION
========================================================= */

.proRoleDashboard .proDashboardMetric,
.proRoleDashboard .proDashboardPanel,
.proRoleDashboard .proDashboardInsightCard {
  animation:
    professionalRoleIn
    .38s ease both;
}

@keyframes professionalRoleIn {
  from {
    opacity: 0;
    transform: translateY(8px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}


/* =========================================================
   RESPONSIVE
========================================================= */

@media (max-width: 1100px) {

  .proRoleDashboard .proDashboardHero {
    grid-template-columns: 1fr;
  }

  .proRoleDashboard .proDashboardHeroAside {
    min-height: 260px;
  }

  .proRoleDashboard .proDashboardGrid {
    grid-template-columns: 1fr;
  }

}

@media (max-width: 850px) {

  .proRoleDashboard .proDashboardMetrics {
    grid-template-columns:
      repeat(2,minmax(0,1fr));
  }

}

@media (max-width: 650px) {

  .proRoleDashboard .proDashboardHero {
    min-height: auto;

    padding: 20px;

    border-radius: 21px;
  }

  .proRoleDashboard .proDashboardHeroContent h1 {
    font-size: 32px;
  }

  .proRoleDashboard .proDashboardGreeting {
    align-items: flex-start;
    flex-direction: column;
  }

  .proRoleDashboard .proDashboardRail {
    overflow-x: auto;
    flex-wrap: nowrap;
  }

  .proRoleDashboard .proDashboardRail > span {
    display: none;
  }

}

@media (max-width: 520px) {

  .proRoleDashboard .proDashboardMetrics,
  .proRoleDashboard .proDashboardHeroMetrics {
    grid-template-columns: 1fr;
  }

  .proRoleDashboard .proDashboardPriorityList > button {
    grid-template-columns:
      36px
      minmax(0,1fr)
      18px;
  }

  .proRoleDashboard .proDashboardPriorityList > button > span {
    display: none;
  }

}


