/* CAMPUSCONNECT PROFESSIONAL OPENING */

.ccOpening {
  position: fixed;
  inset: 0;
  z-index: 2147483647;
  display: grid;
  place-items: center;
  overflow: hidden;
  color: #17243a;
  background:
    radial-gradient(
      circle at 50% 40%,
      rgba(49, 89, 217, 0.11),
      transparent 36%
    ),
    linear-gradient(
      145deg,
      #ffffff 0%,
      #f5f7fb 52%,
      #edf2ff 100%
    );
  isolation: isolate;
  animation: ccOpeningExit 5.2s ease both;
}

.ccOpeningGrid {
  position: absolute;
  inset: 0;
  z-index: -3;
  opacity: 0.42;
  background-image:
    linear-gradient(
      rgba(49, 89, 217, 0.045) 1px,
      transparent 1px
    ),
    linear-gradient(
      90deg,
      rgba(49, 89, 217, 0.045) 1px,
      transparent 1px
    );
  background-size: 48px 48px;
  mask-image:
    radial-gradient(
      circle at center,
      #000 5%,
      transparent 68%
    );
  -webkit-mask-image:
    radial-gradient(
      circle at center,
      #000 5%,
      transparent 68%
    );
  animation: ccOpeningGridMove 5s ease-out both;
}

.ccOpeningGlow {
  position: absolute;
  z-index: -2;
  width: 420px;
  height: 420px;
  border-radius: 50%;
  filter: blur(90px);
  pointer-events: none;
}

.ccOpeningGlowOne {
  top: -190px;
  right: -120px;
  background: rgba(49, 89, 217, 0.16);
  animation: ccOpeningGlowOne 5s ease-in-out both;
}

.ccOpeningGlowTwo {
  bottom: -230px;
  left: -140px;
  background: rgba(115, 85, 199, 0.12);
  animation: ccOpeningGlowTwo 5s ease-in-out both;
}

.ccOpeningStage {
  width: min(650px, calc(100% - 40px));
  display: grid;
  justify-items: center;
  text-align: center;
}

.ccOpeningLogoScene {
  position: relative;
  width: 190px;
  height: 190px;
  display: grid;
  place-items: center;
}

.ccOpeningLogoCard {
  position: relative;
  z-index: 3;
  width: 126px;
  height: 126px;
  display: grid;
  place-items: center;
  overflow: hidden;
  border: 1px solid rgba(49, 89, 217, 0.14);
  border-radius: 30px;
  background: rgba(255, 255, 255, 0.92);
  box-shadow:
    0 25px 70px rgba(24, 34, 56, 0.15),
    0 8px 24px rgba(49, 89, 217, 0.14),
    inset 0 1px 0 rgba(255, 255, 255, 0.9);
  transform: scale(0.45) rotate(-8deg);
  opacity: 0;
  animation:
    ccOpeningLogoIn 0.9s
    cubic-bezier(0.16, 1, 0.3, 1)
    0.2s forwards;
}

.ccOpeningLogo {
  width: 104px;
  height: 104px;
  object-fit: contain;
}

.ccOpeningOrbit {
  position: absolute;
  inset: 7px;
  border: 1px solid rgba(49, 89, 217, 0.18);
  border-radius: 50%;
  opacity: 0;
  animation:
    ccOpeningOrbitIn 0.7s ease 0.65s forwards,
    ccOpeningOrbitSpin 9s linear 0.65s infinite;
}

.ccOpeningOrbit::before {
  content: "";
  position: absolute;
  top: 16px;
  left: 17px;
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: #3159d9;
  box-shadow:
    0 0 0 6px rgba(49, 89, 217, 0.09),
