  border-radius: 10px;
  background: #f7f9fc;
  color: #566479;
  font-size: 7px;
  line-height: 1.55;
}


/* SUMMARY */

.academicMarksSummary {
  display: grid;
  grid-template-columns:
    repeat(4,minmax(0,1fr));
  gap: 10px;
  margin-bottom: 15px;
}


.academicMarksSummary
article {
  padding: 14px;
  border: 1px solid #e5e8ed;
  border-radius: 12px;
  background: #fff;
}


.academicMarksSummary
