  display: block;
  color: #9099a8;
  font-size: 5px;
  font-weight: 850;
  letter-spacing: .08em;
}


.academicMarksSummary
strong {
  display: block;
  margin-top: 5px;
  color: #243248;
  font-size: 14px;
}


/* MANAGEMENT TABLE */

.academicMarksManagementTable
> header,
.academicMarksManagementTable
> article {
  grid-template-columns:
    minmax(180px,1.4fr)
    minmax(100px,.8fr)
    minmax(130px,1fr)
    minmax(120px,.8fr);
}


.academicMarksManagementTable
article {
  transition:
    background .18s ease;
}


.academicMarksManagementTable
article:hover {
  background: #fbfcfe;
}


.academicMarksProgress
> i {
  position: relative;
  display: block;
  width: 100%;
  height: 5px;
  overflow: hidden;
  border-radius: 999px;
  background: #e8ecf2;
}


.academicMarksProgress
> i > span {
  position: absolute;
  inset:
    0 auto 0 0;
  display: block;
  border-radius: inherit;
  background:
    linear-gradient(
      90deg,
      #3159d9,
      #5c7cf0
    );
}


.academicMarksRowActions {
  display: flex;
  align-items: center;
  gap: 6px;
}


.academicMarksRowActions
button {
  min-height: 28px;
  padding: 0 9px;
  border: 1px solid #dfe4eb;
  border-radius: 8px;
  background: #fff;
  color: #526178;
  font-size: 6px;
  font-weight: 800;
  cursor: pointer;
  transition:
    border-color .18s ease,
    background .18s ease,
    color .18s ease;
}


.academicMarksRowActions
button:hover:not(:disabled) {
  border-color: #bdc8da;
  background: #f6f8fb;
  color: #27374f;
}


.academicMarksRowActions
button:last-child {
  color: #b33d4d;
}


.academicMarksRowActions
button:last-child:hover:not(:disabled) {
  border-color: #efcbd1;
  background: #fff5f6;
  color: #9d3040;
}


.academicMarksRowActions
button:disabled {
  cursor: not-allowed;
  opacity: .5;
}


