/* =========================================================
   ACADEMICS — SUBJECTS PROFESSIONAL REDESIGN
   ========================================================= */

/* Section containing My Subjects */
.academicProSection:has(.academicSubjectCards) {
  padding: 30px;
}


/* Heading */

.academicProSection:has(.academicSubjectCards)
.academicProSectionHeading {
  margin-bottom: 24px;
}

.academicProSection:has(.academicSubjectCards)
.academicProSectionHeading span {
  font-size: 10px;
  letter-spacing: .12em;
}

.academicProSection:has(.academicSubjectCards)
.academicProSectionHeading h2 {
  margin: 8px 0 6px;
  font-size: 27px;
  line-height: 1.15;
  letter-spacing: -.025em;
}

.academicProSection:has(.academicSubjectCards)
.academicProSectionHeading p {
  font-size: 13px;
  line-height: 1.6;
}

.academicProSection:has(.academicSubjectCards)
.academicProSectionHeading > strong {
  padding: 9px 14px;
  font-size: 10px;
}


/* Subject grid */

.academicSubjectCards {
  grid-template-columns:
    repeat(3,minmax(0,1fr));
  gap: 16px;
}


/* Main subject card */

.academicSubjectCards > article {
  position: relative;
  min-height: 255px;
  padding: 22px;
  overflow: hidden;

  border:
    1px solid
    #dde3eb;

  border-radius: 20px;

  background:
    linear-gradient(
      150deg,
      #ffffff 0%,
      #fbfcff 62%,
      #f6f8fc 100%
    );

  box-shadow:
    0 8px 22px
    rgba(27,39,61,.035);

  transition:
    transform .22s ease,
    box-shadow .22s ease,
    border-color .22s ease;
}


/* Subtle card accent */

.academicSubjectCards
> article::before {
  content: "";
  position: absolute;
  inset: 0 auto 0 0;
  width: 4px;

  background:
    linear-gradient(
      180deg,
      #3159d9,
      #6682ea
    );

  opacity: .9;
}


.academicSubjectCards
> article:hover {
  transform:
    translateY(-5px);

  border-color:
    #ccd6ed;

  box-shadow:
    0 18px 42px
    rgba(28,43,72,.09);
}


/* Top subject metadata */

.academicSubjectCards
article > header {
  min-height: 26px;
}

.academicSubjectCards
header span {
  display: inline-flex;
  align-items: center;

  min-height: 24px;

  padding:
    0 9px;

  border-radius:
    999px;

  background:
    #edf2ff;

  color:
    #3159d9;

  font-size:
    9px;

  font-weight:
    850;

  letter-spacing:
    .06em;
}


.academicSubjectCards
header code {
  padding:
    5px 8px;

  border-radius:
    7px;

  background:
    #f4f6fa;

  color:
    #6f7d91;

  font-family:
    inherit;

  font-size:
    10px;

  font-weight:
    750;
}


/* Subject name */

.academicSubjectCards h3 {
  min-height: unset;

  margin:
    22px 0 9px;

  color:
    #1f2d43;

  font-size:
    18px;

  line-height:
    1.3;

  letter-spacing:
    -.015em;
}


/* Faculty */

.academicSubjectCards
> article > p {
  min-height: 28px;

  margin:
    0;

  color:
    #788699;

  font-size:
    11px;

  line-height:
    1.5;
}


/* Add faculty label visually */

.academicSubjectCards
> article > p:not(:empty)::before {
  content:
    "Faculty · ";

  color:
    #9aa4b3;

  font-weight:
    650;
}


/* Statistics section */

.academicSubjectStats {
  grid-template-columns:
    repeat(3,minmax(0,1fr));

  gap:
    8px;

  margin-top:
    24px;
}


.academicSubjectStats > div {
  min-width: 0;

  padding:
    12px;

  border:
    1px solid
    #edf0f5;

  border-radius:
    12px;

  background:
    #f7f9fc;

  transition:
    background .18s ease,
    transform .18s ease;
}


.academicSubjectStats
> div:hover {
  background:
    #f2f5fb;

  transform:
    translateY(-1px);
}


.academicSubjectStats small {
  display:
    block;

  color:
    #929dac;

  font-size:
    8px;

  font-weight:
    800;

  letter-spacing:
    .06em;
}


.academicSubjectStats strong {
  display:
    block;

  margin-top:
    7px;

  color:
    #223148;

  font-size:
    16px;

  line-height:
    1;
}


/* Make attendance values stronger */

.academicSubjectStats
> div:nth-child(2)
strong {
  color:
    #3159d9;
}


/* Assignment count */

.academicSubjectStats
> div:nth-child(3)
strong {
  color:
    #243149;
}


