/* =========================================================
   GRID
   ========================================================= */

.campusTimetableShell {
  overflow: hidden;
  border: 1px solid #dce2ea;
  border-radius: 17px;
  background: #fff;
}


.campusTimetableScroll {
  overflow-x: auto;
  overscroll-behavior-x: contain;
}


.campusTimetableGrid {
  position: relative;
  display: grid;
  min-width: 1000px;
  grid-template-rows:
    72px repeat(6, 112px);
  background: #fff;
}


.campusTimetableCorner,
.campusTimetableTimeHeader,
.campusTimetableDay,
.campusTimetableEmptySlot {
  border-right: 1px solid #e2e6ec;
  border-bottom: 1px solid #e2e6ec;
