  flex-direction: column;
  justify-content: center;
  padding: 16px;
  background: #fafbfc;
}


.campusTimetableDay
strong {
  color: #243248;
  font-size: 13px;
}


.campusTimetableDay
small {
  margin-top: 5px;
  color: #8a95a4;
  font-size: 9px;
}


.campusTimetableEmptySlot {
  min-width: 0;
  background:
    linear-gradient(
      145deg,
      #fff,
      #fcfdff
    );
}


