  position: relative;
  z-index: 3;
  align-self: stretch;
  min-width: 0;
  margin: 5px;
  padding: 10px;
  overflow: hidden;
  border: 1px solid #cfd9f5;
  border-radius: 10px;
  background:
    linear-gradient(
      145deg,
      #eff3ff,
      #f8faff
    );
  box-shadow:
    0 5px 13px
    rgba(49,89,217,.08);
}


.campusTimetableClass.isLab {
