.campusTimetableClass
header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 5px;
}


.campusTimetableClass
header span {
  color: #3159d9;
  font-size: 8px;
  font-weight: 850;
  letter-spacing: .05em;
}


.campusTimetableClass.isLab
header span {
  color: #28705a;
}


.campusTimetableClass
code {
  color: #78859a;
