  padding: 5px 7px;
  border: 1px solid #d7deeb;
  border-radius: 6px;
  background: rgba(255,255,255,.75);
  color: #4d5d75;
  font-size: 8px;
  cursor: pointer;
}


.campusTimetableClass
footer button:last-child {
  color: #ab3c4c;
}


/* VERTICAL BREAK COLUMN */

.campusTimetableBreakColumn {
  position: relative;
  z-index: 6;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  margin: 0;
  border-right: 1px solid #e3c96f;
  border-left: 1px solid #e3c96f;
  background:
    linear-gradient(
      180deg,
      #ffd85e,
      #ffcc38
    );
  color: #5c4710;
  writing-mode: vertical-rl;
  transform: rotate(180deg);
}


.campusTimetableBreakColumn
strong {
  font-size: 11px;
  letter-spacing: .08em;
  text-transform: uppercase;
}


.campusTimetableBreakColumn
small {
  margin-top: 8px;
  font-size: 8px;
}


/* STUDENT VERSION */

.academicStudentTimetable {
  padding: 30px;
}


.academicStudentTimetable
.campusTimetableGrid {
  grid-template-rows:
    72px repeat(6, 104px);
}


/* STAFF ACTIONS NOW 4 ITEMS */

@media(min-width:851px) {
  .academicStaffActionGrid {
    grid-template-columns:
      repeat(4,minmax(0,1fr));
  }
}


/* =========================================================
   RESPONSIVE
   ========================================================= */

@media(max-width:1050px) {

  .academicTimetableForm {
    grid-template-columns:
      repeat(2,minmax(0,1fr));
  }

  .academicBreakManager {
    grid-template-columns:
      1fr 1fr;
  }

  .academicBreakManager
  > div {
    grid-column: 1 / -1;
  }

}


@media(max-width:650px) {

  .academicTimetableForm {
    grid-template-columns: 1fr;
  }

  .academicBreakManager {
    grid-template-columns: 1fr;
  }

  .academicBreakManager
  > div {
    grid-column: auto;
  }

  .academicTimetablePreviewHeading {
    align-items: flex-start;
    flex-direction: column;
    gap: 5px;
  }

  .academicStudentTimetable {
    padding: 20px;
  }

  .campusTimetableScroll::after {
    content:
