}

.timetablePdfControls {
  display: flex;
  align-items: end;
  gap: 14px;
  flex-wrap: wrap;
}

.timetablePdfControls > label:first-child {
  display: grid;
  gap: 7px;
  flex: 1 1 300px;
}

.timetablePdfControls label span {
  font-size: 0.8rem;
  font-weight: 700;
}

.timetablePdfControls select {
  width: 100%;
  min-height: 46px;
  padding: 0 14px;
