  gap: 4px;
}

.timetablePdfMeta strong {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.timetablePdfMeta small {
  opacity: 0.62;
}

.timetablePdfBadge {
