  padding: 0 15px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid rgba(127, 127, 127, 0.26);
  border-radius: 10px;
  background: transparent;
  color: inherit;
  font: inherit;
  font-weight: 700;
  text-decoration: none;
  cursor: pointer;
}

.timetablePdfViewer {
  width: 100%;
  height: min(74vh, 900px);
  min-height: 650px;
  border: 0;
  border-radius: 14px;
  background: white;
}

.timetablePdfEmpty {
