  margin-bottom: 2px;
  color: #64748b;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.11em;
}

.attendanceBulkFile strong {
  max-width: 480px;
  overflow: hidden;
  font-size: 12px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.attendanceBulkFile > small {
  color: #64748b;
  font-size: 10px;
