  font-size: 12px;
}

.attendanceBulkProgress p {
  margin: 3px 0 0;
  color: #64748b;
  font-size: 10px;
}

.attendanceBulkSpinner {
  width: 25px;
  height: 25px;
  flex: 0 0 25px;
  border: 3px solid rgba(37, 99, 235, 0.18);
  border-top-color: #2563eb;
  border-radius: 50%;
  animation: attendanceBulkSpin 0.75s linear infinite;
}

@keyframes attendanceBulkSpin {
  to {
    transform: rotate(360deg);
  }
}

.attendanceBulkStats {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 9px;
  margin-top: 16px;
}

.attendanceBulkStats article {
  min-width: 0;
  padding: 12px;
  border: 1px solid rgba(148, 163, 184, 0.18);
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.62);
}

.attendanceBulkStats span,
.attendanceBulkStats strong,
.attendanceBulkStats small {
  display: block;
}

.attendanceBulkStats span {
  color: #64748b;
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.08em;
}

.attendanceBulkStats strong {
  margin-top: 5px;
  font-size: 21px;
