  font-size: 11px;
}

.attendanceBulkTable thead {
  position: sticky;
  top: 0;
  z-index: 2;
}

.attendanceBulkTable th {
  padding: 10px 11px;
  background: #f8fafc;
  color: #64748b;
  text-align: left;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.07em;
  text-transform: uppercase;
}

.attendanceBulkTable td {
  padding: 10px 11px;
  border-top: 1px solid rgba(148, 163, 184, 0.13);
  vertical-align: middle;
}

.attendanceBulkTable tbody tr:hover {
  background: rgba(37, 99, 235, 0.025);
}

.attendanceBulkTable td strong {
  font-size: 10px;
}

.attendanceBulkStatus {
  display: inline-flex;
  align-items: center;
  padding: 4px 7px;
  border-radius: 999px;
  font-size: 9px;
  font-weight: 800;
  white-space: nowrap;
}

.attendanceBulkStatus.ready {
  background: rgba(22, 163, 74, 0.1);
  color: #15803d;
}

.attendanceBulkStatus.already-in-batch,
.attendanceBulkStatus.duplicate-file {
  background: rgba(217, 119, 6, 0.1);
  color: #b45309;
}

.attendanceBulkStatus.not-found,
.attendanceBulkStatus.invalid {
  background: rgba(220, 38, 38, 0.09);
  color: #b91c1c;
}

.attendanceBulkActions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 9px;
  margin-top: 14px;
}

.attendanceBulkMessage {
  margin: 12px 0 0;
  padding: 10px 12px;
  border: 1px solid rgba(220, 38, 38, 0.15);
  border-radius: 10px;
  background: rgba(220, 38, 38, 0.055);
  color: #b91c1c;
  font-size: 10px;
  line-height: 1.45;
}

@media (max-width: 760px) {
  .attendanceBulkStudentImport {
    padding: 15px;
  }

  .attendanceBulkStudentImportHeader {
    flex-direction: column;
  }

  .attendanceBulkUpload {
    width: 100%;
  }

  .attendanceBulkStats {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .attendanceBulkTable {
    min-width: 620px;
  }

  .attendanceBulkFile {
    align-items: flex-start;
    flex-direction: column;
  }

  .attendanceBulkActions {
    align-items: stretch;
    flex-direction: column-reverse;
  }

  .attendanceBulkActions button {
    width: 100%;
  }
}


