  margin-bottom: 5px;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.12em;
  opacity: 0.65;
}

.timetableScanReviewHeader h4 {
  margin: 0;
  font-size: 20px;
}

.timetableScanReviewHeader p {
  max-width: 680px;
  margin: 7px 0 0;
