}

.timetableScanStats span {
  display: block;
  margin-top: 3px;
  font-size: 11px;
  opacity: 0.65;
}

.timetableScanWarnings {
  margin-top: 16px;
  padding: 14px 16px;
  border: 1px solid rgba(180, 120, 0, 0.2);
  border-radius: 13px;
  background: rgba(180, 120, 0, 0.06);
}

.timetableScanWarnings > strong {
  font-size: 12px;
}

.timetableScanWarnings ul {
  margin: 8px 0 0;
  padding-left: 18px;
}

.timetableScanWarnings li {
  margin: 4px 0;
  font-size: 12px;
  line-height: 1.5;
}

.timetableScanBreaks {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
