.timetableScanMapping {
  margin-top: 12px;
  padding-top: 11px;
  border-top: 1px solid var(--border);
}

.timetableScanMapping strong {
  font-size: 12px;
}

.timetableScanMapping p {
  margin: 4px 0 0;
  font-size: 11px;
  line-height: 1.45;
  opacity: 0.7;
}

.timetableScanPdfText {
  margin-top: 18px;
}

.timetableScanPdfText p {
  font-size: 12px;
