/* ============================================================
   CAMPUSCONNECT — ECE FACULTY WORKLOAD
   Faculty Assignment & Workload Engine
   ============================================================ */

.facultyWorkloadShell {
  width: 100%;
  margin: 28px 0 8px;
  display: flex;
  flex-direction: column;
  gap: 20px;
  color: var(--text, #172033);
}

.facultyWorkloadHero {
  position: relative;
  overflow: hidden;
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 24px;
  padding: 28px 30px;
  border: 1px solid rgba(20, 33, 61, 0.08);
  border-radius: 24px;
  background:
    radial-gradient(
      circle at 92% 12%,
      rgba(53, 93, 255, 0.09),
      transparent 30%
    ),
    linear-gradient(
      135deg,
      rgba(255, 255, 255, 0.98),
      rgba(247, 249, 253, 0.96)
    );
  box-shadow:
    0 16px 44px rgba(20, 33, 61, 0.07);
}

.facultyWorkloadHero::after {
  content: "";
  position: absolute;
  right: -55px;
  bottom: -80px;
  width: 210px;
  height: 210px;
  border-radius: 50%;
  border: 34px solid rgba(53, 93, 255, 0.035);
  pointer-events: none;
}

.facultyWorkloadHero > div {
  position: relative;
  z-index: 1;
  max-width: 760px;
}

.facultyWorkloadHero > div > span,
.facultyAllocationForm > header > span,
.facultyWorkloadBoard > header > span {
  display: block;
  margin-bottom: 7px;
  font-size: 11px;
  line-height: 1.3;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: #52627a;
}

.facultyWorkloadHero h2 {
  margin: 0;
  font-size: clamp(24px, 3vw, 34px);
  line-height: 1.12;
  letter-spacing: -0.035em;
  color: #15213a;
}

.facultyWorkloadHero p {
  max-width: 700px;
  margin: 10px 0 0;
  font-size: 14px;
  line-height: 1.65;
  color: #68758a;
}

.facultyWorkloadHero > strong {
  position: relative;
  z-index: 1;
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  min-height: 36px;
  padding: 0 14px;
  border: 1px solid rgba(53, 93, 255, 0.14);
  border-radius: 999px;
  background: rgba(53, 93, 255, 0.07);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.06em;
  color: #3154bf;
}


/* STATUS / NOTICE */

.facultyWorkloadStatus {
  padding: 13px 16px;
  border: 1px solid rgba(42, 91, 215, 0.14);
  border-radius: 14px;
  background: rgba(42, 91, 215, 0.055);
  font-size: 13px;
  line-height: 1.5;
  font-weight: 650;
  color: #2c4c9c;
}

.facultyWorkloadNotice {
  padding: 26px 28px;
  border: 1px solid rgba(20, 33, 61, 0.09);
  border-radius: 22px;
  background: rgba(255, 255, 255, 0.92);
  box-shadow: 0 12px 32px rgba(20, 33, 61, 0.055);
}

.facultyWorkloadNotice > span {
  display: block;
  margin-bottom: 7px;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.11em;
  color: #66748a;
}

.facultyWorkloadNotice h2 {
  margin: 0 0 8px;
  font-size: 22px;
  letter-spacing: -0.025em;
  color: #17233c;
}

.facultyWorkloadNotice p {
  max-width: 720px;
  margin: 0;
  font-size: 14px;
  line-height: 1.6;
  color: #6d798b;
}


/* METRICS */

.facultyWorkloadMetrics {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 14px;
}

.facultyWorkloadMetrics article {
  min-width: 0;
  padding: 20px;
  border: 1px solid rgba(20, 33, 61, 0.08);
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.94);
  box-shadow: 0 8px 26px rgba(20, 33, 61, 0.045);
}

.facultyWorkloadMetrics article > span {
  display: block;
  margin-bottom: 9px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.11em;
  color: #7a8698;
}

.facultyWorkloadMetrics article > strong {
  display: block;
  margin-bottom: 5px;
  font-size: 28px;
  line-height: 1;
  letter-spacing: -0.04em;
  color: #17233c;
}

.facultyWorkloadMetrics article > small {
  display: block;
  font-size: 12px;
  line-height: 1.45;
  color: #7a8697;
}


/* MAIN ADMIN MANAGEMENT GRID */

.facultyWorkloadManagementGrid {
  display: grid;
  grid-template-columns:
    minmax(300px, 0.82fr)
    minmax(420px, 1.45fr);
  gap: 18px;
  align-items: start;
}

.facultyAllocationForm,
.facultyWorkloadBoard {
  min-width: 0;
  padding: 24px;
  border: 1px solid rgba(20, 33, 61, 0.08);
  border-radius: 22px;
  background: rgba(255, 255, 255, 0.96);
  box-shadow: 0 12px 34px rgba(20, 33, 61, 0.055);
}

.facultyAllocationForm > header,
.facultyWorkloadBoard > header {
  margin-bottom: 20px;
}

.facultyAllocationForm > header h3,
.facultyWorkloadBoard > header h3 {
  margin: 0;
  font-size: 19px;
  line-height: 1.25;
  letter-spacing: -0.025em;
  color: #17233c;
}

.facultyAllocationForm > header p,
.facultyWorkloadBoard > header p {
  margin: 7px 0 0;
  font-size: 12.5px;
  line-height: 1.55;
  color: #748095;
}


/* FORM */

.facultyAllocationForm > label,
.facultyAllocationSplit > label {
  display: flex;
  flex-direction: column;
  gap: 7px;
  margin-bottom: 15px;
}

.facultyAllocationForm label > span,
.facultyAllocationSplit label > span {
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.09em;
  color: #69768a;
}

.facultyAllocationForm select,
.facultyAllocationForm input:not([type="checkbox"]),
.facultyAllocationForm textarea {
  width: 100%;
  min-height: 44px;
  box-sizing: border-box;
  padding: 10px 12px;
  border: 1px solid #dce2eb;
  border-radius: 11px;
  outline: none;
  background: #fbfcfe;
  font: inherit;
  font-size: 13px;
  color: #17233c;
  transition:
    border-color 160ms ease,
    box-shadow 160ms ease,
    background 160ms ease;
}

.facultyAllocationForm textarea {
  min-height: 82px;
  resize: vertical;
  line-height: 1.5;
}

.facultyAllocationForm select:focus,
.facultyAllocationForm input:not([type="checkbox"]):focus,
.facultyAllocationForm textarea:focus {
  border-color: rgba(49, 84, 191, 0.55);
  background: #fff;
  box-shadow: 0 0 0 3px rgba(49, 84, 191, 0.08);
}

.facultyAllocationForm select:disabled,
.facultyAllocationForm input:disabled,
.facultyAllocationForm textarea:disabled {
  cursor: not-allowed;
  opacity: 0.62;
}

.facultyAllocationSplit {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

.facultyAllocationCheckbox {
  display: flex !important;
  flex-direction: row !important;
  align-items: center;
  gap: 9px !important;
  min-height: 42px;
  margin: 2px 0 16px !important;
  padding: 10px 12px;
  border: 1px solid #e1e6ed;
  border-radius: 11px;
  background: #fafbfc;
  cursor: pointer;
}

.facultyAllocationCheckbox input {
  width: 16px;
  height: 16px;
  margin: 0;
  accent-color: #3154bf;
}

.facultyAllocationCheckbox span {
  letter-spacing: 0 !important;
  text-transform: none;
  font-size: 12.5px !important;
  color: #445168 !important;
}

.facultyAllocationPrimary {
  width: 100%;
  min-height: 46px;
  border: 0;
  border-radius: 12px;
  background: #172b52;
  color: #fff;
  font: inherit;
  font-size: 13px;
  font-weight: 750;
  cursor: pointer;
  box-shadow: 0 8px 20px rgba(23, 43, 82, 0.16);
  transition:
    transform 150ms ease,
    box-shadow 150ms ease,
    opacity 150ms ease;
}

.facultyAllocationPrimary:hover:not(:disabled) {
  transform: translateY(-1px);
  box-shadow: 0 11px 24px rgba(23, 43, 82, 0.2);
}

.facultyAllocationPrimary:disabled {
  cursor: not-allowed;
  opacity: 0.48;
  box-shadow: none;
}


/* LIVE WORKLOAD BOARD */

.facultyWorkloadFacultyList {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.facultyWorkloadFaculty {
  overflow: hidden;
  border: 1px solid #e4e8ef;
  border-radius: 16px;
  background: #fbfcfd;
}

.facultyWorkloadFaculty > header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 15px 16px;
  border-bottom: 1px solid #e9edf2;
  background: #fff;
}

.facultyWorkloadFaculty > header > div {
  min-width: 0;
}

.facultyWorkloadFaculty > header span {
  display: block;
  margin-bottom: 3px;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.1em;
  color: #8993a3;
}

.facultyWorkloadFaculty > header b {
  display: block;
  overflow: hidden;
  font-size: 14px;
  line-height: 1.35;
  text-overflow: ellipsis;
  color: #1b2840;
}

.facultyWorkloadFaculty > header strong {
  flex: 0 0 auto;
  font-size: 13px;
  color: #3154bf;
}

.facultyAllocationRows {
  display: flex;
  flex-direction: column;
}

.facultyAllocationRow {
  display: grid;
  grid-template-columns:
    minmax(105px, 0.8fr)
    minmax(95px, 0.7fr)
    minmax(95px, 0.65fr)
    auto;
  gap: 10px;
  align-items: center;
  min-height: 54px;
  padding: 10px 14px;
  border-bottom: 1px solid #edf0f4;
}

.facultyAllocationRow:last-child {
  border-bottom: 0;
}

.facultyAllocationRow.needsConfiguration {
  background: rgba(184, 116, 19, 0.045);
}

.facultyAllocationRow > span,
.facultyAllocationRow > strong,
.facultyAllocationRow > small {
  min-width: 0;
  font-size: 12px;
}

.facultyAllocationRow > strong {
  color: #1e2b43;
}

.facultyAllocationRow > small {
  color: #778397;
}

.facultyAllocationRow input {
  width: 70px;
  min-height: 34px;
  padding: 6px 8px;
  box-sizing: border-box;
  border: 1px solid #d9dfe8;
  border-radius: 9px;
  outline: none;
  background: #fff;
  font: inherit;
  font-size: 12px;
}

.facultyAllocationRow input:focus {
  border-color: rgba(49, 84, 191, 0.55);
  box-shadow: 0 0 0 3px rgba(49, 84, 191, 0.07);
}

.facultyAllocationRow button {
  min-height: 32px;
  padding: 0 10px;
  border: 1px solid rgba(173, 54, 54, 0.15);
  border-radius: 9px;
  background: rgba(173, 54, 54, 0.055);
  font: inherit;
  font-size: 11px;
  font-weight: 700;
  color: #a53d3d;
  cursor: pointer;
}


/* FACULTY PERSONAL VIEW */

.facultyTeachingGrid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
}

.facultyTeachingCard {
  min-width: 0;
  padding: 20px;
  border: 1px solid rgba(20, 33, 61, 0.08);
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.96);
  box-shadow: 0 9px 28px rgba(20, 33, 61, 0.045);
}

.facultyTeachingCard > header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
}

.facultyTeachingCard > header > div {
  min-width: 0;
}

.facultyTeachingCard > header span {
  display: block;
  margin-bottom: 5px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.09em;
  color: #6f7c90;
}

.facultyTeachingCard > header h3 {
  margin: 0;
  font-size: 17px;
  line-height: 1.3;
  letter-spacing: -0.02em;
  color: #17233c;
}

.facultyTeachingCard > header strong {
  flex: 0 0 auto;
  font-size: 17px;
  color: #3154bf;
}

.facultyTeachingTags {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
  margin-top: 15px;
}

.facultyTeachingTags span {
  display: inline-flex;
  align-items: center;
  min-height: 27px;
  padding: 0 9px;
  border: 1px solid #e0e5ed;
  border-radius: 999px;
  background: #f7f9fc;
  font-size: 10.5px;
  font-weight: 700;
  color: #536178;
}

.facultyNeedsConfiguration {
  display: block;
  margin-top: 13px;
  padding: 9px 10px;
  border: 1px solid rgba(180, 115, 21, 0.15);
  border-radius: 9px;
  background: rgba(180, 115, 21, 0.06);
  font-size: 11px;
  line-height: 1.45;
  font-weight: 650;
  color: #8c5b17;
}


/* EMPTY STATE */

.facultyWorkloadEmpty {
  display: flex;
  min-height: 170px;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 24px;
  text-align: center;
  border: 1px dashed #d8dee8;
  border-radius: 15px;
  background: #fafbfd;
}

.facultyWorkloadEmpty > span {
  margin-bottom: 8px;
  font-size: 25px;
  color: #7d899b;
}

.facultyWorkloadEmpty h3 {
  margin: 0;
  font-size: 15px;
  color: #26344c;
}

.facultyWorkloadEmpty p {
  max-width: 440px;
  margin: 7px 0 0;
  font-size: 12px;
  line-height: 1.5;
  color: #7b8798;
}


/* ============================================================
   RESPONSIVE
   ============================================================ */

@media (max-width: 1100px) {
  .facultyWorkloadManagementGrid {
    grid-template-columns: 1fr;
  }

  .facultyWorkloadMetrics {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 760px) {
  .facultyWorkloadShell {
    margin-top: 18px;
    gap: 14px;
  }

  .facultyWorkloadHero {
    align-items: flex-start;
    flex-direction: column;
    padding: 22px 20px;
    border-radius: 18px;
  }

  .facultyWorkloadHero h2 {
    font-size: 24px;
  }

  .facultyWorkloadMetrics {
    grid-template-columns: 1fr 1fr;
    gap: 10px;
  }

  .facultyWorkloadMetrics article {
    padding: 16px;
  }

  .facultyWorkloadMetrics article > strong {
    font-size: 24px;
  }

  .facultyAllocationForm,
  .facultyWorkloadBoard {
    padding: 18px;
    border-radius: 18px;
  }

  .facultyTeachingGrid {
    grid-template-columns: 1fr;
  }

  .facultyAllocationRow {
    grid-template-columns: 1fr 1fr;
  }
}

@media (max-width: 520px) {
  .facultyWorkloadMetrics {
    grid-template-columns: 1fr;
  }

  .facultyAllocationSplit {
    grid-template-columns: 1fr;
    gap: 0;
  }

  .facultyWorkloadFaculty > header {
    align-items: flex-start;
    flex-direction: column;
  }

  .facultyAllocationRow {
    grid-template-columns: 1fr;
    gap: 7px;
    padding: 13px;
  }

  .facultyAllocationRow input {
    width: 100%;
  }
}

/* ============================================================
   FACULTY WORKLOAD — ALLOCATION IDENTITY
   ============================================================ */

.facultyAllocationRow {
  grid-template-columns:
    minmax(230px, 1.7fr)
    minmax(100px, 0.55fr)
    minmax(110px, 0.65fr);
  align-items: center;
}

.facultyAllocationIdentity {
  min-width: 0;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 3px;
}

.facultyAllocationSubjectCode {
  display: block;
  font-size: 9px !important;
  line-height: 1.2;
  font-weight: 850;
  letter-spacing: 0.09em;
  color: #3154bf !important;
}

.facultyAllocationIdentity > b {
  display: block;
  max-width: 100%;
  overflow: hidden;
  font-size: 13px;
  line-height: 1.35;
  font-weight: 750;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: #1c2941;
}

.facultyAllocationIdentity > small {
  display: block;
  max-width: 100%;
  overflow: hidden;
  font-size: 10.5px;
  line-height: 1.4;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: #7b8799;
}

.facultyAllocationMeta {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
  margin-top: 5px;
}

.facultyAllocationMeta > span,
.facultyAllocationMeta > em {
  display: inline-flex;
  align-items: center;
  min-height: 22px;
  padding: 0 7px;
  border: 1px solid #e0e5ec;
  border-radius: 999px;
  background: #f7f9fb;
  font-size: 9px;
  line-height: 1;
  font-weight: 750;
  font-style: normal;
  color: #59667b;
}

.facultyAllocationMeta > em {
  border-color: rgba(176, 111, 18, 0.18);
  background: rgba(176, 111, 18, 0.07);
  color: #8d5a13;
}

.facultyAllocationRow > label {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  gap: 7px;
  margin: 0;
}

.facultyAllocationRow > label > span {
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.08em;
  color: #7b8798;
}

.facultyAllocationRow > button {
  width: 100%;
}

@media (max-width: 760px) {
  .facultyAllocationRow {
    grid-template-columns: 1fr;
    gap: 12px;
    padding: 14px;
  }

  .facultyAllocationIdentity > b,
  .facultyAllocationIdentity > small {
    white-space: normal;
  }

  .facultyAllocationRow > label {
    justify-content: space-between;
  }

  .facultyAllocationRow > label input {
    width: 100px;
  }
}

/* ============================================================
   CAMPUSCONNECT — TIMETABLE AUTOMATION
   ============================================================ */

.timetableAutomationShell {
  width: 100%;
  margin-top: 24px;
  padding: 24px;
  border: 1px solid rgba(15, 23, 42, 0.09);
  border-radius: 28px;
  background:
    radial-gradient(
      circle at 92% 0%,
      rgba(99, 102, 241, 0.09),
      transparent 30%
    ),
    linear-gradient(
      145deg,
      rgba(255, 255, 255, 0.98),
      rgba(248, 250, 252, 0.96)
    );
  box-shadow:
    0 24px 70px rgba(15, 23, 42, 0.07);
}

.timetableAutomationHero {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 24px;
