  max-width: 700px;
}

.timetableAutomationHero > div:first-child > span {
  display: inline-flex;
  margin-bottom: 9px;
  font-size: 11px;
  line-height: 1;
  font-weight: 800;
  letter-spacing: 0.13em;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.64);
}

.timetableAutomationHero h2 {
  margin: 0;
  font-size: clamp(24px, 3vw, 34px);
  line-height: 1.08;
  letter-spacing: -0.035em;
  color: #fff;
}

.timetableAutomationHero p {
  max-width: 660px;
  margin: 12px 0 0;
  font-size: 14px;
  line-height: 1.65;
  color: rgba(255, 255, 255, 0.7);
}

.timetableAutomationHeroStats {
  display: grid;
  grid-template-columns: repeat(2, minmax(110px, 1fr));
  gap: 10px;
  min-width: 250px;
}

.timetableAutomationHeroStats > div {
  min-width: 0;
  padding: 14px 16px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 17px;
  background: rgba(255, 255, 255, 0.07);
