}

.timetableAutomationHeroStats strong {
  display: block;
  font-size: 21px;
  line-height: 1.1;
  color: #fff;
}

.timetableAutomationHeroStats span {
  display: block;
  margin-top: 5px;
  font-size: 11px;
  line-height: 1.3;
  color: rgba(255, 255, 255, 0.62);
}

.timetableAutomationGrid {
  display: grid;
  grid-template-columns:
    repeat(2, minmax(0, 1fr));
  gap: 18px;
}

.timetableAutomationCard {
  min-width: 0;
  padding: 22px;
  border: 1px solid rgba(15, 23, 42, 0.09);
  border-radius: 22px;
  background: rgba(255, 255, 255, 0.92);
  box-shadow:
    0 10px 30px rgba(15, 23, 42, 0.04);
}

.timetableAutomationWide {
  grid-column: 1 / -1;
}

.timetableAutomationCard > header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 18px;
}

.timetableAutomationCard > header > div {
  min-width: 0;
}

.timetableAutomationCard > header span {
  display: block;
  margin-bottom: 6px;
  font-size: 10px;
  line-height: 1;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: #64748b;
}

.timetableAutomationCard > header h3 {
  margin: 0;
  font-size: 18px;
  line-height: 1.2;
  letter-spacing: -0.02em;
  color: #0f172a;
}

.timetableAutomationCard > header p {
  margin: 7px 0 0;
  font-size: 13px;
  line-height: 1.55;
  color: #64748b;
}

.timetableAutomationForm {
  display: grid;
  gap: 13px;
}

.timetableAutomationSplit {
  display: grid;
  grid-template-columns:
    repeat(2, minmax(0, 1fr));
