  line-height: 1.2;
  font-weight: 750;
  color: #475569;
}

.timetableAutomationField input,
.timetableAutomationField select,
.timetableAutomationForm input,
.timetableAutomationForm select,
.timetableAutomationPeriodForm input,
.timetableAutomationPeriodForm select,
.timetableAutomationResourceForm input,
.timetableAutomationResourceForm select {
  width: 100%;
  min-width: 0;
  height: 43px;
  padding: 0 12px;
  border: 1px solid rgba(15, 23, 42, 0.13);
  border-radius: 12px;
  outline: none;
  background: #fff;
  color: #0f172a;
