.timetableAutomationShell button {
  min-height: 40px;
  padding: 9px 14px;
  border: 1px solid rgba(15, 23, 42, 0.1);
  border-radius: 12px;
  background: #0f172a;
  color: #fff;
  font: inherit;
  font-size: 12px;
  line-height: 1.2;
  font-weight: 750;
  cursor: pointer;
  transition:
    transform 150ms ease,
    box-shadow 150ms ease,
    opacity 150ms ease,
    background 150ms ease;
}

.timetableAutomationShell button:hover:not(:disabled) {
  transform: translateY(-1px);
  box-shadow:
    0 8px 20px rgba(15, 23, 42, 0.14);
}

.timetableAutomationShell button:disabled {
  opacity: 0.45;
  cursor: not-allowed;
  transform: none;
}

.timetableAutomationBatchList {
  display: grid;
  gap: 9px;
}

.timetableAutomationBatchList > * {
  min-width: 0;
}

.timetableAutomationBatchList label {
  display: flex;
  align-items: center;
  gap: 12px;
  min-height: 58px;
  padding: 12px 14px;
  border: 1px solid rgba(15, 23, 42, 0.09);
  border-radius: 15px;
  background: #f8fafc;
  cursor: pointer;
  transition:
    border-color 150ms ease,
    background 150ms ease,
    transform 150ms ease;
}

.timetableAutomationBatchList label:hover {
  border-color: rgba(79, 70, 229, 0.25);
  background: #fff;
}

.timetableAutomationBatchList input[type="checkbox"] {
  width: 17px;
  height: 17px;
  flex: 0 0 auto;
  accent-color: #0f172a;
}

.timetableAutomationSelected {
  border-color: rgba(79, 70, 229, 0.3) !important;
  background: rgba(79, 70, 229, 0.055) !important;
}

.timetableAutomationDays {
  display: grid;
  grid-template-columns:
    repeat(3, minmax(0, 1fr));
  gap: 9px;
}

.timetableAutomationDays > * {
  min-width: 0;
}

.timetableAutomationDays label {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  min-height: 54px;
  padding: 11px 12px;
  border: 1px solid rgba(15, 23, 42, 0.09);
  border-radius: 14px;
  background: #f8fafc;
  font-size: 12px;
  font-weight: 700;
  color: #334155;
}

.timetableAutomationDays input[type="checkbox"] {
  width: 17px;
  height: 17px;
  accent-color: #0f172a;
}

.timetableAutomationPeriodForm {
  display: grid;
  grid-template-columns:
    minmax(130px, 1.4fr)
    minmax(85px, 0.7fr)
    minmax(110px, 0.9fr)
    minmax(110px, 0.9fr)
    auto;
  gap: 10px;
  align-items: end;
  margin-bottom: 16px;
}

.timetableAutomationResourceForm {
  display: grid;
  grid-template-columns:
    minmax(100px, 0.8fr)
    minmax(170px, 1.4fr)
    minmax(140px, 1fr)
    minmax(120px, 1fr)
    minmax(90px, 0.7fr)
    minmax(90px, 0.7fr)
    auto;
  gap: 10px;
  align-items: end;
  margin-bottom: 16px;
}

.timetableAutomationTeachingToggle {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 43px;
  padding: 0 10px;
  border: 1px solid rgba(15, 23, 42, 0.09);
  border-radius: 12px;
  background: #f8fafc;
  font-size: 11px;
  font-weight: 700;
  color: #475569;
}

.timetableAutomationTeachingToggle input {
  width: 16px;
  height: 16px;
  accent-color: #0f172a;
}

.timetableAutomationPeriods,
.timetableAutomationResources {
  display: grid;
  gap: 9px;
}

.timetableAutomationPeriods > div,
.timetableAutomationResources > div {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  min-width: 0;
  padding: 13px 14px;
  border: 1px solid rgba(15, 23, 42, 0.08);
  border-radius: 15px;
  background: #f8fafc;
}

.timetableAutomationPeriods > div > div,
.timetableAutomationResources > div > div {
  min-width: 0;
}

.timetableAutomationPeriods strong,
.timetableAutomationResources strong {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 13px;
  color: #0f172a;
}

.timetableAutomationPeriods span,
.timetableAutomationResources span,
.timetableAutomationPeriods small,
.timetableAutomationResources small {
  display: block;
  margin-top: 4px;
  font-size: 11px;
  line-height: 1.4;
  color: #64748b;
}

.timetableAutomationPeriods button,
.timetableAutomationResources button {
  flex: 0 0 auto;
  min-height: 34px;
  padding: 7px 10px;
  background: #fff;
  color: #475569;
}

.timetableAutomationPeriods button:hover:not(:disabled),
.timetableAutomationResources button:hover:not(:disabled) {
  color: #0f172a;
}

.timetableAutomationEmpty {
  padding: 22px;
  border: 1px dashed rgba(15, 23, 42, 0.14);
  border-radius: 15px;
  background: #f8fafc;
  text-align: center;
  font-size: 12px;
  line-height: 1.55;
  color: #64748b;
}

.timetableAutomationStatus,
.timetableAutomationError {
  margin: 0 0 15px;
  padding: 11px 13px;
  border-radius: 12px;
  font-size: 12px;
  line-height: 1.5;
  font-weight: 650;
}

.timetableAutomationStatus {
  border: 1px solid rgba(22, 163, 74, 0.16);
  background: rgba(22, 163, 74, 0.07);
  color: #166534;
}

.timetableAutomationError {
  border: 1px solid rgba(220, 38, 38, 0.16);
  background: rgba(220, 38, 38, 0.06);
  color: #991b1b;
}

.timetableAutomationNext {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  margin-top: 20px;
  padding: 19px 20px;
  border: 1px solid rgba(79, 70, 229, 0.16);
  border-radius: 19px;
  background:
    linear-gradient(
      135deg,
      rgba(79, 70, 229, 0.06),
      rgba(14, 165, 233, 0.035)
    );
}

.timetableAutomationNext > div {
  min-width: 0;
}

.timetableAutomationNext strong {
  display: block;
  font-size: 14px;
  color: #0f172a;
}

.timetableAutomationNext p {
  margin: 5px 0 0;
  font-size: 12px;
  line-height: 1.5;
  color: #64748b;
}

.timetableAutomationNext button {
  flex: 0 0 auto;
  min-width: 150px;
  min-height: 44px;
}

@media (max-width: 1100px) {
  .timetableAutomationHero {
    flex-direction: column;
  }

  .timetableAutomationHeroStats {
    width: 100%;
    grid-template-columns:
      repeat(4, minmax(0, 1fr));
  }

  .timetableAutomationResourceForm {
    grid-template-columns:
      repeat(3, minmax(0, 1fr));
  }
}

@media (max-width: 820px) {
  .timetableAutomationShell {
    padding: 16px;
    border-radius: 22px;
  }

  .timetableAutomationGrid {
    grid-template-columns: 1fr;
  }

  .timetableAutomationWide {
    grid-column: auto;
  }

  .timetableAutomationPeriodForm,
  .timetableAutomationResourceForm {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .timetableAutomationDays {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 560px) {
  .timetableAutomationShell {
    padding: 12px;
    border-radius: 18px;
  }

  .timetableAutomationHero,
  .timetableAutomationCard {
    padding: 17px;
    border-radius: 18px;
  }

  .timetableAutomationHeroStats {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .timetableAutomationSplit,
  .timetableAutomationPeriodForm,
  .timetableAutomationResourceForm,
  .timetableAutomationDays {
    grid-template-columns: 1fr;
  }

  .timetableAutomationPeriods > div,
  .timetableAutomationResources > div,
  .timetableAutomationNext {
    align-items: stretch;
    flex-direction: column;
  }

  .timetableAutomationPeriods button,
  .timetableAutomationResources button,
  .timetableAutomationNext button {
    width: 100%;
  }
}

/* ============================================================
   CAMPUSCONNECT — ACADEMIC CONTROL WORKSPACE
   ============================================================ */

.academicControlWorkspace {
  display: grid;
  gap: 24px;
  width: 100%;
  padding-bottom: 40px;
}

.academicControlHero {
  position: relative;
  display: grid;
  grid-template-columns:
    minmax(0, 1.5fr)
    minmax(280px, 0.7fr);
  gap: 28px;
  overflow: hidden;
  padding: 34px;
  border: 1px solid rgba(15, 23, 42, 0.08);
  border-radius: 30px;
  background:
    radial-gradient(
      circle at 90% 10%,
      rgba(99, 102, 241, 0.18),
      transparent 32%
    ),
    linear-gradient(
      135deg,
      #0f172a,
      #172033 55%,
      #1e293b
    );
  box-shadow:
    0 28px 70px rgba(15, 23, 42, 0.13);
}

.academicControlHero::after {
  content: "";
  position: absolute;
  right: -80px;
  bottom: -100px;
  width: 280px;
  height: 280px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 50%;
  pointer-events: none;
}

.academicControlHeroCopy {
  position: relative;
  z-index: 1;
  align-self: center;
}

.academicControlHeroCopy > span,
.academicControlModuleNav header span,
.academicControlSectionHeader span {
  display: block;
  margin-bottom: 9px;
  font-size: 10px;
  line-height: 1;
  font-weight: 800;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.academicControlHeroCopy > span {
  color: rgba(255, 255, 255, 0.58);
}

.academicControlHeroCopy h1 {
  margin: 0;
  font-size: clamp(32px, 5vw, 52px);
  line-height: 0.98;
  letter-spacing: -0.05em;
  color: #fff;
}

.academicControlHeroCopy p {
  max-width: 680px;
  margin: 17px 0 0;
  font-size: 14px;
  line-height: 1.7;
  color: rgba(255, 255, 255, 0.68);
}

.academicControlHeroActions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 24px;
}

.academicControlHeroActions button {
  min-height: 43px;
  padding: 10px 16px;
  border-radius: 12px;
  font: inherit;
  font-size: 12px;
  font-weight: 750;
  cursor: pointer;
}

.academicControlHeroActions .primary {
  border: 1px solid #fff;
  background: #fff;
  color: #0f172a;
}

.academicControlHeroActions .secondary {
  border: 1px solid rgba(255, 255, 255, 0.18);
  background: rgba(255, 255, 255, 0.07);
  color: #fff;
}

.academicControlHeroPanel {
  position: relative;
  z-index: 1;
  align-self: stretch;
  padding: 22px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 22px;
  background: rgba(255, 255, 255, 0.07);
  backdrop-filter: blur(14px);
}

.academicControlHeroPanel > span {
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.14em;
  color: rgba(255, 255, 255, 0.52);
}

.academicControlHeroPanel > strong {
  display: block;
  margin-top: 12px;
  font-size: 30px;
  letter-spacing: -0.04em;
  color: #fff;
}

.academicControlHeroPanel > p {
  margin: 4px 0 20px;
  font-size: 11px;
  color: rgba(255, 255, 255, 0.56);
}

.academicControlHeroPanel > div {
  display: grid;
  grid-template-columns:
    repeat(2, minmax(0, 1fr));
  gap: 8px;
}

.academicControlHeroPanel > div > span {
  display: grid;
  gap: 4px;
  padding: 11px;
  border: 1px solid rgba(255, 255, 255, 0.09);
  border-radius: 13px;
  background: rgba(255, 255, 255, 0.05);
  font-size: 9px;
  color: rgba(255, 255, 255, 0.5);
}

.academicControlHeroPanel b {
  font-size: 11px;
  color: #fff;
}

.academicControlModuleNav,
.academicControlModuleSection {
  padding: 25px;
  border: 1px solid rgba(15, 23, 42, 0.08);
  border-radius: 25px;
  background: rgba(255, 255, 255, 0.96);
  box-shadow:
    0 16px 45px rgba(15, 23, 42, 0.055);
}

.academicControlModuleNav > header {
  margin-bottom: 18px;
}

.academicControlModuleNav header span,
.academicControlSectionHeader span {
  color: #64748b;
}

.academicControlModuleNav h2,
.academicControlSectionHeader h2 {
  margin: 0;
  font-size: 22px;
  line-height: 1.15;
  letter-spacing: -0.03em;
  color: #0f172a;
}

.academicControlModuleNav header p,
.academicControlSectionHeader p {
  margin: 7px 0 0;
  font-size: 12px;
  line-height: 1.55;
  color: #64748b;
}

.academicControlModuleGrid {
  display: grid;
  grid-template-columns:
    repeat(2, minmax(0, 1fr));
  gap: 13px;
}

.academicControlModuleGrid > button,
.academicControlFutureCard {
  display: grid;
  grid-template-columns:
    auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 15px;
  min-height: 140px;
  padding: 18px;
  border: 1px solid rgba(15, 23, 42, 0.09);
  border-radius: 18px;
  background: #f8fafc;
  text-align: left;
}

.academicControlModuleGrid > button {
  color: inherit;
  font: inherit;
  cursor: pointer;
  transition:
    transform 160ms ease,
    border-color 160ms ease,
    box-shadow 160ms ease,
    background 160ms ease;
}

.academicControlModuleGrid > button:hover,
.academicControlModuleGrid > button.active {
  transform: translateY(-2px);
  border-color: rgba(79, 70, 229, 0.25);
  background: #fff;
  box-shadow:
    0 12px 28px rgba(15, 23, 42, 0.07);
}

.academicControlModuleGrid i,
.academicControlFutureCard > i {
  display: grid;
  place-items: center;
  width: 43px;
  height: 43px;
  border-radius: 13px;
  background: #0f172a;
  font-style: normal;
  font-size: 11px;
  font-weight: 800;
  color: #fff;
}

.academicControlModuleGrid h3 {
  margin: 3px 0 5px;
  font-size: 16px;
  color: #0f172a;
}

.academicControlModuleGrid div > span {
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.11em;
  color: #64748b;
}

.academicControlModuleGrid p {
  margin: 0;
  font-size: 11px;
  line-height: 1.5;
  color: #64748b;
}

.academicControlModuleGrid > button > strong {
  font-size: 18px;
  color: #94a3b8;
}

.academicControlFutureCard {
  opacity: 0.72;
}

.academicControlFutureCard em {
  padding: 6px 8px;
  border-radius: 999px;
  background: #e2e8f0;
  font-style: normal;
  font-size: 9px;
  font-weight: 800;
  color: #475569;
}

.academicControlSectionHeader {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 18px;
  margin-bottom: 8px;
}

.academicControlSectionHeader > div {
  min-width: 0;
}

.academicControlSectionHeader > button {
  flex: 0 0 auto;
  min-height: 38px;
  padding: 8px 12px;
  border: 1px solid rgba(15, 23, 42, 0.1);
  border-radius: 11px;
  background: #f8fafc;
  color: #475569;
  font: inherit;
  font-size: 11px;
  font-weight: 700;
  cursor: pointer;
}

.academicControlModuleSection >
.facultyWorkloadShell,
.academicControlModuleSection >
.timetableAutomationShell {
  margin-top: 20px;
}

.academicControlAccess {
  max-width: 650px;
  margin: 40px auto;
  padding: 28px;
  border: 1px solid rgba(15, 23, 42, 0.09);
  border-radius: 20px;
  background: #fff;
  text-align: center;
}

.academicControlAccess strong {
  display: block;
  font-size: 20px;
  color: #0f172a;
}

.academicControlAccess p {
  margin: 8px 0 0;
  color: #64748b;
}

@media (max-width: 950px) {
  .academicControlHero {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 720px) {
  .academicControlWorkspace {
    gap: 16px;
  }

  .academicControlHero,
  .academicControlModuleNav,
  .academicControlModuleSection {
    padding: 19px;
    border-radius: 20px;
  }

  .academicControlModuleGrid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 520px) {
  .academicControlHero {
    padding: 18px;
  }

  .academicControlHeroPanel > div {
    grid-template-columns: 1fr;
  }

  .academicControlHeroActions {
    display: grid;
  }

  .academicControlHeroActions button {
    width: 100%;
  }

  .academicControlModuleGrid > button,
  .academicControlFutureCard {
    grid-template-columns:
      auto minmax(0, 1fr);
  }

  .academicControlModuleGrid >
  button > strong,
  .academicControlFutureCard em {
    grid-column: 2;
  }

  .academicControlSectionHeader {
    flex-direction: column;
  }
}

/* ============================================================
   ACADEMIC CONTROL — DEDICATED MODULE PAGES
   ============================================================ */

.academicControlModulePage {
  display: grid;
  gap: 20px;
  width: 100%;
}

.academicControlModulePageHeader {
