/* ==========================================================
   FACULTY AVAILABILITY
   ========================================================== */

.facultyAvailabilityShell {
  margin-top: 28px;
  display: grid;
  gap: 18px;
}

.facultyAvailabilityHero {
  position: relative;
  overflow: hidden;
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 24px;
  padding: 28px;
  border: 1px solid var(--border);
  border-radius: 24px;
  background:
    radial-gradient(
      circle at 92% 10%,
      color-mix(in srgb, var(--accent) 15%, transparent),
      transparent 36%
    ),
    var(--card);
}

.facultyAvailabilityHero::after {
  content: "";
  position: absolute;
  width: 180px;
  height: 180px;
  right: -80px;
  bottom: -110px;
  border-radius: 50%;
  border: 28px solid
    color-mix(
      in srgb,
      var(--accent) 9%,
      transparent
    );
  pointer-events: none;
}

.facultyAvailabilityHero > div,
.facultyAvailabilityHero > strong {
  position: relative;
  z-index: 1;
}

.facultyAvailabilityHero span,
.facultyAvailabilityBoard header span,
.facultyAvailabilityExceptions header span {
  display: block;
  margin-bottom: 7px;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: .13em;
  color: var(--accent);
}

.facultyAvailabilityHero h2,
.facultyAvailabilityBoard h3,
.facultyAvailabilityExceptions h3 {
  margin: 0;
  color: var(--text);
}

.facultyAvailabilityHero h2 {
  font-size: clamp(25px, 3vw, 38px);
  letter-spacing: -.04em;
}

.facultyAvailabilityHero p,
.facultyAvailabilityBoard header p,
.facultyAvailabilityExceptions header p {
  max-width: 720px;
  margin: 9px 0 0;
  line-height: 1.65;
  color: var(--muted);
}

.facultyAvailabilityHero > strong {
  flex: 0 0 auto;
  padding: 9px 13px;
  border: 1px solid var(--border);
  border-radius: 999px;
  background: var(--surface);
  font-size: 12px;
  color: var(--text);
}

.facultyAvailabilityToolbar {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: 18px;
  padding: 18px 20px;
  border: 1px solid var(--border);
  border-radius: 18px;
  background: var(--card);
}

.facultyAvailabilityToolbar label,
.facultyAvailabilityExceptionForm label {
  display: grid;
  gap: 7px;
}

.facultyAvailabilityToolbar label {
  min-width: min(420px, 100%);
}

.facultyAvailabilityToolbar label,
.facultyAvailabilityExceptionForm label > span {
  font-size: 12px;
  font-weight: 750;
  color: var(--muted);
}

.facultyAvailabilityToolbar select,
.facultyAvailabilityExceptionForm input,
.facultyAvailabilityExceptionForm select {
  min-height: 44px;
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 0 12px;
  outline: none;
  background: var(--surface);
  color: var(--text);
  font: inherit;
}

.facultyAvailabilityToolbar select:focus,
.facultyAvailabilityExceptionForm input:focus,
.facultyAvailabilityExceptionForm select:focus {
  border-color: var(--accent);
}

.facultyAvailabilityLegend {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 8px;
}

.facultyAvailabilityLegend span {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 7px 10px;
