}

.facultyAvailabilityExceptionForm button:disabled {
  opacity: .55;
  cursor: not-allowed;
}

.facultyAvailabilityExceptionList {
  display: grid;
  gap: 9px;
  padding: 0 22px 22px;
}

.facultyAvailabilityExceptionList article {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
  padding: 13px 15px;
  border: 1px solid var(--border);
  border-radius: 14px;
  background: var(--surface);
}

.facultyAvailabilityExceptionList article > div {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px 12px;
}

.facultyAvailabilityExceptionList span {
  color: var(--muted);
  font-size: 11px;
  font-weight: 750;
}

.facultyAvailabilityExceptionList strong {
  color: var(--text);
  font-size: 13px;
}

.facultyAvailabilityExceptionList small {
  flex-basis: 100%;
  color: var(--muted);
}

.facultyAvailabilityExceptionList button {
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 7px 10px;
  background: var(--card);
  color: var(--muted);
  font: inherit;
  font-size: 11px;
  font-weight: 750;
  cursor: pointer;
}

.facultyAvailabilityEmpty {
  padding: 28px 22px;
  text-align: center;
  color: var(--muted);
  line-height: 1.55;
}

.facultyAvailabilityMessage {
  padding: 26px;
}

.facultyAvailabilityMessage > span {
  display: block;
  margin-bottom: 7px;
  color: var(--accent);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .12em;
}

.facultyAvailabilityMessage h3 {
  margin: 0;
  color: var(--text);
}

.facultyAvailabilityMessage p {
  margin: 8px 0 0;
  max-width: 680px;
  color: var(--muted);
  line-height: 1.6;
}

.facultyAvailabilityMessage.error > span {
  color: #b91c1c;
}


@media (max-width: 980px) {
  .facultyAvailabilityMetrics {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .facultyAvailabilityExceptionForm {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .facultyAvailabilityReason {
    grid-column: 1 / -1;
  }
}


@media (max-width: 680px) {
  .facultyAvailabilityHero,
  .facultyAvailabilityToolbar,
  .facultyAvailabilityBoard > header,
  .facultyAvailabilityExceptions > header {
    flex-direction: column;
  }

  .facultyAvailabilityToolbar {
    align-items: stretch;
  }

  .facultyAvailabilityLegend {
    justify-content: flex-start;
  }

  .facultyAvailabilityMetrics {
    grid-template-columns: 1fr 1fr;
  }

