/* ==========================================================
   FACULTY AVAILABILITY — PREMIUM ANIMATED UI OVERRIDE
   ========================================================== */

.facultyAvailabilityShell {
  --fa-green: #10b981;
  --fa-green-dark: #047857;
  --fa-blue: #3b82f6;
  --fa-violet: #8b5cf6;
  --fa-amber: #f59e0b;
  --fa-red: #ef4444;

  position: relative;
  isolation: isolate;
  margin-top: 32px;
  display: grid;
  gap: 20px;
  animation: faShellEnter .65s cubic-bezier(.2,.8,.2,1) both;
}

.facultyAvailabilityShell::before {
  content: "";
  position: absolute;
  z-index: -1;
  top: -70px;
  right: -60px;
  width: 300px;
  height: 300px;
  border-radius: 50%;
  background:
    radial-gradient(
      circle,
      color-mix(in srgb, var(--fa-violet) 12%, transparent),
      transparent 70%
    );
  filter: blur(10px);
  pointer-events: none;
  animation: faAmbientFloat 9s ease-in-out infinite;
}


/* HERO */

.facultyAvailabilityHero {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 30px;

  min-height: 190px;
  padding: 34px 36px;

  border:
    1px solid
    color-mix(
      in srgb,
      var(--accent) 20%,
      var(--border)
    );

  border-radius: 30px;

  background:
    radial-gradient(
      circle at 85% 10%,
      color-mix(
        in srgb,
        var(--fa-violet) 18%,
        transparent
      ),
      transparent 38%
    ),
    radial-gradient(
      circle at 5% 100%,
      color-mix(
        in srgb,
        var(--fa-blue) 12%,
        transparent
      ),
      transparent 38%
    ),
    linear-gradient(
      135deg,
      color-mix(
        in srgb,
        var(--card) 96%,
        var(--fa-violet)
      ),
      var(--card)
    );

  box-shadow:
    0 20px 55px rgba(15, 23, 42, .08),
    inset 0 1px 0 rgba(255,255,255,.5);

  animation:
    faCardEnter .65s cubic-bezier(.2,.8,.2,1) both;
}

.facultyAvailabilityHero::before {
  content: "";
  position: absolute;
  z-index: -1;
  width: 330px;
  height: 330px;
  right: -95px;
  top: -170px;
  border-radius: 50%;
  border:
    42px solid
    color-mix(
      in srgb,
      var(--fa-violet) 8%,
      transparent
    );
  animation: faHeroOrb 12s linear infinite;
}

.facultyAvailabilityHero::after {
  content: "";
  position: absolute;
  z-index: -1;
  width: 150px;
  height: 150px;
  right: 100px;
  bottom: -105px;
  border-radius: 50%;
  background:
    color-mix(
      in srgb,
      var(--fa-blue) 9%,
      transparent
    );
  filter: blur(2px);
  animation: faAmbientFloat 7s ease-in-out infinite reverse;
}

.facultyAvailabilityHero > div,
.facultyAvailabilityHero > strong {
  position: relative;
  z-index: 2;
}

.facultyAvailabilityHero span,
.facultyAvailabilityBoard header span,
.facultyAvailabilityExceptions header span {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  width: fit-content;
  margin-bottom: 10px;
  font-size: 10px;
  font-weight: 900;
  letter-spacing: .16em;
  text-transform: uppercase;
  color: var(--accent);
}

.facultyAvailabilityHero span::before,
.facultyAvailabilityBoard header span::before,
.facultyAvailabilityExceptions header span::before {
  content: "";
  width: 7px;
  height: 7px;
  flex: 0 0 7px;
  border-radius: 50%;
  background: currentColor;
  box-shadow:
    0 0 0 5px
    color-mix(
      in srgb,
      currentColor 10%,
      transparent
    );
  animation: faPulseDot 2s ease-in-out infinite;
}

.facultyAvailabilityHero h2 {
  margin: 0;
  max-width: 720px;
  font-size: clamp(28px, 3.3vw, 44px);
  line-height: 1.03;
  letter-spacing: -.045em;
  color: var(--text);
}

.facultyAvailabilityHero p {
  max-width: 760px;
  margin: 13px 0 0;
  font-size: 14px;
  line-height: 1.75;
  color: var(--muted);
}

.facultyAvailabilityHero > strong {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  min-height: 40px;
  padding: 0 16px;

  border:
    1px solid
    color-mix(
      in srgb,
      var(--accent) 22%,
      var(--border)
    );

  border-radius: 999px;

  background:
    color-mix(
      in srgb,
      var(--card) 80%,
      transparent
    );

  box-shadow:
    0 8px 24px rgba(15,23,42,.06);

  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);

  color: var(--text);
  font-size: 11px;
  font-weight: 850;
  letter-spacing: .02em;
}


/* TOOLBAR */

.facultyAvailabilityToolbar {
  position: relative;
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: 20px;
  padding: 20px 22px;

