    linear-gradient(
      135deg,
      var(--card),
      color-mix(
        in srgb,
        var(--card) 96%,
        var(--fa-blue)
      )
    );

  box-shadow:
    0 10px 35px rgba(15,23,42,.045);

  animation:
    faCardEnter .65s .08s cubic-bezier(.2,.8,.2,1) both;

  transition:
    border-color .25s ease,
    box-shadow .25s ease,
    transform .25s ease;
}

.facultyAvailabilityToolbar:hover {
  border-color:
