/* PERIOD CELLS */

.facultyAvailabilityCell {
  position: relative;
  overflow: hidden;

  width: 100%;
  min-height: 76px;

  display: grid;
  align-content: center;
  gap: 5px;

  padding: 11px 12px;

  border: 1px solid var(--border);
  border-radius: 14px;

  background:
    linear-gradient(
      145deg,
      var(--surface),
      color-mix(
        in srgb,
        var(--surface) 96%,
        var(--accent)
      )
    );

  color: var(--text);
  text-align: left;
  font: inherit;

  cursor: pointer;

  transition:
    transform .22s cubic-bezier(.2,.8,.2,1),
    border-color .22s ease,
    box-shadow .22s ease,
    background .22s ease;
}

.facultyAvailabilityCell::after {
  content: "";
  position: absolute;
  width: 55px;
  height: 140%;
  top: -20%;
  left: -85px;
  transform: rotate(18deg);

  background:
    linear-gradient(
      90deg,
      transparent,
      rgba(255,255,255,.35),
      transparent
    );

  transition: left .55s ease;
  pointer-events: none;
}

button.facultyAvailabilityCell:hover:not(:disabled) {
  transform: translateY(-3px) scale(1.015);

  border-color:
    color-mix(
      in srgb,
      var(--accent) 45%,
      var(--border)
    );

  box-shadow:
    0 10px 22px rgba(15,23,42,.09);
}

button.facultyAvailabilityCell:hover:not(:disabled)::after {
  left: calc(100% + 30px);
}

button.facultyAvailabilityCell:active:not(:disabled) {
  transform: translateY(-1px) scale(.99);
}

.facultyAvailabilityCell strong {
  font-size: 11px;
  font-weight: 850;
}

.facultyAvailabilityCell small {
  font-size: 9px;
  line-height: 1.4;
  color: var(--muted);
}


/* AVAILABLE */

.facultyAvailabilityCell.available {
  border-color:
    color-mix(
      in srgb,
      var(--fa-green) 40%,
      var(--border)
    );

  background:
    linear-gradient(
      145deg,
      color-mix(
        in srgb,
        var(--fa-green) 10%,
        var(--surface)
      ),
      color-mix(
        in srgb,
        var(--fa-green) 4%,
        var(--surface)
      )
    );

  box-shadow:
    inset 3px 0 0
    color-mix(
      in srgb,
      var(--fa-green) 75%,
      transparent
    );
}

.facultyAvailabilityCell.available strong {
  color: var(--fa-green-dark);
}


/* BUSY */

.facultyAvailabilityCell.busy {
  border-color:
    color-mix(
      in srgb,
      var(--fa-amber) 35%,
      var(--border)
    );

  background:
    linear-gradient(
      145deg,
      color-mix(
        in srgb,
        var(--fa-amber) 10%,
        var(--surface)
      ),
      color-mix(
        in srgb,
        var(--fa-amber) 4%,
        var(--surface)
      )
    );

  box-shadow:
    inset 3px 0 0
    color-mix(
      in srgb,
      var(--fa-amber) 75%,
      transparent
    );

  cursor: not-allowed;
}

.facultyAvailabilityCell.busy strong {
  color: #b45309;
}

.facultyAvailabilityCell.unavailable {
  opacity: .52;
  cursor: default;
}


/* EXCEPTION FORM */

.facultyAvailabilityExceptionForm {
  display: grid;

  grid-template-columns:
    minmax(155px, .75fr)
    minmax(200px, .95fr)
    minmax(240px, 1.4fr)
    auto;

  gap: 14px;
  align-items: end;

  padding: 23px 26px;
}

.facultyAvailabilityExceptionForm label {
  display: grid;
  gap: 8px;
}

.facultyAvailabilityExceptionForm label > span {
  font-size: 10px;
  font-weight: 850;
  letter-spacing: .04em;
  color: var(--muted);
}

.facultyAvailabilityExceptionForm button {
  position: relative;
  overflow: hidden;

  min-height: 46px;
  padding: 0 20px;

  border: 0;
  border-radius: 13px;

  background:
    linear-gradient(
      135deg,
      var(--accent),
      color-mix(
        in srgb,
        var(--accent) 75%,
        var(--fa-violet)
      )
    );

  color: #fff;

  font: inherit;
  font-size: 12px;
  font-weight: 850;

  cursor: pointer;

  box-shadow:
    0 9px 22px
    color-mix(
      in srgb,
      var(--accent) 20%,
      transparent
    );

  transition:
    transform .2s ease,
    box-shadow .2s ease,
    opacity .2s ease;
}

.facultyAvailabilityExceptionForm button:hover:not(:disabled) {
  transform: translateY(-2px);

  box-shadow:
    0 14px 28px
    color-mix(
      in srgb,
      var(--accent) 28%,
      transparent
    );
}

.facultyAvailabilityExceptionForm button:active:not(:disabled) {
  transform: translateY(0) scale(.98);
}

.facultyAvailabilityExceptionForm button:disabled {
  opacity: .5;
  cursor: not-allowed;
}


/* EXCEPTION LIST */

.facultyAvailabilityExceptionList {
  display: grid;
  gap: 10px;
  padding: 0 26px 25px;
}

.facultyAvailabilityExceptionList article {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;

  padding: 14px 16px;

  border: 1px solid var(--border);
  border-radius: 15px;

  background: var(--surface);

  transition:
    transform .2s ease,
    border-color .2s ease,
    box-shadow .2s ease;
}

.facultyAvailabilityExceptionList article:hover {
  transform: translateX(3px);

  border-color:
    color-mix(
      in srgb,
      var(--accent) 22%,
      var(--border)
    );

  box-shadow:
    0 8px 22px rgba(15,23,42,.055);
}

.facultyAvailabilityExceptionList article > div {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px 12px;
}

.facultyAvailabilityExceptionList span {
  color: var(--muted);
  font-size: 10px;
  font-weight: 800;
}

.facultyAvailabilityExceptionList strong {
  color: var(--text);
  font-size: 12px;
}

.facultyAvailabilityExceptionList small {
  flex-basis: 100%;
  color: var(--muted);
}

.facultyAvailabilityExceptionList button {
  padding: 8px 12px;

  border: 1px solid var(--border);
  border-radius: 10px;

  background: var(--card);
  color: var(--muted);

  font: inherit;
  font-size: 10px;
  font-weight: 800;

  cursor: pointer;

  transition:
    color .2s ease,
    border-color .2s ease,
    transform .2s ease;
}

.facultyAvailabilityExceptionList button:hover {
  color: var(--fa-red);

  border-color:
    color-mix(
      in srgb,
      var(--fa-red) 35%,
      var(--border)
    );

  transform: translateY(-1px);
}


/* ALERTS */

.facultyAvailabilityAlert {
  padding: 13px 16px;
  border-radius: 14px;
  font-size: 12px;
  line-height: 1.55;
  animation: faAlertEnter .35s ease both;
}

.facultyAvailabilityAlert.success {
  border:
    1px solid
    color-mix(
      in srgb,
      var(--fa-green) 30%,
      var(--border)
    );

  background:
    color-mix(
      in srgb,
      var(--fa-green) 7%,
      var(--card)
    );

  color: var(--fa-green-dark);
}

.facultyAvailabilityAlert.error {
  border:
    1px solid
    color-mix(
      in srgb,
      var(--fa-red) 30%,
      var(--border)
    );

  background:
    color-mix(
      in srgb,
      var(--fa-red) 7%,
      var(--card)
    );

  color: #b91c1c;
}

.facultyAvailabilityEmpty {
  padding: 36px 24px;
  text-align: center;
  color: var(--muted);
  line-height: 1.6;
}

.facultyAvailabilityMessage {
  padding: 28px;
}

.facultyAvailabilityMessage > span {
  display: block;
  margin-bottom: 8px;

  color: var(--accent);

  font-size: 9px;
  font-weight: 900;
  letter-spacing: .14em;
  text-transform: uppercase;
}

.facultyAvailabilityMessage h3 {
  margin: 0;
  color: var(--text);
}

.facultyAvailabilityMessage p {
  max-width: 680px;
  margin: 9px 0 0;
  color: var(--muted);
  line-height: 1.65;
}


/* ANIMATION */

@keyframes faShellEnter {
  from {
    opacity: 0;
    transform: translateY(18px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes faCardEnter {
  from {
    opacity: 0;
    transform:
      translateY(18px)
      scale(.985);
  }

  to {
    opacity: 1;
    transform:
      translateY(0)
      scale(1);
  }
}

@keyframes faAmbientFloat {
  0%,
  100% {
    transform:
      translate3d(0,0,0)
      scale(1);
  }

  50% {
    transform:
      translate3d(-12px,14px,0)
      scale(1.05);
  }
}

@keyframes faHeroOrb {
  from {
    transform: rotate(0deg);
  }

  to {
    transform: rotate(360deg);
  }
}

@keyframes faPulseDot {
  0%,
  100% {
    opacity: .65;
    transform: scale(.85);
  }

  50% {
    opacity: 1;
    transform: scale(1.12);
  }
}

@keyframes faAlertEnter {
  from {
    opacity: 0;
    transform: translateY(-5px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}


/* RESPONSIVE */

@media (max-width: 980px) {
  .facultyAvailabilityMetrics {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .facultyAvailabilityExceptionForm {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .facultyAvailabilityReason {
    grid-column: 1 / -1;
  }
}

@media (max-width: 680px) {
  .facultyAvailabilityShell {
    gap: 14px;
  }

  .facultyAvailabilityHero {
    min-height: auto;
    padding: 25px 21px;
    border-radius: 23px;
    flex-direction: column;
    align-items: flex-start;
  }

  .facultyAvailabilityHero h2 {
    font-size: 29px;
  }

  .facultyAvailabilityToolbar,
  .facultyAvailabilityBoard > header,
  .facultyAvailabilityExceptions > header {
    flex-direction: column;
  }

  .facultyAvailabilityToolbar {
    padding: 17px;
    align-items: stretch;
  }

  .facultyAvailabilityLegend {
    justify-content: flex-start;
  }

  .facultyAvailabilityMetrics {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
    gap: 10px;
  }

  .facultyAvailabilityMetrics article {
    min-height: 115px;
    padding: 16px;
    border-radius: 18px;
  }

  .facultyAvailabilityExceptionForm {
    grid-template-columns: 1fr;
    padding: 19px;
  }

  .facultyAvailabilityReason {
    grid-column: auto;
  }

  .facultyAvailabilityExceptionList {
    padding:
      0 19px 19px;
  }

  .facultyAvailabilityExceptionList article {
    align-items: flex-start;
    flex-direction: column;
  }
}


/* Respect OS accessibility preference */

@media (prefers-reduced-motion: reduce) {
  .facultyAvailabilityShell,
  .facultyAvailabilityHero,
  .facultyAvailabilityToolbar,
  .facultyAvailabilityMetrics,
  .facultyAvailabilityBoard,
  .facultyAvailabilityExceptions,
  .facultyAvailabilityAlert,
  .facultyAvailabilityHero::before,
  .facultyAvailabilityHero::after,
  .facultyAvailabilityShell::before,
  .facultyAvailabilityHero span::before,
  .facultyAvailabilityBoard header span::before,
  .facultyAvailabilityExceptions header span::before {
    animation: none !important;
  }

  .facultyAvailabilityCell,
  .facultyAvailabilityMetrics article,
  .facultyAvailabilityToolbar,
  .facultyAvailabilityExceptionList article {
    transition-duration: .01ms !important;
  }
}


/* ==========================================================
   END FACULTY AVAILABILITY — PREMIUM ANIMATED UI OVERRIDE
   ========================================================== */


/* ==========================================================
   FACULTY COVERAGE — PROFESSIONAL COMMAND CENTER
   ========================================================== */

.facultyCoverage {
  --fc-green: #16865c;
  --fc-green-soft: rgba(22, 134, 92, .08);
  --fc-amber: #c76a13;
  --fc-amber-soft: rgba(199, 106, 19, .08);
  --fc-red: #c2413b;
  --fc-blue: #496f9c;

  position: relative;
  isolation: isolate;

  display: grid;
  gap: 18px;

  margin-top: 26px;

  animation:
    facultyCoverageEnter
    .55s cubic-bezier(.22, 1, .36, 1)
    both;
}


/* ==========================================================
   HERO
   ========================================================== */

.facultyCoverageHero {
  position: relative;
  overflow: hidden;

  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 28px;

  min-height: 170px;
  padding: 30px 32px;

  border:
    1px solid
    color-mix(
      in srgb,
      var(--accent) 16%,
      var(--border)
    );

  border-radius: 27px;

  background:
    radial-gradient(
      circle at 88% 15%,
      color-mix(
        in srgb,
        var(--accent) 12%,
        transparent
      ),
      transparent 34%
    ),
    radial-gradient(
      circle at 72% 120%,
      rgba(22, 134, 92, .08),
      transparent 36%
    ),
    linear-gradient(
      135deg,
      var(--card),
      color-mix(
        in srgb,
        var(--surface) 68%,
        var(--card)
      )
    );

  box-shadow:
    0 18px 48px rgba(15, 23, 42, .065);
}

.facultyCoverageHero::before {
  content: "";

  position: absolute;
  width: 230px;
  height: 230px;

  right: -85px;
  top: -135px;

  border:
    28px solid
    color-mix(
      in srgb,
      var(--accent) 6%,
      transparent
    );

  border-radius: 50%;

  pointer-events: none;

  animation:
    facultyCoverageOrbit
    15s linear infinite;
}

.facultyCoverageHero::after {
  content: "";

  position: absolute;

  width: 90px;
  height: 90px;

  right: 190px;
  bottom: -58px;

  border-radius: 26px;

  background:
    color-mix(
      in srgb,
      var(--fc-green) 7%,
      transparent
    );

  transform: rotate(24deg);

  animation:
    facultyCoverageFloat
    6s ease-in-out infinite;
}

.facultyCoverageHero > * {
  position: relative;
  z-index: 2;
}

.facultyCoverageHero > div:first-child {
  max-width: 760px;
}

.facultyCoverageHero span {
  display: inline-flex;
  align-items: center;
  gap: 8px;

  margin-bottom: 9px;

  color: var(--accent);

  font-size: 10px;
  font-weight: 900;
  letter-spacing: .15em;
}

.facultyCoverageHero span::before {
  content: "";

  width: 7px;
  height: 7px;

  border-radius: 50%;

  background: currentColor;

  box-shadow:
    0 0 0 5px
    color-mix(
      in srgb,
      currentColor 9%,
      transparent
    );

  animation:
    facultyCoveragePulse
    2.2s ease-in-out infinite;
}

.facultyCoverageHero h2 {
  margin: 0;

  font-size:
    clamp(27px, 3vw, 40px);

  line-height: 1.05;

  letter-spacing: -.045em;

  color: var(--text);
}

.facultyCoverageHero p {
  max-width: 760px;

  margin: 12px 0 0;

  font-size: 13px;
  line-height: 1.7;

  color: var(--muted);
}


/* ==========================================================
   HERO STATS
   ========================================================== */

.facultyCoverageHeroStats {
  flex: 0 0 auto;

  display: grid;
  grid-template-columns:
    repeat(3, minmax(82px, 1fr));

  gap: 9px;
}

.facultyCoverageHeroStats article,
.facultyCoverageHeroStats > div {
  position: relative;
  overflow: hidden;

  min-width: 90px;
  padding: 13px 14px;

  border: 1px solid var(--border);
  border-radius: 15px;

  background:
    color-mix(
      in srgb,
      var(--card) 82%,
      transparent
    );

  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);

  box-shadow:
    0 7px 20px rgba(15, 23, 42, .045);

  transition:
    transform .2s ease,
    border-color .2s ease,
    box-shadow .2s ease;
}

.facultyCoverageHeroStats article:hover,
.facultyCoverageHeroStats > div:hover {
  transform: translateY(-3px);

  border-color:
    color-mix(
      in srgb,
      var(--accent) 25%,
      var(--border)
    );

  box-shadow:
    0 12px 26px rgba(15, 23, 42, .075);
}

.facultyCoverageHeroStats span {
  display: block;

  margin: 0 0 7px;

  color: var(--muted);

  font-size: 8px;
  font-weight: 900;
  letter-spacing: .09em;
}

.facultyCoverageHeroStats span::before {
  display: none;
}

.facultyCoverageHeroStats strong {
  display: block;

  color: var(--text);

  font-size: 24px;
  line-height: 1;

  letter-spacing: -.04em;
}


/* ==========================================================
   TOOLBAR + TABS
   ========================================================== */

.facultyCoverageToolbar {
  display: flex;
  justify-content: space-between;
  align-items: center;

  gap: 14px;

  padding: 10px;

  border: 1px solid var(--border);
  border-radius: 19px;

  background: var(--card);

  box-shadow:
    0 8px 28px rgba(15, 23, 42, .04);
}

.facultyCoverageTabs {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.facultyCoverageTabs button {
  position: relative;

  min-height: 40px;

  padding: 0 15px;

  border: 0;
  border-radius: 12px;

  background: transparent;

  color: var(--muted);

  font: inherit;
  font-size: 11px;
  font-weight: 800;

  cursor: pointer;

  transition:
    color .18s ease,
    background .18s ease,
    transform .18s ease,
    box-shadow .18s ease;
}

.facultyCoverageTabs button:hover {
  color: var(--text);
  background: var(--surface);
}

.facultyCoverageTabs button.active,
.facultyCoverageTabs button[aria-selected="true"] {
  color: var(--text);

  background:
    color-mix(
      in srgb,
      var(--accent) 9%,
      var(--surface)
    );

  box-shadow:
    inset 0 0 0 1px
    color-mix(
      in srgb,
      var(--accent) 14%,
      transparent
    );
}

.facultyCoverageTabs button.active::after,
.facultyCoverageTabs button[aria-selected="true"]::after {
  content: "";

  position: absolute;

  left: 16px;
  right: 16px;
  bottom: 4px;

  height: 2px;

  border-radius: 99px;

  background: var(--accent);

  animation:
    facultyCoverageTabLine
    .25s ease both;
}

.facultyCoverageRefresh {
  flex: 0 0 auto;

  min-height: 40px;

  padding: 0 14px;

  border: 1px solid var(--border);
  border-radius: 12px;

  background: var(--surface);
  color: var(--text);

  font: inherit;
  font-size: 10px;
  font-weight: 800;

  cursor: pointer;

  transition:
    transform .18s ease,
    border-color .18s ease,
    box-shadow .18s ease;
}

.facultyCoverageRefresh:hover:not(:disabled) {
  transform: translateY(-2px);

  border-color:
    color-mix(
      in srgb,
      var(--accent) 28%,
      var(--border)
    );

  box-shadow:
    0 8px 20px rgba(15, 23, 42, .065);
}

.facultyCoverageRefresh:disabled {
  opacity: .55;
  cursor: wait;
}


/* ==========================================================
   MAIN GRID
   ========================================================== */

.facultyCoverageGrid {
  display: grid;
  grid-template-columns:
    repeat(2, minmax(0, 1fr));

  gap: 14px;
}


/* ==========================================================
   CLASS CARD
   ========================================================== */

.facultyCoverageClassCard {
  position: relative;
  overflow: hidden;

  display: grid;
  gap: 17px;

  min-height: 210px;

  padding: 20px;

  border: 1px solid var(--border);
  border-radius: 21px;

  background:
    linear-gradient(
      145deg,
      var(--card),
      color-mix(
        in srgb,
        var(--surface) 65%,
        var(--card)
      )
    );

  box-shadow:
    0 10px 30px rgba(15, 23, 42, .045);

  transition:
    transform .24s
      cubic-bezier(.22, 1, .36, 1),
    border-color .24s ease,
    box-shadow .24s ease;

  animation:
    facultyCoverageCardEnter
    .45s cubic-bezier(.22, 1, .36, 1)
    both;
}

.facultyCoverageClassCard::before {
  content: "";

  position: absolute;

  width: 110px;
  height: 110px;

  right: -55px;
  top: -55px;

  border-radius: 50%;

  background:
    color-mix(
      in srgb,
      var(--accent) 6%,
      transparent
    );

  transition:
    transform .35s ease;
}

.facultyCoverageClassCard:hover {
  transform: translateY(-4px);

  border-color:
    color-mix(
      in srgb,
      var(--accent) 22%,
      var(--border)
    );

  box-shadow:
    0 18px 40px rgba(15, 23, 42, .085);
}

.facultyCoverageClassCard:hover::before {
  transform: scale(1.3);
}

.facultyCoverageClassTop {
  position: relative;
  z-index: 1;

  display: flex;
  justify-content: space-between;
  align-items: flex-start;

  gap: 14px;
}

.facultyCoverageClassTop > div {
  min-width: 0;
}

.facultyCoverageClassTop span {
  display: inline-flex;

  margin-bottom: 7px;

  padding: 5px 8px;

  border-radius: 8px;

  background:
    color-mix(
      in srgb,
      var(--accent) 7%,
      var(--surface)
    );

  color: var(--muted);

  font-size: 8px;
  font-weight: 900;
  letter-spacing: .08em;
  text-transform: uppercase;
}

.facultyCoverageClassTop h3,
.facultyCoverageClassTop h4 {
  margin: 0;

  color: var(--text);

  font-size: 18px;
  line-height: 1.2;

  letter-spacing: -.025em;
}

.facultyCoverageClassTop p {
  margin: 6px 0 0;

  color: var(--muted);

  font-size: 11px;
  line-height: 1.5;
}


/* ==========================================================
   CLASS METADATA
   ========================================================== */

.facultyCoverageClassMeta {
  position: relative;
  z-index: 1;

  display: grid;
  grid-template-columns:
    repeat(3, minmax(0, 1fr));

  gap: 8px;
}

.facultyCoverageClassMeta > div {
  min-width: 0;

  padding: 10px;

  border: 1px solid var(--border);
  border-radius: 12px;

  background: var(--surface);
}

.facultyCoverageClassMeta span,
.facultyCoverageClassMeta small {
  display: block;

  margin-bottom: 4px;

  color: var(--muted);

  font-size: 8px;
  font-weight: 800;

  letter-spacing: .06em;
  text-transform: uppercase;
}

.facultyCoverageClassMeta strong {
  display: block;

  overflow: hidden;

  color: var(--text);

  font-size: 11px;
  font-weight: 800;

  text-overflow: ellipsis;
  white-space: nowrap;
}


/* ==========================================================
   REQUEST BUTTON
   ========================================================== */

.facultyCoverageRequestButton {
  position: relative;
  z-index: 1;

  justify-self: start;

  min-height: 42px;

  padding: 0 16px;

  border:
    1px solid
    color-mix(
      in srgb,
      var(--fc-amber) 30%,
      var(--border)
    );

  border-radius: 12px;

  background:
    linear-gradient(
      135deg,
      color-mix(
        in srgb,
        var(--fc-amber) 9%,
        var(--card)
      ),
      color-mix(
        in srgb,
        var(--fc-amber) 4%,
        var(--card)
      )
    );

  color: #a84d08;

  font: inherit;
  font-size: 11px;
  font-weight: 850;

  cursor: pointer;

  transition:
    transform .18s ease,
    border-color .18s ease,
    box-shadow .18s ease;
}

.facultyCoverageRequestButton:hover:not(:disabled) {
  transform: translateY(-2px);

  border-color:
    color-mix(
      in srgb,
      var(--fc-amber) 52%,
      var(--border)
    );

  box-shadow:
    0 9px 20px rgba(199, 106, 19, .11);
}

.facultyCoverageRequestButton:active:not(:disabled) {
  transform: translateY(0) scale(.98);
}

.facultyCoverageRequestButton:disabled {
  opacity: .55;
  cursor: not-allowed;
}


/* ==========================================================
   EXISTING REQUEST
   ========================================================== */

.facultyCoverageExisting {
  position: relative;
  z-index: 1;

  display: flex;
  align-items: center;
  justify-content: space-between;

  gap: 10px;

  padding: 11px 12px;

  border:
    1px solid
    color-mix(
      in srgb,
      var(--fc-blue) 20%,
      var(--border)
    );

  border-radius: 12px;

  background:
    color-mix(
      in srgb,
      var(--fc-blue) 5%,
      var(--surface)
    );

  color: var(--muted);

  font-size: 10px;
}

.facultyCoverageExisting strong {
  color: var(--text);
}


/* ==========================================================
   REQUESTS
   ========================================================== */

.facultyCoverageRequestList,
.facultyCoverageOfferList {
  display: grid;
  gap: 12px;
}

.facultyCoverageRequestCard,
.facultyCoverageOfferCard {
  position: relative;
  overflow: hidden;

  display: grid;
  gap: 14px;

  padding: 19px;

  border: 1px solid var(--border);
  border-radius: 20px;

  background: var(--card);

  box-shadow:
    0 9px 28px rgba(15, 23, 42, .04);

  transition:
    transform .2s ease,
    border-color .2s ease,
    box-shadow .2s ease;

  animation:
    facultyCoverageCardEnter
    .4s cubic-bezier(.22, 1, .36, 1)
    both;
}

.facultyCoverageRequestCard:hover,
.facultyCoverageOfferCard:hover {
  transform: translateY(-3px);

  border-color:
    color-mix(
      in srgb,
      var(--accent) 20%,
      var(--border)
    );

  box-shadow:
    0 15px 36px rgba(15, 23, 42, .075);
}

.facultyCoverageRequestHeading,
.facultyCoverageOfferHeading {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;

  gap: 15px;
}

.facultyCoverageRequestHeading h3,
.facultyCoverageRequestHeading h4,
.facultyCoverageOfferHeading h3,
.facultyCoverageOfferHeading h4 {
  margin: 0;

  color: var(--text);

  font-size: 16px;
  line-height: 1.25;

  letter-spacing: -.02em;
}

.facultyCoverageRequestHeading p,
.facultyCoverageOfferHeading p {
  margin: 6px 0 0;

  color: var(--muted);

  font-size: 10px;
  line-height: 1.5;
}


/* ==========================================================
   REQUEST METRICS
   ========================================================== */

.facultyCoverageRequestMetrics {
  display: grid;

  grid-template-columns:
    repeat(3, minmax(0, 1fr));

  gap: 8px;
}

.facultyCoverageRequestMetrics > div {
  padding: 10px 11px;

  border: 1px solid var(--border);
  border-radius: 12px;

  background: var(--surface);
}

.facultyCoverageRequestMetrics span {
  display: block;

  margin-bottom: 4px;

  color: var(--muted);

  font-size: 8px;
  font-weight: 850;

  letter-spacing: .05em;
  text-transform: uppercase;
}

.facultyCoverageRequestMetrics strong {
  display: block;

  color: var(--text);

  font-size: 12px;
}


/* ==========================================================
   ASSIGNED SUBSTITUTE
   ========================================================== */

.facultyCoverageAssigned {
  position: relative;

  padding: 13px 14px 13px 17px;

  border:
    1px solid
    color-mix(
      in srgb,
      var(--fc-green) 24%,
      var(--border)
    );

  border-radius: 13px;

  background:
    color-mix(
      in srgb,
      var(--fc-green) 6%,
      var(--surface)
    );
}

.facultyCoverageAssigned::before {
  content: "";

  position: absolute;

  left: 0;
  top: 10px;
  bottom: 10px;

  width: 3px;

  border-radius: 0 5px 5px 0;

  background: var(--fc-green);
}

.facultyCoverageAssigned span {
  display: block;

  margin-bottom: 4px;

  color: var(--fc-green);

  font-size: 8px;
  font-weight: 900;
  letter-spacing: .07em;
  text-transform: uppercase;
}

.facultyCoverageAssigned strong {
  color: var(--text);

  font-size: 12px;
}


/* ==========================================================
   UNCOVERED
   ========================================================== */

.facultyCoverageUncoveredNote {
  padding: 12px 13px;

  border:
    1px solid
    color-mix(
      in srgb,
      var(--fc-amber) 25%,
      var(--border)
    );

  border-radius: 12px;

  background:
    color-mix(
      in srgb,
      var(--fc-amber) 6%,
      var(--surface)
    );

  color: #a84d08;

  font-size: 10px;
  line-height: 1.5;
}

.facultyCoverageRetry {
  min-height: 38px;

  padding: 0 13px;

  border: 1px solid var(--border);
  border-radius: 11px;

  background: var(--surface);
  color: var(--text);

  font: inherit;
  font-size: 10px;
  font-weight: 800;

  cursor: pointer;

  transition:
    transform .18s ease,
    border-color .18s ease;
}

.facultyCoverageRetry:hover:not(:disabled) {
  transform: translateY(-1px);

  border-color:
    color-mix(
      in srgb,
      var(--accent) 35%,
      var(--border)
    );
}


/* ==========================================================
   INCOMING OFFERS
   ========================================================== */

.facultyCoverageOfferCard {
  grid-template-columns: auto 1fr;
}

.facultyCoverageOfferIcon {
  width: 44px;
  height: 44px;

  display: grid;
  place-items: center;

  border:
    1px solid
    color-mix(
      in srgb,
      var(--fc-green) 20%,
      var(--border)
    );

  border-radius: 14px;

  background:
    color-mix(
      in srgb,
      var(--fc-green) 7%,
      var(--surface)
    );

  color: var(--fc-green);

  font-size: 16px;
  font-weight: 900;

  animation:
    facultyCoverageOfferPulse
    2.5s ease-in-out infinite;
}

.facultyCoverageOfferBody {
  min-width: 0;

  display: grid;
  gap: 12px;
}

.facultyCoverageOfferContext {
  display: grid;

  grid-template-columns:
    repeat(3, minmax(0, 1fr));

  gap: 8px;
}

.facultyCoverageOfferContext > div {
  padding: 9px 10px;

  border: 1px solid var(--border);
  border-radius: 11px;

  background: var(--surface);
}

.facultyCoverageOfferContext span,
.facultyCoverageOfferContext small {
  display: block;

  margin-bottom: 4px;

  color: var(--muted);

  font-size: 8px;
  font-weight: 800;
  text-transform: uppercase;
}

.facultyCoverageOfferContext strong {
  display: block;

  overflow: hidden;

  color: var(--text);

  font-size: 11px;

  text-overflow: ellipsis;
  white-space: nowrap;
}


/* ==========================================================
   MATCH REASON
   ========================================================== */

.facultyCoverageMatchReason {
  display: inline-flex;
  align-items: center;
  gap: 7px;

  width: fit-content;

  padding: 6px 9px;

  border-radius: 999px;

  background:
    color-mix(
      in srgb,
      var(--fc-green) 7%,
      var(--surface)
    );

  color: var(--fc-green);

  font-size: 9px;
  font-weight: 800;
}

.facultyCoverageMatchReason::before {
  content: "✓";

  width: 16px;
  height: 16px;

  display: grid;
  place-items: center;

  border-radius: 50%;

  background:
    color-mix(
      in srgb,
      var(--fc-green) 13%,
      transparent
    );

  font-size: 8px;
}


/* ==========================================================
   OFFER ACTIONS
   ========================================================== */

.facultyCoverageOfferActions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.facultyCoverageOfferActions button {
  min-height: 39px;

  padding: 0 15px;

  border-radius: 11px;

  font: inherit;
  font-size: 10px;
  font-weight: 850;

  cursor: pointer;

  transition:
    transform .18s ease,
    box-shadow .18s ease,
    border-color .18s ease;
}

.facultyCoverageOfferActions button.accept,
.facultyCoverageOfferActions .accept {
  border: 1px solid transparent;

  background:
    linear-gradient(
      135deg,
      var(--fc-green),
      #087354
    );

  color: #fff;

  box-shadow:
    0 8px 18px rgba(22, 134, 92, .16);
}

.facultyCoverageOfferActions button.accept:hover:not(:disabled),
.facultyCoverageOfferActions .accept:hover:not(:disabled) {
  transform: translateY(-2px);

  box-shadow:
    0 12px 24px rgba(22, 134, 92, .22);
}

.facultyCoverageOfferActions button.decline,
.facultyCoverageOfferActions .decline {
  border: 1px solid var(--border);

  background: var(--surface);

  color: var(--muted);
}

.facultyCoverageOfferActions button.decline:hover:not(:disabled),
.facultyCoverageOfferActions .decline:hover:not(:disabled) {
  transform: translateY(-2px);

  border-color:
    color-mix(
      in srgb,
      var(--fc-red) 30%,
      var(--border)
    );

  color: var(--fc-red);
}


/* ==========================================================
   EMPTY
   ========================================================== */

.facultyCoverageEmpty {
  display: grid;
  place-items: center;

  min-height: 180px;

  padding: 34px;

  border:
    1px dashed
    color-mix(
      in srgb,
      var(--border) 90%,
      transparent
    );

  border-radius: 20px;

  background:
    color-mix(
      in srgb,
      var(--surface) 55%,
      transparent
    );

  text-align: center;

  color: var(--muted);

  line-height: 1.6;
}

.facultyCoverageEmpty::before {
  content: "✓";

  width: 42px;
  height: 42px;

  display: grid;
  place-items: center;

  margin-bottom: 9px;

  border: 1px solid var(--border);
  border-radius: 14px;

  background: var(--card);

  color: var(--fc-green);

  font-size: 16px;
  font-weight: 900;

  box-shadow:
    0 7px 18px rgba(15, 23, 42, .05);
}


/* ==========================================================
   MODAL
   ========================================================== */

.facultyCoverageModalBackdrop {
  position: fixed;
  z-index: 10000;

  inset: 0;

  display: grid;
  place-items: center;

  padding: 20px;

  background: rgba(15, 23, 42, .46);

  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);

  animation:
    facultyCoverageBackdropIn
    .2s ease both;
}

.facultyCoverageModal {
  width: min(560px, 100%);

  max-height: min(760px, 90vh);
  overflow-y: auto;

  padding: 25px;

  border:
    1px solid
    color-mix(
      in srgb,
      var(--border) 70%,
      transparent
    );

  border-radius: 24px;

  background: var(--card);

  box-shadow:
    0 35px 90px rgba(15, 23, 42, .25);

  animation:
    facultyCoverageModalIn
    .3s cubic-bezier(.22, 1, .36, 1)
    both;
}

.facultyCoverageModal h3 {
  margin: 0;

  color: var(--text);

  font-size: 23px;
  letter-spacing: -.03em;
}

.facultyCoverageModal > p {
  margin: 8px 0 18px;

  color: var(--muted);

  font-size: 12px;
  line-height: 1.6;
}

.facultyCoverageModalClass {
  margin-bottom: 17px;
  padding: 14px;

  border: 1px solid var(--border);
  border-radius: 14px;

  background: var(--surface);
}

.facultyCoverageModalClass span {
  display: block;

  margin-bottom: 5px;

  color: var(--muted);

  font-size: 9px;
  font-weight: 850;
  letter-spacing: .06em;
}

.facultyCoverageModalClass strong {
  display: block;

  color: var(--text);

  font-size: 14px;
}

.facultyCoverageModal textarea {
  width: 100%;
  min-height: 105px;

  resize: vertical;

  padding: 12px 13px;

  border: 1px solid var(--border);
  border-radius: 13px;

  outline: none;

  background: var(--surface);
  color: var(--text);

  font: inherit;
  font-size: 12px;

  transition:
    border-color .18s ease,
    box-shadow .18s ease;
}

.facultyCoverageModal textarea:focus {
  border-color:
    color-mix(
      in srgb,
      var(--accent) 65%,
      var(--border)
    );

  box-shadow:
    0 0 0 4px
    color-mix(
      in srgb,
      var(--accent) 9%,
      transparent
    );
}

.facultyCoverageModalActions {
  display: flex;
  justify-content: flex-end;
  flex-wrap: wrap;

  gap: 9px;

  margin-top: 18px;
}

.facultyCoverageModalActions button {
  min-height: 42px;

  padding: 0 17px;

  border-radius: 12px;

  font: inherit;
  font-size: 11px;
  font-weight: 850;

  cursor: pointer;

  transition:
    transform .18s ease,
    box-shadow .18s ease;
}

.facultyCoverageModalActions .primary {
  border: 0;

  background:
    linear-gradient(
      135deg,
      var(--accent),
      color-mix(
        in srgb,
        var(--accent) 78%,
        #172554
      )
    );

  color: #fff;

  box-shadow:
    0 8px 20px
    color-mix(
      in srgb,
      var(--accent) 20%,
      transparent
    );
}

.facultyCoverageModalActions .secondary {
  border: 1px solid var(--border);

  background: var(--surface);
  color: var(--muted);
}

.facultyCoverageModalActions button:hover:not(:disabled) {
  transform: translateY(-2px);
}


/* ==========================================================
   ANIMATIONS
   ========================================================== */

@keyframes facultyCoverageEnter {
  from {
    opacity: 0;
    transform: translateY(16px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes facultyCoverageCardEnter {
  from {
    opacity: 0;
    transform:
      translateY(14px)
      scale(.985);
  }

  to {
    opacity: 1;
    transform:
      translateY(0)
      scale(1);
  }
}

@keyframes facultyCoverageFloat {
  0%,
  100% {
    transform:
      translateY(0)
      rotate(24deg);
  }

  50% {
    transform:
      translateY(-12px)
      rotate(31deg);
  }
}

@keyframes facultyCoverageOrbit {
  from {
    transform: rotate(0);
  }

  to {
    transform: rotate(360deg);
  }
}

@keyframes facultyCoveragePulse {
  0%,
  100% {
    opacity: .55;
    transform: scale(.85);
  }

  50% {
    opacity: 1;
    transform: scale(1.1);
  }
}

@keyframes facultyCoverageOfferPulse {
  0%,
  100% {
    box-shadow:
      0 0 0 0
      rgba(22, 134, 92, .08);
  }

  50% {
    box-shadow:
      0 0 0 7px
      rgba(22, 134, 92, 0);
  }
}

@keyframes facultyCoverageTabLine {
  from {
    transform: scaleX(0);
  }

  to {
    transform: scaleX(1);
  }
}

@keyframes facultyCoverageBackdropIn {
  from {
    opacity: 0;
  }

  to {
    opacity: 1;
  }
}

@keyframes facultyCoverageModalIn {
  from {
    opacity: 0;

    transform:
      translateY(15px)
      scale(.97);
  }

  to {
    opacity: 1;

    transform:
      translateY(0)
      scale(1);
  }
}


/* ==========================================================
   RESPONSIVE
   ========================================================== */

@media (max-width: 980px) {
  .facultyCoverageHero {
    align-items: flex-start;
    flex-direction: column;
  }

  .facultyCoverageHeroStats {
    width: 100%;
  }

  .facultyCoverageGrid {
    grid-template-columns: 1fr;
  }
}


@media (max-width: 680px) {
  .facultyCoverage {
    margin-top: 20px;
  }

  .facultyCoverageHero {
    min-height: auto;

    padding: 24px 20px;

    border-radius: 22px;
  }

  .facultyCoverageHero h2 {
    font-size: 29px;
  }

  .facultyCoverageHeroStats {
    grid-template-columns:
      repeat(3, minmax(0, 1fr));
  }

  .facultyCoverageHeroStats article,
  .facultyCoverageHeroStats > div {
    min-width: 0;
    padding: 11px 9px;
  }

  .facultyCoverageToolbar {
    align-items: stretch;
    flex-direction: column;
  }

  .facultyCoverageTabs {
    display: grid;

    grid-template-columns:
      repeat(3, minmax(0, 1fr));
  }

  .facultyCoverageTabs button {
    padding: 0 8px;
  }

  .facultyCoverageRefresh {
    width: 100%;
  }

  .facultyCoverageClassMeta,
  .facultyCoverageRequestMetrics,
  .facultyCoverageOfferContext {
    grid-template-columns: 1fr;
  }

  .facultyCoverageOfferCard {
    grid-template-columns: 1fr;
  }

  .facultyCoverageModal {
    padding: 20px;
    border-radius: 20px;
  }
}


/* ==========================================================
   REDUCED MOTION
   ========================================================== */

@media (prefers-reduced-motion: reduce) {
  .facultyCoverage,
  .facultyCoverageClassCard,
  .facultyCoverageRequestCard,
  .facultyCoverageOfferCard,
  .facultyCoverageModalBackdrop,
  .facultyCoverageModal,
  .facultyCoverageHero::before,
  .facultyCoverageHero::after,
  .facultyCoverageHero span::before,
  .facultyCoverageOfferIcon {
    animation: none !important;
  }

  .facultyCoverageClassCard,
  .facultyCoverageRequestCard,
  .facultyCoverageOfferCard,
  .facultyCoverageRequestButton,
  .facultyCoverageRefresh,
  .facultyCoverageTabs button {
    transition-duration: .01ms !important;
  }
}


/* ==========================================================
   END FACULTY COVERAGE — PROFESSIONAL COMMAND CENTER
   ========================================================== */



/* ==========================================================
   CAMPUSCONNECT — ACADEMICS MODULE COLOR IDENTITIES
   Weekly Availability  = Blue
   Date Override        = Amber
   Faculty Coverage     = Sage / Teal
   Official Timetable   = Indigo / Lavender
   ========================================================== */


/* ==========================================================
   01 — WEEKLY AVAILABILITY
   Cool blue / sky professional identity
   ========================================================== */

.facultyAvailabilityBoard {
  position: relative;
  isolation: isolate;
  overflow: hidden;

  border:
    1px solid
    color-mix(
      in srgb,
      #4f7cac 22%,
      var(--border)
    ) !important;

  background:
    radial-gradient(
      circle at 94% 4%,
      rgba(79, 124, 172, .12),
      transparent 26%
    ),
    radial-gradient(
      circle at 4% 100%,
      rgba(126, 166, 203, .07),
      transparent 30%
    ),
    linear-gradient(
      145deg,
      color-mix(
        in srgb,
        #eef6fc 72%,
        var(--card)
      ),
      color-mix(
        in srgb,
        #f8fbfe 82%,
        var(--card)
      )
    ) !important;

  box-shadow:
    0 20px 55px rgba(54, 87, 120, .08),
    inset 0 1px 0 rgba(255, 255, 255, .6);

  transition:
    transform .3s cubic-bezier(.22, 1, .36, 1),
    box-shadow .3s ease,
    border-color .3s ease;
}

.facultyAvailabilityBoard::before {
  content: "";

  position: absolute;
  z-index: -1;

  width: 220px;
  height: 220px;

  right: -125px;
  top: -125px;

  border-radius: 50%;

  border: 32px solid rgba(79, 124, 172, .055);

  animation:
    ccAcademicBlueOrbit
    18s linear infinite;

  pointer-events: none;
}

.facultyAvailabilityBoard::after {
  content: "";

  position: absolute;
  z-index: -1;

  width: 90px;
  height: 90px;

  left: 42%;
  top: -65px;

  border-radius: 30px;

  background:
    rgba(79, 124, 172, .045);

  transform: rotate(32deg);

  animation:
    ccAcademicBlueFloat
    8s ease-in-out infinite;

  pointer-events: none;
}

.facultyAvailabilityBoard:hover {
  border-color:
    color-mix(
      in srgb,
      #4f7cac 34%,
      var(--border)
    ) !important;

  box-shadow:
    0 24px 65px rgba(54, 87, 120, .11),
    inset 0 1px 0 rgba(255, 255, 255, .7);
}

.facultyAvailabilityBoard > header {
  position: relative;
  z-index: 2;

  background:
    linear-gradient(
      90deg,
      rgba(79, 124, 172, .055),
      transparent 58%
    );
}

.facultyAvailabilityBoard > header span {
  color: #416f9d !important;
}

.facultyAvailabilityBoard > header span::before {
  background: #527fa9 !important;

  box-shadow:
    0 0 0 6px
    rgba(82, 127, 169, .10) !important;
}

.facultyAvailabilityBoard > header > strong {
  border:
    1px solid
    rgba(79, 124, 172, .15);

  background:
    rgba(255, 255, 255, .52);

  color: #55728e;
}


/* keep timetable cells readable */

.facultyAvailabilityBoard
.facultyAvailabilityTableWrap {
  position: relative;
  z-index: 2;

  background:
    rgba(255, 255, 255, .22);
}

.facultyAvailabilityBoard
.facultyAvailabilityTable thead th {
  background:
    rgba(232, 242, 250, .68);
}

.facultyAvailabilityBoard
.facultyAvailabilityTable tbody > tr > th {
  background:
    rgba(239, 246, 251, .58);
}


/* ==========================================================
   02 — DATE-SPECIFIC OVERRIDE
   Warm sand / amber identity
   ========================================================== */

.facultyAvailabilityExceptions {
  position: relative;
  isolation: isolate;
