/* ==========================================================
   SHARED PROFESSIONAL HOVER BEHAVIOUR
   ========================================================== */

.facultyAvailabilityBoard,
.facultyAvailabilityExceptions,
.facultyCoverage,
.timetablePdfPanel {
  transform: translateZ(0);
}

.facultyAvailabilityBoard:hover,
.facultyAvailabilityExceptions:hover,
.facultyCoverage:hover,
.timetablePdfPanel:hover {
  transform: translateY(-2px);
}


/* ==========================================================
   AMBIENT ANIMATIONS
   ========================================================== */

@keyframes ccAcademicBlueOrbit {
  from {
    transform: rotate(0deg);
  }

  to {
    transform: rotate(360deg);
  }
}

@keyframes ccAcademicBlueFloat {
  0%,
  100% {
    transform:
      translateY(0)
      rotate(32deg);
  }

  50% {
    transform:
      translateY(14px)
      rotate(39deg);
  }
}

@keyframes ccAcademicAmberOrbit {
  from {
    transform: rotate(360deg);
  }

  to {
    transform: rotate(0deg);
  }
}

@keyframes ccAcademicAmberFloat {
  0%,
  100% {
    transform:
      translateY(0)
      rotate(28deg);
  }

  50% {
    transform:
      translateY(13px)
      rotate(35deg);
  }
}

@keyframes ccAcademicIndigoOrbit {
  from {
    transform: rotate(0deg);
  }

  to {
    transform: rotate(360deg);
  }
}

@keyframes ccAcademicIndigoFloat {
  0%,
  100% {
    transform:
      translateY(0)
      rotate(30deg);
  }

  50% {
    transform:
      translateY(-14px)
      rotate(37deg);
  }
}


/* ==========================================================
   DARK MODE SAFETY
   ========================================================== */

@media (prefers-color-scheme: dark) {
  .facultyAvailabilityBoard {
    background:
      radial-gradient(
        circle at 94% 4%,
        rgba(79, 124, 172, .12),
        transparent 27%
      ),
      var(--card) !important;
  }

  .facultyAvailabilityExceptions {
    background:
      radial-gradient(
        circle at 90% 8%,
        rgba(200, 135, 54, .10),
        transparent 27%
      ),
      var(--card) !important;
  }

  .facultyCoverage {
    background:
      radial-gradient(
        circle at 94% 5%,
        rgba(49, 128, 106, .11),
        transparent 26%
      ),
      var(--card);
  }

  .timetablePdfPanel {
    background:
      radial-gradient(
        circle at 92% 6%,
        rgba(113, 109, 167, .12),
        transparent 27%
      ),
      var(--card) !important;
  }
}


/* ==========================================================
   RESPONSIVE
   ========================================================== */

@media (max-width: 680px) {
  .facultyCoverage {
    padding: 14px;

    border-radius: 22px;
  }

  .facultyAvailabilityBoard,
  .facultyAvailabilityExceptions,
  .timetablePdfPanel {
    border-radius: 22px !important;
  }
}


/* ==========================================================
   ACCESSIBILITY — REDUCED MOTION
   ========================================================== */

@media (prefers-reduced-motion: reduce) {
  .facultyAvailabilityBoard::before,
  .facultyAvailabilityBoard::after,
  .facultyAvailabilityExceptions::before,
  .facultyAvailabilityExceptions::after,
  .timetablePdfPanel::before,
  .timetablePdfPanel::after {
    animation: none !important;
  }

  .facultyAvailabilityBoard,
  .facultyAvailabilityExceptions,
  .facultyCoverage,
  .timetablePdfPanel {
    transition: none !important;
  }

  .facultyAvailabilityBoard:hover,
  .facultyAvailabilityExceptions:hover,
  .facultyCoverage:hover,
  .timetablePdfPanel:hover {
    transform: none;
  }
}


