/* ============================================================
   FACULTY COVERAGE MODAL — OPAQUE PROFESSIONAL SURFACE
   Fixes transparent/glass modal while preserving backdrop blur.
   ============================================================ */

.facultyCoverageModalBackdrop {
  z-index: 10000 !important;

  background:
    rgba(15, 23, 42, 0.62) !important;

  backdrop-filter:
    blur(10px) saturate(0.9) !important;

  -webkit-backdrop-filter:
    blur(10px) saturate(0.9) !important;
}


.facultyCoverageModal {
  position: relative;
  z-index: 10001;

  isolation: isolate;

  /*
   * Intentionally NOT var(--card).
   * The application's card token can contain transparency,
   * which is inappropriate for a dialog surface.
   */
  background: #ffffff !important;

  border:
    1px solid
    rgba(15, 23, 42, 0.10) !important;

  box-shadow:
    0 40px 100px
      rgba(15, 23, 42, 0.34),
    0 12px 35px
      rgba(15, 23, 42, 0.16),
    inset 0 1px 0
      rgba(255, 255, 255, 1) !important;

  opacity: 1 !important;
}


/*
 * Keep every major surface inside the dialog opaque too.
 */

.facultyCoverageModalClass {
  background:
    linear-gradient(
      135deg,
      #f5f8ff 0%,
      #f8faff 100%
    ) !important;

  border-color:
    rgba(37, 99, 235, 0.12) !important;
}


.facultyCoverageModal label {
  display: grid;

  gap: 7px;

  margin-top: 15px;
}


.facultyCoverageModal label > span {
  display: flex;

  align-items: center;

  gap: 7px;

  color: #172033;

  font-size: 12px;

  font-weight: 800;
}


.facultyCoverageModal label > span em {
  color: #7b8496;

  font-size: 10px;

  font-style: normal;

  font-weight: 650;
}


.facultyCoverageModal label > small {
  display: block;

  color: #697386;

  font-size: 10px;

  line-height: 1.55;
}


.facultyCoverageModal input,
.facultyCoverageModal textarea {
  box-sizing: border-box;

  width: 100%;

  border:
    1px solid
    rgba(15, 23, 42, 0.14) !important;

  background: #ffffff !important;

  color: #172033 !important;

  opacity: 1 !important;

  box-shadow:
    inset 0 1px 2px
      rgba(15, 23, 42, 0.025);
}


.facultyCoverageModal input {
  min-height: 44px;

  padding: 0 13px;

  border-radius: 12px;

  font: inherit;

  font-size: 12px;

  outline: none;
}


.facultyCoverageModal textarea {
  min-height: 108px;
}


.facultyCoverageModal input:focus,
.facultyCoverageModal textarea:focus {
  border-color:
    rgba(37, 99, 235, 0.55) !important;

  box-shadow:
    0 0 0 4px
      rgba(37, 99, 235, 0.09) !important;
}


.facultyCoverageModalActions .secondary {
  background: #ffffff !important;

  border-color:
    rgba(15, 23, 42, 0.12) !important;

  color: #475569 !important;
}


/*
 * Header was already present in the component.
 * Give it proper spacing and ensure the close control remains
 * visually separate from the content.
 */

.facultyCoverageModal > header {
  display: flex;

  align-items: flex-start;

  justify-content: space-between;

  gap: 20px;

  margin-bottom: 18px;
}


.facultyCoverageModal > header > div > span {
  display: block;

  margin-bottom: 6px;

  color: #64748b;

  font-size: 9px;

  font-weight: 850;

  letter-spacing: 0.12em;
}


.facultyCoverageModal > header h3 {
  color: #111827 !important;
}


.facultyCoverageModal > header > button {
  flex: 0 0 auto;

  display: grid;

  place-items: center;

  width: 34px;

  height: 34px;

  padding: 0;

  border:
    1px solid
    rgba(15, 23, 42, 0.09);

  border-radius: 10px;

  background: #f8fafc;

  color: #475569;

  font-size: 19px;

  line-height: 1;

  cursor: pointer;

  transition:
    background 0.18s ease,
    color 0.18s ease,
    transform 0.18s ease;
}


.facultyCoverageModal > header > button:hover {
  background: #eef2f7;

  color: #111827;

  transform: rotate(4deg);
}


/*
 * Explicit dark-mode surface.
 * This keeps the dialog opaque in both application themes.
 */

[data-theme="dark"] .facultyCoverageModal,
.dark .facultyCoverageModal {
  background: #111827 !important;

  border-color:
    rgba(255, 255, 255, 0.10) !important;

  box-shadow:
    0 40px 100px
      rgba(0, 0, 0, 0.55),
    0 12px 35px
      rgba(0, 0, 0, 0.30) !important;
}


[data-theme="dark"] .facultyCoverageModalClass,
.dark .facultyCoverageModalClass {
  background:
    linear-gradient(
      135deg,
      #172033,
      #182235
    ) !important;

  border-color:
    rgba(255, 255, 255, 0.08) !important;
}


[data-theme="dark"] .facultyCoverageModal input,
[data-theme="dark"] .facultyCoverageModal textarea,
.dark .facultyCoverageModal input,
.dark .facultyCoverageModal textarea {
  background: #182235 !important;

  border-color:
    rgba(255, 255, 255, 0.11) !important;

  color: #f8fafc !important;
}


[data-theme="dark"] .facultyCoverageModal label > span,
.dark .facultyCoverageModal label > span,
[data-theme="dark"] .facultyCoverageModal > header h3,
.dark .facultyCoverageModal > header h3 {
  color: #f8fafc !important;
}


[data-theme="dark"] .facultyCoverageModalActions .secondary,
.dark .facultyCoverageModalActions .secondary {
  background: #182235 !important;

  border-color:
    rgba(255, 255, 255, 0.10) !important;

  color: #cbd5e1 !important;
}


/* END FACULTY COVERAGE MODAL — OPAQUE PROFESSIONAL SURFACE */


/* ============================================================
