/* ATTENDANCE — ACTIVE SUBJECT SELECTION */

.attendanceBatchSubjectCard {
  position: relative;
  cursor: pointer;
  transition:
    transform 160ms ease,
    border-color 160ms ease,
    box-shadow 160ms ease,
    background 160ms ease;
}

.attendanceBatchSubjectCard:hover {
  transform: translateY(-2px);
  border-color: rgba(37, 99, 235, .24);
  box-shadow:
    0 10px 26px rgba(15, 23, 42, .06);
}

.attendanceBatchSubjectCard:focus-visible {
  outline: 3px solid rgba(37, 99, 235, .16);
  outline-offset: 3px;
}

.attendanceBatchSubjectCard.active {
  border-color: rgba(37, 99, 235, .55);
  background:
    linear-gradient(
      145deg,
      rgba(37, 99, 235, .075),
      rgba(255, 255, 255, .97)
    );
  box-shadow:
    0 14px 34px rgba(37, 99, 235, .09);
}

.attendanceBatchSubjectCard.active::after {
  position: absolute;
  top: 15px;
  right: 15px;

  content: "SELECTED";

  padding: 5px 8px;

  border-radius: 999px;

  background: rgba(37, 99, 235, .1);
  color: #1d4ed8;

  font-size: 8px;
  font-weight: 900;
  letter-spacing: .08em;
}

.attendanceBatchSubjectCard.active::before {
  position: absolute;

  top: 16px;
  bottom: 16px;
  left: 0;

  width: 4px;

  border-radius:
    0 999px 999px 0;

  background: #2563eb;

  content: "";
}

.attendanceBatchSubjectCard.active
  .attendanceBatchSubjectFaculty {
  opacity: 1;
}

@media (max-width: 700px) {
  .attendanceBatchSubjectCard.active::after {
    position: static;

    display: inline-flex;

    margin-top: 10px;
  }
}


/* ============================================================
   FACULTY DIARY
   ============================================================ */

.facultyDiaryPage {
  display: grid;
  gap: 20px;
  width: 100%;
  min-width: 0;
}

.facultyDiaryHero {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;

  padding: 26px 28px;

  border: 1px solid rgba(15, 23, 42, .08);
  border-radius: 22px;

  background:
    linear-gradient(
      135deg,
      rgba(37, 99, 235, .065),
      rgba(255, 255, 255, .98) 56%
    );

  box-shadow:
    0 16px 40px rgba(15, 23, 42, .045);
}

.facultyDiaryEyebrow,
.facultyDiaryHero > div:first-child > span {
  display: block;

  margin-bottom: 7px;

  color: #2563eb;

  font-size: 9px;
  font-weight: 900;
  letter-spacing: .13em;
}

.facultyDiaryHero h1 {
  margin: 0;

  color: var(--text, #142238);

  font-size: clamp(
    26px,
    3vw,
    38px
  );

  line-height: 1.05;
}

.facultyDiaryHero p {
  max-width: 650px;

  margin:
    9px 0 0;

  color: var(--muted, #64748b);

  font-size: 13px;
  line-height: 1.6;
}

.facultyDiaryHeroActions {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 9px;
}

.facultyDiaryHeroActions button,
.facultyDiaryEmpty button {
  min-height: 42px;

  padding:
    0 15px;

  border:
    1px solid rgba(15, 23, 42, .1);
  border-radius: 11px;

  background: #fff;
  color: #182236;

  font: inherit;
  font-size: 12px;
  font-weight: 750;

  cursor: pointer;
}

.facultyDiaryHeroActions button.primary,
.facultyDiaryEmpty button.primary {
  border-color: #2563eb;

  background: #2563eb;
  color: #fff;
}

.facultyDiaryHeroActions button:disabled {
  cursor: wait;
  opacity: .65;
}

.facultyDiaryMetrics {
  display: grid;
  grid-template-columns:
    repeat(
      4,
      minmax(0, 1fr)
    );
  gap: 13px;
}

.facultyDiaryMetrics article {
  min-width: 0;

  padding: 18px 20px;

  border:
    1px solid rgba(15, 23, 42, .075);
  border-radius: 16px;

  background: #fff;
}

.facultyDiaryMetrics span {
  display: block;

  margin-bottom: 12px;

  color: #64748b;

  font-size: 8px;
  font-weight: 900;
  letter-spacing: .12em;
}

.facultyDiaryMetrics strong {
  display: block;

  color: #172238;

  font-size: 27px;
  line-height: 1;
}

.facultyDiaryMetrics small {
  display: block;

  margin-top: 8px;

  color: #94a3b8;

  font-size: 10px;
}

.facultyDiaryFilters {
  display: grid;
  grid-template-columns:
    minmax(240px, 1.6fr)
    minmax(145px, .8fr)
    minmax(180px, 1fr)
    minmax(180px, 1fr)
    minmax(170px, .9fr)
    auto;

  align-items: end;

  gap: 11px;

  padding: 17px;

  border:
    1px solid rgba(15, 23, 42, .075);
  border-radius: 16px;

  background: #fff;
}

.facultyDiaryFilters label {
  display: grid;
  gap: 6px;

  min-width: 0;
}

.facultyDiaryFilters label > span {
  color: #64748b;

  font-size: 8px;
  font-weight: 900;
  letter-spacing: .1em;
}

.facultyDiaryFilters input,
.facultyDiaryFilters select {
  width: 100%;
  min-width: 0;
  min-height: 42px;

  padding:
    0 12px;

  border:
    1px solid rgba(15, 23, 42, .11);
  border-radius: 10px;

  background: #fff;
  color: #172238;

  font: inherit;
  font-size: 12px;

  outline: none;
}

.facultyDiaryFilters input:focus,
.facultyDiaryFilters select:focus {
  border-color:
    rgba(37, 99, 235, .4);

