    0 0 0 3px
    rgba(37, 99, 235, .07);
}

.facultyDiaryClear {
  min-height: 42px;

  padding:
    0 13px;

  border:
    1px solid rgba(15, 23, 42, .09);
  border-radius: 10px;

  background:
    #f8fafc;

  color: #475569;

  font: inherit;
  font-size: 11px;
  font-weight: 750;

  cursor: pointer;
}

.facultyDiaryResultsHead {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 16px;

  padding:
    0 3px;
}

.facultyDiaryResultsHead > div {
  display: grid;
  gap: 4px;
}

.facultyDiaryResultsHead span {
  color: #2563eb;

  font-size: 8px;
  font-weight: 900;
  letter-spacing: .12em;
}

.facultyDiaryResultsHead strong {
  color: #172238;

  font-size: 17px;
}

.facultyDiaryResultsHead small {
  color: #94a3b8;

  font-size: 10px;
}

.facultyDiaryResultsHead small b {
  color: #475569;
}

.facultyDiaryTimeline {
  display: grid;
  gap: 13px;
}

.facultyDiaryCard {
