  color: #64748b;

  font-size: 9px;
  font-weight: 850;
  letter-spacing: .1em;
}

.facultyDiaryCardBody {
  display: grid;
  gap: 15px;

  min-width: 0;

  padding: 20px 22px;
}

.facultyDiaryCardBody > header {
  display: flex;
