  justify-content: space-between;
  gap: 20px;
}

.facultyDiarySubjectLine {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 9px;
}

.facultyDiarySubjectLine > span {
  padding:
    5px 7px;

  border-radius: 7px;

  background:
    rgba(37, 99, 235, .08);

  color: #1d4ed8;

  font-size: 9px;
  font-weight: 900;
  letter-spacing: .06em;
}

.facultyDiarySubjectLine h2 {
  margin: 0;

  color: #172238;

  font-size: 18px;
}

.facultyDiaryCardBody header p {
  margin:
    7px 0 0;

  color: #64748b;

  font-size: 11px;
}

.facultyDiarySource {
  flex: 0 0 auto;

  padding:
    6px 9px;

  border-radius: 999px;

  background:
