  color: #64748b;

  font-size: 8px;
  font-weight: 900;
  letter-spacing: .05em;
  text-transform: uppercase;
}

.facultyDiarySource.published {
  background:
    rgba(37, 99, 235, .09);

  color: #1d4ed8;
}

.facultyDiaryTopic {
  display: grid;
  gap: 5px;

  padding:
    13px 15px;

  border:
    1px solid rgba(15, 23, 42, .06);
  border-radius: 11px;

  background:
    #f8fafc;
}

.facultyDiaryTopic span {
  color: #64748b;

  font-size: 8px;
  font-weight: 900;
  letter-spacing: .09em;
}

.facultyDiaryTopic strong {
  color: #243147;

  font-size: 13px;
  font-weight: 700;
}

.facultyDiaryAttendance {
  display: grid;
  grid-template-columns:
    repeat(
      5,
      minmax(0, 1fr)
    );
  gap: 8px;
}

.facultyDiaryAttendance > div {
  display: grid;
  gap: 4px;

  padding:
    10px 11px;

  border:
    1px solid rgba(15, 23, 42, .06);
  border-radius: 10px;

  background: #f8fafc;
}

.facultyDiaryAttendance strong {
  color: #172238;

  font-size: 16px;
}

.facultyDiaryAttendance span {
  color: #64748b;

  font-size: 9px;
}

.facultyDiaryAttendance .present {
  background:
    rgba(16, 185, 129, .055);
}

.facultyDiaryAttendance .present strong {
  color: #047857;
}

.facultyDiaryAttendance .absent {
  background:
    rgba(239, 68, 68, .05);
}

.facultyDiaryAttendance .absent strong {
  color: #dc2626;
}

.facultyDiaryAttendance .late {
  background:
    rgba(245, 158, 11, .06);
}

.facultyDiaryAttendance .late strong {
  color: #b45309;
}

.facultyDiaryAttendance .excused {
  background:
    rgba(100, 116, 139, .06);
}

.facultyDiaryRate {
  background:
    rgba(37, 99, 235, .055)
