}

.facultyDiaryRate strong {
  color: #1d4ed8
    !important;
}

.facultyDiaryCardBody > footer {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 7px 16px;

  padding-top: 3px;
}

.facultyDiaryCardBody > footer span {
  color: #94a3b8;

  font-size: 9px;
}

.facultyDiaryEmpty,
.facultyDiaryLoading {
  display: grid;
  place-items: center;
  gap: 8px;

  min-height: 300px;

  padding: 45px;

  border:
    1px solid rgba(15, 23, 42, .075);
  border-radius: 18px;

  background: #fff;

  text-align: center;
}

.facultyDiaryEmpty > span {
  display: grid;
  place-items: center;

  width: 48px;
  height: 48px;

  border-radius: 14px;

  background:
    rgba(37, 99, 235, .07);

  color: #2563eb;

  font-size: 20px;
}

.facultyDiaryEmpty h2 {
  margin: 3px 0 0;

  color: #172238;

  font-size: 19px;
}

.facultyDiaryEmpty p {
  max-width: 520px;

  margin: 0;

  color: #64748b;

  font-size: 12px;
  line-height: 1.6;
}

.facultyDiaryLoading span {
  color: #2563eb;

  font-size: 9px;
  font-weight: 900;
  letter-spacing: .12em;
}

.facultyDiaryLoading strong {
  color: #172238;
}

.facultyDiaryError {
  padding:
    12px 15px;

  border:
    1px solid rgba(220, 38, 38, .12);
  border-radius: 11px;

  background:
    rgba(220, 38, 38, .045);

  color: #b91c1c;

  font-size: 11px;
}


@media (
  max-width: 1100px
) {

  .facultyDiaryMetrics {
    grid-template-columns:
      repeat(
        2,
        minmax(0, 1fr)
      );
  }

  .facultyDiaryFilters {
    grid-template-columns:
      repeat(
        2,
        minmax(0, 1fr)
      );
  }

  .facultyDiarySearch {
    grid-column:
      1 / -1;
  }

}


@media (
  max-width: 700px
) {

  .facultyDiaryHero {
    align-items:
      flex-start;

    flex-direction:
      column;
  }

  .facultyDiaryHeroActions {
    width: 100%;
  }

  .facultyDiaryHeroActions button {
    flex:
      1 1 auto;
  }

  .facultyDiaryMetrics {
    grid-template-columns:
      1fr 1fr;
  }

  .facultyDiaryFilters {
    grid-template-columns:
      1fr;
  }

  .facultyDiarySearch {
    grid-column: auto;
  }

  .facultyDiaryCard {
    grid-template-columns:
      1fr;
  }

  .facultyDiaryDate {
    display: flex;
    justify-content:
      flex-start;
    gap: 5px;

    min-height: auto;

    padding:
      10px 16px;

    border-right: 0;
    border-bottom:
      1px solid
      rgba(15, 23, 42, .07);
  }

  .facultyDiaryDate strong {
    font-size: 15px;
  }

  .facultyDiaryCardBody > header {
    flex-direction:
      column;
  }

  .facultyDiaryAttendance {
    grid-template-columns:
      repeat(
        2,
        minmax(0, 1fr)
      );
  }

  .facultyDiaryRate {
    grid-column:
      1 / -1;
  }

  .facultyDiaryResultsHead {
    align-items:
      flex-start;

    flex-direction:
      column;
  }

}


/* ============================================================
   FACULTY DIARY — MONTHLY REPORT
   ============================================================ */

.facultyDiaryMonthlyReport {
