  gap: 4px;
}

.facultyDiaryMonthlyReport > header span {
  color: #2563eb;

  font-size: 8px;
  font-weight: 900;
  letter-spacing: .11em;
}

.facultyDiaryMonthlyReport h2 {
  margin: 0;

  color: #172238;

  font-size: 21px;
}

.facultyDiaryMonthlyReport > header p {
  margin: 2px 0 0;

  color: #64748b;

  font-size: 11px;
}

.facultyDiaryMonthlyActions {
  display: flex;
  align-items: flex-end;
  gap: 9px;
}

.facultyDiaryMonthlyActions label {
