/* ============================================================
   FACULTY DIARY — PRINT REPORT
   ============================================================ */

.facultyDiaryPrintReport {
  display: none;
}


@media (max-width: 700px) {

  .facultyDiaryMonthlyReport > header,
  .facultyDiaryMonthlyActions {
    align-items: stretch;
    flex-direction: column;
  }

  .facultyDiaryMonthlyStats,
  .facultyDiaryMonthlyDistribution {
    grid-template-columns:
      1fr 1fr;
  }

  .facultyDiaryMonthlySubjects > div {
    grid-template-columns:
      minmax(0, 1fr)
      65px
      65px;
  }

}


@media print {

  @page {
    size: A4 portrait;
    margin: 12mm;
  }

  body {
    background: #fff !important;
  }

  body * {
    visibility: hidden !important;
  }

  .facultyDiaryPrintReport,
  .facultyDiaryPrintReport * {
    visibility: visible !important;
  }

  .facultyDiaryPrintReport {
    position: absolute;
    top: 0;
    left: 0;

    display: block;

    width: 100%;

    background: #fff;

    color: #111827;
  }

  .facultyDiaryPrintReport > header {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;

    gap: 20px;

    padding-bottom: 14px;

    border-bottom:
      2px solid #111827;
  }

  .facultyDiaryPrintReport > header span {
    display: block;

    font-size: 9px;
    font-weight: 700;
    letter-spacing: .08em;
  }

  .facultyDiaryPrintReport > header h1 {
    margin:
      4px 0;

    font-size: 24px;
  }

  .facultyDiaryPrintReport > header p {
    margin: 0;

    font-size: 11px;
  }

  .facultyDiaryPrintReport > header > div:last-child {
    text-align: right;
  }

  .facultyDiaryPrintReport > header > div:last-child strong {
    display: block;

    font-size: 13px;
  }

  .facultyDiaryPrintFaculty {
    display: grid;
    grid-template-columns:
      repeat(
        4,
        minmax(0, 1fr)
      );

    gap: 8px;

    margin-top: 14px;
  }

  .facultyDiaryPrintFaculty > div,
  .facultyDiaryPrintSummary > div {
    padding: 8px;

    border:
      1px solid #cbd5e1;
  }

  .facultyDiaryPrintFaculty span,
  .facultyDiaryPrintSummary span {
    display: block;

    font-size: 7px;
    font-weight: 700;
    letter-spacing: .06em;
  }

  .facultyDiaryPrintFaculty strong,
  .facultyDiaryPrintSummary strong {
    display: block;

    margin-top: 3px;

    font-size: 10px;
  }

  .facultyDiaryPrintSummary {
    display: grid;
    grid-template-columns:
      repeat(
        5,
        minmax(0, 1fr)
      );

    gap: 6px;

    margin:
      10px 0 14px;
  }

  .facultyDiaryPrintTable {
    width: 100%;

    border-collapse:
      collapse;

    table-layout:
      fixed;

    font-size: 7.5px;
  }

  .facultyDiaryPrintTable th,
  .facultyDiaryPrintTable td {
    padding:
      6px 5px;

    border:
      1px solid #94a3b8;

    vertical-align: top;

    text-align: left;
  }

  .facultyDiaryPrintTable th {
    background:
      #f1f5f9 !important;

    font-size: 7px;
    font-weight: 800;

    print-color-adjust: exact;
    -webkit-print-color-adjust: exact;
  }

  .facultyDiaryPrintTable th:nth-child(1) {
    width: 10%;
  }

  .facultyDiaryPrintTable th:nth-child(2) {
    width: 18%;
  }

  .facultyDiaryPrintTable th:nth-child(3) {
    width: 13%;
  }

  .facultyDiaryPrintTable th:nth-child(4) {
    width: 7%;
  }

  .facultyDiaryPrintTable th:nth-child(5) {
    width: 32%;
  }

  .facultyDiaryPrintTable th:nth-child(n+6) {
    width: 5%;
    text-align: center;
  }

  .facultyDiaryPrintTable td:nth-child(n+6) {
    text-align: center;
  }

  .facultyDiaryPrintTable tr {
    break-inside: avoid;
  }

  .facultyDiaryPrintReport > footer {
    display: grid;
    grid-template-columns:
      1fr 1fr;

    gap: 70px;

    margin-top: 32px;
  }

  .facultyDiaryPrintReport > footer > div {
    padding-top: 24px;

    border-top:
      1px solid #111827;

    text-align: center;

    font-size: 8px;
  }

}


/* ============================================================
   ATTENDANCE — SYLLABUS TOPIC SELECTOR
   ============================================================ */

.attendanceSyllabusTopicSelector {
  display: grid;
  gap: 6px;

  grid-column:
    1 / -1;

  padding: 12px;

  border:
    1px solid
    rgba(37, 99, 235, .12);

  border-radius: 11px;

  background:
    linear-gradient(
      135deg,
      rgba(37, 99, 235, .045),
      rgba(255, 255, 255, .98)
    );
}


.attendanceSyllabusTopicSelector > span {
  color: #2563eb !important;

  font-size: 8px !important;
  font-weight: 900 !important;
  letter-spacing: .1em;
}


.attendanceSyllabusTopicSelector select {
  width: 100%;
  min-height: 42px;

  padding:
    0 11px;

  border:
    1px solid
    rgba(15, 23, 42, .11);

  border-radius: 9px;

  background: #fff;
  color: #172238;

  font: inherit;
  font-size: 12px;

  outline: none;
}


.attendanceSyllabusTopicSelector select:focus {
  border-color:
    rgba(37, 99, 235, .42);

  box-shadow:
    0 0 0 3px
    rgba(37, 99, 235, .07);
}


.attendanceSyllabusTopicSelector select:disabled {
