  opacity: .65;
}


.attendanceSyllabusTopicSelector small {
  color: #64748b;

  font-size: 9px;
  line-height: 1.45;
}


.attendanceSyllabusLinked {
  display: inline-flex;

  width: fit-content;

  margin-top: 5px;

  padding:
    4px 7px;

  border-radius: 999px;

