    grid-column: auto;
  }

}


/* ============================================================
   FACULTY — SYLLABUS PROGRESS
   ============================================================ */

.facultySyllabusShell {
  display: grid;
  gap: 16px;
  width: 100%;
}

.facultySyllabusHero {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 22px;

  padding: 24px;

  border: 1px solid rgba(15, 23, 42, .07);
  border-radius: 20px;

  background:
    linear-gradient(
      135deg,
      rgba(37, 99, 235, .07),
      rgba(255, 255, 255, .98) 48%,
      rgba(14, 165, 233, .045)
    );
}

.facultySyllabusHero > div:first-child {
  max-width: 720px;
}

.facultySyllabusHero span {
  color: #2563eb;
  font-size: 9px;
  font-weight: 900;
  letter-spacing: .11em;
}

.facultySyllabusHero h1 {
  margin: 6px 0;
  color: #172238;
  font-size: clamp(24px, 3vw, 34px);
}

.facultySyllabusHero p {
  margin: 0;
  color: #64748b;
  font-size: 12px;
  line-height: 1.65;
}

.facultySyllabusHeroActions {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.facultySyllabusHeroActions button,
.facultySyllabusToolbar button,
.facultySyllabusEditor button,
.facultySyllabusEmpty button {
  min-height: 39px;
  padding: 0 13px;

  border: 1px solid rgba(15, 23, 42, .1);
  border-radius: 9px;

  background: #fff;
  color: #334155;

  font: inherit;
  font-size: 10px;
  font-weight: 800;

  cursor: pointer;
}

.facultySyllabusHeroActions button.primary,
.facultySyllabusEditor button.primary {
  border-color: #2563eb;
  background: #2563eb;
  color: #fff;
}

.facultySyllabusStatus {
  padding: 10px 13px;

  border: 1px solid rgba(37, 99, 235, .1);
  border-radius: 10px;

  background: rgba(37, 99, 235, .045);
  color: #1d4ed8;

  font-size: 10px;
  font-weight: 700;
}

.facultySyllabusSubjectStrip {
  display: grid;
  grid-template-columns:
    repeat(
      auto-fit,
      minmax(220px, 1fr)
    );
  gap: 9px;
}

.facultySyllabusSubjectStrip > button {
  display: grid;
  grid-template-columns:
    minmax(0, 1fr) auto;
  align-items: center;
  gap: 12px;

  padding: 14px;

  border: 1px solid rgba(15, 23, 42, .08);
  border-radius: 13px;

  background: #fff;
  text-align: left;

  cursor: pointer;
  transition: .16s ease;
}

.facultySyllabusSubjectStrip > button:hover {
  transform: translateY(-1px);
  border-color: rgba(37, 99, 235, .25);
}

.facultySyllabusSubjectStrip > button.active {
  border-color: rgba(37, 99, 235, .45);

  box-shadow:
    0 0 0 3px rgba(37, 99, 235, .055);

  background:
    linear-gradient(
      135deg,
      rgba(37, 99, 235, .055),
      #fff
    );
}

.facultySyllabusSubjectStrip > button > div:first-child {
  display: grid;
  gap: 3px;
}

.facultySyllabusSubjectStrip span {
  color: #2563eb;
  font-size: 8px;
  font-weight: 900;
  letter-spacing: .08em;
}

.facultySyllabusSubjectStrip strong {
  overflow: hidden;
  color: #172238;
  font-size: 11px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.facultySyllabusSubjectStrip small {
  color: #94a3b8;
  font-size: 8px;
}

.facultySyllabusSubjectProgress {
  display: grid;
  gap: 5px;
  min-width: 58px;
  text-align: right;
}

.facultySyllabusSubjectProgress b {
  color: #172238;
  font-size: 12px;
}

.facultySyllabusSubjectProgress i {
  display: block;
  overflow: hidden;

  width: 58px;
  height: 4px;

  border-radius: 999px;
  background: #e2e8f0;
}

.facultySyllabusSubjectProgress i span {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: #2563eb;
}

.facultySyllabusOverview {
  position: relative;
  overflow: hidden;

  display: grid;
  grid-template-columns:
    minmax(220px, 1fr)
    minmax(360px, 1.4fr);
  gap: 18px;

  padding: 20px;

  border: 1px solid rgba(15, 23, 42, .07);
  border-radius: 17px;

  background: #fff;
}

.facultySyllabusOverview > div:first-child > span {
  color: #2563eb;
  font-size: 9px;
  font-weight: 900;
  letter-spacing: .08em;
}

.facultySyllabusOverview h2 {
  margin: 5px 0 4px;
  color: #172238;
  font-size: 19px;
}

.facultySyllabusOverview p {
  margin: 0;
  color: #64748b;
  font-size: 10px;
}

.facultySyllabusMetrics {
  display: grid;
  grid-template-columns:
    repeat(
      4,
      minmax(0, 1fr)
    );
  gap: 7px;
}

.facultySyllabusMetrics article {
  padding: 11px;

  border: 1px solid rgba(15, 23, 42, .055);
  border-radius: 10px;

  background: #f8fafc;
}

.facultySyllabusMetrics span {
  display: block;
  color: #94a3b8;
  font-size: 7px;
  font-weight: 900;
  letter-spacing: .07em;
}

.facultySyllabusMetrics strong {
  display: block;
  margin-top: 6px;

  color: #172238;
  font-size: 16px;
}

.facultySyllabusOverallBar {
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;

  height: 4px;
  background: #e2e8f0;
}

.facultySyllabusOverallBar span {
  display: block;
  height: 100%;
  background: #2563eb;
}

.facultySyllabusToolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;

  padding: 15px 17px;

  border: 1px solid rgba(15, 23, 42, .065);
  border-radius: 13px;

  background: #fff;
}

.facultySyllabusToolbar > div {
  display: grid;
  gap: 2px;
}

.facultySyllabusToolbar strong {
  color: #172238;
  font-size: 12px;
}

.facultySyllabusToolbar small {
  color: #64748b;
  font-size: 9px;
}

.facultySyllabusToolbar button {
  border-color: rgba(37, 99, 235, .2);
  background: rgba(37, 99, 235, .07);
  color: #1d4ed8;
}

.facultySyllabusEditor {
  padding: 17px;

  border: 1px solid rgba(37, 99, 235, .14);
  border-radius: 15px;

  background:
    linear-gradient(
      135deg,
      rgba(37, 99, 235, .035),
      #fff
    );
}

.facultySyllabusEditor > header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 15px;
}

.facultySyllabusEditor > header span {
  color: #2563eb;
  font-size: 8px;
  font-weight: 900;
  letter-spacing: .09em;
}

.facultySyllabusEditor h3 {
  margin: 3px 0 0;
  color: #172238;
  font-size: 15px;
}

.facultySyllabusEditor > header > button {
  width: 31px;
  min-height: 31px;
  padding: 0;
  font-size: 17px;
}

.facultySyllabusEditorGrid {
  display: grid;
  grid-template-columns:
    repeat(
      2,
      minmax(0, 1fr)
    );
  gap: 11px;

  margin-top: 14px;
}

.facultySyllabusEditorGrid label {
  display: grid;
  gap: 5px;
}

.facultySyllabusEditorGrid label.wide {
  grid-column: 1 / -1;
}

.facultySyllabusEditorGrid label > span {
  color: #64748b;
  font-size: 8px;
  font-weight: 900;
  letter-spacing: .07em;
}

.facultySyllabusEditorGrid input,
.facultySyllabusEditorGrid select,
.facultySyllabusEditorGrid textarea {
  width: 100%;
  box-sizing: border-box;

  border: 1px solid rgba(15, 23, 42, .1);
  border-radius: 9px;

  background: #fff;
  color: #172238;

  font: inherit;
  font-size: 11px;

  outline: none;
}

.facultySyllabusEditorGrid input,
.facultySyllabusEditorGrid select {
  min-height: 40px;
  padding: 0 10px;
}

.facultySyllabusEditorGrid textarea {
  min-height: 72px;
  padding: 10px;
  resize: vertical;
}

.facultySyllabusEditorGrid small {
  color: #64748b;
  font-size: 8px;
  line-height: 1.5;
}

.facultySyllabusEditor > footer {
  display: flex;
  justify-content: flex-end;
  gap: 8px;

  margin-top: 13px;
}

.facultySyllabusUnits {
  display: grid;
  gap: 12px;
}

.facultySyllabusUnitCard {
  overflow: hidden;

  border: 1px solid rgba(15, 23, 42, .07);
  border-radius: 15px;

  background: #fff;
}

.facultySyllabusUnitCard > header {
  display: grid;
  grid-template-columns:
    38px
    minmax(0, 1fr)
    145px
    auto;
  align-items: center;
  gap: 13px;

  padding: 14px 15px;

  background: #f8fafc;
}

.facultySyllabusUnitNumber {
  display: grid;
  place-items: center;

  width: 36px;
  height: 36px;

  border-radius: 10px;

  background: rgba(37, 99, 235, .09);
  color: #1d4ed8;

  font-size: 13px;
  font-weight: 900;
}

.facultySyllabusUnitTitle > span {
  color: #2563eb;
  font-size: 7px;
  font-weight: 900;
  letter-spacing: .08em;
}

.facultySyllabusUnitTitle h3 {
  margin: 2px 0;
  color: #172238;
  font-size: 13px;
}

.facultySyllabusUnitTitle p {
  margin: 0;
  color: #64748b;
  font-size: 9px;
}

.facultySyllabusUnitProgress {
  display: grid;
  gap: 3px;
}

.facultySyllabusUnitProgress strong {
  color: #172238;
  font-size: 14px;
}

.facultySyllabusUnitProgress small {
  color: #64748b;
  font-size: 8px;
}

.facultySyllabusUnitProgress i {
  display: block;
  overflow: hidden;

  height: 5px;
  border-radius: 999px;
  background: #e2e8f0;
}

.facultySyllabusUnitProgress i span {
  display: block;
  height: 100%;
  background: #2563eb;
}

.facultySyllabusUnitActions,
.facultySyllabusTopicActions {
  display: flex;
  gap: 5px;
}

.facultySyllabusUnitActions button,
.facultySyllabusTopicActions button {
  min-height: 31px;
  padding: 0 9px;

  border: 1px solid rgba(15, 23, 42, .09);
  border-radius: 7px;

  background: #fff;
  color: #475569;

  font: inherit;
  font-size: 8px;
  font-weight: 800;

  cursor: pointer;
}

.facultySyllabusUnitActions button.danger,
.facultySyllabusTopicActions button.danger {
  color: #b91c1c;
}

.facultySyllabusTopicList {
  display: grid;
}

.facultySyllabusTopicRow {
  display: grid;
  grid-template-columns:
    32px
    minmax(0, 1fr)
    125px
    90px
    auto;
  align-items: center;
  gap: 11px;

  padding: 12px 15px;

  border-top: 1px solid rgba(15, 23, 42, .055);
}

.facultySyllabusTopicRow.completed {
  background: rgba(16, 185, 129, .025);
}

.facultySyllabusTopicRow.inProgress {
  background: rgba(37, 99, 235, .018);
}

.facultySyllabusTopicState {
  display: grid;
  place-items: center;
}

.facultySyllabusTopicState span {
  display: grid;
  place-items: center;

  width: 25px;
  height: 25px;

  border-radius: 999px;

  background: #f1f5f9;
  color: #64748b;

  font-size: 10px;
  font-weight: 900;
}

.facultySyllabusTopicRow.completed
.facultySyllabusTopicState span {
  background: rgba(16, 185, 129, .1);
  color: #047857;
}

.facultySyllabusTopicRow.inProgress
.facultySyllabusTopicState span {
  background: rgba(37, 99, 235, .1);
  color: #1d4ed8;
}

.facultySyllabusTopicInfo {
  min-width: 0;
}

.facultySyllabusTopicInfo > div:first-child {
  display: grid;
  gap: 2px;
}

.facultySyllabusTopicInfo > div:first-child span {
  color: #94a3b8;
  font-size: 7px;
  font-weight: 900;
  letter-spacing: .06em;
}

.facultySyllabusTopicInfo strong {
  color: #172238;
  font-size: 11px;
}

.facultySyllabusTopicInfo p {
  margin: 4px 0 0;

  color: #64748b;
  font-size: 8px;
  line-height: 1.45;
}

.facultySyllabusTopicBar {
  display: flex;
  align-items: center;
  gap: 7px;

  margin-top: 7px;
}

.facultySyllabusTopicBar i {
  display: block;
  overflow: hidden;

  width: min(220px, 80%);
  height: 4px;

  border-radius: 999px;
  background: #e2e8f0;
}

.facultySyllabusTopicBar i span {
  display: block;
  height: 100%;
  background: #2563eb;
}

.facultySyllabusTopicRow.completed
.facultySyllabusTopicBar i span {
  background: #059669;
}

.facultySyllabusTopicBar b {
  color: #64748b;
  font-size: 8px;
}

.facultySyllabusTopicCoverage {
  display: grid;
  gap: 2px;
}

.facultySyllabusTopicCoverage strong {
  color: #172238;
  font-size: 12px;
}

.facultySyllabusTopicCoverage span,
.facultySyllabusTopicCoverage small {
  color: #64748b;
  font-size: 7px;
}

.facultySyllabusTopicStatus span {
  display: inline-flex;
  justify-content: center;

  min-width: 72px;
  padding: 5px 7px;

  border-radius: 999px;

  font-size: 7px;
  font-weight: 900;
  letter-spacing: .04em;
}

.facultySyllabusTopicStatus span.pending {
  background: #f1f5f9;
  color: #64748b;
}

.facultySyllabusTopicStatus span.progress {
  background: rgba(37, 99, 235, .09);
  color: #1d4ed8;
}

.facultySyllabusTopicStatus span.complete {
  background: rgba(16, 185, 129, .1);
  color: #047857;
}

.facultySyllabusUnitEmpty {
  padding: 17px;

  color: #64748b;
  font-size: 9px;
  text-align: center;
}

.facultySyllabusEmpty,
.facultySyllabusLoading {
  display: grid;
  justify-items: center;
  gap: 6px;

  padding: 34px 20px;

  border: 1px dashed rgba(15, 23, 42, .13);
  border-radius: 14px;

  background: #fff;

  text-align: center;
}

.facultySyllabusEmpty strong {
  color: #172238;
  font-size: 13px;
}

.facultySyllabusEmpty p,
.facultySyllabusLoading {
  color: #64748b;
  font-size: 10px;
}

.facultySyllabusEmpty p {
  margin: 0;
}

.facultySyllabusEmpty button {
  margin-top: 6px;

  border-color: rgba(37, 99, 235, .2);
  background: rgba(37, 99, 235, .07);
  color: #1d4ed8;
}


@media (max-width: 900px) {

  .facultySyllabusHero,
  .facultySyllabusToolbar {
    align-items: stretch;
    flex-direction: column;
  }

  .facultySyllabusOverview {
    grid-template-columns: 1fr;
  }

  .facultySyllabusUnitCard > header {
    grid-template-columns:
      38px
      minmax(0, 1fr);
  }

  .facultySyllabusUnitProgress,
  .facultySyllabusUnitActions {
    grid-column: 2;
  }

  .facultySyllabusTopicRow {
    grid-template-columns:
      30px
      minmax(0, 1fr)
      auto;
  }

  .facultySyllabusTopicCoverage {
    grid-column: 2;
  }

  .facultySyllabusTopicStatus {
    grid-column: 3;
    grid-row: 1;
  }

  .facultySyllabusTopicActions {
    grid-column: 2 / -1;
  }

}


@media (max-width: 620px) {

  .facultySyllabusHero {
    padding: 17px;
  }

  .facultySyllabusMetrics {
    grid-template-columns:
      1fr 1fr;
  }

  .facultySyllabusEditorGrid {
    grid-template-columns: 1fr;
  }

  .facultySyllabusEditorGrid label.wide {
    grid-column: auto;
  }

  .facultySyllabusTopicRow {
    grid-template-columns:
      28px
      minmax(0, 1fr);
  }

  .facultySyllabusTopicStatus,
  .facultySyllabusTopicCoverage,
  .facultySyllabusTopicActions {
    grid-column: 2;
    grid-row: auto;
  }

}


