/* ============================================================
   ATTENDANCE SESSION — VIEWPORT / ROSTER SCROLL FIX
   ============================================================ */

/*
 * Keep the attendance dialog inside the visible viewport.
 * Student rows already exist in the DOM; previously the lower
 * portion of the dialog could extend below the screen.
 */
.attendanceSessionScrim {
  overflow-y: auto;
  overscroll-behavior: contain;
}


/*
 * The entire Attendance session becomes vertically scrollable.
 * 100dvh handles modern browsers/mobile viewport changes more
 * reliably than a fixed pixel/modal height.
 */
.attendanceSessionModal {
  max-height:
    calc(100dvh - 44px) !important;

  overflow-x: hidden !important;
  overflow-y: auto !important;

  overscroll-behavior:
    contain;

  scrollbar-gutter:
    stable;
}


/*
 * Keep the class identity visible while Faculty scroll through
 * the roster.
 */
.attendanceSessionModalHeader {
  position: sticky;
  top: 0;
  z-index: 20;

  background: #fff;
}


/*
 * Make sure the actual student roster is allowed to expand.
 * Do not constrain it to the remaining visible viewport.
 */
.attendanceSessionRoster {
  min-height: 0;
  overflow: visible;
}


/*
 * Keep Save / Cancel reachable even with a long class roster.
 */
.attendanceSessionFooter {
  position: sticky;
  bottom: 0;
  z-index: 20;

  background: #fff;

  box-shadow:
    0 -8px 24px
    rgba(15, 23, 42, .045);
}


/* Smaller laptop / tablet screens */
@media (max-height: 800px) {

  .attendanceSessionModal {
    max-height:
      calc(100dvh - 24px) !important;
  }

}


/* Mobile */
@media (max-width: 700px) {

  .attendanceSessionScrim {
    padding: 10px;
  }


  .attendanceSessionModal {
    max-height:
      calc(100dvh - 20px) !important;
  }

}


