   - first student hidden behind sticky footer
   - grey backdrop should scroll
   - footer text should not overlap
   ============================================================ */

.attendanceSessionScrim {
  align-items: flex-start;
  overflow-y: auto;
  overscroll-behavior: contain;
  padding: 24px 20px;
}

.attendanceSessionModal {
  display: flex;
  flex-direction: column;
  width: min(1150px, calc(100vw - 40px));
  max-height: calc(100vh - 48px);
  margin: auto;
  overflow: hidden !important;
}

.attendanceSessionModalHeader {
  position: sticky;
  top: 0;
  z-index: 8;
  background: #fff;
}

.attendanceSessionRoster {
  flex: 1 1 auto;
  min-height: 0;
  overflow-y: auto !important;
  overflow-x: hidden;
  padding-top: 0 !important;
  padding-bottom: 110px;
  scroll-padding-top: 12px;
}

.attendanceSessionRosterHead {
  position: sticky;
  top: 0;
  z-index: 7;
  background: #fff;
}

.attendanceSessionFooter {
  position: sticky;
  bottom: 0;
  top: auto !important;
  z-index: 9;
  margin-top: 0 !important;
  background: #fff;
  border-top: 1px solid #e6ebf2;
}

.attendanceSessionFooter > div:first-child {
  min-width: 0;
}

.attendanceSessionFooter > div:first-child span,
.attendanceSessionFooter > div:first-child small {
  display: block;
}

.attendanceSessionFooter > div:last-child {
  display: flex;
  align-items: center;
  gap: 10px;
