    0;

  line-height:
    1.25;

  overflow-wrap:
    anywhere;
}


.attendanceSessionScrim
.attendanceSessionStudent small {
  display:
    block;

  min-width:
    0;

  overflow:
    hidden;

  white-space:
    nowrap;

  text-overflow:
    ellipsis;
}


/*
 * UID must not push into student name/status columns.
 */
.attendanceSessionScrim
.attendanceSessionRosterRow
> code {
  min-width:
    0;

  overflow:
    hidden;

  white-space:
    nowrap;

  text-overflow:
    ellipsis;
}


/* ============================================================
   FOOTER — NORMAL FLOW, NEVER OVER STUDENTS
   ============================================================ */

.attendanceSessionScrim
.attendanceSessionFooter {
  position:
    relative !important;

  top:
    auto !important;

  bottom:
    auto !important;

  z-index:
    2 !important;

  display:
    flex !important;

  align-items:
    center !important;

  justify-content:
    space-between !important;

  flex:
    none !important;

  gap:
    18px !important;

  margin:
    0 !important;

  padding:
