/* ============================================================
   CAMPUSCONNECT — ATTENDANCE SESSION MODAL
   FINAL PROFESSIONAL LAYOUT
   ============================================================ */


/*
 * Fixed viewport backdrop.
 *
 * The overlay itself NEVER becomes the page-sized document.
 */
.attendanceModalScrim.attendanceSessionScrim {
  position: fixed !important;
  inset: 0 !important;
  z-index: 1000 !important;

  display: grid !important;
  place-items: center !important;

  padding: 22px !important;

  overflow: hidden !important;

  background:
    rgba(15, 23, 42, .48) !important;

  backdrop-filter:
    blur(5px);

  -webkit-backdrop-filter:
    blur(5px);

  overscroll-behavior:
    none !important;
}


