/* ============================================================
   CAMPUSCONNECT — ATTENDANCE MODAL
   CANONICAL OVERRIDE
   ============================================================ */

/*
 * Full viewport backdrop.
 */
.attendanceSessionScrim {
  position: fixed !important;
  inset: 0 !important;
  z-index: 10000 !important;

  display: flex !important;
  align-items: center !important;
  justify-content: center !important;

  width: 100vw !important;
  height: 100dvh !important;

  margin: 0 !important;
  padding: 20px !important;

  overflow: hidden !important;

  background: rgba(15, 23, 42, 0.52) !important;

  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
}


/*
 * Professional centered attendance dialog.
 */
.attendanceSessionScrim > .attendanceSessionModal {
  position: relative !important;

  display: grid !important;
  grid-template-rows:
    auto
    minmax(0, 1fr)
    auto !important;

  width: min(1180px, calc(100vw - 40px)) !important;
  height: min(800px, calc(100dvh - 40px)) !important;

  min-height: 0 !important;
  max-height: calc(100dvh - 40px) !important;

  margin: 0 !important;

  overflow: hidden !important;

  border-radius: 20px !important;

  background: #ffffff !important;

  box-shadow:
    0 30px 90px rgba(15, 23, 42, 0.28) !important;
}


/*
 * Header stays visible.
 */
.attendanceSessionScrim
> .attendanceSessionModal
> .attendanceSessionModalHeader {
  position: relative !important;
  top: auto !important;
  bottom: auto !important;

  z-index: 20 !important;

  background: #ffffff !important;

  border-bottom:
    1px solid rgba(15, 23, 42, 0.07);
}


/*
 * This is the only internal scrolling area.
 */
.attendanceSessionScrim
> .attendanceSessionModal
> .attendanceSessionContent {
  min-width: 0 !important;
  min-height: 0 !important;

  overflow-x: hidden !important;
  overflow-y: auto !important;

  overscroll-behavior: contain !important;

  -webkit-overflow-scrolling: touch;
}


/*
 * Roster participates normally inside content.
 */
.attendanceSessionScrim
.attendanceSessionRoster {
  min-height: 0 !important;
  max-height: none !important;

  overflow: visible !important;

  padding-bottom: 0 !important;
}


/*
 * Student column heading.
 */
.attendanceSessionScrim
.attendanceSessionRosterHead {
  position: sticky !important;
  top: 0 !important;

  z-index: 8 !important;

  background: #f8fafc !important;

  border-bottom:
    1px solid rgba(15, 23, 42, 0.07);
}


/*
 * Prevent student identity overflow.
 */
.attendanceSessionScrim
.attendanceSessionStudent {
  min-width: 0 !important;
}


.attendanceSessionScrim
.attendanceSessionStudent > div:last-child {
  min-width: 0 !important;
  overflow: hidden;
}


.attendanceSessionScrim
.attendanceSessionStudent small {
  display: block;

  overflow: hidden;

  white-space: nowrap;

  text-overflow: ellipsis;
}


/*
 * Footer is a dedicated modal row.
 * It does NOT overlap students.
 */
.attendanceSessionScrim
> .attendanceSessionModal
> .attendanceSessionFooter {
  position: relative !important;

  top: auto !important;
  bottom: auto !important;

  z-index: 20 !important;

  display: flex !important;

  align-items: center !important;
  justify-content: space-between !important;

  flex: 0 0 auto !important;

  gap: 18px !important;

  min-height: 72px;

  margin: 0 !important;
  padding: 13px 20px !important;

  border-top:
    1px solid rgba(15, 23, 42, 0.08);

  background: #ffffff !important;

  box-shadow:
    0 -6px 20px rgba(15, 23, 42, 0.035) !important;
}


/*
 * Attendance summary.
 */
.attendanceSessionScrim
.attendanceSessionFooter > div:first-child {
  display: grid;

  min-width: 0;

  gap: 3px;
}


.attendanceSessionScrim
.attendanceSessionFooter > div:first-child > span,
.attendanceSessionScrim
.attendanceSessionFooter > div:first-child > small {
  display: block;
}


.attendanceSessionScrim
.attendanceChangedSummary {
  color: #2563eb !important;
  font-weight: 800 !important;
}


/*
 * Footer actions.
 */
.attendanceSessionScrim
.attendanceSessionFooter > div:last-child {
  display: flex;

  align-items: center;

  flex: 0 0 auto;

  gap: 10px;
}


@media (max-height: 760px) {

  .attendanceSessionScrim {
    padding: 12px !important;
  }

  .attendanceSessionScrim > .attendanceSessionModal {
    width: min(1180px, calc(100vw - 24px)) !important;

    height: calc(100dvh - 24px) !important;

    max-height: calc(100dvh - 24px) !important;
  }

}


@media (max-width: 700px) {

  .attendanceSessionScrim {
    padding: 8px !important;
  }

  .attendanceSessionScrim > .attendanceSessionModal {
    width: calc(100vw - 16px) !important;
    height: calc(100dvh - 16px) !important;

    max-height: calc(100dvh - 16px) !important;

    border-radius: 15px !important;
  }

  .attendanceSessionScrim
  > .attendanceSessionModal
  > .attendanceSessionFooter {
    align-items: stretch !important;

    flex-direction: column !important;
  }

  .attendanceSessionScrim
