/* ------------------------------------------------------------
   SKELETON
   ------------------------------------------------------------ */

.facultyScheduleSkeleton {
  position: relative;
  overflow: hidden;
  border-radius: 10px;
  background: #edf1f5;
}

.facultyScheduleSkeleton::after {
  content: "";
  position: absolute;
  inset: 0;
  transform: translateX(-100%);
  background:
    linear-gradient(
      90deg,
      transparent,
      rgba(255, 255, 255, 0.72),
      transparent
    );
  animation:
    facultyScheduleShimmer 1.35s infinite;
}

@keyframes facultyScheduleShimmer {
  100% {
    transform: translateX(100%);
  }
}

.facultyTeachingScheduleSkeletonHero {
  padding: 34px;
  border: 1px solid #e6ebf1;
  border-radius: 24px;
  background: #ffffff;
}

.facultyScheduleSkeletonTag {
  width: 165px;
  height: 13px;
}

.facultyScheduleSkeletonTitle {
  width: min(410px, 70%);
  height: 38px;
  margin-top: 16px;
}

.facultyScheduleSkeletonText {
  width: min(610px, 90%);
  height: 17px;
  margin-top: 14px;
}

.facultyTeachingScheduleSkeletonMetrics {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 13px;
  margin-top: 16px;
}

.facultyScheduleSkeletonMetric {
  height: 122px;
  border-radius: 18px;
}

.facultyScheduleSkeletonPanel {
  height: 490px;
  margin-top: 16px;
  border-radius: 22px;
}


/* ------------------------------------------------------------
   RESPONSIVE
   ------------------------------------------------------------ */

@media (max-width: 1100px) {
  .facultyTeachingScheduleMetrics {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .facultyTeachingScheduleHeroTop,
  .facultyTeachingScheduleFocus,
  .facultyTeachingScheduleToolbar {
    align-items: stretch;
    flex-direction: column;
  }

  .facultyTeachingScheduleToolbarActions {
    width: 100%;
  }

  .facultyTeachingScheduleSearch {
    width: 100%;
  }
}

@media (max-width: 760px) {
  .facultyTeachingSchedule {
    padding: 14px;
  }

  .facultyTeachingScheduleHero {
    padding: 21px;
    border-radius: 19px;
  }

  .facultyTeachingScheduleHeroActions {
    width: 100%;
  }

  .facultyTeachingScheduleVersion {
    flex: 1 1 auto;
  }

  .facultyTeachingScheduleRefresh {
    flex: 0 0 auto;
  }

  .facultyTeachingScheduleMetrics {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 9px;
  }

  .facultyTeachingScheduleMetrics article {
    min-height: 104px;
    padding: 15px;
  }

  .facultyTeachingScheduleFocusMeta {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
  }

  .facultyTeachingScheduleDays {
    display: flex;
    overflow-x: auto;
    padding: 5px;
  }

  .facultyTeachingScheduleDays button {
    min-width: 76px;
    flex: 1 0 auto;
  }

  .facultyTeachingScheduleToolbarActions {
    align-items: stretch;
    flex-direction: column;
  }

  .facultyTeachingScheduleViewSwitch {
    align-self: flex-start;
  }

  .facultyTeachingScheduleClass {
    grid-template-columns: 1fr;
    min-height: 0;
  }

  .facultyTeachingScheduleTime {
    align-items: center;
    flex-direction: row;
    gap: 7px;
    padding-top: 12px;
  }

  .facultyTeachingScheduleTime small {
    margin: 0 0 0 auto;
  }

  .facultyTeachingScheduleRail {
    display: none;
  }

  .facultyTeachingScheduleClassDetails {
    grid-template-columns: 1fr;
  }

  .facultyTeachingScheduleClassFooter {
    align-items: flex-start;
    flex-direction: column;
  }

  .facultyTeachingScheduleSkeletonMetrics {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 480px) {
  .facultyTeachingScheduleMetrics {
    grid-template-columns: 1fr 1fr;
  }

  .facultyTeachingScheduleHeroActions {
    flex-direction: column;
  }

  .facultyTeachingScheduleRefresh,
  .facultyTeachingScheduleVersion {
    width: 100%;
  }

  .facultyTeachingScheduleFocusMeta {
    grid-template-columns: 1fr;
  }

  .facultyTeachingSchedulePanel {
    padding: 15px;
  }
}

