  margin: 12px 22px 0;
  padding: 10px 12px;
  border-radius: 9px;
  font-size: 0.62rem;
}

.digitalBuilderAlert.error {
  border: 1px solid #edcece;
  background: #fff9f9;
  color: #994d4d;
}

.digitalBuilderAlert.success {
  border: 1px solid #d4e5d8;
  background: #f8fcf9;
  color: #54765c;
}

.digitalBuilderValidation {
  margin: 12px 22px;
  padding: 12px;
  border-radius: 10px;
}

.digitalBuilderValidation.valid {
  border: 1px solid #d0e5d5;
  background: #f7fbf8;
}

.digitalBuilderValidation.invalid {
  border: 1px solid #ead7b8;
  background: #fffaf2;
}

.digitalBuilderValidation > div {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.digitalBuilderValidation strong {
  color: #46556b;
  font-size: 0.63rem;
}

.digitalBuilderValidation span,
.digitalBuilderValidation li {
  color: #8490a1;
  font-size: 0.55rem;
}

.digitalBuilderValidation ul {
  margin: 9px 0 0;
  padding-left: 18px;
}

.digitalBuilderLoading,
.digitalBuilderEmpty {
  display: grid;
  min-height: 250px;
  place-items: center;
  align-content: center;
  padding: 25px;
  text-align: center;
}

.digitalBuilderLoading {
  gap: 9px;
  color: #8290a2;
  font-size: 0.65rem;
}

.digitalBuilderLoading > span {
  width: 26px;
  height: 26px;
  border: 3px solid #e5eaf0;
  border-top-color: #6687b6;
  border-radius: 50%;
  animation:
    digitalBuilderSpin 0.8s linear infinite;
}

@keyframes digitalBuilderSpin {
  to {
    transform: rotate(360deg);
  }
}

.digitalBuilderEmpty strong {
  color: #475569;
  font-size: 0.78rem;
}

.digitalBuilderEmpty p {
  max-width: 470px;
  margin: 5px 0 0;
  color: #909baa;
  font-size: 0.62rem;
  line-height: 1.55;
}

.digitalBuilderModalBackdrop {
  position: fixed;
  z-index: 10050;
  inset: 0;
  display: grid;
  place-items: center;
  padding: 20px;
  background: rgba(15, 23, 42, 0.42);
  backdrop-filter: blur(5px);
}

.digitalBuilderModal {
  width: min(100%, 690px);
  max-height: min(90vh, 900px);
  overflow-y: auto;
  border: 1px solid #e1e6ed;
  border-radius: 20px;
  background: #fff;
  box-shadow:
    0 30px 90px rgba(15, 23, 42, 0.22);
}

.digitalBuilderModal > header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 18px;
  padding: 21px;
  border-bottom: 1px solid #edf0f4;
}

.digitalBuilderModal > header span {
  color: #6480a8;
  font-size: 0.53rem;
  font-weight: 850;
  letter-spacing: 0.1em;
}

.digitalBuilderModal > header h2 {
  margin: 5px 0 0;
  color: #26364d;
  font-size: 1rem;
}

.digitalBuilderModal > header p {
  margin: 5px 0 0;
  color: #8b96a5;
  font-size: 0.59rem;
}

.digitalBuilderModal > header > button {
  width: 34px;
  height: 34px;
  flex: 0 0 auto;
  border: 1px solid #dde3eb;
  border-radius: 9px;
  background: #fff;
  color: #66758a;
  cursor: pointer;
}

.digitalBuilderFormGrid {
  display: grid;
  grid-template-columns:
    repeat(2, minmax(0, 1fr));
  gap: 13px;
  padding: 20px;
}

.digitalBuilderFormGrid label {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 6px;
}

.digitalBuilderFormGrid label.wide {
  grid-column: 1 / -1;
}

.digitalBuilderFormGrid label > span {
  color: #536174;
  font-size: 0.58rem;
  font-weight: 800;
}

.digitalBuilderFormGrid input,
.digitalBuilderFormGrid select,
.digitalBuilderFormGrid textarea {
  width: 100%;
  min-width: 0;
  border: 1px solid #dce3eb;
  border-radius: 9px;
  outline: 0;
  background: #fff;
  color: #334155;
  font: inherit;
  font-size: 0.66rem;
}

.digitalBuilderFormGrid input,
.digitalBuilderFormGrid select {
  min-height: 42px;
  padding: 0 10px;
}

.digitalBuilderFormGrid textarea {
  padding: 10px;
  resize: vertical;
}

.digitalBuilderFormGrid input:focus,
.digitalBuilderFormGrid select:focus,
.digitalBuilderFormGrid textarea:focus {
  border-color: #9bb3d4;
  box-shadow:
    0 0 0 3px rgba(37, 99, 235, 0.06);
}

.digitalBuilderFormGrid small {
  color: #97a2b0;
  font-size: 0.5rem;
  line-height: 1.4;
}

.digitalBuilderFormGrid small.error {
  color: #a45d5d;
}

.digitalBuilderAllocationHint {
  display: flex;
  margin: 0 20px 18px;
  flex-direction: column;
  gap: 3px;
  padding: 10px 11px;
  border: 1px solid #dce7f4;
  border-radius: 9px;
  background: #f8fbff;
}

.digitalBuilderAllocationHint strong {
  color: #4d6688;
  font-size: 0.57rem;
}

.digitalBuilderAllocationHint span {
  color: #8493a6;
  font-size: 0.53rem;
}

.digitalBuilderModal > footer {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 14px 20px;
  border-top: 1px solid #edf0f4;
  background: #fafbfc;
}

.digitalBuilderModalSpacer {
  flex: 1;
}

@media (max-width: 900px) {
  .digitalBuilderControlBar {
    grid-template-columns: 1fr;
  }

  .digitalBuilderBatchMeta {
    grid-template-columns:
      repeat(3, minmax(0, 1fr));
  }

  .digitalBuilderToolbar {
    align-items: stretch;
    flex-direction: column;
  }

  .digitalBuilderToolbarActions {
    justify-content: flex-start;
  }
}

@media (max-width: 680px) {
  .digitalBuilder {
    border-radius: 15px;
  }

  .digitalBuilderHero {
    flex-direction: column;
    padding: 20px;
  }

  .digitalBuilderHeroState {
    align-items: flex-start;
  }

  .digitalBuilderBatchMeta {
    grid-template-columns: 1fr;
  }

  .digitalBuilderFormGrid {
    grid-template-columns: 1fr;
    padding: 16px;
  }

  .digitalBuilderFormGrid label.wide {
    grid-column: auto;
  }

  .digitalBuilderGridFooter {
    align-items: flex-start;
    flex-direction: column;
  }

  .digitalBuilderModalBackdrop {
    padding: 9px;
  }

  .digitalBuilderModal {
    border-radius: 14px;
  }
}
